    /// Optional SQL COPY PROGRAM adapter. Antfly never executes shell commands
    /// directly; embeddings must install an adapter that applies its own command
    /// allowlist/sandbox and returns or consumes bytes for the SQL bulk route.
    sql_bulk_io_program_io: ?SqlBulkIoProgramIo = null,
};

const RowsUniqueSelectorResolverContext = struct {
    source: ?table_reads.TableReadSource,

    fn resolver(self: *@This()) ?relational_rows_api.UniqueSelectorResolver {
        if (self.source == null) return null;
        return .{
            .ptr = self,
            .resolve = resolve,
            .resolve_temporal = resolveTemporal,
            .resolve_temporal_overlap = resolveTemporalOverlap,
            .resolve_primary = resolvePrimary,
            .lookup_primary = lookupPrimary,
        };
    }

    fn resolve(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
    ) !?[]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        return source.relationalUniqueOwnerLookup(alloc, table_name, constraint_name, encoded_value, .read_index) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    fn resolveTemporal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_point: []const u8,
    ) !?[]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        return source.relationalTemporalUniqueOwnerLookup(alloc, table_name, constraint_name, encoded_value, encoded_point, .read_index) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    fn resolveTemporalOverlap(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_start: []const u8,
        encoded_end: []const u8,
    ) !?[]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        return source.relationalTemporalUniqueOverlapOwnerLookup(alloc, table_name, constraint_name, encoded_value, encoded_start, encoded_end, .read_index) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    fn resolvePrimary(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) !bool {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        var lookup = (try source.lookup(alloc, table_name, physical_key, .{}, .read_index)) orelse return false;
        lookup.deinit(alloc);
        return true;
    }

    fn lookupPrimary(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) !?relational_rows_api.ResolvedPrimaryRow {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        const lookup = (try source.lookup(alloc, table_name, physical_key, .{}, .read_index)) orelse return null;
        return .{
            .json = lookup.json,
            .version = lookup.version,
        };
    }
};

