pub const AuthenticatedIdentity = struct {
    username: []u8,
    permissions: []usermgr.Permission = &.{},
    row_filter: []usermgr.RowFilterEntry = &.{},
    metadata_json: []u8 = &.{},
    roles: [][]u8 = &.{},
    role_settings: []usermgr.RoleSetting = &.{},
    role_runtime_settings: []usermgr.RoleSetting = &.{},

    pub fn deinit(self: *AuthenticatedIdentity, alloc: std.mem.Allocator) void {
        alloc.free(self.username);
        for (self.permissions) |*permission| permission.deinit(alloc);
        if (self.permissions.len > 0) alloc.free(self.permissions);
        for (self.row_filter) |*entry| entry.deinit(alloc);
        if (self.row_filter.len > 0) alloc.free(self.row_filter);
        if (self.metadata_json.len > 0) alloc.free(self.metadata_json);
        for (self.roles) |role| alloc.free(role);
        if (self.roles.len > 0) alloc.free(self.roles);
        for (self.role_settings) |*setting| setting.deinit(alloc);
        if (self.role_settings.len > 0) alloc.free(self.role_settings);
        for (self.role_runtime_settings) |*setting| setting.deinit(alloc);
        if (self.role_runtime_settings.len > 0) alloc.free(self.role_runtime_settings);
        self.* = undefined;
    }
};

fn delegatedIdentityView(identity: ?AuthenticatedIdentity) ?protocol_adapters.DelegatedIdentity {
    const value = identity orelse return null;
    return .{
        .username = value.username,
        .permissions = value.permissions,
        .row_filter = value.row_filter,
        .metadata_json = value.metadata_json,
        .roles = value.roles,
        .role_settings = value.role_settings,
        .role_runtime_settings = value.role_runtime_settings,
    };
}

