            }

            fn deleteArtifactEnrichment(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8) anyerror!void {
                return try deleteArtifactEnrichmentOnService(cast(ptr), alloc, table_name, artifact_name);
            }

            fn waitTableLifecycle(ptr: *anyopaque, table_name: []const u8, expected: TableVisibility) anyerror!void {
                return try cast(ptr).waitForTableLifecycle(table_name, switch (expected) {
                    .present => .present,
                    .absent => .absent,
                });
            }

            fn waitTableProjection(ptr: *anyopaque, table_name: []const u8, schema_json: ?[]const u8, indexes_json: ?[]const u8) anyerror!void {
                return try cast(ptr).waitForTableProjection(table_name, .{
                    .schema_json = schema_json,
                    .indexes_json = indexes_json,
                });
            }

            fn runRound(ptr: *anyopaque) anyerror!void {
                return try cast(ptr).runRound();
            }

            fn getJoinShuffleLease(ptr: *anyopaque, job_id: u64) anyerror!?metadata_table_manager.ShuffleJoinLeaseRecord {
                return try cast(ptr).getProjectedShuffleJoinLease(job_id);
            }

            fn upsertJoinShuffleLease(ptr: *anyopaque, record: metadata_table_manager.ShuffleJoinLeaseRecord) anyerror!void {
                try cast(ptr).upsertShuffleJoinLease(record);
            }

            fn removeJoinShuffleLease(ptr: *anyopaque, job_id: u64) anyerror!void {
                try cast(ptr).removeShuffleJoinLease(job_id);
            }

            fn installExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.InstallExtensionRequest) anyerror!extension_domain.InstalledExtension {
                return try installExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn updateExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.UpdateExtensionRequest) anyerror!extension_domain.InstalledExtension {
                return try updateExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn dropExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.DropExtensionRequest) anyerror!void {
                return try dropExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn enableExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8) anyerror!extension_domain.InstalledExtension {
                return try enableExtensionOnService(cast(ptr), alloc, name);
            }

            fn disableExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8) anyerror!extension_domain.InstalledExtension {
                return try disableExtensionOnService(cast(ptr), alloc, name);
            }

            fn configureExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.ConfigureExtensionRequest) anyerror!extension_domain.InstalledExtension {
                return try configureExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn restoreExtensions(
                ptr: *anyopaque,
                alloc: std.mem.Allocator,
                installed: []const extension_domain.InstalledExtension,
                members: []const extension_domain.ExtensionMember,
                dependencies: []const extension_domain.ExtensionDependency,
            ) anyerror!void {
                return try restoreExtensionsOnService(cast(ptr), alloc, installed, members, dependencies);
            }
        };

        return .{
            .status = Gen.status,
            .admin_snapshot = Gen.adminSnapshot,
            .cached_admin_snapshot = Gen.cachedAdminSnapshot,
            .ensure_linearizable_read = Gen.ensureLinearizableRead,
            .free_admin_snapshot = Gen.freeAdminSnapshot,
            .create_table = Gen.createTable,
            .create_catalog_table = Gen.createCatalogTable,
            .restore_table = Gen.restoreTable,
            .drop_table = Gen.dropTable,
            .drop_catalog_table = Gen.dropCatalogTable,
            .update_schema = Gen.updateSchema,
            .apply_relational_sql_ddl_plan_with_session = Gen.applyRelationalSqlDdlPlanWithSession,
            .compare_and_swap_table_schema = Gen.compareAndSwapTableSchema,
            .apply_prepared_transaction_plan = Gen.applyPreparedTransactionPlan,
            .apply_database_catalog_plan = Gen.applyDatabaseCatalogPlan,
            .apply_tablespace_catalog_plan = Gen.applyTablespaceCatalogPlan,
            .set_database_tablespace = Gen.setDatabaseTablespace,
            .set_namespace_tablespace = Gen.setNamespaceTablespace,
            .create_namespace = Gen.createNamespace,
            .drop_namespace = Gen.dropNamespace,
            .create_index = Gen.createIndex,
            .create_catalog_index = Gen.createCatalogIndex,
            .drop_index = Gen.dropIndex,
            .drop_catalog_index = Gen.dropCatalogIndex,
            .put_artifact_enrichment = Gen.putArtifactEnrichment,
            .delete_artifact_enrichment = Gen.deleteArtifactEnrichment,
            .wait_table_lifecycle = Gen.waitTableLifecycle,
            .wait_table_projection = Gen.waitTableProjection,
            .run_round = Gen.runRound,
            .get_join_shuffle_lease = Gen.getJoinShuffleLease,
            .upsert_join_shuffle_lease = Gen.upsertJoinShuffleLease,
            .remove_join_shuffle_lease = Gen.removeJoinShuffleLease,
            .install_extension = Gen.installExtension,
            .update_extension = Gen.updateExtension,
            .drop_extension = Gen.dropExtension,
            .enable_extension = Gen.enableExtension,
            .disable_extension = Gen.disableExtension,
            .configure_extension = Gen.configureExtension,
            .restore_extensions = Gen.restoreExtensions,
        };
    }

    pub fn fromMetadataHttpService(svc: *metadata_service.MetadataHttpService) StatusSource {
        return .{ .ptr = svc, .vtable = &comptime makeServiceVTable(metadata_service.MetadataHttpService) };
    }

    pub fn fromMetadataService(svc: *metadata_service.MetadataService) StatusSource {
        return .{ .ptr = svc, .vtable = &comptime makeServiceVTable(metadata_service.MetadataService) };
    }

    pub fn fromMetadataServer(srv: *metadata_server.MetadataServer) StatusSource {
        return fromMetadataHttpService(srv.svc);
    }
};

const RestoreMetadataSpec = struct {
    manifest: backups_api.TableBackupManifest,
    table: metadata_table_manager.TableRecord,
    ranges: []metadata_table_manager.RangeRecord,

    fn deinit(self: *RestoreMetadataSpec, alloc: std.mem.Allocator) void {
        self.manifest.deinit(alloc);
        metadata_table_manager.freeTable(alloc, self.table);
        for (self.ranges) |record| metadata_table_manager.freeRange(alloc, record);
        alloc.free(self.ranges);
        self.* = undefined;
    }
};

fn loadRestoreMetadataSpec(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    location_uri: []const u8,
    backup_id: []const u8,
    secret_store: ?*common_secrets.FileStore,
) !RestoreMetadataSpec {
    var location = try backups_api.openBackupLocationWithSecrets(alloc, location_uri, secret_store);
    defer location.deinit(alloc);
    var manifest = backups_api.readManifestFromLocation(alloc, &location, backup_id) catch return error.InvalidBackupRequest;
    errdefer manifest.deinit(alloc);
    if (!std.mem.eql(u8, manifest.table_name, table_name)) return error.InvalidBackupRequest;
    const table = backups_api.deriveRestoreTableRecord(alloc, table_name, location_uri, &manifest) catch |err| switch (err) {
        error.UnsupportedBackupMigrationState => return error.UnsupportedBackupMigrationState,
        else => return err,
    };
    errdefer metadata_table_manager.freeTable(alloc, table);
    const ranges = try backups_api.deriveRestoreRanges(alloc, table.table_id, location_uri, &manifest);
    errdefer {
        for (ranges) |record| metadata_table_manager.freeRange(alloc, record);
        alloc.free(ranges);
    }
    return .{
        .manifest = manifest,
        .table = table,
        .ranges = ranges,
    };
}

fn createTableOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, req: tables_api.CreateTableRequest) !void {
    return try createCatalogTableOnService(svc, alloc, .{
        .database_name = tables_api.default_database_name,
        .namespace_name = tables_api.default_namespace_name,
        .table_name = table_name,
    }, req);
}

fn createCatalogTableOnService(svc: anytype, alloc: std.mem.Allocator, target: catalog_resources.TableTarget, req: tables_api.CreateTableRequest) !void {
    var workflow = metadata_table_workflow.TableWorkflow.init(alloc);
    defer workflow.deinit();
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    if (!std.mem.eql(u8, target.database_name, tables_api.default_database_name) or
        !std.mem.eql(u8, target.namespace_name, tables_api.default_namespace_name))
    {
        if (tables_api.findDatabaseByName(&snapshot, target.database_name) == null) return error.DatabaseNotFound;
        if (tables_api.findNamespaceByName(&snapshot, target.database_name, target.namespace_name) == null) return error.NamespaceNotFound;
    }
    if (tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) != null) return error.TableAlreadyExists;
    if (req.tablespace_name) |tablespace_name| {
        _ = tables_api.findTablespaceByName(&snapshot, tablespace_name) orelse return error.TablespaceNotFound;
    }

    var normalized_req = req;
    var expanded_indexes_json: ?[]u8 = null;
    defer if (expanded_indexes_json) |value| alloc.free(value);
    const indexes_json = req.indexes_json orelse tables_api.default_indexes_json;
    expanded_indexes_json = try tables_api.prepareTableIndexesForSchemaAlloc(alloc, target.table_name, indexes_json, tables_api.effectiveSchemaJson(req.schema_json));
    normalized_req.indexes_json = expanded_indexes_json;
    const base_table = tables_api.deriveQualifiedTableRecord(target.database_name, target.namespace_name, target.table_name, normalized_req);
    var policy_table: ?metadata_table_manager.TableRecord = null;
    defer if (policy_table) |record| metadata_table_manager.freeTable(alloc, record);
    const table = if (tables_api.effectiveTablespaceForTarget(&snapshot, target.database_name, target.namespace_name, normalized_req.tablespace_name)) |tablespace| blk: {
        policy_table = try tables_api.applyTablespacePlacementPolicyAlloc(alloc, base_table, tablespace);
        break :blk policy_table.?;
    } else base_table;
    const ranges = try tables_api.deriveInitialRanges(alloc, table);
    defer {
        for (ranges) |record| metadata_table_manager.freeRange(alloc, record);
        alloc.free(ranges);
    }
    _ = try workflow.createTableWithRanges(svc, table, ranges);
    try svc.runRound();
}

fn dropTableOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8) !void {
    return try dropCatalogTableOnService(svc, alloc, .{
        .database_name = tables_api.default_database_name,
        .namespace_name = tables_api.default_namespace_name,
        .table_name = table_name,
    });
}

fn dropCatalogTableOnService(svc: anytype, alloc: std.mem.Allocator, target: catalog_resources.TableTarget) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;
    if (extensionOwnsTableScopedObject(&snapshot, target.table_name)) return error.ExtensionOwnedObject;

    var workflow = metadata_table_workflow.TableWorkflow.init(alloc);
    defer workflow.deinit();
    _ = try workflow.dropTable(svc, table.table_id);
    try svc.runRound();
}

fn updateSchemaOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsTableShape(&snapshot, table_name)) return error.ExtensionOwnedObject;

    const updated = try tables_api.applySchemaUpdateRecord(alloc, table, schema_json);
    defer metadata_table_manager.freeTable(alloc, updated);
    try svc.upsertTable(updated);
    try svc.runRound();
}

fn createNamespaceOnService(svc: anytype, database_name: []const u8, namespace_name: []const u8) !void {
    const ServiceType = @TypeOf(svc);
    const ServiceDeclType = switch (@typeInfo(ServiceType)) {
        .pointer => |pointer| pointer.child,
        else => ServiceType,
    };
    if (comptime !@hasDecl(ServiceDeclType, "upsertNamespace")) return error.UnsupportedOperation;
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return error.DatabaseNotFound;
    if (tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) != null) return error.NamespaceAlreadyExists;
    try svc.upsertNamespace(.{
        .namespace_id = metadata_table_manager.deriveNamespaceId(database.database_id, namespace_name),
        .database_id = database.database_id,
        .name = namespace_name,
    });
    try svc.runRound();
}

fn dropNamespaceOnService(svc: anytype, database_name: []const u8, namespace_name: []const u8) !void {
    const ServiceType = @TypeOf(svc);
    const ServiceDeclType = switch (@typeInfo(ServiceType)) {
        .pointer => |pointer| pointer.child,
        else => ServiceType,
    };
    if (comptime !@hasDecl(ServiceDeclType, "removeNamespace")) return error.UnsupportedOperation;
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    _ = tables_api.findDatabaseByName(&snapshot, database_name) orelse return error.DatabaseNotFound;
    const namespace = tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) orelse return error.NamespaceNotFound;
    try svc.removeNamespace(namespace.namespace_id);
    try svc.runRound();
}

fn setDatabaseTablespaceOnService(svc: anytype, database_name: []const u8, tablespace_name: ?[]const u8) !void {
    const ServiceType = @TypeOf(svc);
    const ServiceDeclType = switch (@typeInfo(ServiceType)) {
        .pointer => |pointer| pointer.child,
        else => ServiceType,
    };
    if (comptime !@hasDecl(ServiceDeclType, "upsertDatabase")) return error.UnsupportedOperation;
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return error.DatabaseNotFound;
    if (tablespace_name) |name| {
        _ = tables_api.findTablespaceByName(&snapshot, name) orelse return error.TablespaceNotFound;
    }
    var updated = database.*;
    updated.tablespace_name = tablespace_name orelse "";
    try svc.upsertDatabase(updated);
    try svc.runRound();
}

fn setNamespaceTablespaceOnService(svc: anytype, database_name: []const u8, namespace_name: []const u8, tablespace_name: ?[]const u8) !void {
    const ServiceType = @TypeOf(svc);
    const ServiceDeclType = switch (@typeInfo(ServiceType)) {
        .pointer => |pointer| pointer.child,
        else => ServiceType,
    };
    if (comptime !@hasDecl(ServiceDeclType, "upsertNamespace")) return error.UnsupportedOperation;
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    _ = tables_api.findDatabaseByName(&snapshot, database_name) orelse return error.DatabaseNotFound;
    const namespace = tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) orelse return error.NamespaceNotFound;
    if (tablespace_name) |name| {
        _ = tables_api.findTablespaceByName(&snapshot, name) orelse return error.TablespaceNotFound;
    }
    var updated = namespace.*;
    updated.tablespace_name = tablespace_name orelse "";
    try svc.upsertNamespace(updated);
    try svc.runRound();
}

fn applyRelationalSqlDdlPlanOnServiceWithSession(
    svc: anytype,
    alloc: std.mem.Allocator,
    plan: *sql_adapter.DurableSqlPlan,
    session: catalog_resources.SqlCatalogSession,
) !tables_api.AppliedRelationalSqlDdlRecord {
    var applied = try relational_sql_ddl.applyDurablePlanOnServiceWithSessionAlloc(alloc, svc, plan, session);
    errdefer applied.deinit(alloc);
    try svc.runRound();
    return applied;
}

const SchemaRewriteWakeJob = struct {
    runtime: *db_mod.background_runtime.BackendRuntime,
    owner_id: u64,
    source: table_writes.TableWriteSource,
    catalog: ?StatusSource = null,
    registry: ?*SchemaRewriteWakeRegistry = null,
    table_name: []u8,
    table_id: u64 = 0,
    promoted_table: ?metadata_table_manager.TableRecord = null,
    worker_id: []const u8 = "api-schema-rewrite",
    lease_ms: u64 = 60_000,
    max_work_units_per_pass: usize = 16,
    max_passes: usize = 64,

    fn submit(
        runtime: *db_mod.background_runtime.BackendRuntime,
        owner_id: u64,
        source: table_writes.TableWriteSource,
        table_name: []const u8,
    ) !void {
        return try SchemaRewriteWakeJob.submitWithPromotion(runtime, owner_id, source, table_name, null, null);
    }

    fn submitWithPromotion(
        runtime: *db_mod.background_runtime.BackendRuntime,
        owner_id: u64,
        source: table_writes.TableWriteSource,
        table_name: []const u8,
        catalog: ?StatusSource,
        promoted_table: ?metadata_table_manager.TableRecord,
    ) !void {
        return try SchemaRewriteWakeJob.submitWithPromotionAndRegistry(runtime, owner_id, source, table_name, catalog, promoted_table, null, 0);
    }

    fn submitWithPromotionAndRegistry(
        runtime: *db_mod.background_runtime.BackendRuntime,
        owner_id: u64,
        source: table_writes.TableWriteSource,
        table_name: []const u8,
        catalog: ?StatusSource,
        promoted_table: ?metadata_table_manager.TableRecord,
        registry: ?*SchemaRewriteWakeRegistry,
        table_id: u64,
    ) !void {
        const alloc = std.heap.page_allocator;
        const work = try alloc.create(SchemaRewriteWakeJob);
        var work_transferred = false;
        errdefer if (!work_transferred) alloc.destroy(work);
        const owned_table_name = try alloc.dupe(u8, table_name);
        var table_name_transferred = false;
        errdefer if (!table_name_transferred) alloc.free(owned_table_name);
        const owned_promoted_table = if (promoted_table) |table|
            try metadata_table_manager.cloneTable(alloc, table)
        else
            null;
        var promoted_table_transferred = false;
        errdefer if (!promoted_table_transferred) if (owned_promoted_table) |table| metadata_table_manager.freeTable(alloc, table);
        work.* = .{
            .runtime = runtime,
            .owner_id = owner_id,
            .source = source,
            .catalog = catalog,
            .registry = registry,
            .table_name = owned_table_name,
            .table_id = table_id,
            .promoted_table = owned_promoted_table,
        };
        table_name_transferred = true;
        promoted_table_transferred = true;
        work_transferred = true;
        var submitted = false;
        errdefer if (!submitted) SchemaRewriteWakeJob.deinit(work);
        try runtime.durable_jobs.submit(.{
            .owner_id = owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = SchemaRewriteWakeJob.run,
            .deinit = SchemaRewriteWakeJob.deinit,
        });
        submitted = true;
    }

    fn run(ptr: *anyopaque) !void {
        const self: *SchemaRewriteWakeJob = @ptrCast(@alignCast(ptr));
        const alloc = std.heap.page_allocator;
        var pass_count: usize = 0;
        var made_progress = false;
        while (pass_count < self.max_passes) : (pass_count += 1) {
            var pass = (try self.source.schemaRewriteWorkerPass(
                alloc,
                self.table_name,
                self.worker_id,
                self.lease_ms,
                self.max_work_units_per_pass,
            )) orelse return;
            defer pass.deinit(alloc);

            if (pass.complete) {
                try self.promoteCompletedSchemaRewrite();
                return;
            }
            const pass_made_progress = pass.jobs_claimed != 0 or
                pass.jobs_completed != 0 or
                pass.jobs_invalidated != 0;
            if (!pass_made_progress) return;
            made_progress = true;
        }
        if (!made_progress or self.runtime.backend == .manual) return;
        SchemaRewriteWakeJob.submitWithPromotionAndRegistry(
            self.runtime,
            self.owner_id,
            self.source,
            self.table_name,
            self.catalog,
            self.promoted_table,
            self.registry,
            self.table_id,
        ) catch |err| switch (err) {
            error.BackgroundOwnerClosing => return,
            else => return err,
        };
        self.registry = null;
    }

    fn promoteCompletedSchemaRewrite(self: *SchemaRewriteWakeJob) !void {
        const catalog = self.catalog orelse return;
        const promoted_table = self.promoted_table orelse return;
        catalog.compareAndSwapTableSchema(.{
            .table_id = promoted_table.table_id,
            .expected_schema_json = promoted_table.schema_json,
            .promoted_table = promoted_table,
        }) catch |err| switch (err) {
            error.UnsupportedOperation => return,
            else => return err,
        };
    }

    fn deinit(ptr: *anyopaque) void {
        const self: *SchemaRewriteWakeJob = @ptrCast(@alignCast(ptr));
        const alloc = std.heap.page_allocator;
        if (self.registry) |registry| registry.release(self.table_id);
        if (self.promoted_table) |table| metadata_table_manager.freeTable(alloc, table);
        alloc.free(self.table_name);
        alloc.destroy(self);
    }
};

const SchemaRewriteWakeRegistry = struct {
    mutex: std.atomic.Mutex = .unlocked,
    table_ids: std.AutoHashMapUnmanaged(u64, void) = .empty,

    fn deinit(self: *SchemaRewriteWakeRegistry, alloc: std.mem.Allocator) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        self.table_ids.deinit(alloc);
        self.table_ids = .empty;
    }

    fn tryAcquire(self: *SchemaRewriteWakeRegistry, alloc: std.mem.Allocator, table_id: u64) !bool {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const gop = try self.table_ids.getOrPut(alloc, table_id);
        return !gop.found_existing;
    }

    fn release(self: *SchemaRewriteWakeRegistry, table_id: u64) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        _ = self.table_ids.remove(table_id);
    }
};

fn schemaRewriteJobNeedsCatalogCatchup(job: metadata_table_manager.SchemaRewriteJobRecord) bool {
    return std.mem.eql(u8, job.state, metadata_table_manager.schema_rewrite_declared) or
        std.mem.eql(u8, job.state, metadata_table_manager.schema_rewrite_running) or
        std.mem.eql(u8, job.state, metadata_table_manager.schema_rewrite_ready);
}

fn schemaRewriteGenerationHasInvalidJob(
    snapshot: *const metadata_api.AdminSnapshot,
    job: metadata_table_manager.SchemaRewriteJobRecord,
) bool {
    for (snapshot.schema_rewrite_jobs) |candidate| {
        if (candidate.table_id == job.table_id and
            candidate.schema_generation == job.schema_generation and
            std.mem.eql(u8, candidate.state, metadata_table_manager.schema_rewrite_invalid))
        {
            return true;
        }
    }
    return false;
}

fn schemaRewriteSnapshotTableById(
    snapshot: *const metadata_api.AdminSnapshot,
    table_id: u64,
) ?metadata_table_manager.TableRecord {
    for (snapshot.tables) |table| {
        if (table.table_id == table_id) return table;
    }
    return null;
}

fn schemaRewriteCatchupAlreadyScheduled(table_ids: []const u64, table_id: u64) bool {
    for (table_ids) |scheduled_table_id| {
        if (scheduled_table_id == table_id) return true;
    }
    return false;
}

fn droppedRelationalSqlTableRecordAlloc(
    alloc: std.mem.Allocator,
    table: metadata_table_manager.TableRecord,
) !tables_api.AppliedRelationalSqlDdlRecord {
    const dropped = try metadata_table_manager.cloneTable(alloc, table);
    errdefer metadata_table_manager.freeTable(alloc, dropped);
    const work_items = try sql_adapter.appliedDdlTableWorkItemsForFlagsAlloc(alloc, true, true, true);
    errdefer if (work_items.len > 0) {
        for (work_items) |item| {
            var mutable = item;
            mutable.deinit(alloc);
        }
        alloc.free(work_items);
    };
    return .{
        .table = dropped,
        .dropped_table = true,
        .requires_rebuild = true,
        .validation_required = true,
        .rewrite_required = true,
        .work_items = work_items,
    };
}

test "api http server sql ddl drop table record carries catalog work items" {
    const table: metadata_table_manager.TableRecord = .{
        .table_id = 41,
        .name = "events",
        .schema_json =
        \\{"schema":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]},"primary_key":{"fields":["id"]},"relational":true}
        ,
        .indexes_json = "{}",
        .replication_sources_json = "[]",
        .placement_role = "data",
    };

    var dropped = try droppedRelationalSqlTableRecordAlloc(std.testing.allocator, table);
    defer dropped.deinit(std.testing.allocator);

    try std.testing.expect(dropped.dropped_table);
    try std.testing.expect(dropped.requires_rebuild);
    try std.testing.expect(dropped.validation_required);
    try std.testing.expect(dropped.rewrite_required);
    try std.testing.expectEqual(@as(usize, 3), dropped.work_items.len);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkAction.rebuild, dropped.work_items[0].action);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkSubject.table, dropped.work_items[0].subject);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkReason.derived_artifacts, dropped.work_items[0].reason);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkAction.validate, dropped.work_items[1].action);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkSubject.table, dropped.work_items[1].subject);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkReason.constraints, dropped.work_items[1].reason);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkAction.rewrite, dropped.work_items[2].action);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkSubject.table, dropped.work_items[2].subject);
    try std.testing.expectEqual(sql_adapter.AppliedDdlWorkReason.row_images, dropped.work_items[2].reason);
}

test "api http server applies SQL derived index DDL to catalog index metadata" {
    const alloc = std.testing.allocator;
    const FakeService = struct {
        table: metadata_table_manager.TableRecord,
        upsert_count: usize = 0,
        run_round_count: usize = 0,

        fn init(allocator: std.mem.Allocator) !@This() {
            return .{
                .table = try metadata_table_manager.cloneTable(allocator, .{
                    .table_id = 99,
                    .name = "docs",
                    .schema_json = "{\"version\":2,\"storage_mode\":\"relational\",\"document_schemas\":{\"row\":{\"schema\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"keyword\"},\"body\":{\"type\":\"text\"},\"embedding\":{\"type\":\"array\"},\"edge_type\":{\"type\":\"keyword\"}},\"required\":[\"id\"],\"additionalProperties\":false}}},\"primary_key\":{\"columns\":[\"id\"]}}",
                    .indexes_json = "{}",
                    .placement_role = "data",
                }),
            };
        }

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            metadata_table_manager.freeTable(allocator, self.table);
            self.* = undefined;
        }

        pub fn adminSnapshot(self: *@This()) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{self.table})[0..]),
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        pub fn freeAdminSnapshot(_: *@This(), _: *metadata_api.AdminSnapshot) void {}

        pub fn upsertTable(self: *@This(), record: metadata_table_manager.TableRecord) !void {
            const owned = try metadata_table_manager.cloneTable(std.testing.allocator, record);
            metadata_table_manager.freeTable(std.testing.allocator, self.table);
            self.table = owned;
            self.upsert_count += 1;
        }

        pub fn runRound(self: *@This()) !void {
            self.run_round_count += 1;
        }

        pub fn proposeTransitionCommand(_: *@This(), _: anytype) !void {}
    };

    var service = try FakeService.init(alloc);
    defer service.deinit(alloc);

    const TestPlans = struct {
        fn tableDdlPlanAlloc(allocator: std.mem.Allocator, sql: []const u8) !sql_adapter.TableDdlLogicalPlan {
            var parsed_sql = try sql_adapter.ParsedSql.initAlloc(allocator, sql);
            defer parsed_sql.deinit(allocator);
            var logical_plan = try sql_adapter.planDdlLogicalPlanParsedSqlWithFunctionBindingsAlloc(allocator, &parsed_sql, .{});
            errdefer logical_plan.deinit(allocator);
            return switch (logical_plan) {
                .table_ddl => |plan| blk: {
                    logical_plan = .{ .other_ddl = .{ .moved = {} } };
                    break :blk plan;
                },
                else => error.UnsupportedSqlShape,
            };
        }
    };

    const full_text_sql = "CREATE INDEX docs_body_fts ON docs USING antfly_full_text (body) WITH (analyzer = 'standard');";
    var full_text_plan = try TestPlans.tableDdlPlanAlloc(alloc, full_text_sql);
    defer full_text_plan.deinit(alloc);
    var full_text_target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(
        alloc,
        full_text_plan,
        catalog_resources.SqlCatalogSession.default(),
    );
    defer full_text_target.deinit(alloc);
    var full_text = (try tables_api.applyRelationalDerivedIndexTablePlanOnServiceAlloc(
        alloc,
        &service,
        &service.table,
        full_text_target,
        full_text_plan,
    )).?;
    defer full_text.deinit(alloc);
    try std.testing.expect(full_text.requires_rebuild);
    try std.testing.expect(std.mem.indexOf(u8, full_text.table.indexes_json, "\"docs_body_fts\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, full_text.table.indexes_json, "\"type\":\"full_text\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, service.table.indexes_json, "\"field\":\"body\"") != null);

    const vector_sql = "CREATE INDEX docs_embedding_hnsw ON docs USING hnsw (embedding vector_l2_ops) WITH (dimension = 3);";
    var vector_plan = try TestPlans.tableDdlPlanAlloc(alloc, vector_sql);
    defer vector_plan.deinit(alloc);
    var vector_target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(
        alloc,
        vector_plan,
        catalog_resources.SqlCatalogSession.default(),
    );
    defer vector_target.deinit(alloc);
    var vector = (try tables_api.applyRelationalDerivedIndexTablePlanOnServiceAlloc(
        alloc,
        &service,
        &service.table,
        vector_target,
        vector_plan,
    )).?;
    defer vector.deinit(alloc);
    try std.testing.expect(vector.requires_rebuild);
    try std.testing.expect(std.mem.indexOf(u8, vector.table.indexes_json, "\"docs_embedding_hnsw\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, vector.table.indexes_json, "\"type\":\"embeddings\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, vector.table.indexes_json, "\"external\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, vector.table.indexes_json, "\"metric\":\"l2_squared\"") != null);

    const aknn_sql = "CREATE INDEX docs_body_semantic ON docs USING antfly_aknn (body) WITH (embedding_name = 'body_embedding_v1', model = 'local-model', dimension = 384);";
    var aknn_plan = try TestPlans.tableDdlPlanAlloc(alloc, aknn_sql);
    defer aknn_plan.deinit(alloc);
    var aknn_target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(
