test "api http server wakes durable schema rewrite worker after SQL ALTER rewrite DDL" {
    const alloc = std.testing.allocator;

    var runtime = try db_mod.background_runtime.BackendRuntimeHandle.init(alloc, .{ .backend = .manual });
    defer runtime.deinit();

    const FakeSource = struct {
        apply_count: usize = 0,
        compare_count: usize = 0,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                    .compare_and_swap_table_schema = compareAndSwapTableSchema,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            _ = plan;
            _ = session;
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.apply_count += 1;

            const table = try metadata_table_manager.cloneTable(allocator, .{
                .table_id = 88,
                .name = "audit_log",
                .database_name = catalog_resources.default_database_name,
                .namespace_name = catalog_resources.default_namespace_name,
                .schema_json = "{\"version\":2,\"storage_mode\":\"relational\"}",
                .indexes_json = "{}",
                .replication_sources_json = "[]",
                .placement_role = "data",
            });
            errdefer metadata_table_manager.freeTable(allocator, table);
            const work_items = try allocator.alloc(sql_adapter.AppliedDdlWorkItem, 1);
            errdefer allocator.free(work_items);
            const target_column = try allocator.dupe(u8, "amount");
            errdefer allocator.free(target_column);
            const rewrite_expression = try runtime_schema_mod.cloneRelationalRowsExpressionAlloc(allocator, .{
                .kind = .value,
                .value_json = "0",
            });
            errdefer runtime_schema_mod.freeRelationalRowsExpression(allocator, rewrite_expression);
            work_items[0] = .{
                .action = .rewrite,
                .subject = .table,
                .reason = .row_images,
                .rewrite_expression = .{
                    .target_column = target_column,
                    .expression = rewrite_expression,
                },
            };
            return .{
                .table = table,
                .rewrite_required = true,
                .work_items = work_items,
            };
        }

        fn compareAndSwapTableSchema(
            ptr: *anyopaque,
            request: metadata_table_manager.TableSchemaCompareAndSwapRequest,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.compare_count += 1;
            try std.testing.expectEqual(@as(u64, 88), request.table_id);
            try std.testing.expectEqual(@as(u64, 88), request.promoted_table.table_id);
            try std.testing.expectEqualStrings("audit_log", request.promoted_table.name);
            try std.testing.expectEqualStrings(request.promoted_table.schema_json, request.expected_schema_json);
            try std.testing.expect(std.mem.indexOf(u8, request.promoted_table.schema_json, "\"storage_mode\":\"relational\"") != null);
        }
    };

    const FakeWrites = struct {
        pass_count: usize = 0,
        last_table_name_buf: [128]u8 = undefined,
        last_table_name_len: usize = 0,
        last_worker_id_buf: [128]u8 = undefined,
        last_worker_id_len: usize = 0,

        fn iface(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .schema_rewrite_worker_pass = schemaRewriteWorkerPass,
                },
            };
        }

        fn batch(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) !?void {
            return error.TestUnexpectedResult;
        }

        fn schemaRewriteWorkerPass(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            table_name: []const u8,
            worker_id: []const u8,
            lease_ms: u64,
            max_work_units: usize,
        ) !?table_writes.SchemaRewriteWorkerPassResult {
            _ = allocator;
            if (lease_ms == 0 or max_work_units == 0) return error.TestUnexpectedResult;
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.pass_count += 1;
            if (table_name.len > self.last_table_name_buf.len or worker_id.len > self.last_worker_id_buf.len) return error.TestUnexpectedResult;
            @memcpy(self.last_table_name_buf[0..table_name.len], table_name);
            self.last_table_name_len = table_name.len;
            @memcpy(self.last_worker_id_buf[0..worker_id.len], worker_id);
            self.last_worker_id_len = worker_id.len;
            return .{
                .complete = self.pass_count >= 2,
                .jobs_scanned = 1,
                .jobs_claimed = 1,
                .jobs_completed = 1,
            };
        }
    };

    var source = FakeSource{};
    var writes = FakeWrites{};
    var server = try ApiHttpServer.initWithConfig(
        alloc,
        .{ .backend_runtime = runtime.ptr() },
        source.iface(),
        null,
        writes.iface(),
    );
    defer server.deinit();

    var applied = try server.applyRelationalSqlDdl("ALTER TABLE audit_log ALTER COLUMN amount TYPE numeric USING amount + 1;");
    defer applied.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), source.apply_count);
    try std.testing.expectEqual(@as(usize, 1), source.compare_count);
    try std.testing.expectEqual(@as(usize, 2), writes.pass_count);
    try std.testing.expectEqualStrings("audit_log", writes.last_table_name_buf[0..writes.last_table_name_len]);
    try std.testing.expectEqualStrings("api-schema-rewrite", writes.last_worker_id_buf[0..writes.last_worker_id_len]);
}

