test "api schema rewrite catalog catch-up dedupes in-flight table wakes" {
    const alloc = std.testing.allocator;

    var runtime = try db_mod.background_runtime.BackendRuntimeHandle.init(alloc, .{ .backend = .io_threaded });
    defer runtime.deinit();

    const FakeSource = struct {
        snapshot_count: std.atomic.Value(u32) = .init(0),
        compare_count: std.atomic.Value(u32) = .init(0),
        table: metadata_table_manager.TableRecord = .{
            .table_id = 88,
            .name = "audit_log",
            .database_name = catalog_resources.default_database_name,
            .namespace_name = catalog_resources.default_namespace_name,
            .schema_json = "{\"version\":2,\"storage_mode\":\"relational\"}",
            .indexes_json = "{}",
            .replication_sources_json = "[]",
            .placement_role = "data",
        },
        job: metadata_table_manager.SchemaRewriteJobRecord = .{
            .job_id = 1,
            .table_id = 88,
            .group_id = 100,
            .schema_generation = 2,
            .action = "rewrite",
            .reason = "row_images",
            .start_row_key = "",
            .state = metadata_table_manager.schema_rewrite_ready,
        },

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .compare_and_swap_table_schema = compareAndSwapTableSchema,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.snapshot_count.fetchAdd(1, .monotonic);
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @as([*]metadata_table_manager.TableRecord, @ptrCast(&self.table))[0..1],
                .ranges = &.{},
                .schema_rewrite_jobs = @as([*]metadata_table_manager.SchemaRewriteJobRecord, @ptrCast(&self.job))[0..1],
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn compareAndSwapTableSchema(
            ptr: *anyopaque,
            request: metadata_table_manager.TableSchemaCompareAndSwapRequest,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.compare_count.fetchAdd(1, .monotonic);
            try std.testing.expectEqual(@as(u64, 88), request.table_id);
            try std.testing.expectEqualStrings("audit_log", request.promoted_table.name);
        }
    };

    const FakeWrites = struct {
        allow_finish: std.atomic.Value(bool) = .init(false),
        pass_count: std.atomic.Value(u32) = .init(0),

        fn iface(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .schema_rewrite_worker_pass = schemaRewriteWorkerPass,
                },
            };
        }

        fn batch(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) !?void {
            return error.TestUnexpectedResult;
        }

        fn schemaRewriteWorkerPass(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            table_name: []const u8,
            worker_id: []const u8,
            lease_ms: u64,
            max_work_units: usize,
        ) !?table_writes.SchemaRewriteWorkerPassResult {
            if (!std.mem.eql(u8, table_name, "audit_log")) return error.TestUnexpectedResult;
            if (!std.mem.eql(u8, worker_id, "api-schema-rewrite")) return error.TestUnexpectedResult;
            if (lease_ms == 0 or max_work_units == 0) return error.TestUnexpectedResult;
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self.pass_count.fetchAdd(1, .monotonic);
            while (!self.allow_finish.load(.acquire)) {
                std.atomic.spinLoopHint();
            }
            return .{
                .complete = true,
                .jobs_scanned = 1,
                .jobs_completed = 1,
            };
        }
    };

    var source = FakeSource{};
    var writes = FakeWrites{};
    var server = try ApiHttpServer.initWithConfig(
        alloc,
        .{ .backend_runtime = runtime.ptr() },
        source.iface(),
        null,
        writes.iface(),
    );
    defer server.deinit();

    try std.testing.expectEqual(@as(usize, 1), try server.runSchemaRewriteCatalogCatchupOnce());
    try std.testing.expectEqual(@as(usize, 0), try server.runSchemaRewriteCatalogCatchupOnce());

    writes.allow_finish.store(true, .release);
    runtime.ptr().durable_jobs.drainOwner(server.schema_rewrite_wake_owner_id);

    try std.testing.expectEqual(@as(u32, 2), source.snapshot_count.load(.monotonic));
    try std.testing.expectEqual(@as(u32, 1), writes.pass_count.load(.monotonic));
    try std.testing.expectEqual(@as(u32, 1), source.compare_count.load(.monotonic));
}

test "api http server applies SQL ALTER COLUMN USING through durable schema rewrite jobs" {
    const alloc = std.testing.allocator;
    const initial_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const FakeService = struct {
        table: metadata_table_manager.TableRecord = .{
            .table_id = 88,
            .name = "audit_log",
            .database_name = catalog_resources.default_database_name,
            .namespace_name = catalog_resources.default_namespace_name,
            .schema_json = initial_schema_json,
            .indexes_json = "{}",
            .replication_sources_json = "[]",
            .placement_role = "data",
        },
        table_owned: bool = false,
        ranges: [2]metadata_table_manager.RangeRecord = .{
            .{ .group_id = 9901, .range_id = 9911, .table_id = 88, .start_key = "", .end_key = "n" },
            .{ .group_id = 9902, .range_id = 9912, .table_id = 88, .start_key = "n", .end_key = null },
        },
        jobs: std.ArrayListUnmanaged(metadata_table_manager.SchemaRewriteJobRecord) = .empty,
        upsert_table_count: usize = 0,
        run_round_count: usize = 0,

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.table_owned) metadata_table_manager.freeTable(allocator, self.table);
            for (self.jobs.items) |record| metadata_table_manager.freeSchemaRewriteJob(allocator, record);
            self.jobs.deinit(allocator);
            self.* = undefined;
        }

        fn tableSlice(self: *@This()) []metadata_table_manager.TableRecord {
            return @as([*]metadata_table_manager.TableRecord, @ptrCast(&self.table))[0..1];
        }

        pub fn adminSnapshot(self: *@This()) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = self.tableSlice(),
                .ranges = self.ranges[0..],
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        pub fn freeAdminSnapshot(_: *@This(), _: *metadata_api.AdminSnapshot) void {}

        pub fn upsertTable(self: *@This(), record: metadata_table_manager.TableRecord) !void {
            const cloned = try metadata_table_manager.cloneTable(std.testing.allocator, record);
            if (self.table_owned) metadata_table_manager.freeTable(std.testing.allocator, self.table);
            self.table = cloned;
            self.table_owned = true;
            self.upsert_table_count += 1;
        }

        pub fn upsertSchemaRewriteJob(self: *@This(), record: metadata_table_manager.SchemaRewriteJobRecord) !void {
            const owned = try metadata_table_manager.cloneSchemaRewriteJob(std.testing.allocator, record);
            errdefer metadata_table_manager.freeSchemaRewriteJob(std.testing.allocator, owned);
            for (self.jobs.items) |*existing| {
                if (existing.job_id != record.job_id) continue;
                metadata_table_manager.freeSchemaRewriteJob(std.testing.allocator, existing.*);
                existing.* = owned;
                return;
            }
            try self.jobs.append(std.testing.allocator, owned);
        }

        pub fn runRound(self: *@This()) !void {
            self.run_round_count += 1;
        }
    };

    var service = FakeService{};
    defer service.deinit(alloc);

    var snapshot = try service.adminSnapshot();
    defer service.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByQualifiedName(
        &snapshot,
        catalog_resources.default_database_name,
        catalog_resources.default_namespace_name,
        "audit_log",
    ) orelse return error.TestUnexpectedResult;
    var applied = try tables_api.applyRelationalSqlDdlToTableRecordWithSessionAlloc(
        alloc,
        table,
        "ALTER TABLE audit_log ALTER COLUMN amount TYPE numeric USING amount + 1;",
        catalog_resources.SqlCatalogSession.default(),
    );
    defer applied.deinit(alloc);
    try service.upsertTable(applied.table);
    try catalog_jobs.scheduleSchemaRewriteJobsForAppliedDdlOnService(&service, alloc, applied);
    try catalog_jobs.scheduleSchemaRewriteJobsForAppliedDdlOnService(&service, alloc, applied);
    try service.runRound();

    try std.testing.expect(applied.rewrite_required);
    try std.testing.expectEqual(@as(usize, 1), service.upsert_table_count);
    try std.testing.expectEqual(@as(usize, 1), service.run_round_count);
    try std.testing.expectEqual(@as(usize, 4), service.jobs.items.len);

    var rewrite_count: usize = 0;
    var validate_count: usize = 0;
    var first_rewrite: ?*const metadata_table_manager.SchemaRewriteJobRecord = null;
    var second_rewrite: ?*const metadata_table_manager.SchemaRewriteJobRecord = null;
    for (service.jobs.items) |*job| {
        if (std.mem.eql(u8, job.action, "rewrite") and std.mem.eql(u8, job.reason, "row_images")) {
            rewrite_count += 1;
            if (job.group_id == 9901) first_rewrite = job;
            if (job.group_id == 9902) second_rewrite = job;
        } else if (std.mem.eql(u8, job.action, "validate") and std.mem.eql(u8, job.reason, "constraints")) {
            validate_count += 1;
            try std.testing.expect(job.expression == null);
            try std.testing.expectEqualStrings("", job.target_column);
        } else {
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expectEqual(@as(usize, 2), rewrite_count);
    try std.testing.expectEqual(@as(usize, 2), validate_count);

    const first = first_rewrite orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 88), first.table_id);
    try std.testing.expectEqual(@as(u64, 9901), first.group_id);
    try std.testing.expectEqualStrings("", first.start_row_key);
    try std.testing.expectEqualStrings("n", first.end_row_key.?);
    try std.testing.expectEqualStrings("rewrite", first.action);
    try std.testing.expectEqualStrings("row_images", first.reason);
    try std.testing.expectEqualStrings("amount", first.target_column);
    const expression = first.expression orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(runtime_schema_mod.RelationalRowsExpressionKind.add, expression.kind);
    try std.testing.expectEqual(@as(usize, 2), expression.operands.len);
    try std.testing.expectEqualStrings("amount", expression.operands[0].field);
    try std.testing.expectEqualStrings("1", expression.operands[1].value_json);

    const second = second_rewrite orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u64, 9902), second.group_id);
    try std.testing.expectEqualStrings("n", second.start_row_key);
    try std.testing.expect(second.end_row_key == null);
}

fn applyDatabaseCatalogPlanOnService(
    svc: anytype,
    alloc: std.mem.Allocator,
    plan: sql_adapter.DatabaseCatalogPlan,
) !tables_api.AppliedRelationalSqlDdlRecord {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    var applied = try tables_api.applyDatabaseCatalogPlanOnServiceAlloc(alloc, svc, &snapshot, plan);
    errdefer applied.deinit(alloc);
    try svc.runRound();
    return applied;
}

fn applyTablespaceCatalogPlanOnService(
    svc: anytype,
    alloc: std.mem.Allocator,
    plan: sql_adapter.TablespaceCatalogPlan,
) !tables_api.AppliedRelationalSqlDdlRecord {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    var applied = try tables_api.applyTablespaceCatalogPlanOnServiceAlloc(alloc, svc, &snapshot, plan);
    errdefer applied.deinit(alloc);
    try svc.runRound();
    return applied;
}

fn applyRelationalDropTableCascadeReferences(
    svc: anytype,
    alloc: std.mem.Allocator,
    snapshot: *const metadata_api.AdminSnapshot,
    target_table: metadata_table_manager.TableRecord,
) !void {
    for (snapshot.tables) |candidate_table| {
        if (candidate_table.table_id == target_table.table_id) continue;
        const next_schema_json = (try tables_api.schemaWithoutForeignKeysReferencingTableAlloc(
            alloc,
            candidate_table.schema_json,
            target_table.name,
        )) orelse continue;
        defer alloc.free(next_schema_json);

        const updated = try tables_api.applySchemaUpdateRecord(alloc, &candidate_table, next_schema_json);
        defer metadata_table_manager.freeTable(alloc, updated);
        try svc.upsertTable(updated);
    }
}

fn createIndexOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8, index_json: []const u8) !void {
    return try createCatalogIndexOnService(svc, alloc, .{
        .database_name = tables_api.default_database_name,
        .namespace_name = tables_api.default_namespace_name,
        .table_name = table_name,
    }, index_name, index_json);
}

fn createCatalogIndexOnService(svc: anytype, alloc: std.mem.Allocator, target: catalog_resources.TableTarget, index_name: []const u8, index_json: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;
    if (extensionOwnsIndex(&snapshot, target.table_name, index_name)) return error.ExtensionOwnedObject;
    try tables_api.validateDerivedIndexFieldRefsForSchemaAlloc(alloc, index_json, table.schema_json);
    const expanded_index_json = try tables_api.expandSchemaDerivedAlgebraicIndexAlloc(alloc, target.table_name, index_json, table.schema_json);
    defer alloc.free(expanded_index_json);

    var updated_record = table.*;
    updated_record.indexes_json = try indexes_api.addIndexToTableIndexesJson(alloc, table.indexes_json, index_name, expanded_index_json);
    defer alloc.free(updated_record.indexes_json);
    try svc.upsertTable(updated_record);
    try svc.runRound();
}

fn dropIndexOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8) !void {
    return try dropCatalogIndexOnService(svc, alloc, .{
        .database_name = tables_api.default_database_name,
        .namespace_name = tables_api.default_namespace_name,
        .table_name = table_name,
    }, index_name);
}

fn dropCatalogIndexOnService(svc: anytype, alloc: std.mem.Allocator, target: catalog_resources.TableTarget, index_name: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;
    if (extensionOwnsIndex(&snapshot, target.table_name, index_name)) return error.ExtensionOwnedObject;

    const indexes_json = (try indexes_api.removeIndexFromTableIndexesJson(alloc, table.indexes_json, index_name)) orelse return error.IndexNotFound;
    defer alloc.free(indexes_json);
    var updated_record = table.*;
    updated_record.indexes_json = indexes_json;
    try svc.upsertTable(updated_record);
    try svc.runRound();
}

fn putArtifactEnrichmentOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8, enrichment_json: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsEnrichment(&snapshot, table_name, artifact_name)) return error.ExtensionOwnedObject;

    var updated_record = table.*;
    updated_record.indexes_json = try indexes_api.addEnrichmentToTableIndexesJson(alloc, table.indexes_json, artifact_name, enrichment_json);
    defer alloc.free(updated_record.indexes_json);
    try indexes_api.validateArtifactEnrichmentsForTableIndexesJson(alloc, updated_record.indexes_json);
    try svc.upsertTable(updated_record);
    try svc.runRound();
}

fn deleteArtifactEnrichmentOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsEnrichment(&snapshot, table_name, artifact_name)) return error.ExtensionOwnedObject;

    const indexes_json = (try indexes_api.removeEnrichmentFromTableIndexesJson(alloc, table.indexes_json, artifact_name)) orelse return error.EnrichmentNotFound;
    defer alloc.free(indexes_json);
    try indexes_api.validateArtifactEnrichmentsForTableIndexesJson(alloc, indexes_json);
    var updated_record = table.*;
    updated_record.indexes_json = indexes_json;
    try svc.upsertTable(updated_record);
    try svc.runRound();
}

fn serviceSecretStore(service: anytype) ?*common_secrets.FileStore {
    const Ptr = @TypeOf(service);
    const Service = std.meta.Child(Ptr);
    if (comptime @hasField(Service, "secret_store")) {
        return service.secret_store;
    }
    return null;
}

fn persistRestoreTableIntent(service: anytype, alloc: std.mem.Allocator, table_name: []const u8, location_uri: []const u8, backup_id: []const u8, secret_store: ?*common_secrets.FileStore) !void {
    var snapshot = try service.adminSnapshot();
    defer service.freeAdminSnapshot(&snapshot);
    if (tables_api.findTableByName(&snapshot, table_name) != null) return error.TableAlreadyExists;

    var spec = try loadRestoreMetadataSpec(alloc, table_name, location_uri, backup_id, secret_store);
    defer spec.deinit(alloc);

    var workflow = metadata_table_workflow.TableWorkflow.init(alloc);
    defer workflow.deinit();
    _ = try workflow.createTableWithRanges(service, spec.table, spec.ranges);
}

