    alloc: std.mem.Allocator,
    cfg: ApiHttpServerConfig,
    source: StatusSource,
    table_reads: ?table_reads.TableReadSource = null,
    external_lake_configured_resolver: table_reads.ConfiguredExternalLakeObjectStoreResolver = .{},
    external_lake_routing_reads: ?table_reads.ExternalLakeRoutingTableReadSource = null,
    table_writes: ?table_writes.TableWriteSource = null,
    antfly_provider: ?managed_embedder.AntflyProvider = null,
    foreign_registry: ?*const foreign_mod.Registry = null,
    owned_foreign_registry: ?*foreign_mod.Registry = null,
    txn_sessions: transactions_api.SessionRegistry = .{},
    last_session_cleanup_ns: u64 = 0,
    last_session_lease_renew_ns: u64 = 0,
    created_at_ns: u64 = 0,
    request_count: std.atomic.Value(u64) = .init(0),
    first_request_started_at_ns: std.atomic.Value(u64) = .init(0),
    opened_session_store: ?*transactions_api.OpenedSessionStore = null,
    join_job_store: distributed_join.JoinJobStore = .{ .alloc = undefined, .cfg = .{} },
    artifact_reprocess_job_store: artifact_reprocess_jobs.Store = .{ .alloc = undefined, .cfg = .{} },
    sql_notification_runtime: sql_notifications.Runtime = .{ .alloc = undefined },
    sql_catalog_session_runtime: SqlCatalogSessionRuntime = .{ .alloc = undefined },
    sql_prepared_statement_runtime: SqlPreparedStatementRuntime = .{ .alloc = undefined },
    sql_routine_runtime: sql_routines.Runtime = .{ .alloc = undefined },
    schema_rewrite_wake_owner_id: u64 = 0,
    schema_rewrite_wake_registry: SchemaRewriteWakeRegistry = .{},
    mcp_sessions: mcp.InMemorySessionStore = .{},
    a2a_tasks: a2a.InMemoryTaskStore = .{},
    connections_cache: connections_api.Cache = .{ .alloc = undefined },

    pub const RequestStats = struct {
        request_count: u64 = 0,
        first_request_started_at_ns: u64 = 0,
        first_request_elapsed_ms: u64 = 0,
    };

    pub const BulkSqlExecutionResult = union(enum) {
        import_rows: relational_rows_api.OwnedRowsBatchRequest,
        export_stdout: []u8,
        export_file: void,

        pub fn deinit(self: *@This(), alloc_arg: std.mem.Allocator) void {
            switch (self.*) {
                .import_rows => |*rows| rows.deinit(alloc_arg),
                .export_stdout => |payload| alloc_arg.free(payload),
                .export_file => {},
            }
            self.* = undefined;
        }
    };

    const SqlPreparedStatementRuntime = struct {
        alloc: std.mem.Allocator,
        sessions: std.AutoHashMapUnmanaged(u64, Session) = .empty,

        const Session = struct {
            statements: std.StringHashMapUnmanaged(Record) = .empty,

            fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
                var it = self.statements.iterator();
                while (it.next()) |entry| alloc.free(entry.key_ptr.*);
                self.statements.deinit(alloc);
                self.* = undefined;
            }

            fn clear(self: *@This(), alloc: std.mem.Allocator) void {
                var it = self.statements.iterator();
                while (it.next()) |entry| alloc.free(entry.key_ptr.*);
                self.statements.clearRetainingCapacity();
            }
        };

        const Record = struct {
            parameter_count: usize,
            statement_kind: sql_adapter.PreparedStatementSubjectKind,
            statement_family: sql_adapter.PreparedStatementStatementKind,
        };

        fn init(alloc: std.mem.Allocator) SqlPreparedStatementRuntime {
            return .{ .alloc = alloc };
        }

        fn deinit(self: *@This()) void {
            var it = self.sessions.iterator();
            while (it.next()) |entry| entry.value_ptr.deinit(self.alloc);
            self.sessions.deinit(self.alloc);
            self.* = undefined;
        }

        fn apply(self: *@This(), plan: sql_adapter.PreparedStatementPlan, session_id: u64) !void {
            if (session_id == 0) return error.InvalidSqlSession;
            switch (plan) {
                .prepare => |prepare_plan| try self.prepare(session_id, prepare_plan),
                .execute => |execute_plan| try self.execute(session_id, execute_plan),
                .deallocate => |deallocate_plan| try self.deallocate(session_id, deallocate_plan),
            }
        }

        fn prepare(
            self: *@This(),
            session_id: u64,
            plan: sql_adapter.PrepareStatementPlan,
        ) !void {
            const result = try self.sessions.getOrPut(self.alloc, session_id);
            if (!result.found_existing) result.value_ptr.* = .{};
            const session = result.value_ptr;
            if (session.statements.contains(plan.statement_name)) return error.PreparedStatementAlreadyExists;
            const key = try self.alloc.dupe(u8, plan.statement_name);
            errdefer self.alloc.free(key);
            try session.statements.put(self.alloc, key, .{
                .parameter_count = plan.parameter_count,
                .statement_kind = plan.statement_kind,
                .statement_family = plan.statement_family,
            });
        }

        fn execute(
            self: *@This(),
            session_id: u64,
            plan: sql_adapter.ExecutePreparedStatementPlan,
        ) !void {
            _ = try self.executeRecord(session_id, plan);
        }

        fn executeRecord(
            self: *@This(),
            session_id: u64,
            plan: sql_adapter.ExecutePreparedStatementPlan,
        ) !Record {
            const session = self.sessions.getPtr(session_id) orelse return error.PreparedStatementNotFound;
            const record = session.statements.get(plan.statement_name) orelse return error.PreparedStatementNotFound;
            if (record.parameter_count != plan.argument_count) return error.PreparedStatementArgumentMismatch;
            return record;
        }

        fn statementKindForExecute(
            self: *@This(),
            session_id: u64,
            plan: sql_adapter.ExecutePreparedStatementPlan,
        ) !sql_adapter.PreparedStatementSubjectKind {
            return (try self.executeRecord(session_id, plan)).statement_kind;
        }

        fn deallocate(
            self: *@This(),
            session_id: u64,
            plan: sql_adapter.DeallocatePreparedStatementPlan,
        ) !void {
            const session = self.sessions.getPtr(session_id) orelse {
                if (plan.all) return;
                return error.PreparedStatementNotFound;
            };
            if (plan.all) {
                session.clear(self.alloc);
                return;
            }
            const name = plan.statement_name orelse return error.UnsupportedSqlShape;
            if (session.statements.fetchRemove(name)) |removed| {
                self.alloc.free(removed.key);
                return;
            }
            return error.PreparedStatementNotFound;
        }

        fn statementCountForTest(self: *@This(), session_id: u64) usize {
            const session = self.sessions.getPtr(session_id) orelse return 0;
            return session.statements.count();
        }
    };

    const SqlCatalogSessionRuntime = struct {
        alloc: std.mem.Allocator,
        sessions: std.AutoHashMapUnmanaged(u64, sql_adapter.OwnedSqlCatalogSession) = .empty,

        fn init(alloc: std.mem.Allocator) SqlCatalogSessionRuntime {
            return .{ .alloc = alloc };
        }

        fn deinit(self: *@This()) void {
            var it = self.sessions.iterator();
            while (it.next()) |entry| entry.value_ptr.deinit(self.alloc);
            self.sessions.deinit(self.alloc);
            self.* = undefined;
        }

        fn loadAlloc(self: *@This(), session_id: ?u64) !sql_adapter.OwnedSqlCatalogSession {
            if (session_id) |id| {
                if (self.sessions.getPtr(id)) |stored| {
                    var session = try stored.cloneAlloc(self.alloc);
                    session.request_read_only = false;
                    session.notification_session_id = id;
                    return session;
                }
            }
            var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(self.alloc, catalog_resources.SqlCatalogSession.default());
            if (session_id) |id| session.notification_session_id = id;
            return session;
        }

        fn save(self: *@This(), session: sql_adapter.OwnedSqlCatalogSession) !void {
            if (session.notification_session_id == 0) return;
            var stored = try session.cloneAlloc(self.alloc);
            errdefer stored.deinit(self.alloc);
            stored.notification_session_id = session.notification_session_id;
            stored.restoreRequestOverridesForPersistence(self.alloc);
            if (!self.sessionHasPersistentCatalogState(stored)) {
                if (self.sessions.fetchRemove(session.notification_session_id)) |old| {
                    var old_value = old.value;
                    old_value.deinit(self.alloc);
                }
                stored.deinit(self.alloc);
                return;
            }
            if (try self.sessions.fetchPut(self.alloc, session.notification_session_id, stored)) |old| {
                var old_value = old.value;
                old_value.deinit(self.alloc);
            }
        }

        fn sessionHasPersistentCatalogState(_: *@This(), session: sql_adapter.OwnedSqlCatalogSession) bool {
            if (session.in_sql_transaction) return true;
            if (session.sql_transaction_failed) return true;
            if (session.settings.len > 0) return true;
            if (session.transaction_local_settings_base != null) return true;
            if (session.transaction_local_search_path_base != null) return true;
            if (!std.ascii.eqlIgnoreCase(session.current_database_name, catalog_resources.default_database_name)) return true;
            if (session.search_path.len != 1 or !std.ascii.eqlIgnoreCase(session.search_path[0], catalog_resources.default_namespace_name)) return true;
            return false;
        }

        fn sessionCountForTest(self: *@This()) usize {
            return self.sessions.count();
        }
    };

    pub fn init(
        alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) ApiHttpServer {
        return .{
            .alloc = alloc,
            .cfg = cfg,
            .source = source,
            .table_reads = table_read_source,
            .table_writes = table_write_source,
            .foreign_registry = cfg.foreign_registry,
            .created_at_ns = platform_time.monotonicNs(),
            .txn_sessions = transactions_api.SessionRegistry.initWithOptions(
                cfg.session_store,
                if (cfg.session_store != null and cfg.session_owner_lease_ttl_ns != null)
                    transactions_api.SessionLeaseStore.init(alloc, cfg.session_store.?.store)
                else
                    null,
                cfg.session_owner_lease_ttl_ns,
                cfg.session_savepoint_limit,
            ),
            .join_job_store = distributed_join.JoinJobStore.init(alloc, .{
                .join_job_store_path = cfg.join_job_store_path,
                .join_job_lease_ttl_ms = cfg.join_job_lease_ttl_ms,
                .join_job_retention_ms = cfg.join_job_retention_ms,
            }),
            .artifact_reprocess_job_store = artifact_reprocess_jobs.Store.init(alloc, .{
                .artifact_reprocess_job_store_path = cfg.artifact_reprocess_job_store_path,
                .artifact_reprocess_job_retention_ms = cfg.artifact_reprocess_job_retention_ms,
            }),
            .sql_notification_runtime = sql_notifications.Runtime.init(alloc),
            .sql_catalog_session_runtime = SqlCatalogSessionRuntime.init(alloc),
            .sql_prepared_statement_runtime = SqlPreparedStatementRuntime.init(alloc),
            .sql_routine_runtime = sql_routines.Runtime.init(alloc),
            .connections_cache = connections_api.Cache.init(alloc),
            .mcp_sessions = mcp.InMemorySessionStore.init(alloc),
            .a2a_tasks = a2a.InMemoryTaskStore.init(alloc),
        };
    }

    pub fn requestStats(self: *const ApiHttpServer) RequestStats {
        const request_count = self.request_count.load(.monotonic);
        const first_request_started_at_ns = self.first_request_started_at_ns.load(.monotonic);
        return .{
            .request_count = request_count,
            .first_request_started_at_ns = first_request_started_at_ns,
            .first_request_elapsed_ms = if (first_request_started_at_ns == 0 or first_request_started_at_ns < self.created_at_ns)
                0
            else
                @intCast(@divTrunc(first_request_started_at_ns - self.created_at_ns, std.time.ns_per_ms)),
        };
    }

    fn effectivePublicTableReads(self: *ApiHttpServer) ?table_reads.TableReadSource {
        const base = self.table_reads orelse return null;
        if (self.external_lake_routing_reads == null) {
            self.external_lake_configured_resolver.configure(self.cfg.node_config, self.cfg.secret_store);
            const resolver = self.cfg.external_lake_object_store_resolver orelse self.external_lake_configured_resolver.resolver();
            self.external_lake_routing_reads = table_reads.ExternalLakeRoutingTableReadSource.init(base, resolver, self.externalLakeRowsSourceOptions());
        }
        return self.external_lake_routing_reads.?.source();
    }

