    pub fn initWithConfig(
        alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) !ApiHttpServer {
        var effective_cfg = cfg;
        var server = ApiHttpServer.init(alloc, effective_cfg, source, table_read_source, table_write_source);
        if (cfg.session_store_path) |path| {
            if (cfg.session_store != null) return error.InvalidApiServerConfig;
            const opened = try alloc.create(transactions_api.OpenedSessionStore);
            errdefer alloc.destroy(opened);
            opened.* = try transactions_api.OpenedSessionStore.open(alloc, path);
            server.opened_session_store = opened;
            effective_cfg.session_store = opened.durableStore();
            server.cfg = effective_cfg;
            server.txn_sessions = transactions_api.SessionRegistry.initWithOptions(
                effective_cfg.session_store,
                opened.leaseStore().*,
                effective_cfg.session_owner_lease_ttl_ns,
                effective_cfg.session_savepoint_limit,
            );
        }
        if (cfg.join_job_store_path orelse cfg.session_store_path) |base_path| {
            const join_job_path = if (cfg.join_job_store_path != null)
                try alloc.dupe(u8, base_path)
            else
                try std.fmt.allocPrint(alloc, "{s}.join_jobs", .{base_path});
            defer alloc.free(join_job_path);
            const opened = try alloc.create(distributed_join.OpenedJoinJobStore);
            errdefer alloc.destroy(opened);
            opened.* = try distributed_join.OpenedJoinJobStore.open(alloc, join_job_path);
            server.join_job_store.opened_join_job_store = opened;
        }
        if (cfg.artifact_reprocess_job_store_path) |path| {
            const opened = try alloc.create(artifact_reprocess_jobs.OpenedStore);
            errdefer alloc.destroy(opened);
            opened.* = try artifact_reprocess_jobs.OpenedStore.open(alloc, path);
            errdefer opened.deinit();
            try server.artifact_reprocess_job_store.attachOpenedStore(opened);
        }
        if (cfg.sql_routine_store_path orelse cfg.session_store_path) |base_path| {
            const routine_path = if (cfg.sql_routine_store_path != null)
                try alloc.dupe(u8, base_path)
            else
                try std.fmt.allocPrint(alloc, "{s}.sql_routines", .{base_path});
            defer alloc.free(routine_path);
            const opened = try alloc.create(sql_routines.OpenedStore);
            errdefer alloc.destroy(opened);
            opened.* = try sql_routines.OpenedStore.open(alloc, routine_path);
            errdefer opened.deinit();
            try server.sql_routine_runtime.attachOpenedStore(opened);
        }
        return server;
    }

    pub fn setForeignRegistry(self: *ApiHttpServer, registry: *const foreign_mod.Registry) void {
        self.foreign_registry = registry;
        self.cfg.foreign_registry = registry;
    }

    fn ensureForeignRegistry(self: *ApiHttpServer) !*const foreign_mod.Registry {
        if (self.foreign_registry) |registry| return registry;
        const registry = try self.alloc.create(foreign_mod.Registry);
        errdefer self.alloc.destroy(registry);
        registry.* = .{};
        errdefer registry.deinit(self.alloc);
        try foreign_mod.registerDefaultPostgresExecutor(self.alloc, registry);
        self.owned_foreign_registry = registry;
        self.foreign_registry = registry;
        self.cfg.foreign_registry = registry;
        return registry;
    }

    pub fn deinit(self: *ApiHttpServer) void {
        if (self.schema_rewrite_wake_owner_id != 0) {
            if (self.cfg.backend_runtime) |runtime| {
                runtime.durable_jobs.closeOwner(self.schema_rewrite_wake_owner_id);
            }
        }
        self.schema_rewrite_wake_registry.deinit(self.alloc);
        self.mcp_sessions.deinit(self.alloc);
        self.a2a_tasks.deinit(self.alloc);
        self.txn_sessions.deinit(self.alloc);
        if (self.opened_session_store) |opened| {
            opened.deinit();
            self.alloc.destroy(opened);
        }
        self.artifact_reprocess_job_store.deinit();
        self.sql_notification_runtime.deinit();
        self.sql_catalog_session_runtime.deinit();
        self.sql_prepared_statement_runtime.deinit();
        self.sql_routine_runtime.deinit();
        self.join_job_store.deinit();
        if (self.owned_foreign_registry) |registry| {
            registry.deinit(self.alloc);
            self.alloc.destroy(registry);
        }
        self.connections_cache.deinit();
        self.* = undefined;
    }

    /// Build the GET /connections response body. Shared by the legacy
    /// dispatcher and the generated httpx handler so both paths use the same
    /// per-connection result cache. The caller owns the returned JSON.
    pub fn listConnectionsJsonAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        types_param: ?[]const u8,
        include_param: ?[]const u8,
        refresh_param: ?[]const u8,
    ) ![]u8 {
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const arena = arena_impl.allocator();

        var snapshot_opt = self.source.cachedAdminSnapshot() catch null;
        if (snapshot_opt == null) snapshot_opt = self.source.adminSnapshot() catch null;
        defer if (snapshot_opt) |*snapshot| self.source.freeAdminSnapshot(snapshot);

        const node_config = self.cfg.node_config;
        const response = try connections_api.buildConnectionsResponse(arena, .{
            .node_config = node_config,
            .snapshot = if (snapshot_opt) |*snapshot| snapshot else null,
            .antfly_provider = self.antfly_provider,
            .inference_api_url = if (node_config) |cfg| cfg.inference.api_url else null,
            .inference_api_key = self.cfg.inference_api_key,
        }, &self.connections_cache, .{
            .include_models = connections_api.includeHasModels(include_param),
            .refresh = if (refresh_param) |value| std.mem.eql(u8, value, "true") else false,
            .types_filter = types_param,
        });
        return try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(response, .{})});
    }

