    pub fn runSessionMaintenanceOnce(self: *ApiHttpServer) !void {
        try self.maybeCleanupExpiredSessions();
        try self.maybeRenewOwnedSessionLeases();
        self.join_job_store.cleanupExpiredJoinJobs();
        _ = try self.runSchemaRewriteCatalogCatchupOnce();
    }

    pub fn runSchemaRewriteCatalogCatchupOnce(self: *ApiHttpServer) !usize {
        const runtime = self.cfg.backend_runtime orelse return 0;
        const write_source = self.table_writes orelse return 0;
        var snapshot = (try self.source.adminSnapshot()) orelse return 0;
        defer self.source.freeAdminSnapshot(&snapshot);

        var scheduled_table_ids = std.ArrayListUnmanaged(u64).empty;
        defer scheduled_table_ids.deinit(self.alloc);

        var scheduled: usize = 0;
        for (snapshot.schema_rewrite_jobs) |job| {
            if (!schemaRewriteJobNeedsCatalogCatchup(job)) continue;
            if (schemaRewriteGenerationHasInvalidJob(&snapshot, job)) continue;
            if (schemaRewriteCatchupAlreadyScheduled(scheduled_table_ids.items, job.table_id)) continue;
            const table = schemaRewriteSnapshotTableById(&snapshot, job.table_id) orelse continue;
            if (!try self.submitSchemaRewriteWakeForTable(runtime, write_source, table)) continue;
            try scheduled_table_ids.append(self.alloc, job.table_id);
            scheduled += 1;
        }
        return scheduled;
    }

    fn localTableRuntimeStatuses(
        self: *ApiHttpServer,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        return try self.localTableRuntimeStatusesWithSnapshot(table_name, null);
    }

    fn localTableRuntimeStatusesWithSnapshot(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        errdefer {
            for (items.items) |*item| item.deinit(self.alloc);
            items.deinit(self.alloc);
        }

        if (self.table_reads) |source| {
            if (try source.localRuntimeStatuses(self.alloc, table_name)) |statuses| {
                var owned = statuses;
                errdefer owned.deinit(self.alloc);
                try self.appendLocalRuntimeStatuses(table_name, snapshot, &items, &owned, .append);
            }
        } else {
            if (self.table_writes) |source| {
                if (try source.localRuntimeStatuses(self.alloc, table_name)) |statuses| {
                    var owned = statuses;
                    errdefer owned.deinit(self.alloc);
                    try self.appendLocalRuntimeStatuses(table_name, snapshot, &items, &owned, .append);
                }
            }
        }
        if (snapshot) |admin_snapshot| {
            try self.appendRemoteRuntimeStatusesFromSnapshot(&items, table_name, admin_snapshot);
        }
        if (items.items.len == 0) {
            items.deinit(self.alloc);
            return null;
        }
        return .{ .items = try items.toOwnedSlice(self.alloc) };
    }

    fn localCatalogTableRuntimeStatusesWithSnapshot(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        snapshot: ?*const metadata_api.AdminSnapshot,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const catalog_table_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(catalog_table_name);

        var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        errdefer {
            for (items.items) |*item| item.deinit(self.alloc);
            items.deinit(self.alloc);
        }

        if (self.table_reads) |source| {
            if (try source.localRuntimeStatusesCatalog(self.alloc, target)) |statuses| {
                var owned = statuses;
                errdefer owned.deinit(self.alloc);
                try self.appendLocalRuntimeStatuses(catalog_table_name, snapshot, &items, &owned, .append);
            }
        } else if (self.table_writes) |source| {
            if (try source.localRuntimeStatusesCatalog(self.alloc, target)) |statuses| {
                var owned = statuses;
                errdefer owned.deinit(self.alloc);
                try self.appendLocalRuntimeStatuses(catalog_table_name, snapshot, &items, &owned, .append);
            }
        }
        if (snapshot) |admin_snapshot| {
            try self.appendRemoteRuntimeStatusesFromSnapshot(&items, catalog_table_name, admin_snapshot);
        }
        if (items.items.len == 0) {
            items.deinit(self.alloc);
            return null;
        }
        return .{ .items = try items.toOwnedSlice(self.alloc) };
    }

    const LocalRuntimeAppendMode = enum {
        append,
        replace_existing,
    };

    fn appendLocalRuntimeStatuses(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        owned: *runtime_status.LocalTableRuntimeStatuses,
        mode: LocalRuntimeAppendMode,
    ) !void {
        try items.ensureUnusedCapacity(self.alloc, owned.items.len);
        for (owned.items) |item| {
            if (!self.localRuntimeStatusAllowedBySnapshot(table_name, snapshot, item)) {
                var discard = item;
                discard.deinit(self.alloc);
                continue;
            }
            if (localRuntimeStatusGroupIndex(items.items, item.group_id)) |existing_index| {
                switch (mode) {
                    .append => {},
                    .replace_existing => {
                        items.items[existing_index].deinit(self.alloc);
                        items.items[existing_index] = item;
                        continue;
                    },
                }
            }
            items.appendAssumeCapacity(item);
        }
        if (owned.items.len > 0) self.alloc.free(owned.items);
        owned.items = &.{};
    }

    fn localRuntimeStatusGroupIndex(items: []const runtime_status.LocalTableRuntimeStatus, group_id: u64) ?usize {
        for (items, 0..) |item, i| {
            if (item.group_id == group_id) return i;
        }
        return null;
    }

    fn statusAdminSnapshot(self: *ApiHttpServer) !?metadata_api.AdminSnapshot {
        return (try self.source.cachedAdminSnapshot()) orelse try self.source.adminSnapshot();
    }

    fn appendRemoteRuntimeStatusesFromSnapshot(
        self: *ApiHttpServer,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        table_name: []const u8,
        snapshot: *const metadata_api.AdminSnapshot,
    ) !void {
        const table = tables_api.findTableByName(snapshot, table_name) orelse return;
        for (snapshot.stores) |store| {
            for (store.runtime_statuses) |remote| {
                if (remote.table_id != 0 and remote.table_id != table.table_id) continue;
                if (remote.table_name.len != 0 and !std.mem.eql(u8, remote.table_name, table_name)) continue;
                if (!tableHasGroup(snapshot, table.table_id, remote.group_id)) continue;
                if (!storeOwnsRuntimeGroup(snapshot, store, remote.group_id)) continue;

                var status = try localRuntimeStatusFromRemoteReport(self.alloc, remote);
                var consumed = false;
                errdefer if (!consumed) status.deinit(self.alloc);
                try upsertRemoteRuntimeStatus(self.alloc, items, &status);
                consumed = true;
            }
        }
    }

    fn upsertRemoteRuntimeStatus(
        alloc: std.mem.Allocator,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        status: *runtime_status.LocalTableRuntimeStatus,
    ) !void {
        for (items.items) |*existing| {
            if (existing.group_id != status.group_id) continue;
            if (existing.metadata.source != .remote_store) {
                status.deinit(alloc);
                return;
            }
            if (existing.metadata.updated_at_ns >= status.metadata.updated_at_ns) {
                status.deinit(alloc);
                return;
            }
            existing.deinit(alloc);
            existing.* = status.*;
            status.* = undefined;
            return;
        }
        try items.append(alloc, status.*);
        status.* = undefined;
    }

    fn localRuntimeStatusAllowedBySnapshot(
        self: *ApiHttpServer,
        table_name: []const u8,
        maybe_snapshot: ?*const metadata_api.AdminSnapshot,
        status: runtime_status.LocalTableRuntimeStatus,
    ) bool {
        const snapshot = maybe_snapshot orelse return true;
        const table = tables_api.findTableByName(snapshot, table_name) orelse return true;
        if (tableHasAnyGroup(snapshot, table.table_id) and !tableHasGroup(snapshot, table.table_id, status.group_id)) return false;

        const local_node_id = if (status.metadata.node_id != 0)
            status.metadata.node_id
        else if (self.cfg.session_router) |router|
            router.localNodeId()
        else
            0;
        const local_store_id = status.metadata.store_id;

        var saw_group_placement = false;
        for (snapshot.placement_intents) |intent| {
            if (intent.record.group_id != status.group_id) continue;
            saw_group_placement = true;
            if (local_store_id != 0 and intent.store_id == local_store_id) return true;
            if (local_node_id != 0 and intent.record.local_node_id == local_node_id) return true;
            if (local_node_id != 0) {
                for (intent.peer_node_ids) |peer_node_id| {
                    if (peer_node_id == local_node_id) return true;
                }
            }
        }
        if (local_node_id == 0 and local_store_id == 0) return !saw_group_placement or snapshot.stores.len <= 1;
        return !saw_group_placement;
    }

    fn snapshotHasProjectedTableGroups(
        self: *ApiHttpServer,
        table_name: []const u8,
        maybe_snapshot: ?*const metadata_api.AdminSnapshot,
    ) bool {
        _ = self;
        const snapshot = maybe_snapshot orelse return false;
        const table = tables_api.findTableByName(snapshot, table_name) orelse return false;
        return tableHasAnyGroup(snapshot, table.table_id);
    }

    fn localRuntimeStatusFromRemoteReport(
        alloc: std.mem.Allocator,
        report: metadata_table_manager.RuntimeGroupStatusReport,
    ) !runtime_status.LocalTableRuntimeStatus {
        const indexes = try alloc.alloc(db_mod.types.DBIndexStats, report.indexes.len);
        var initialized: usize = 0;
        errdefer {
            for (indexes[0..initialized]) |item| alloc.free(item.name);
            if (indexes.len > 0) alloc.free(indexes);
        }
        for (report.indexes, 0..) |index, i| {
            const kind = parseRemoteIndexKind(index.kind);
            const dense_catch_up_active = kind == .dense_vector and report.async_dense_catch_up_active;
            indexes[i] = .{
                .name = try alloc.dupe(u8, index.name),
                .kind = kind,
                .doc_count = index.doc_count,
                .term_count = index.term_count,
                .edge_count = index.edge_count,
                .node_count = index.node_count,
                .root_node = index.root_node,
                .backfill_active = index.backfill_active,
                .backfill_progress = @as(f64, @floatFromInt(index.backfill_progress_millis)) / 1000.0,
                .replay_applied_sequence = index.replay_applied_sequence,
                .replay_target_sequence = index.replay_target_sequence,
                .replay_catch_up_required = index.replay_catch_up_required,
                .catch_up_active = dense_catch_up_active,
                .catch_up_phase = if (dense_catch_up_active) .replay else .idle,
                .catch_up_applied_sequence = index.replay_applied_sequence,
                .catch_up_target_sequence = index.replay_target_sequence,
            };
            initialized += 1;
        }
        return .{
            .group_id = report.group_id,
            .disk_bytes = report.disk_bytes,
            .created_at_millis = report.created_at_millis,
            .metadata = .{
                .updated_at_ns = report.updated_at_ns,
                .source = .remote_store,
                .freshness = parseRemoteRuntimeFreshness(report.freshness),
                .topology_generation = report.topology_generation,
                .lsm_root_generation = report.lsm_root_generation,
                .status_generation = report.status_generation,
                .store_id = report.store_id,
                .node_id = report.node_id,
            },
            .stats = .{
                .doc_count = report.doc_count,
                .index_count = report.index_count,
                .indexes = indexes,
                .enrichment = .{
                    .enabled = report.enrichment_enabled,
                    .target_sequence = report.enrichment_target_sequence,
                    .applied_sequence = report.enrichment_applied_sequence,
                    .retrying = report.enrichment_retrying,
                    .worker_failed = report.enrichment_worker_failed,
                },
                .async_indexing = .{
                    .startup = .{ .active = report.async_startup_active },
                    .dense_catch_up = .{ .active = report.async_dense_catch_up_active },
                    .bulk_coalescing = .{ .active_session = report.async_bulk_coalescing_active },
                },
                .doc_identity = docIdentityStatsFromRemoteReport(report.doc_identity),
                .doc_set_planning = docSetPlanningStatsFromRemoteReport(report.doc_set_planning),
            },
        };
    }

    fn docIdentityStatsFromRemoteReport(
        report: metadata_table_manager.RuntimeDocIdentityStatusReport,
    ) db_mod.types.DocIdentityStats {
        return .{
            .namespace_table_id = report.namespace_table_id,
            .namespace_shard_id = report.namespace_shard_id,
            .namespace_range_id = report.namespace_range_id,
            .next_ordinal = report.next_ordinal,
            .allocated_ordinals = report.allocated_ordinals,
            .ordinal_capacity_remaining = report.ordinal_capacity_remaining,
            .ordinal_capacity_exhausted = report.ordinal_capacity_exhausted,
            .rebuild_required = report.rebuild_required,
            .state_rows = report.state_rows,
            .live_ordinals = report.live_ordinals,
            .tombstone_ordinals = report.tombstone_ordinals,
            .min_created_generation = report.min_created_generation,
            .max_created_generation = report.max_created_generation,
            .min_deleted_generation = report.min_deleted_generation,
            .max_deleted_generation = report.max_deleted_generation,
            .scanned_primary_docs = report.scanned_primary_docs,
            .primary_docs_missing_ordinals = report.primary_docs_missing_ordinals,
            .primary_docs_missing_identity_state = report.primary_docs_missing_identity_state,
            .primary_docs_with_tombstone_ordinals = report.primary_docs_with_tombstone_ordinals,
            .complete = report.complete,
        };
    }

    fn docSetPlanningStatsFromRemoteReport(
        report: metadata_table_manager.RuntimeDocSetPlanningStatusReport,
    ) db_mod.types.DocSetPlanningStats {
        return .{
            .resolved_set_count = report.resolved_set_count,
            .all_set_count = report.all_set_count,
            .none_set_count = report.none_set_count,
            .doc_key_list_count = report.doc_key_list_count,
            .ordinal_list_count = report.ordinal_list_count,
            .ordinal_bitmap_count = report.ordinal_bitmap_count,
            .doc_key_list_docs = report.doc_key_list_docs,
            .ordinal_list_docs = report.ordinal_list_docs,
            .ordinal_bitmap_docs = report.ordinal_bitmap_docs,
            .missing_ordinal_coverage_count = report.missing_ordinal_coverage_count,
            .bitmap_promotion_count = report.bitmap_promotion_count,
            .unsupported_filter_shape_count = report.unsupported_filter_shape_count,
            .stale_identity_generation_rejection_count = report.stale_identity_generation_rejection_count,
        };
    }

    fn parseRemoteIndexKind(kind: []const u8) db_mod.types.IndexKind {
        if (std.mem.eql(u8, kind, "full_text")) return .full_text;
        if (std.mem.eql(u8, kind, "sparse_vector")) return .sparse_vector;
        if (std.mem.eql(u8, kind, "graph")) return .graph;
        if (std.mem.eql(u8, kind, "algebraic")) return .algebraic;
        return .dense_vector;
    }

    fn parseRemoteRuntimeFreshness(freshness: []const u8) runtime_status.RuntimeStatusFreshness {
        inline for (@typeInfo(runtime_status.RuntimeStatusFreshness).@"enum".fields) |field| {
            if (std.mem.eql(u8, freshness, field.name)) return @enumFromInt(field.value);
        }
        return .remote_unknown;
    }

    fn tableHasGroup(snapshot: *const metadata_api.AdminSnapshot, table_id: u64, group_id: u64) bool {
        for (snapshot.ranges) |range| {
            if (range.table_id == table_id and range.group_id == group_id) return true;
        }
        return false;
    }

    fn tableHasAnyGroup(snapshot: *const metadata_api.AdminSnapshot, table_id: u64) bool {
        for (snapshot.ranges) |range| {
            if (range.table_id == table_id) return true;
        }
        return false;
    }

    fn storeOwnsRuntimeGroup(
        snapshot: *const metadata_api.AdminSnapshot,
        store: metadata_table_manager.StoreRecord,
        group_id: u64,
    ) bool {
        var saw_group_placement = false;
        for (snapshot.placement_intents) |intent| {
            if (intent.record.group_id != group_id) continue;
            saw_group_placement = true;
            if (intent.store_id != 0 and intent.store_id == store.store_id) return true;
            if (intent.record.local_node_id == store.node_id) return true;
            for (intent.peer_node_ids) |peer_node_id| {
                if (peer_node_id == store.node_id) return true;
            }
        }
        return !saw_group_placement;
    }

    pub fn bestEffortSingleTableStorageStatus(
        self: *ApiHttpServer,
        table_name: []const u8,
    ) !?tables_api.TableStorageStatus {
        var local_statuses = (try self.localTableRuntimeStatuses(table_name)) orelse return null;
        defer local_statuses.deinit(self.alloc);

        var doc_count: u64 = 0;
        for (local_statuses.items) |item| doc_count +|= item.stats.doc_count;
        return .{
            .table_name = table_name,
            .empty = doc_count == 0,
            .lsm = try self.bestEffortLsmStorageStatus(table_name),
        };
    }

    fn bestEffortLsmStorageStatus(self: *ApiHttpServer, table_name: []const u8) !?tables_api.LsmStorageStatus {
        const source = self.table_reads orelse return null;
        const stats = (try source.lsmStorageStats(table_name)) orelse return null;
        return tables_api.lsmStorageStatusFromMaintenanceStats(stats.maintenance);
    }

    pub fn bestEffortSingleTableStorageStatuses(
        self: *ApiHttpServer,
        table_name: []const u8,
        storage_status_buf: *[1]tables_api.TableStorageStatus,
    ) !?[]const tables_api.TableStorageStatus {
        const status = (try self.bestEffortSingleTableStorageStatus(table_name)) orelse return null;
        storage_status_buf[0] = status;
        return storage_status_buf[0..];
    }

    fn catalogSource(self: *ApiHttpServer) table_catalog.CatalogSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .admin_snapshot = apiHttpServerCatalogAdminSnapshot,
                .free_admin_snapshot = apiHttpServerCatalogFreeAdminSnapshot,
            },
        };
    }

    fn hostedWriteRoutesVisible(self: *ApiHttpServer, table_name: []const u8) !?bool {
        const router = self.cfg.session_router orelse return null;
        var snapshot = (try self.source.adminSnapshot()) orelse return null;
        defer self.source.freeAdminSnapshot(&snapshot);

        const table = tables_api.findTableByName(&snapshot, table_name) orelse return false;
        const ranges = try metadata_admin.listTableRanges(self.alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(self.alloc, ranges);
        if (ranges.len == 0) return false;

        const catalog = self.catalogSource();
        for (ranges) |range| {
            var route = (try table_router.resolveGroupRoute(
                self.alloc,
                catalog,
                router,
                range.group_id,
                .prefer_leader,
            )) orelse return false;
            route.deinit(self.alloc);
        }
        return true;
    }

    pub fn cleanupExpiredSessions(self: *ApiHttpServer, cutoff_ns: u64) !usize {
        return try self.txn_sessions.cleanupExpired(self.alloc, cutoff_ns);
    }

    pub fn applyRelationalSqlDdl(self: *ApiHttpServer, sql: []const u8) !tables_api.AppliedRelationalSqlDdlRecord {
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(self.alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(self.alloc);
        return try self.applyRelationalSqlDdlWithSession(sql, &session);
    }

    pub fn applyRelationalSqlDdlInTransactionSession(
        self: *ApiHttpServer,
        txn_id: db_mod.types.TxnId,
        sql: []const u8,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        var state = (try self.txn_sessions.getSqlCatalogSessionState(self.alloc, txn_id)) orelse return error.TxnNotFound;
        defer state.deinit(self.alloc);

        var session = try state.toOwnedSqlCatalogSessionAlloc(self.alloc);
        defer session.deinit(self.alloc);

        var applied = try self.applyRelationalSqlDdlWithSession(sql, &session);
        errdefer applied.deinit(self.alloc);

        var updated = try transactions_api.SqlCatalogSessionState.fromOwnedSqlCatalogSessionAlloc(self.alloc, session);
        defer updated.deinit(self.alloc);
        _ = (try self.txn_sessions.updateSqlCatalogSessionState(self.alloc, txn_id, updated)) orelse return error.TxnNotFound;
        return applied;
    }

    pub fn sqlCatalogSessionForAuthenticatedIdentityDatabaseAlloc(
        self: *ApiHttpServer,
        identity: ?*const AuthenticatedIdentity,
        database_name: []const u8,
    ) !sql_adapter.OwnedSqlCatalogSession {
        var database_settings: []usermgr.RoleSetting = &.{};
        defer {
            for (database_settings) |*setting| setting.deinit(self.alloc);
            if (database_settings.len > 0) self.alloc.free(database_settings);
        }

        var runtime_settings: []usermgr.RoleSetting = &.{};
        var owns_runtime_settings = false;
        defer if (owns_runtime_settings) {
            for (runtime_settings) |*setting| setting.deinit(self.alloc);
            if (runtime_settings.len > 0) self.alloc.free(runtime_settings);
        };

        if (identity) |active_identity| {
            if (self.cfg.user_manager) |manager| {
                if (manager.hasUser(active_identity.username)) {
                    runtime_settings = try manager.getEffectiveRoleRuntimeSettingsForDatabase(active_identity.username, database_name);
                    owns_runtime_settings = true;
                } else {
                    runtime_settings = active_identity.role_runtime_settings;
                }
            } else {
                runtime_settings = active_identity.role_runtime_settings;
            }
        }

        if (self.source.adminSnapshot()) |maybe_snapshot| {
            if (maybe_snapshot) |*snapshot| {
                defer self.source.freeAdminSnapshot(snapshot);
                if (tables_api.findDatabaseByName(snapshot, database_name)) |database| {
                    database_settings = try sqlDatabaseSettingsFromJsonAlloc(self.alloc, database.settings_json);
                }
            }
        } else |err| switch (err) {
            error.UnsupportedOperation => {},
            else => return err,
        }

        return try ownedSqlCatalogSessionFromSettingLayersAlloc(self.alloc, database_name, database_settings, runtime_settings);
    }

    fn ensureSqlNotificationSessionId(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) u64 {
        if (session.notification_session_id == 0) {
            session.notification_session_id = self.sql_notification_runtime.allocateSessionId();
        }
        return session.notification_session_id;
    }

    fn ensureSqlProtocolSessionId(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) u64 {
        return self.ensureSqlNotificationSessionId(session);
    }

    fn enforceSqlStatementTimeout(_: *ApiHttpServer, statement_timeout_ns: ?u64, statement_start_ns: u64) !void {
        if (sql_adapter.sqlStatementTimeoutExpired(statement_timeout_ns, statement_start_ns, platform_time.monotonicNs())) return error.StatementTimeout;
    }

    fn parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql: *const sql_adapter.ParsedSql) bool {
        const tokens = parsed_sql.items();
        const raw = parsed_sql.statement.raw();
        if (raw.token_start >= raw.token_end or raw.token_start >= tokens.len) return false;
        const first = tokens[raw.token_start];
        const next = raw.token_start + 1;
        if (first.matchesKeywordTag(.commit)) {
            return next >= raw.token_end or !tokens[next].matchesKeywordTag(.prepared);
        }
        if (first.matchesKeywordTag(.rollback)) {
            return next >= raw.token_end or
                (!tokens[next].matchesKeywordTag(.prepared) and
                    !tokens[next].matchesKeywordTag(.to) and
                    !tokens[next].matchesKeywordTag(.savepoint));
        }
        return false;
    }

    fn parsedSqlTransactionBoundaryStartsSession(parsed_sql: *const sql_adapter.ParsedSql) bool {
        const tokens = parsed_sql.items();
        const raw = parsed_sql.statement.raw();
        if (raw.token_start >= raw.token_end or raw.token_start >= tokens.len) return false;
        const first = tokens[raw.token_start];
        if (first.matchesKeywordTag(.begin)) return true;
        if (first.matchesKeyword("start")) {
            const next = raw.token_start + 1;
            return next < raw.token_end and tokens[next].matchesKeyword("transaction");
        }
        return false;
    }

    fn publicSqlTransactionStatus(_: *ApiHttpServer, session: *const sql_adapter.OwnedSqlCatalogSession) PublicSqlTransactionStatus {
        if (session.sql_transaction_failed) return .failed_transaction;
        if (session.in_sql_transaction or session.transaction_local_search_path or session.transaction_local_settings) return .in_transaction;
        return .idle;
    }

    fn markPublicSqlTransactionFailedIfActive(_: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) void {
        if (session.in_sql_transaction or session.transaction_local_search_path or session.transaction_local_settings) {
            session.in_sql_transaction = true;
            session.sql_transaction_failed = true;
        }
    }

    fn publicSqlReadOnlyActive(_: *ApiHttpServer, session: *const sql_adapter.OwnedSqlCatalogSession) !bool {
        return session.request_read_only or try sql_adapter.sqlEffectiveTransactionReadOnlyFromSession(session.session());
    }

    fn sessionCatalogPlanAllowedInReadOnly(_: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession, plan: sql_adapter.SessionCatalogPlan) !bool {
        return switch (plan) {
            .set_search_path,
            .reset_search_path,
            .show_search_path,
            => true,
            .discard_all => false,
            .set_setting => |set| blk: {
                if (std.ascii.eqlIgnoreCase(set.name, "transaction_read_only") or
                    std.ascii.eqlIgnoreCase(set.name, "default_transaction_read_only"))
                {
                    break :blk try sql_adapter.parseSqlBoolSetting(set.value);
                }
                break :blk true;
            },
            .reset_setting => |reset| blk: {
                if (std.ascii.eqlIgnoreCase(reset.name, "default_transaction_read_only")) break :blk false;
                if (std.ascii.eqlIgnoreCase(reset.name, "transaction_read_only")) {
                    break :blk try sql_adapter.sqlDefaultTransactionReadOnlyFromSession(session.session());
                }
                break :blk true;
            },
        };
    }

    fn transactionControlPlanAllowedInReadOnly(_: *ApiHttpServer, plan: sql_adapter.TransactionControlPlan) !bool {
        return switch (plan) {
            .transaction_mode => |mode| switch (mode.access_mode orelse .read_only) {
                .read_only => true,
                .read_write => false,
            },
            .constraint_mode,
            .advisory_lock,
            => true,
            .table_lock => false,
        };
    }

    fn applyTransactionModePlanToSession(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession, plan: sql_adapter.TransactionModePlan) !bool {
        if (plan.starter == .begin or plan.starter == .start_transaction) {
            session.in_sql_transaction = true;
            session.sql_transaction_failed = false;
        }
        const access_mode = plan.access_mode orelse return false;
        const value = switch (access_mode) {
            .read_only => "on",
            .read_write => "off",
        };
        try session.setTransactionLocalSettingAlloc(self.alloc, "transaction_read_only", value);
        return true;
    }

    pub fn applyRelationalSqlDdlWithSession(self: *ApiHttpServer, sql: []const u8, session: *sql_adapter.OwnedSqlCatalogSession) !tables_api.AppliedRelationalSqlDdlRecord {
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(self.alloc, sql);
        defer parsed_sql.deinit(self.alloc);
        return try self.applyRelationalParsedSqlDdlWithSession(&parsed_sql, session);
    }

    pub const SqlStatementExecutionTiming = struct {
        timeout_ns: ?u64,
        start_ns: u64,
    };

    pub const RelationalDdlPlanExecutionContext = struct {
        parsed_sql: ?*const sql_adapter.ParsedSql = null,
        function_bindings: sql_adapter.SqlFunctionBindings = .{},
        statement_timing: ?SqlStatementExecutionTiming = null,
    };

    pub fn applyRelationalParsedSqlDdlWithSession(self: *ApiHttpServer, parsed_sql: *const sql_adapter.ParsedSql, session: *sql_adapter.OwnedSqlCatalogSession) !tables_api.AppliedRelationalSqlDdlRecord {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };
        var logical_plan = sql_adapter.planDdlLogicalPlanParsedSqlWithFunctionBindingsAlloc(self.alloc, parsed_sql, function_bindings) catch |err| switch (err) {
            error.UnsupportedSqlShape => {
                if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;
                return err;
            },
            else => return err,
        };
        defer logical_plan.deinit(self.alloc);
        return try self.applyLogicalSqlPlanWithSession(&logical_plan, session, .{
            .parsed_sql = parsed_sql,
            .function_bindings = function_bindings,
            .statement_timing = .{
                .timeout_ns = statement_timeout_ns,
                .start_ns = statement_start_ns,
            },
        });
    }

    fn applyLogicalSqlPlanWithSession(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        switch (logical_plan.*) {
            .table_ddl, .catalog_ddl, .extension => return try self.applyDurableLogicalPlanWithSession(logical_plan, session, context),
            .other_ddl => |plan| return try self.applyOtherDdlLogicalPlanWithSession(plan, session, context),
            .session => |plan| return try self.applySessionLogicalPlanWithSession(plan, session, context),
            .transaction => |plan| return try self.applyTransactionLogicalPlanWithSession(plan, session, context),
            .prepared_statement => |plan| return try self.applyPreparedStatementLogicalPlanWithSession(plan, session, context),
            .notification => |plan| return try self.applyNotificationLogicalPlanWithSession(plan, session, context),
            .routine => |*plan| return try self.applyRoutineLogicalPlanWithSession(plan, session, context),
            .auth => return try self.applyAuthLogicalPlanWithSession(logical_plan, session, context),
            .cursor, .maintenance, .bulk_io => return error.UnsupportedSqlShape,
            .read, .write, .catalog_read, .catalog_write => return error.UnsupportedSqlShape,
        }
    }

    fn sqlStatementExecutionTimingForContext(
        self: *ApiHttpServer,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !SqlStatementExecutionTiming {
        _ = self;
        return context.statement_timing orelse SqlStatementExecutionTiming{
            .timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session()),
            .start_ns = platform_time.monotonicNs(),
        };
    }

    fn emptyAppliedSqlDdlRecordWithTiming(
        self: *ApiHttpServer,
        timing: SqlStatementExecutionTiming,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
        errdefer applied.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        return applied;
    }

    fn applyOtherDdlLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.OtherDdlLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            switch (plan) {
                .adapter_noop => {},
                .moved => return error.SqlReadOnlyTransaction,
            }
        }
        switch (plan) {
            .adapter_noop => |noop| switch (noop.reason) {
                .transaction_control => {
                    if (context.parsed_sql) |parsed_sql| {
                        if (parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql)) {
                            try session.clearTransactionLocalState(self.alloc);
                            var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                            applied.noop = true;
                            return applied;
                        }
                        if (parsedSqlTransactionBoundaryStartsSession(parsed_sql)) {
                            session.in_sql_transaction = true;
                            session.sql_transaction_failed = false;
                            var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                            applied.noop = true;
                            return applied;
                        }
                    }
                    return error.UnsupportedSqlShape;
                },
                .extension => return try extension_domain.sql_adapter.executeRelationalSqlExtensionNoopAlloc(self.alloc),
                else => return error.UnsupportedSqlShape,
            },
            .moved => return error.UnsupportedSqlShape,
        }
    }

    fn applySessionLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.SessionCatalogPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            if (!try self.sessionCatalogPlanAllowedInReadOnly(session, plan)) return error.SqlReadOnlyTransaction;
        }

        const notification_session_id = session.notification_session_id;
        const clear_prepared_statements = switch (plan) {
            .discard_all => true,
            else => false,
        };
        var updated = try sql_adapter.applyOwnedSessionCatalogPlanAlloc(self.alloc, session.*, plan);
        errdefer updated.deinit(self.alloc);
        updated.notification_session_id = notification_session_id;
        updated.request_read_only = session.request_read_only;
        if (clear_prepared_statements and notification_session_id != 0) {
            try self.sql_prepared_statement_runtime.apply(.{ .deallocate = .{ .all = true } }, notification_session_id);
        }
        session.deinit(self.alloc);
        session.* = updated;
        var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
        applied.noop = true;
        return applied;
    }

    fn applyTransactionLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.TransactionLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);

        switch (plan) {
            .control => |control| {
                if (try self.publicSqlReadOnlyActive(session)) {
                    if (!try self.transactionControlPlanAllowedInReadOnly(control)) return error.SqlReadOnlyTransaction;
                }
                switch (control) {
                    .transaction_mode => |transaction_mode| {
                        const applied_mode = try self.applyTransactionModePlanToSession(session, transaction_mode);
                        var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                        applied.noop = applied_mode;
                        return applied;
                    },
                    else => return error.UnsupportedSqlShape,
                }
            },
            .prepared => |prepared| {
                if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;
                _ = try self.applyPreparedTransactionPlan(prepared, sqlDdlTimestampNs());
                if (prepared.action == .prepare) {
                    try session.clearTransactionLocalState(self.alloc);
                }
                return try self.emptyAppliedSqlDdlRecordWithTiming(timing);
            },
            .savepoint => return error.UnsupportedSqlShape,
        }
    }

    fn applyPreparedStatementLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.PreparedStatementPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            const allowed = switch (plan) {
                .prepare => |prepare| prepare.statement_kind == .read,
                .deallocate => true,
                .execute => |execute_plan| blk: {
                    const session_id = session.notification_session_id;
                    if (session_id == 0) return error.PreparedStatementNotFound;
                    break :blk (try self.sql_prepared_statement_runtime.statementKindForExecute(session_id, execute_plan)) == .read;
                },
            };
            if (!allowed) return error.SqlReadOnlyTransaction;
        }
        const session_id = self.ensureSqlProtocolSessionId(session);
        try self.sql_prepared_statement_runtime.apply(plan, session_id);
        var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
        applied.noop = true;
        return applied;
    }

    fn applyNotificationLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.NotificationChannelPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            const allowed = switch (plan) {
                .listen, .unlisten => true,
                .notify => false,
            };
            if (!allowed) return error.SqlReadOnlyTransaction;
        }
        const session_id = self.ensureSqlNotificationSessionId(session);
        _ = try self.sql_notification_runtime.apply(plan, session_id, sqlDdlTimestampNs());
        return try self.emptyAppliedSqlDdlRecordWithTiming(timing);
    }

    fn applyRoutineLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: *sql_adapter.RoutineLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;

        switch (plan.*) {
            .function_catalog => |*function_plan| {
                try self.resolveRoutineSettingsFromCurrentInPlace(function_plan, session.session());
                try self.sql_routine_runtime.apply(function_plan.*);
            },
            .trigger_catalog => |trigger_plan| {
                return try self.applyTriggerCatalogPlanWithUpdatePolicyFallback(trigger_plan, session, context, timing);
            },
            .procedure_call => |procedure_call| {
                try self.sql_routine_runtime.executeProcedureRoutineArgs(procedure_call.routine_name, procedure_call.argument_count);
            },
        }
        return try self.emptyAppliedSqlDdlRecordWithTiming(timing);
    }

    fn applyAuthLogicalPlanWithSession(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;

        const auth_plan = switch (logical_plan.*) {
            .auth => |plan| plan,
            else => return error.UnsupportedSqlShape,
        };

        if (self.cfg.user_manager) |manager| {
            var catalog = try self.sqlAuthCatalogForAuthLogicalPlanWithSession(auth_plan, session.session());
            defer catalog.deinit(self.alloc);
            if (try auth_sql_adapter.executeRelationalSqlAuthPlanOnUserManagerWithCatalog(manager, self.alloc, auth_plan, catalog.value)) |applied_value| {
                var applied = applied_value;
                errdefer applied.deinit(self.alloc);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            }
        }

        return try self.applyDurableLogicalPlanWithSession(logical_plan, session, context);
    }

    fn applyDurableLogicalPlanWithSession(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;

        var durable_plan = try sql_adapter.DurableSqlPlan.fromLogical(logical_plan);
        defer durable_plan.deinit(self.alloc);
        try self.rejectUnsupportedDocumentSqlViewMappingForDurablePlan(durable_plan, session.session());
        switch (durable_plan) {
            .extension => {
                var applied = try self.source.applyRelationalSqlDdlPlanWithSessionAndFunctionBindings(self.alloc, &durable_plan, session.session(), context.function_bindings);
                errdefer applied.deinit(self.alloc);
                try self.refreshSqlExtensionQueryFunctions();
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
            else => {
                var applied = try self.source.applyRelationalSqlDdlPlanWithSessionAndFunctionBindings(self.alloc, &durable_plan, session.session(), context.function_bindings);
                errdefer applied.deinit(self.alloc);
                try self.scheduleSchemaRewriteRuntimeHintForAppliedDdl(applied);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
        }
    }

    fn applyTriggerCatalogPlanWithUpdatePolicyFallback(
        self: *ApiHttpServer,
        plan: sql_adapter.TriggerCatalogPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
        timing: SqlStatementExecutionTiming,
    ) anyerror!tables_api.AppliedRelationalSqlDdlRecord {
        self.sql_routine_runtime.applyTriggerCatalogPlan(plan) catch |err| switch (err) {
            error.TriggerNotFound => switch (plan) {
                .drop => |drop| return try self.applyUpdatePolicyDropTriggerPlan(drop, session, context, timing),
                .create => return err,
            },
            else => return err,
        };
        var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
        applied.noop = true;
        return applied;
    }

    fn applyUpdatePolicyDropTriggerPlan(
        self: *ApiHttpServer,
        drop: sql_adapter.DropRoutineTriggerPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
        timing: SqlStatementExecutionTiming,
    ) anyerror!tables_api.AppliedRelationalSqlDdlRecord {
        const operations = try self.alloc.alloc(sql_adapter.AlterTableOperation, 1);
        var operations_transferred = false;
        errdefer if (!operations_transferred) self.alloc.free(operations);
        operations[0] = .{ .drop_update_policy = .{
            .trigger_name = try self.alloc.dupe(u8, drop.trigger_name),
            .if_exists = drop.if_exists,
        } };
        var operation_transferred = false;
        errdefer if (!operation_transferred) sql_adapter.freeAlterTableOperation(self.alloc, operations[0]);
        const table_name = try self.alloc.dupe(u8, drop.table_name);
        errdefer self.alloc.free(table_name);

        var logical_plan: sql_adapter.LogicalSqlPlan = .{ .table_ddl = .{ .alter_table = .{
            .table_name = table_name,
            .operations = operations,
        } } };
        operations_transferred = true;
        operation_transferred = true;
        defer logical_plan.deinit(self.alloc);

        return try self.applyDurableLogicalPlanWithSession(&logical_plan, session, .{
            .function_bindings = context.function_bindings,
            .statement_timing = timing,
        });
    }

    fn rejectUnsupportedDocumentSqlViewMappingForDurablePlan(
        self: *ApiHttpServer,
        plan: sql_adapter.DurableSqlPlan,
        session: catalog_resources.SqlCatalogSession,
    ) !void {
        const create_view = switch (plan) {
            .table_ddl => |table_plan| switch (table_plan) {
                .view_catalog => |view_plan| switch (view_plan) {
                    .create => |create| create,
                    else => return,
                },
                else => return,
            },
            else => return,
        };
        const schema = sql_adapter.runtimeSchemaForCatalogTableWithSessionAlloc(
            self.alloc,
            self.catalogSource(),
            create_view.source_table_name,
            session,
        ) catch |err| switch (err) {
            error.TableNotFound, error.InvalidSqlCatalog => return,
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);
        if (schema.storage_mode == .document) return error.DocumentSqlViewMappingUnsupported;
    }

    pub const PublicSqlRequest = struct {
        sql: []const u8,
        session_id: ?u64 = null,
        database: ?[]const u8 = null,
        namespace: ?[]const u8 = null,
        read_only: ?bool = null,
        params: []const sql_adapter.SqlValue = &.{},
    };

    const PublicSqlJsonRequest = struct {
        sql: []const u8,
        session_id: ?u64 = null,
        database: ?[]const u8 = null,
        namespace: ?[]const u8 = null,
        read_only: ?bool = null,
        params: ?[]const std.json.Value = null,
    };

    pub const OwnedPublicSqlParams = struct {
        values: []sql_adapter.SqlValue = &.{},

        pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            for (self.values) |value| freePublicSqlParam(alloc, value);
            if (self.values.len > 0) alloc.free(self.values);
            self.* = .{};
        }
    };

    pub fn publicSqlParamsFromJsonAlloc(alloc: std.mem.Allocator, params: ?[]const std.json.Value) !OwnedPublicSqlParams {
        const items = params orelse return .{};
        if (items.len == 0) return .{};
        const values = try alloc.alloc(sql_adapter.SqlValue, items.len);
        var initialized: usize = 0;
        errdefer {
            for (values[0..initialized]) |value| freePublicSqlParam(alloc, value);
            alloc.free(values);
        }
        for (items, 0..) |item, i| {
            values[i] = try publicSqlParamFromJsonAlloc(alloc, item);
            initialized += 1;
        }
        return .{ .values = values };
    }

    pub fn freePublicSqlParam(alloc: std.mem.Allocator, value: sql_adapter.SqlValue) void {
        switch (value) {
            .string => |text| alloc.free(@constCast(text)),
            .json => |json| alloc.free(@constCast(json)),
            .null, .bool, .integer, .float => {},
        }
    }

    fn publicSqlParamFromJsonAlloc(alloc: std.mem.Allocator, value: std.json.Value) !sql_adapter.SqlValue {
        return switch (value) {
            .null => .null,
            .bool => |flag| .{ .bool = flag },
            .integer => |number| .{ .integer = number },
            .float => |number| .{ .float = number },
            .number_string => |number| .{ .json = try alloc.dupe(u8, number) },
            .string => |text| .{ .string = try alloc.dupe(u8, text) },
            .array, .object => .{ .json = try std.json.Stringify.valueAlloc(alloc, value, .{}) },
        };
    }

    const PublicSqlResponse = struct {
        kind: []const u8,
        session_id: u64,
        statement_kind: []const u8,
        noop: bool,
        applied: tables_api.AppliedRelationalSqlDdlRecord,
    };

    pub const PublicSqlTransactionStatus = enum {
        idle,
        in_transaction,
        failed_transaction,
    };

    pub const PublicSqlResult = struct {
        pub const Read = struct {
            result: table_reads.LoweredSqlReadPlanResult,
            columns: []const runtime_schema_mod.RelationalColumn = &.{},

            pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
                self.result.deinit(alloc);
                relational_rows_api.freeRowsOutputColumns(alloc, self.columns);
                self.* = undefined;
            }
        };

        pub const Ddl = struct {
            applied: tables_api.AppliedRelationalSqlDdlRecord,
            command_tag: []const u8 = "DDL",

            pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
                self.applied.deinit(alloc);
                self.* = undefined;
            }
        };

        pub const RowsBatch = struct {
            result: relational_rows_api.OwnedRowsBatchRequest,
            columns: []const runtime_schema_mod.RelationalColumn = &.{},

            pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
                self.result.deinit(alloc);
                relational_rows_api.freeRowsOutputColumns(alloc, self.columns);
                self.* = undefined;
            }
        };

        pub const MutationSource = struct {
            result: db_mod.types.RelationalRowsMutationSourceResult,
            columns: []const runtime_schema_mod.RelationalColumn = &.{},

            pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
                self.result.deinit(alloc);
                relational_rows_api.freeRowsOutputColumns(alloc, self.columns);
                self.* = undefined;
            }
        };

        session_id: u64,
        statement_kind: []const u8,
        transaction_status: PublicSqlTransactionStatus = .idle,
        result: union(enum) {
            ddl: Ddl,
            read: Read,
            rows_batch: RowsBatch,
            mutation_source: MutationSource,
        },

        pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            switch (self.result) {
                .ddl => |*ddl| ddl.deinit(alloc),
                .read => |*read| read.deinit(alloc),
                .rows_batch => |*rows_batch| rows_batch.deinit(alloc),
                .mutation_source => |*mutation_source| mutation_source.deinit(alloc),
            }
            self.* = undefined;
        }
    };

    pub const PublicSqlResultOrResponse = union(enum) {
        result: PublicSqlResult,
        response: http_common.HttpResponse,

        pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            switch (self.*) {
                .result => |*result| result.deinit(alloc),
                .response => |*response| response.deinit(alloc),
            }
            self.* = undefined;
        }
    };

    pub const PublicSqlDescribeResult = struct {
        session_id: u64,
        statement_kind: []const u8,
