    fn ownedSqlCatalogSessionForPublicRequestAlloc(self: *ApiHttpServer, request: PublicSqlRequest) !sql_adapter.OwnedSqlCatalogSession {
        var session = try self.sql_catalog_session_runtime.loadAlloc(request.session_id);
        errdefer session.deinit(self.alloc);
        if (request.database) |database| {
            if (!catalogApiIdentifierValid(database)) return error.InvalidSqlRequest;
            if (session.request_database_name_base == null) {
                session.request_database_name_base = try self.alloc.dupe(u8, session.current_database_name);
            }
            self.alloc.free(session.current_database_name);
            session.current_database_name = try self.alloc.dupe(u8, database);
        }
        if (request.namespace) |namespace| {
            if (!catalogApiIdentifierValid(namespace)) return error.InvalidSqlRequest;
            if (session.request_search_path_base == null) {
                session.request_search_path_base = try session.cloneSearchPathAlloc(self.alloc);
            }
            for (session.search_path) |name| self.alloc.free(@constCast(name));
            if (session.search_path.len > 0) self.alloc.free(session.search_path);
            const search_path = try self.alloc.alloc([]const u8, 1);
            errdefer self.alloc.free(search_path);
            search_path[0] = try self.alloc.dupe(u8, namespace);
            session.search_path = search_path;
        }
        session.request_read_only = request.read_only orelse false;
        return session;
    }

    fn savePublicSqlSession(self: *ApiHttpServer, session: sql_adapter.OwnedSqlCatalogSession) !void {
        try self.sql_catalog_session_runtime.save(session);
    }

    fn encodePublicSqlReadResultAlloc(
        self: *ApiHttpServer,
        session_id: u64,
        statement_kind: []const u8,
        read: PublicSqlResult.Read,
    ) ![]u8 {
        const result_body = switch (read.result) {
            .query => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .document_query => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .set_operation => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .recursive_cte => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .aggregate => |aggregate| try relational_rows_api.encodeRowsAggregateResponseWithSchemaAlloc(self.alloc, aggregate, read.columns),
            .window => |window| try relational_rows_api.encodeRowsWindowResponseWithSchemaAlloc(self.alloc, window, read.columns),
            .join => |join| try relational_rows_api.encodeRowsJoinResponseWithSchemaAlloc(self.alloc, join, read.columns),
            .lateral => |lateral| try relational_rows_api.encodeRowsJoinResponseWithSchemaAlloc(self.alloc, lateral, read.columns),
        };
        defer self.alloc.free(result_body);

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print(
            "{{\"kind\":\"read\",\"session_id\":{d},\"statement_kind\":{f},\"result\":",
            .{ session_id, std.json.fmt(statement_kind, .{}) },
        );
        try writer.writeAll(result_body);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn encodePublicSqlRowsBatchResultAlloc(
        self: *ApiHttpServer,
        session_id: u64,
        statement_kind: []const u8,
        rows_batch: PublicSqlResult.RowsBatch,
    ) ![]u8 {
        const result_body = try relational_rows_api.encodeRowsBatchResponseAlloc(self.alloc, rows_batch.result);
        defer self.alloc.free(result_body);

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print(
            "{{\"kind\":\"write\",\"session_id\":{d},\"statement_kind\":{f},\"result\":",
            .{ session_id, std.json.fmt(statement_kind, .{}) },
        );
        try writer.writeAll(result_body);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn encodePublicSqlRowsMutationSourceResultAlloc(
        self: *ApiHttpServer,
        session_id: u64,
        statement_kind: []const u8,
        result: PublicSqlResult.MutationSource,
    ) ![]u8 {
        const result_body = try relational_rows_api.encodeRowsMutationSourceResponseAlloc(self.alloc, result.result);
        defer self.alloc.free(result_body);

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print(
            "{{\"kind\":\"write\",\"session_id\":{d},\"statement_kind\":{f},\"result\":",
            .{ session_id, std.json.fmt(statement_kind, .{}) },
        );
        try writer.writeAll(result_body);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn encodePublicSqlResultAlloc(self: *ApiHttpServer, result: PublicSqlResult) ![]u8 {
        return switch (result.result) {
            .ddl => |ddl| blk: {
                var response = try jsonResponse(self.alloc, PublicSqlResponse{
                    .kind = "ddl",
                    .session_id = result.session_id,
                    .statement_kind = "ddl",
                    .noop = ddl.applied.noop,
                    .applied = ddl.applied,
                });
                defer response.deinit(self.alloc);
                break :blk try self.alloc.dupe(u8, response.body);
            },
            .read => |read| try self.encodePublicSqlReadResultAlloc(result.session_id, result.statement_kind, read),
            .rows_batch => |rows_batch| try self.encodePublicSqlRowsBatchResultAlloc(result.session_id, result.statement_kind, rows_batch),
            .mutation_source => |mutation_source| try self.encodePublicSqlRowsMutationSourceResultAlloc(result.session_id, result.statement_kind, mutation_source),
        };
    }

    fn publicSqlDdlCommandTag(parsed_sql: *const sql_adapter.ParsedSql) []const u8 {
        const tokens = parsed_sql.items();
        const raw = parsed_sql.raw_statement;
        if (raw.token_start >= raw.token_end or raw.token_end > tokens.len) return "DDL";
        const first = tokens[raw.token_start];
        if (first.matchesKeywordTag(.create)) return publicSqlCreateDdlCommandTag(tokens[raw.token_start + 1 .. raw.token_end]);
        if (first.matchesKeywordTag(.alter)) return publicSqlDdlObjectCommandTag("ALTER", tokens[raw.token_start + 1 .. raw.token_end]);
        if (first.matchesKeywordTag(.drop)) return publicSqlDdlObjectCommandTag("DROP", tokens[raw.token_start + 1 .. raw.token_end]);
        if (first.matchesKeywordTag(.truncate)) return "TRUNCATE";
        if (first.matchesKeywordTag(.grant)) return "GRANT";
        if (first.matchesKeywordTag(.revoke)) return "REVOKE";
        if (first.matchesKeywordTag(.set)) return "SET";
        if (first.matchesKeywordTag(.show)) return "SHOW";
        if (first.matchesKeywordTag(.reset)) return "RESET";
        if (first.matchesKeywordTag(.discard)) return "DISCARD";
        if (first.matchesKeywordTag(.begin)) return "BEGIN";
        if (first.matchesKeyword("start") and raw.token_start + 1 < raw.token_end and tokens[raw.token_start + 1].matchesKeyword("transaction")) return "BEGIN";
        if (first.matchesKeywordTag(.commit)) return "COMMIT";
        if (first.matchesKeywordTag(.rollback)) return "ROLLBACK";
        if (first.matchesKeywordTag(.listen)) return "LISTEN";
        if (first.matchesKeywordTag(.notify)) return "NOTIFY";
        if (first.matchesKeywordTag(.unlisten)) return "UNLISTEN";
        if (first.matchesKeywordTag(.prepare)) return "PREPARE";
        if (first.matchesKeywordTag(.execute)) return "EXECUTE";
        if (first.matchesKeywordTag(.deallocate)) return "DEALLOCATE";
        if (first.matchesKeywordTag(.call)) return "CALL";
        return "DDL";
    }

    fn publicSqlCreateDdlCommandTag(tokens: []const sql_adapter.Token) []const u8 {
        var index: usize = 0;
        while (index < tokens.len and publicSqlCreateDdlModifier(tokens[index])) : (index += 1) {}
        if (index >= tokens.len) return "CREATE";
        if (tokens[index].matchesKeywordTag(.index)) return "CREATE INDEX";
        return publicSqlDdlObjectCommandTag("CREATE", tokens[index..]);
    }

    fn publicSqlCreateDdlModifier(token: sql_adapter.Token) bool {
        return token.matchesKeywordTag(.unique) or
            token.matchesKeywordTag(.@"or") or
            token.matchesKeywordTag(.replace) or
            token.matchesKeyword("temporary") or
            token.matchesKeyword("temp") or
            token.matchesKeyword("unlogged") or
            token.matchesKeyword("concurrently");
    }

    fn publicSqlDdlObjectCommandTag(comptime verb: []const u8, tokens: []const sql_adapter.Token) []const u8 {
        for (tokens) |token| {
            if (publicSqlDdlObjectModifier(token)) continue;
            if (token.matchesKeywordTag(.table)) return verb ++ " TABLE";
            if (token.matchesKeywordTag(.index)) return verb ++ " INDEX";
            if (token.matchesKeywordTag(.database)) return verb ++ " DATABASE";
            if (token.matchesKeywordTag(.schema)) return verb ++ " SCHEMA";
            if (token.matchesKeyword("tablespace")) return verb ++ " TABLESPACE";
            if (token.matchesKeywordTag(.extension)) return verb ++ " EXTENSION";
            if (token.matchesKeyword("role")) return verb ++ " ROLE";
            if (token.matchesKeywordTag(.function)) return verb ++ " FUNCTION";
            if (token.matchesKeywordTag(.procedure)) return verb ++ " PROCEDURE";
            if (token.matchesKeywordTag(.trigger)) return verb ++ " TRIGGER";
            if (token.matchesKeywordTag(.view)) return verb ++ " VIEW";
            if (token.matchesKeywordTag(.policy)) return verb ++ " POLICY";
            return verb;
        }
        return verb;
    }

    fn publicSqlDdlObjectModifier(token: sql_adapter.Token) bool {
        return token.matchesKeywordTag(.@"if") or
            token.matchesKeywordTag(.not) or
            token.matchesKeywordTag(.exists) or
            token.matchesKeywordTag(.only) or
            token.matchesKeyword("concurrently") or
            token.matchesKeywordTag(.@"or") or
            token.matchesKeywordTag(.replace) or
            token.matchesKeyword("temporary") or
            token.matchesKeyword("temp") or
            token.matchesKeyword("unlogged");
    }

    fn applyLoweredPublicSqlRowsBatch(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !?http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");

        self.applyLoweredPublicSqlRowsBatchBeforeTriggers(table_name, schema, rows_batch) catch |err| switch (err) {
            error.InvalidRowsRequest, error.RoutineBodyNotExecutable, error.RoutineNotFound => return try textResponse(self.alloc, 400, "invalid sql write"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 501, "unsupported sql statement"),
            else => return err,
        };

        if (rows_batch.writes.len == 0 and rows_batch.deletes.len == 0 and rows_batch.transforms.len == 0 and rows_batch.predicates.len == 0) return null;

        self.requireRowsBatchSatisfiesEffectiveFilterForDatabase(tables_api.default_database_name, table_name, null, rows_batch.*, authenticated_identity) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "row filter rejected sql write"),
            else => return err,
        };

        var committed_via_txn = false;
        if (schema.storage_mode == .relational) {
            const txn_writes = try self.alloc.alloc(db_mod.types.TransactionWrite, rows_batch.writes.len);
            defer self.alloc.free(txn_writes);
            for (rows_batch.writes, 0..) |write, i| {
                txn_writes[i] = .{ .key = write.key, .value = write.value };
            }
            const txn_tables = [_]distributed_txn.TableCommitRequest{.{
                .table_name = table_name,
                .writes = txn_writes,
                .deletes = rows_batch.deletes,
                .transforms = rows_batch.transforms,
                .predicates = rows_batch.predicates,
            }};
            if (source.commitTransaction(self.alloc, txn_tables[0..], rows_batch.req.sync_level) catch |err| switch (err) {
                error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid sql write"),
                error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return try textResponse(self.alloc, 409, "version conflict"),
                error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
                error.TableNotFound, error.UnknownGroup => {
                    std.log.err("public sql write transaction not found table={s} err={}", .{ table_name, err });
                    return try textResponse(self.alloc, 404, "not found");
                },
                error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                error.UnsupportedOperation => null,
                else => {
                    std.log.err("public sql write transaction failed table={s} err={}", .{ table_name, err });
                    return try textResponse(self.alloc, 500, "sql write failed");
                },
            }) |outcome| {
                switch (outcome) {
                    .committed => committed_via_txn = true,
                    .conflict => return try textResponse(self.alloc, 409, "version conflict"),
                }
            }
        }

        if (!committed_via_txn) {
            _ = (source.batch(self.alloc, table_name, rows_batch.req) catch |err| switch (err) {
                error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid sql write"),
                error.VersionConflict, error.IntentConflict => return try textResponse(self.alloc, 409, "version conflict"),
                error.TableNotFound => {
                    std.log.err("public sql write batch not found table={s} err={}", .{ table_name, err });
                    return try textResponse(self.alloc, 404, "not found");
                },
                error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                else => {
                    std.log.err("public sql write batch failed table={s} err={}", .{ table_name, err });
                    return try textResponse(self.alloc, 500, "sql write failed");
                },
            }) orelse return try textResponse(self.alloc, 404, "not found");
        }
        return null;
    }

    fn applyLoweredPublicSqlRowsBatchBeforeTriggers(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
    ) !void {
        var insert_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .insert);
        defer if (insert_trigger) |*trigger| trigger.deinit(self.alloc);
        var update_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .update);
        defer if (update_trigger) |*trigger| trigger.deinit(self.alloc);
        var delete_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .delete);
        defer if (delete_trigger) |*trigger| trigger.deinit(self.alloc);

        if (update_trigger != null and rows_batch.transforms.len != 0) return error.UnsupportedOperation;
        if (delete_trigger != null and rows_batch.deletes.len != 0) return error.UnsupportedOperation;
        if (insert_trigger == null or rows_batch.writes.len == 0) return;
        if (rows_batch.transforms.len != 0 or rows_batch.deletes.len != 0 or rows_batch.relational_identity_rewrites.len != 0) return error.UnsupportedOperation;
        if (rows_batch.predicates.len != rows_batch.writes.len) return error.UnsupportedOperation;
        if (rows_batch.returning_rows.len != 0 and rows_batch.returning_rows.len != rows_batch.writes.len) return error.UnsupportedOperation;

        try self.applyLoweredPublicSqlRowsBatchBeforeInsertTrigger(table_name, schema, insert_trigger.?, rows_batch);
    }

    fn applyLoweredPublicSqlRowsBatchBeforeInsertTrigger(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        insert_trigger: RowsBatchTrigger,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
    ) !void {
        _ = table_name;
        var writes = std.ArrayListUnmanaged(db_mod.types.BatchWrite).empty;
        var predicates = std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate).empty;
        var returning_rows = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            writes.deinit(self.alloc);
            for (predicates.items) |predicate| self.alloc.free(@constCast(predicate.key));
            predicates.deinit(self.alloc);
            for (returning_rows.items) |row| self.alloc.free(@constCast(row));
            returning_rows.deinit(self.alloc);
        }

        for (rows_batch.writes, 0..) |write, i| {
            const triggered_row = try self.sql_routine_runtime.executeTriggerRoutineAlloc(self.alloc, insert_trigger.function_name, write.value, null);
            defer self.alloc.free(triggered_row);
            var parsed_triggered = std.json.parseFromSlice(std.json.Value, self.alloc, triggered_row, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
            defer parsed_triggered.deinit();
            if (parsed_triggered.value == .null) continue;
            if (parsed_triggered.value != .object) return error.InvalidRowsRequest;

            const key = try relational_rows_api.physicalPrimaryKeyFromRowJsonAlloc(self.alloc, schema, triggered_row);
            var key_transferred = false;
            errdefer if (!key_transferred) self.alloc.free(key);
            const value = try self.alloc.dupe(u8, triggered_row);
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value);
            try writes.append(self.alloc, .{ .key = key, .value = value });
            key_transferred = true;
            value_transferred = true;

            const predicate_key = try self.alloc.dupe(u8, key);
            var predicate_key_transferred = false;
            errdefer if (!predicate_key_transferred) self.alloc.free(predicate_key);
            try predicates.append(self.alloc, .{
                .key = predicate_key,
                .expected_version = rows_batch.predicates[i].expected_version,
            });
            predicate_key_transferred = true;

            if (rows_batch.returning_rows.len != 0) {
                const returning_row = try self.alloc.dupe(u8, rows_batch.returning_rows[i]);
                var returning_row_transferred = false;
                errdefer if (!returning_row_transferred) self.alloc.free(returning_row);
                try returning_rows.append(self.alloc, returning_row);
                returning_row_transferred = true;
            }
        }

        const writes_slice = try writes.toOwnedSlice(self.alloc);
        errdefer {
            for (writes_slice) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            if (writes_slice.len > 0) self.alloc.free(writes_slice);
        }
        const predicates_slice = try predicates.toOwnedSlice(self.alloc);
        errdefer {
            for (predicates_slice) |predicate| self.alloc.free(@constCast(predicate.key));
            if (predicates_slice.len > 0) self.alloc.free(predicates_slice);
        }
        const returning_rows_slice = try returning_rows.toOwnedSlice(self.alloc);
        errdefer {
            for (returning_rows_slice) |row| self.alloc.free(@constCast(row));
            if (returning_rows_slice.len > 0) self.alloc.free(returning_rows_slice);
        }

        var triggered_req = relational_rows_api.OwnedRowsBatchRequest{
            .writes = writes_slice,
            .predicates = predicates_slice,
            .returning_rows = returning_rows_slice,
            .req = .{
                .writes = writes_slice,
                .predicates = predicates_slice,
                .timestamp_ns = rows_batch.req.timestamp_ns,
                .sync_level = rows_batch.req.sync_level,
            },
            .inserted = @intCast(writes_slice.len),
        };
        errdefer triggered_req.deinit(self.alloc);
        rows_batch.deinit(self.alloc);
        rows_batch.* = triggered_req;
    }

    fn applyLoweredPublicSqlInsertSource(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredInsertSource,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };

        const source_table_name = rowsPlanEffectiveSideTable(target_table_name, lowered.insert_source.req.source_table);
        ensureRowsPlanTableReadable(authenticated_identity, source_table_name) catch |err| switch (err) {
            error.PermissionDenied => return .{ .failure = try textResponse(self.alloc, 403, "forbidden") },
        };

        const source_schema = self.runtimeSchemaForPublicRows(source_table_name) catch |err| switch (err) {
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.InvalidRowsRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var filter = self.rowsAuthFilterPlanForIdentity(source_table_name, authenticated_identity, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (filter) |*value| value.deinit(self.alloc);
        if (filter) |active| {
            for (@constCast(lowered.ctes)) |*cte| try self.applyRowsAuthFilterToQuery(source_schema, active, &cte.query);
            if (lowered.insert_source.req.source.source_cte.len == 0) try self.applyRowsAuthFilterToQuery(source_schema, active, &lowered.insert_source.req.source);
        }

        var source_result = (read_source.rowsQueryPlan(
            self.alloc,
            source_table_name,
            source_schema,
            .{
                .ctes = lowered.ctes,
                .query = lowered.insert_source.req.source,
            },
            .read_index,
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            else => {
                std.log.err("public sql insert source read failed table={s} source={s} err={}", .{ target_table_name, source_table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        defer source_result.deinit(self.alloc);

        const planned_ctes = relational_rows_api.planRowsCteOutputsAlloc(self.alloc, source_schema, lowered.ctes) catch |err| switch (err) {
            error.InvalidRowsRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            else => return err,
        };
        defer relational_rows_api.freeRowsPlannedCtes(self.alloc, planned_ctes);
        const effective_source_schema = relational_rows_api.rowsPlannedQuerySourceSchema(source_schema, planned_ctes, lowered.insert_source.req.source) orelse return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") };

        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        var rows_batch = relational_rows_api.buildRowsInsertSourceBatchWithSchemasAlloc(
            self.alloc,
            target_table_name,
            target_schema,
            effective_source_schema,
            lowered.insert_source.req,
            source_result.rows,
            unique_resolver_ctx.resolver(),
        ) catch |err| switch (err) {
            error.UnsupportedRowsSelector => return .{ .failure = try textResponse(self.alloc, 400, "unsupported rows selector") },
            error.RowSelectorNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "unique owner unavailable") },
            error.InvalidRowsRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            else => {
                std.log.err("public sql insert source plan failed table={s} source={s} err={}", .{ target_table_name, source_table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        };
        defer rows_batch.deinit(self.alloc);
        rows_batch.req.sync_level = lowered.sync_level;

        if (try self.applyLoweredPublicSqlRowsBatch(target_table_name, target_schema, &rows_batch, authenticated_identity)) |failure| return .{ .failure = failure };
        return .{ .result = try rowsInsertSourceMutationResultAlloc(self.alloc, source_result.rows.len, rows_batch) };
    }

    fn nextSqlMutationTxnId() db_mod.types.TxnId {
        const nonce = sql_mutation_txn_id_nonce.fetchAdd(1, .monotonic);
        var txn_id: db_mod.types.TxnId = undefined;
        std.mem.writeInt(u64, txn_id[0..8], platform_time.realtimeNs(), .big);
        std.mem.writeInt(u64, txn_id[8..16], nonce, .big);
        return txn_id;
    }

    fn sqlMutationRowClaimAlloc(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) !db_mod.types.RowClaimRequest {
        const session_id = self.ensureSqlProtocolSessionId(session);
        return .{
            .mode = .for_update,
            .wait_policy = .wait,
            .skip_locked = false,
            .lease_ms = 30_000,
            .owner_id = try std.fmt.allocPrint(self.alloc, "sql:{d}", .{session_id}),
            .txn_id = nextSqlMutationTxnId(),
        };
    }

    fn ensureNoPublicSqlMutationSourceTrigger(
        self: *ApiHttpServer,
        table_name: []const u8,
        kind: db_mod.types.RelationalRowsMutationKind,
    ) !void {
        const event: sql_routines.TriggerEvent = switch (kind) {
            .update => .update,
            .delete => .delete,
        };
        var trigger = try self.rowsBatchTriggerForEventAlloc(table_name, event);
        defer if (trigger) |*value| value.deinit(self.alloc);
        if (trigger != null) return error.UnsupportedOperation;
    }

    fn applyLoweredPublicSqlMutationSource(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredMutationSource,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const source = self.table_writes orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        self.ensureNoPublicSqlMutationSourceTrigger(target_table_name, lowered.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            else => return err,
        };

        var filter = self.rowsAuthFilterPlanForIdentity(target_table_name, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (filter) |*value| value.deinit(self.alloc);
        if (filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, &lowered.mutation.req.source);
        }

        const result = (source.mutateRowsFromSourceAutocommit(
            self.alloc,
            target_table_name,
            target_schema,
            lowered.mutation.req,
            lowered.sync_level,
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return .{ .failure = try textResponse(self.alloc, 409, "version conflict") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.TableNotFound, error.UnknownGroup => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") },
            error.EnrichmentRetryInProgress => return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") },
            else => {
                std.log.err("public sql mutation source failed table={s} err={}", .{ target_table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        return .{ .result = result };
    }

    fn joinedMutationTargetQuery(req: *db_mod.types.RelationalRowsJoinedMutationSourceRequest) *db_mod.types.RelationalRowsQueryRequest {
        return switch (req.target_side) {
            .left => &req.join.left,
            .right => &req.join.right,
        };
    }

    fn joinedMutationSourceQuery(req: *db_mod.types.RelationalRowsJoinedMutationSourceRequest) *db_mod.types.RelationalRowsQueryRequest {
        return switch (req.target_side) {
            .left => &req.join.right,
            .right => &req.join.left,
        };
    }

    fn applyLoweredPublicSqlJoinedMutationSource(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredJoinedMutationSource,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        const write_source = self.table_writes orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        self.ensureNoPublicSqlMutationSourceTrigger(target_table_name, lowered.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            else => return err,
        };

        const source_table_name = rowsPlanEffectiveSideTable(target_table_name, lowered.source_table_name);
        ensureRowsPlanTableReadable(authenticated_identity, source_table_name) catch |err| switch (err) {
            error.PermissionDenied => return .{ .failure = try textResponse(self.alloc, 403, "forbidden") },
        };

        const source_schema = if (std.mem.eql(u8, source_table_name, target_table_name))
            target_schema
        else
            sql_adapter.runtimeSchemaForCatalogTableWithSessionAlloc(
                self.alloc,
                self.catalogSource(),
                source_table_name,
                session,
            ) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                else => return err,
            };
        defer if (!std.mem.eql(u8, source_table_name, target_table_name)) runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var target_filter = self.rowsAuthFilterPlanForIdentity(target_table_name, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, joinedMutationTargetQuery(&lowered.mutation.req));
        }

        var source_filter = self.rowsAuthFilterPlanForIdentity(source_table_name, authenticated_identity, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (source_filter) |*value| value.deinit(self.alloc);
        if (source_filter) |active| {
            for (@constCast(lowered.mutation.req.ctes)) |*cte| try self.applyRowsAuthFilterToQuery(source_schema, active, &cte.query);
            try self.applyRowsAuthFilterToQuery(source_schema, active, joinedMutationSourceQuery(&lowered.mutation.req));
        }

        var source_result = (read_source.rowsQueryPlan(
            self.alloc,
            source_table_name,
            source_schema,
            .{
                .ctes = lowered.mutation.req.ctes,
                .query = joinedMutationSourceQuery(&lowered.mutation.req).*,
            },
            .read_index,
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            else => {
                std.log.err("public sql joined mutation source read failed table={s} source={s} err={}", .{ target_table_name, source_table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        defer source_result.deinit(self.alloc);

        const result = (write_source.mutateRowsJoinedFromSourceRowsAutocommit(
            self.alloc,
            target_table_name,
            target_schema,
            source_schema,
            lowered.mutation.req,
            source_result.rows,
            lowered.sync_level,
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return .{ .failure = try textResponse(self.alloc, 409, "version conflict") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.TableNotFound, error.UnknownGroup => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") },
            error.EnrichmentRetryInProgress => return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") },
            else => {
                std.log.err("public sql joined mutation source failed table={s} source={s} err={}", .{ target_table_name, source_table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        return .{ .result = result };
    }

    fn applyLoweredPublicSqlRecursiveJoinedMutationSource(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: sql_adapter.LoweredRecursiveJoinedMutationSource,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        const write_source = self.table_writes orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        self.ensureNoPublicSqlMutationSourceTrigger(target_table_name, lowered.mutation.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            else => return err,
        };

        var target_filter = self.rowsAuthFilterPlanForIdentity(target_table_name, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter != null) return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") };

        const result = (table_writes.mutateRowsJoinedFromRecursiveCtePlanAutocommitWithSessionAlloc(
            self.alloc,
            read_source,
            write_source,
            self.catalogSource(),
            session,
            target_table_name,
            target_schema,
            target_schema,
            lowered,
            .read_index,
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return .{ .failure = try textResponse(self.alloc, 409, "version conflict") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.TableNotFound, error.UnknownGroup => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") },
            error.EnrichmentRetryInProgress => return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") },
            else => {
                std.log.err("public sql recursive joined mutation source failed table={s} cte={s} err={}", .{ target_table_name, lowered.recursive.cte_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        return .{ .result = result };
    }

    fn applyLoweredPublicSqlMergeMutation(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredMergeMutationPlan,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        batch: relational_rows_api.OwnedRowsBatchRequest,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        if (lowered.data_modifying_ctes.len != 0) {
            return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") };
        }

        const source_table_name = rowsPlanEffectiveSideTable(target_table_name, lowered.source_table_name);
        ensureRowsPlanTableReadable(authenticated_identity, source_table_name) catch |err| switch (err) {
            error.PermissionDenied => return .{ .failure = try textResponse(self.alloc, 403, "forbidden") },
        };

        const source_schema = if (std.mem.eql(u8, source_table_name, target_table_name))
            target_schema
        else
            sql_adapter.runtimeSchemaForCatalogTableWithSessionAlloc(
                self.alloc,
                self.catalogSource(),
                source_table_name,
                session,
            ) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                else => return err,
            };
        defer if (!std.mem.eql(u8, source_table_name, target_table_name)) runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var target_query: relational_rows_api.OwnedRowsQueryRequest = .{ .select_all = true };
        defer self.deinitRowsAuthFilterQueryAdditions(&target_query);
        var target_filter = self.rowsAuthFilterPlanForIdentity(target_table_name, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, &target_query);
        }

        var source_filter = self.rowsAuthFilterPlanForIdentity(source_table_name, authenticated_identity, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (source_filter) |*value| value.deinit(self.alloc);
        if (source_filter) |active| {
            for (@constCast(lowered.ctes)) |*cte| {
                try self.applyRowsAuthFilterToQuery(source_schema, active, &cte.query);
            }
            if (lowered.source.source_cte.len == 0) {
                try self.applyRowsAuthFilterToQuery(source_schema, active, &lowered.source);
            }
        }

        var batch = (table_reads.rowsMergeMutationBatchFromRoutedScansWithSchemasAlloc(
            self.alloc,
            read_source,
            target_table_name,
            source_table_name,
            target_schema,
            source_schema,
            lowered.*,
            target_query,
            &.{},
            lowered.source,
            &.{},
            .read_index,
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery, error.UnsupportedSqlShape => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            else => {
                std.log.err("public sql merge plan failed table={s} source={s} err={}", .{ target_table_name, source_table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        errdefer batch.deinit(self.alloc);

        if (try self.applyLoweredPublicSqlRowsBatch(target_table_name, target_schema, &batch, authenticated_identity)) |failure| return .{ .failure = failure };
        return .{ .batch = batch };
    }

    fn applyLoweredPublicSqlRecursiveMergeMutation(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: sql_adapter.LoweredRecursiveMergeMutation,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        batch: relational_rows_api.OwnedRowsBatchRequest,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };

        var target_filter = self.rowsAuthFilterPlanForIdentity(target_table_name, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter != null) return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") };

        var batch = (table_reads.rowsRecursiveMergeMutationBatchFromRoutedScansWithSchemasAndSessionAlloc(
            self.alloc,
            read_source,
            self.catalogSource(),
            session,
            target_table_name,
            target_table_name,
            target_schema,
            target_schema,
            lowered,
            .{ .select_all = true },
            &.{},
            .read_index,
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery, error.UnsupportedSqlShape => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            else => {
                std.log.err("public sql recursive merge plan failed table={s} cte={s} err={}", .{ target_table_name, lowered.recursive.cte_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        errdefer batch.deinit(self.alloc);

        if (try self.applyLoweredPublicSqlRowsBatch(target_table_name, target_schema, &batch, authenticated_identity)) |failure| return .{ .failure = failure };
        return .{ .batch = batch };
    }

    fn handlePublicSqlWrite(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .read_only_transaction).withMessage("cannot execute write statement in a read-only transaction")) };
        }

        const statement_kind = parsed_sql.writeStatementKind() orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
        switch (statement_kind) {
            .insert, .insert_source, .update, .update_source, .update_joined_source, .delete, .delete_source, .delete_joined_source, .truncate, .merge => {},
        }

        const write_catalog = switch (logical_plan.*) {
            .catalog_write => |*catalog_write| catalog_write,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        const target_binding = write_catalog.target_binding orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };
        const target = target_binding.target();
        const target_table = try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(target_table);
        const schema = try clonePublicSqlRuntimeSchemaAlloc(self.alloc, target_binding.schema());
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var lowered = sql_adapter_runtime.lowerWritePlanWithLogicalPlanAndFunctionBindingsAlloc(
            self.alloc,
            parsed_sql,
            logical_plan,
            schema,
            params,
            function_bindings,
        ) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => {
                std.log.err("public sql write lower not found table={s} err={}", .{ target_table, err });
                return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) };
            },
            error.DocumentSqlWriteUnsupported => return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.plan, .invalid_sql_write).withMessage("document_sql_write_unsupported").withMissingNativeModel("document SQL write execution")) },
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.UnsupportedRowsSelector, error.RowSelectorNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
            error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.plan, .unique_owner_unavailable)) },
            else => return err,
        };
        var lowered_owned = true;
        defer if (lowered_owned) lowered.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        if (lowered == .insert_source) {
            const returning_columns = self.publicSqlInsertSourceRequestReturningColumnsAlloc(schema, lowered.insert_source.insert_source.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const insert_source_result = switch (try self.applyLoweredPublicSqlInsertSource(target_table, schema, &lowered.insert_source, authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = insert_source_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .update_source or lowered == .delete_source) {
            const mutation_source = switch (lowered) {
                .update_source => |*update_source| update_source,
                .delete_source => |*delete_source| delete_source,
                else => unreachable,
            };
            const returning_columns = self.publicSqlMutationRequestReturningColumnsAlloc(schema, mutation_source.mutation.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const mutation_source_result = switch (try self.applyLoweredPublicSqlMutationSource(target_table, schema, mutation_source, authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = mutation_source_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .truncate_source) {
            if (lowered.truncate_source.additional_table_names.len != 0 or lowered.truncate_source.truncate_cascade or lowered.truncate_source.restart_identity) {
                return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
            }
            const truncate_result = switch (try self.applyLoweredPublicSqlMutationSource(target_table, schema, &lowered.truncate_source, authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{ .result = truncate_result } },
            } };
        }

        if (lowered == .update_joined_source or lowered == .delete_joined_source) {
            const joined_mutation_source = switch (lowered) {
                .update_joined_source => |*update_joined_source| update_joined_source,
                .delete_joined_source => |*delete_joined_source| delete_joined_source,
                else => unreachable,
            };
            const owned_source_schema = self.publicSqlSourceSchemaForWriteAlloc(target_table, joined_mutation_source.source_table_name, session.session()) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                else => return err,
            };
            defer if (owned_source_schema) |source_schema| runtime_schema_mod.freeSchema(self.alloc, source_schema);
            const joined_source_schema = owned_source_schema orelse schema;
            const returning_columns = self.publicSqlJoinedMutationRequestReturningColumnsAlloc(schema, joined_source_schema, joined_mutation_source.mutation.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const joined_mutation_result = switch (try self.applyLoweredPublicSqlJoinedMutationSource(target_table, schema, joined_mutation_source, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = joined_mutation_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .recursive_update_joined_source or lowered == .recursive_delete_joined_source) {
            const recursive_joined_mutation_source = switch (lowered) {
                .recursive_update_joined_source => |recursive_update_joined_source| recursive_update_joined_source,
                .recursive_delete_joined_source => |recursive_delete_joined_source| recursive_delete_joined_source,
                else => unreachable,
            };
            var recursive_source_schema = schema;
            recursive_source_schema.relational_columns = recursive_joined_mutation_source.recursive.output_columns;
            const returning_columns = self.publicSqlJoinedMutationRequestReturningColumnsAlloc(schema, recursive_source_schema, recursive_joined_mutation_source.mutation.mutation.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const recursive_joined_mutation_result = switch (try self.applyLoweredPublicSqlRecursiveJoinedMutationSource(target_table, schema, recursive_joined_mutation_source, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = recursive_joined_mutation_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .merge_mutation) {
            const owned_source_schema = self.publicSqlSourceSchemaForWriteAlloc(target_table, lowered.merge_mutation.source_table_name, session.session()) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                else => return err,
            };
            defer if (owned_source_schema) |source_schema| runtime_schema_mod.freeSchema(self.alloc, source_schema);
            const merge_source_schema = owned_source_schema orelse schema;
            const returning_columns = self.publicSqlReturningColumnsAlloc(schema, merge_source_schema, lowered.merge_mutation.returning) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const merge_batch = switch (try self.applyLoweredPublicSqlMergeMutation(target_table, schema, &lowered.merge_mutation, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .batch => |batch| batch,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .rows_batch = .{
                    .result = merge_batch,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .recursive_merge_mutation) {
            var recursive_source_schema = schema;
            recursive_source_schema.relational_columns = lowered.recursive_merge_mutation.recursive.output_columns;
            const returning_columns = self.publicSqlReturningColumnsAlloc(schema, recursive_source_schema, lowered.recursive_merge_mutation.merge.returning) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const merge_batch = switch (try self.applyLoweredPublicSqlRecursiveMergeMutation(target_table, schema, lowered.recursive_merge_mutation, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .batch => |batch| batch,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .rows_batch = .{
                    .result = merge_batch,
                    .columns = returning_columns,
                } },
            } };
        }

        const returning_projection = switch (lowered) {
            .insert => |*insert| insert.returning,
            .update => |*update| update.returning,
            .delete => |*delete| delete.returning,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        const returning_columns = self.publicSqlReturningColumnsAlloc(schema, null, returning_projection) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
            else => return err,
        };
        var returning_columns_owned = true;
        defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
        const rows_batch = switch (lowered) {
            .insert => |*insert| &insert.batch,
            .update => |*update| &update.batch,
            .delete => |*delete| &delete.batch,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        if (try self.applyLoweredPublicSqlRowsBatch(target_table, schema, rows_batch, authenticated_identity)) |failure| return .{ .response = failure };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const owned_rows_batch = rows_batch.*;
        switch (lowered) {
            .insert => |*insert| {
                self.alloc.free(insert.table_name);
                insert.returning.deinit(self.alloc);
                insert.returning = .{};
            },
            .update => |*update| {
                self.alloc.free(update.table_name);
                update.returning.deinit(self.alloc);
                update.returning = .{};
            },
            .delete => |*delete| {
                self.alloc.free(delete.table_name);
                delete.returning.deinit(self.alloc);
                delete.returning = .{};
            },
            else => unreachable,
        }
        lowered_owned = false;
        returning_columns_owned = false;
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .result = .{ .rows_batch = .{
                .result = owned_rows_batch,
                .columns = returning_columns,
            } },
        } };
    }

    fn handlePublicSqlRead(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const statement_kind = parsed_sql.readStatementKind() orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
        if (try self.handlePublicSqlQueryFunctionRead(parsed_sql, session, authenticated_identity, statement_kind)) |response| return response;
        const read_source = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };

        const read_catalog = switch (logical_plan.*) {
            .catalog_read => |*catalog_read| catalog_read,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        const target_binding = read_catalog.target_binding orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) };
        const target = target_binding.target();
        const target_table_name = try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(target_table_name);
        const source_table_name: []const u8 = if (read_catalog.source_binding) |binding|
            try self.alloc.dupe(u8, binding.target().table_name)
        else
            try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(source_table_name);
        const schema = try clonePublicSqlRuntimeSchemaAlloc(self.alloc, target_binding.schema());
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var lowered = sql_adapter_runtime.lowerReadPlanWithLogicalPlanAndFunctionBindingsAlloc(
            self.alloc,
            parsed_sql,
            logical_plan,
            schema,
            params,
            function_bindings,
        ) catch |err| {
            if (documentSqlReadErrorMessage(err)) |message| return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.plan, .invalid_sql_request).withMessage(message).withMissingNativeModel("document SQL read shape")) };
            switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
                error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
                else => return err,
            }
        };
        defer lowered.deinit(self.alloc);
        self.applyPublicSqlDocumentReadRowFilter(&lowered, session.session(), authenticated_identity) catch |err| switch (err) {
            error.InvalidQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const result_columns = self.publicSqlReadResultColumnsAlloc(
            target_table_name,
            schema,
            source_table_name,
            lowered,
            session.session(),
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        var result_columns_owned = true;
        defer if (result_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, result_columns);

        const result = (table_reads.executeLoweredSqlReadPlanWithSessionAlloc(
            self.alloc,
            read_source,
            self.catalogSource(),
            session.session(),
            target_table_name,
            schema,
            lowered,
            .read_index,
        ) catch |err| {
            if (documentSqlReadErrorMessage(err)) |message| return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .invalid_sql_request).withMessage(message).withMissingNativeModel("document SQL read execution")) };
            switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) },
                error.RelationalRowsCteSpillRequired => return .{ .response = try self.publicSqlDiagnosticResponse(429, .init(.execute, .sql_read_backpressured)) },
                error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.execute, .unsupported_sql_statement)) },
                error.TopologyChanged => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .topology_changed)) },
                else => return err,
            }
        }) orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        result_columns_owned = false;
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .result = .{ .read = .{
                .result = result,
                .columns = result_columns,
            } },
        } };
    }

    fn clonePublicSqlRuntimeSchemaAlloc(alloc: std.mem.Allocator, schema: runtime_schema_mod.TableSchema) !runtime_schema_mod.TableSchema {
        const serialized = try runtime_schema_mod.serializeSchema(alloc, schema);
        defer alloc.free(serialized);
        return try runtime_schema_mod.deserializeSchema(alloc, serialized);
