    fn describePublicSqlReadColumnsAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlDescribeResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const statement_kind = parsed_sql.readStatementKind() orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
        _ = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };

        var bound = sql_adapter.bindReadPlanCatalogStatementWithSessionAlloc(self.alloc, parsed_sql, self.catalogSource(), session.session()) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
            error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) },
            else => return err,
        };
        defer bound.deinit(self.alloc);
        const read_catalog = bound.readCatalog() catch |err| switch (err) {
            error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) },
        };
        const target_binding = read_catalog.target_binding orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) };
        const target = target_binding.target();
        const target_table_name = try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(target_table_name);
        const source_table_name: []const u8 = if (read_catalog.source_binding) |binding|
            try self.alloc.dupe(u8, binding.target().table_name)
        else
            try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(source_table_name);
        const schema = try clonePublicSqlRuntimeSchemaAlloc(self.alloc, target_binding.schema());
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var lowered = sql_adapter_runtime.lowerReadPlanWithBoundStatementAndFunctionBindingsAlloc(
            self.alloc,
            parsed_sql,
            &bound,
            schema,
            params,
            function_bindings,
        ) catch |err| {
            if (documentSqlReadErrorMessage(err)) |message| return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.plan, .invalid_sql_request).withMessage(message).withMissingNativeModel("document SQL read shape")) };
            switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
                error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
                else => return err,
            }
        };
        defer lowered.deinit(self.alloc);
        self.applyPublicSqlDocumentReadRowFilter(&lowered, session.session(), authenticated_identity) catch |err| switch (err) {
            error.InvalidQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const result_columns = self.publicSqlReadResultColumnsAlloc(
            target_table_name,
            schema,
            source_table_name,
            lowered,
            session.session(),
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        var result_columns_owned = true;
        defer if (result_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, result_columns);

        result_columns_owned = false;
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .has_row_description = true,
            .columns = result_columns,
        } };
    }

    fn applyPublicSqlDocumentReadRowFilter(
        self: *ApiHttpServer,
        lowered: *sql_adapter_runtime.LoweredReadPlan,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !void {
        switch (lowered.*) {
            .document_query => |*document_plan| {
                const row_filter_json = try self.resolvePublicSqlDocumentReadRowFilterJsonAlloc(session, authenticated_identity, document_plan.table_name);
                defer if (row_filter_json) |value| self.alloc.free(value);
                if (row_filter_json) |value| try sql_adapter.applyDocumentReadPlanFilterConstraintAlloc(self.alloc, document_plan, value);
            },
            .document_aggregate => |*aggregate_plan| {
                const row_filter_json = try self.resolvePublicSqlDocumentReadRowFilterJsonAlloc(session, authenticated_identity, aggregate_plan.table_name);
                defer if (row_filter_json) |value| self.alloc.free(value);
                if (row_filter_json) |value| try sql_adapter.applyDocumentAggregatePlanFilterConstraintAlloc(self.alloc, aggregate_plan, value);
            },
            else => {},
        }
    }

    fn clonePublicSqlReadColumnsAlloc(self: *ApiHttpServer, columns: []const runtime_schema_mod.RelationalColumn) ![]const runtime_schema_mod.RelationalColumn {
        var owned: std.ArrayListUnmanaged(runtime_schema_mod.RelationalColumn) = .empty;
        errdefer {
            for (owned.items) |column| {
                self.alloc.free(column.name);
                self.alloc.free(column.path);
                if (column.collation) |collation| self.alloc.free(collation);
            }
            owned.deinit(self.alloc);
        }
        for (columns) |column| {
            const name = try self.alloc.dupe(u8, column.name);
            errdefer self.alloc.free(name);
            const path = try self.alloc.dupe(u8, column.path);
            errdefer self.alloc.free(path);
            const collation = if (column.collation) |value| try self.alloc.dupe(u8, value) else null;
            errdefer if (collation) |value| self.alloc.free(value);
            var cloned = column;
            cloned.name = name;
            cloned.path = path;
            cloned.collation = collation;
            try owned.append(self.alloc, cloned);
        }
        return try owned.toOwnedSlice(self.alloc);
    }

    fn publicSqlReadResultColumnsAlloc(
        self: *ApiHttpServer,
        default_table_name: []const u8,
        default_schema: runtime_schema_mod.TableSchema,
        source_table_name: []const u8,
        lowered: sql_adapter_runtime.LoweredReadPlan,
        session: catalog_resources.SqlCatalogSession,
    ) ![]const runtime_schema_mod.RelationalColumn {
        switch (lowered) {
            .query => |query| {
                const owned_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, query.table_name, session);
                defer if (owned_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const runtime_schema = owned_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, runtime_schema, .{ .query = query.plan });
            },
            .document_query, .document_aggregate => return &.{},
            .set_operation => |set_operation| return try self.clonePublicSqlReadColumnsAlloc(set_operation.output_columns),
            .recursive_cte => |recursive_cte| return try self.clonePublicSqlReadColumnsAlloc(recursive_cte.output_columns),
            .aggregate => |aggregate| {
                const owned_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, aggregate.table_name, session);
                defer if (owned_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const runtime_schema = owned_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, runtime_schema, .{ .aggregate = aggregate.plan });
            },
            .window => |window| {
                const owned_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, window.table_name, session);
                defer if (owned_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const runtime_schema = owned_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, runtime_schema, .{ .window = window.plan });
            },
            .join => |join| {
                const owned_source_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, source_table_name, session);
                defer if (owned_source_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const source_schema = owned_source_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsWithSchemasAlloc(self.alloc, default_schema, default_schema, source_schema, .{ .join = join.asPlan() });
            },
            .lateral => |lateral| {
                const owned_source_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, source_table_name, session);
                defer if (owned_source_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const source_schema = owned_source_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsWithSchemasAlloc(self.alloc, default_schema, default_schema, source_schema, .{ .lateral = lateral.plan });
            },
        }
    }

