    }

    fn handlePublicSqlQueryFunctionRead(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
        statement_kind: sql_adapter.SqlReadStatementKind,
    ) !?PublicSqlResultOrResponse {
        var semantic_resolver = SemanticStatusResolver{
            .source = self.source,
            .antfly_provider = self.antfly_provider,
            .remote_content = self.cfg.remote_content,
            .inference_api_key = self.cfg.inference_api_key,
        };
        var lowered = sql_adapter.lowerAntflyQueryFunctionReadParsedSqlAlloc(self.alloc, self.semanticResolver(&semantic_resolver), parsed_sql) catch |err| switch (err) {
            error.UnsupportedSqlShape => return null,
            error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            error.ModelNotFound => return .{ .response = try modelNotFoundResponse(self.alloc) },
            else => return err,
        };
        defer lowered.deinit(self.alloc);

        const read_source = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };
        const target = session.session().tableTargetFromObjectName(lowered.table_name) catch |err| switch (err) {
            error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
        };
        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, target.database_name, resource_name);
        defer if (row_filter_json) |value| self.alloc.free(value);

        self.maybeRouteCatalogQueryToReadSchema(target, &lowered.request.req) catch |err| switch (err) {
            error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) },
            error.InvalidSchemaUpdateRequest, error.InvalidTableIndexMetadata => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        if (row_filter_json) |value| {
            injectRowFilterIntoSearchRequest(self.alloc, &lowered.request.req, value) catch return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) };
        }

        var query_response = query_blk: {
            if (read_source.queryCatalog(self.alloc, target, lowered.request.req, .read_index)) |result| {
                break :query_blk result;
            } else |err| switch (err) {
                error.UnsupportedOperation => {},
                error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) },
                error.ModelNotFound => return .{ .response = try modelNotFoundResponse(self.alloc) },
                error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) },
                error.DocIdentityNamespaceMismatch => return .{ .response = try self.publicSqlDiagnosticResponse(503, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .unique_owner_unavailable).withMessage("doc identity unavailable")) },
                else => return err,
            }
            const native_table_name = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, target);
            defer self.alloc.free(native_table_name);
            break :query_blk (read_source.query(self.alloc, native_table_name, lowered.request.req, .read_index) catch |err| switch (err) {
                error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) },
                error.ModelNotFound => return .{ .response = try modelNotFoundResponse(self.alloc) },
                error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) },
                error.DocIdentityNamespaceMismatch => return .{ .response = try self.publicSqlDiagnosticResponse(503, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .unique_owner_unavailable).withMessage("doc identity unavailable")) },
                else => return err,
            });
        } orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) };
        defer query_response.deinit(self.alloc);

        const rows_result = try sqlQueryFunctionRowsFromQueryResponseAlloc(self.alloc, query_response.json, lowered.projection_columns);
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .result = .{ .read = .{
                .result = .{ .document_query = rows_result },
            } },
        } };
    }

    fn sqlQueryFunctionRowsFromQueryResponseAlloc(
        alloc: std.mem.Allocator,
        response_json: []const u8,
        projection_columns: []const []const u8,
    ) !db_mod.types.RelationalRowsQueryResult {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, response_json, .{ .allocate = .alloc_always }) catch return error.InvalidQueryRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidQueryRequest;
        const responses_value = parsed.value.object.get("responses") orelse return error.InvalidQueryRequest;
        if (responses_value != .array or responses_value.array.items.len == 0) return error.InvalidQueryRequest;
        const first_response = responses_value.array.items[0];
        if (first_response != .object) return error.InvalidQueryRequest;
        const hits_value = first_response.object.get("hits") orelse return try sqlQueryFunctionRowsFromGraphEnvelopeAlloc(alloc, first_response, projection_columns);
        if (hits_value != .object) return error.InvalidQueryRequest;
        const total_value = hits_value.object.get("total") orelse return error.InvalidQueryRequest;
        const total = try sqlQueryFunctionU32FromJsonValue(total_value);
        const hit_items = hits_value.object.get("hits") orelse return error.InvalidQueryRequest;
        if (hit_items != .array) return error.InvalidQueryRequest;
        if (hit_items.array.items.len == 0) {
            if (try sqlQueryFunctionMaybeRowsFromGraphEnvelopeAlloc(alloc, first_response, projection_columns)) |rows| return rows;
        }

        const rows = try alloc.alloc([]const u8, hit_items.array.items.len);
        errdefer alloc.free(rows);
        var initialized: usize = 0;
        errdefer {
            for (rows[0..initialized]) |row| alloc.free(@constCast(row));
        }
        for (hit_items.array.items, 0..) |hit, i| {
            if (hit != .object) return error.InvalidQueryRequest;
            rows[i] = try sqlQueryFunctionHitRowAlloc(alloc, hit, projection_columns);
            initialized += 1;
        }
        return .{
            .rows = rows,
            .total = total,
        };
    }

    fn sqlQueryFunctionRowsFromGraphEnvelopeAlloc(
        alloc: std.mem.Allocator,
        first_response: std.json.Value,
        projection_columns: []const []const u8,
    ) !db_mod.types.RelationalRowsQueryResult {
        return (try sqlQueryFunctionMaybeRowsFromGraphEnvelopeAlloc(alloc, first_response, projection_columns)) orelse error.InvalidQueryRequest;
    }

    fn sqlQueryFunctionMaybeRowsFromGraphEnvelopeAlloc(
        alloc: std.mem.Allocator,
        first_response: std.json.Value,
        projection_columns: []const []const u8,
    ) !?db_mod.types.RelationalRowsQueryResult {
        if (try sqlQueryFunctionMaybeRowsFromGraphMetricResultsAlloc(alloc, first_response, projection_columns)) |rows| return rows;
        if (try sqlQueryFunctionMaybeRowsFromGraphResultsAlloc(alloc, first_response, projection_columns)) |rows| return rows;
        return null;
    }

    fn sqlQueryFunctionMaybeRowsFromGraphMetricResultsAlloc(
        alloc: std.mem.Allocator,
        first_response: std.json.Value,
        projection_columns: []const []const u8,
    ) !?db_mod.types.RelationalRowsQueryResult {
        const graph_metric_results = first_response.object.get("graph_metric_results") orelse return null;
        if (graph_metric_results != .object) return error.InvalidQueryRequest;

        var row_count: usize = 0;
        var count_it = graph_metric_results.object.iterator();
        while (count_it.next()) |entry| {
            if (entry.value_ptr.* != .object) return error.InvalidQueryRequest;
            const scores = entry.value_ptr.*.object.get("scores") orelse return error.InvalidQueryRequest;
            if (scores != .array) return error.InvalidQueryRequest;
            row_count += scores.array.items.len;
        }

        const rows = try alloc.alloc([]const u8, row_count);
        errdefer alloc.free(rows);
        var initialized: usize = 0;
        errdefer {
            for (rows[0..initialized]) |row| alloc.free(@constCast(row));
        }

        var it = graph_metric_results.object.iterator();
        while (it.next()) |entry| {
            const result = entry.value_ptr.*;
            const index_name = result.object.get("index_name") orelse return error.InvalidQueryRequest;
            if (index_name != .string) return error.InvalidQueryRequest;
            const metric = result.object.get("metric") orelse return error.InvalidQueryRequest;
            if (metric != .string) return error.InvalidQueryRequest;
            const scores = result.object.get("scores") orelse return error.InvalidQueryRequest;
            if (scores != .array) return error.InvalidQueryRequest;
            for (scores.array.items) |score| {
                if (score != .object) return error.InvalidQueryRequest;
                rows[initialized] = try sqlQueryFunctionGraphMetricRowAlloc(alloc, entry.key_ptr.*, index_name.string, metric.string, score, projection_columns);
                initialized += 1;
            }
        }

        return .{
            .rows = rows,
            .total = @intCast(row_count),
        };
    }

    fn sqlQueryFunctionMaybeRowsFromGraphResultsAlloc(
        alloc: std.mem.Allocator,
        first_response: std.json.Value,
        projection_columns: []const []const u8,
    ) !?db_mod.types.RelationalRowsQueryResult {
        const graph_results = first_response.object.get("graph_results") orelse return null;
        if (graph_results != .object) return error.InvalidQueryRequest;

        var row_count: usize = 0;
        var total: u32 = 0;
        var count_it = graph_results.object.iterator();
        while (count_it.next()) |entry| {
            if (entry.value_ptr.* != .object) return error.InvalidQueryRequest;
            const nodes = entry.value_ptr.*.object.get("nodes") orelse continue;
            if (nodes != .array) return error.InvalidQueryRequest;
            row_count += nodes.array.items.len;
            if (entry.value_ptr.*.object.get("total")) |total_value| {
                total += try sqlQueryFunctionU32FromJsonValue(total_value);
            } else {
                total += @intCast(nodes.array.items.len);
            }
        }

        const rows = try alloc.alloc([]const u8, row_count);
        errdefer alloc.free(rows);
        var initialized: usize = 0;
        errdefer {
            for (rows[0..initialized]) |row| alloc.free(@constCast(row));
        }

        var it = graph_results.object.iterator();
        while (it.next()) |entry| {
            const result = entry.value_ptr.*;
            const result_type = result.object.get("type") orelse return error.InvalidQueryRequest;
            if (result_type != .string) return error.InvalidQueryRequest;
            const nodes = result.object.get("nodes") orelse continue;
            if (nodes != .array) return error.InvalidQueryRequest;
            for (nodes.array.items) |node| {
                if (node != .object) return error.InvalidQueryRequest;
                rows[initialized] = try sqlQueryFunctionGraphNodeRowAlloc(alloc, entry.key_ptr.*, result_type.string, node, projection_columns);
                initialized += 1;
            }
        }

        return .{
            .rows = rows,
            .total = total,
        };
    }

    fn sqlQueryFunctionU32FromJsonValue(value: std.json.Value) !u32 {
        return switch (value) {
            .integer => |int| if (int >= 0 and int <= std.math.maxInt(u32)) @as(u32, @intCast(int)) else return error.InvalidQueryRequest,
            .number_string => |text| std.fmt.parseUnsigned(u32, text, 10) catch return error.InvalidQueryRequest,
            else => return error.InvalidQueryRequest,
        };
    }

    fn sqlQueryFunctionGraphMetricRowAlloc(
        alloc: std.mem.Allocator,
        name: []const u8,
        index_name: []const u8,
        metric: []const u8,
        score: std.json.Value,
        projection_columns: []const []const u8,
    ) ![]const u8 {
        const node = score.object.get("node") orelse return error.InvalidQueryRequest;
        if (node != .string) return error.InvalidQueryRequest;
        const score_value = score.object.get("score") orelse return error.InvalidQueryRequest;

        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        try writer.writeAll("\"_id\":");
        try std.json.Stringify.value(node, .{}, writer);
        try writer.writeAll(",\"_score\":");
        try std.json.Stringify.value(score_value, .{}, writer);
        try writer.writeAll(",\"_source\":null,\"_graph_metric\":");
        try std.json.Stringify.value(name, .{}, writer);
        try writer.writeAll(",\"_index\":");
        try std.json.Stringify.value(index_name, .{}, writer);
        try writer.writeAll(",\"_metric\":");
        try std.json.Stringify.value(metric, .{}, writer);
        try writer.writeByte('}');
        return try sqlQueryFunctionMaybeProjectOwnedRowAlloc(alloc, try out.toOwnedSlice(), projection_columns);
    }

    fn sqlQueryFunctionGraphNodeRowAlloc(
        alloc: std.mem.Allocator,
        name: []const u8,
        result_type: []const u8,
        node: std.json.Value,
        projection_columns: []const []const u8,
    ) ![]const u8 {
        const key = node.object.get("key") orelse return error.InvalidQueryRequest;
        if (key != .string) return error.InvalidQueryRequest;

        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        try writer.writeAll("\"_id\":");
        try std.json.Stringify.value(key, .{}, writer);
        try writer.writeAll(",\"_score\":null,\"_source\":");
        if (node.object.get("document")) |document| {
            try std.json.Stringify.value(document, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
        try writer.writeAll(",\"_graph\":");
        try std.json.Stringify.value(name, .{}, writer);
        try writer.writeAll(",\"_graph_type\":");
        try std.json.Stringify.value(result_type, .{}, writer);
        try writer.writeAll(",\"_depth\":");
        if (node.object.get("depth")) |depth| {
            try std.json.Stringify.value(depth, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
        try writer.writeAll(",\"_distance\":");
        if (node.object.get("distance")) |distance| {
            try std.json.Stringify.value(distance, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
        try writer.writeAll(",\"_node\":");
        try std.json.Stringify.value(node, .{}, writer);
        try writer.writeByte('}');
        return try sqlQueryFunctionMaybeProjectOwnedRowAlloc(alloc, try out.toOwnedSlice(), projection_columns);
    }

    fn sqlQueryFunctionMaybeProjectOwnedRowAlloc(
        alloc: std.mem.Allocator,
        row_json: []const u8,
        projection_columns: []const []const u8,
    ) ![]const u8 {
        if (projection_columns.len == 0) return row_json;
        defer alloc.free(@constCast(row_json));
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{ .allocate = .alloc_always }) catch return error.InvalidQueryRequest;
        defer parsed.deinit();
        return try sqlQueryFunctionHitRowAlloc(alloc, parsed.value, projection_columns);
    }

    fn sqlQueryFunctionHitRowAlloc(
        alloc: std.mem.Allocator,
        hit: std.json.Value,
        projection_columns: []const []const u8,
    ) ![]const u8 {
        if (projection_columns.len == 0) return try std.json.Stringify.valueAlloc(alloc, hit, .{});
        if (hit != .object) return error.InvalidQueryRequest;
        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        for (projection_columns, 0..) |column, i| {
            if (i != 0) try writer.writeByte(',');
            try std.json.Stringify.value(column, .{}, writer);
            try writer.writeByte(':');
            if (hit.object.get(column)) |value| {
                try std.json.Stringify.value(value, .{}, writer);
            } else {
                try writer.writeAll("null");
            }
        }
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn documentSqlReadErrorMessage(err: anyerror) ?[]const u8 {
        return switch (err) {
            error.DocumentSqlIndexUnavailable => "document_sql_index_unavailable",
            error.DocumentSqlRequiresBoundedScan => "document_sql_requires_bounded_scan",
            error.DocumentSqlArrayRequiresUnnest => "document_sql_array_requires_unnest",
            error.DocumentSqlUnsupportedJoin => "document_sql_unsupported_join",
            error.DocumentSqlNativeSearchRequiresTableFunction => "document_sql_native_search_requires_table_function",
            error.DocumentSqlProjectionModifierUnsupported => "document_sql_projection_modifier_unsupported",
            error.DocumentSqlPaginationUnsupported => "document_sql_pagination_unsupported",
            error.DocumentSqlLockingUnsupported => "document_sql_locking_unsupported",
            error.DocumentSqlWindowUnsupported => "document_sql_window_unsupported",
            else => null,
        };
    }

    pub fn handlePublicSql(self: *ApiHttpServer, body: []const u8, authenticated_identity: ?AuthenticatedIdentity) !http_common.HttpResponse {
        var parsed = std.json.parseFromSlice(PublicSqlJsonRequest, self.alloc, body, .{
            .ignore_unknown_fields = true,
            .allocate = .alloc_always,
        }) catch return try self.publicSqlDiagnosticResponse(400, .init(.parse, .invalid_sql_request));
        defer parsed.deinit();
        var params = publicSqlParamsFromJsonAlloc(self.alloc, parsed.value.params) catch return try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request));
        defer params.deinit(self.alloc);
        return try self.handlePublicSqlRequest(.{
            .sql = parsed.value.sql,
            .session_id = parsed.value.session_id,
            .database = parsed.value.database,
            .namespace = parsed.value.namespace,
            .read_only = parsed.value.read_only,
            .params = params.values,
        }, authenticated_identity);
    }

    fn publicSqlDiagnosticResponse(
        self: *ApiHttpServer,
        status: u16,
        diagnostic: sql_adapter.diagnostics.SqlDiagnosticEnvelope,
    ) !http_common.HttpResponse {
        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, status, .{ .@"error" = diagnostic });
    }

    fn publicSqlParsedDiagnosticResponse(
        self: *ApiHttpServer,
        status: u16,
        parsed_sql: *const sql_adapter.ParsedSql,
        diagnostic: sql_adapter.diagnostics.SqlDiagnosticEnvelope,
    ) !http_common.HttpResponse {
        return try self.publicSqlDiagnosticResponse(status, diagnostic.withSpan(parsed_sql.statement.raw().source_span));
    }

    pub fn handlePublicSqlRequest(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !http_common.HttpResponse {
        var outcome = try self.executePublicSqlRequestResult(request, authenticated_identity);
        switch (outcome) {
            .response => |response| return response,
            .result => |*result| {
                const body = try self.encodePublicSqlResultAlloc(result.*);
                defer self.alloc.free(body);
                const response = try jsonBodyResponseWithStatus(self.alloc, 200, body);
                result.deinit(self.alloc);
                return response;
            },
        }
    }

    const PostgresCompatibilityScalar = struct {
        column_name: []const u8,
        value: []u8,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.value);
            self.* = undefined;
        }
    };

    const PostgresCompatibilitySetting = struct {
        name: []const u8,
        value: []u8,
        description: []const u8,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.value);
            self.* = undefined;
        }
    };

    const PostgresCompatibilityInformationSchemaView = enum {
        tables,
        columns,
    };

    const PostgresCompatibilityInformationSchemaFilters = struct {
        table_catalog: ?[]const u8 = null,
        table_schema: ?[]const u8 = null,
        table_name: ?[]const u8 = null,
    };

    const PostgresCompatibilityInformationSchemaOrderKey = struct {
        column: []const u8,
        descending: bool = false,
    };

    const PostgresCompatibilityInformationSchemaTail = struct {
        filters: PostgresCompatibilityInformationSchemaFilters = .{},
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey = &.{},

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.order_by.len != 0) alloc.free(self.order_by);
            self.* = undefined;
        }
    };

    const PostgresCompatibilityInformationSchemaQuery = struct {
        view: PostgresCompatibilityInformationSchemaView,
        columns: []const []const u8,
        filters: PostgresCompatibilityInformationSchemaFilters = .{},
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey = &.{},

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.columns);
            if (self.order_by.len != 0) alloc.free(self.order_by);
            self.* = undefined;
        }
    };

    const PostgresCompatibilityInformationSchemaSortValue = union(enum) {
        text: []const u8,
        number: usize,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            switch (self.*) {
                .text => |value| alloc.free(@constCast(value)),
                .number => {},
            }
            self.* = undefined;
        }
    };

    const PostgresCompatibilityRenderedInformationSchemaRow = struct {
        row: []const u8,
        sort_values: []PostgresCompatibilityInformationSchemaSortValue = &.{},

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.row.len != 0) alloc.free(@constCast(self.row));
            for (self.sort_values) |*value| value.deinit(alloc);
            if (self.sort_values.len != 0) alloc.free(self.sort_values);
            self.* = undefined;
        }
    };

    fn handlePublicSqlPostgresCompatibilityRead(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
    ) !?PublicSqlResultOrResponse {
        if (try self.postgresCompatibilityScalarAlloc(parsed_sql, session.session())) |scalar_value| {
            var scalar = scalar_value;
            defer scalar.deinit(self.alloc);
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = "query",
                .result = .{ .read = try self.publicSqlPostgresCompatibilityScalarReadAlloc(scalar.column_name, scalar.value) },
            } };
        }

        if (try self.postgresCompatibilityInformationSchemaQueryAlloc(parsed_sql)) |query_value| {
            var query = query_value;
            defer query.deinit(self.alloc);
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = "query",
                .result = .{ .read = try self.publicSqlPostgresCompatibilityInformationSchemaReadAlloc(query, session.session()) },
            } };
        }

        if (self.postgresCompatibilityShowAll(parsed_sql)) {
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = "query",
                .result = .{ .read = try self.publicSqlPostgresCompatibilityShowAllReadAlloc(session.session()) },
            } };
        }

        return null;
    }

    fn describePublicSqlPostgresCompatibilityReadAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
    ) !?PublicSqlDescribeResult {
        if (try self.postgresCompatibilityScalarAlloc(parsed_sql, session.session())) |scalar_value| {
            var scalar = scalar_value;
            defer scalar.deinit(self.alloc);
            return .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = "query",
                .has_row_description = true,
                .columns = try self.publicSqlPostgresCompatibilityColumnsAlloc(&.{scalar.column_name}),
            };
        }
        if (try self.postgresCompatibilityInformationSchemaQueryAlloc(parsed_sql)) |query_value| {
            var query = query_value;
            defer query.deinit(self.alloc);
            return .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = "query",
                .has_row_description = true,
                .columns = try self.publicSqlPostgresCompatibilityColumnsAlloc(query.columns),
            };
        }
        if (self.postgresCompatibilityShowAll(parsed_sql)) {
            return .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = "query",
                .has_row_description = true,
                .columns = try self.publicSqlPostgresCompatibilityColumnsAlloc(&.{ "name", "setting", "description" }),
            };
        }
        return null;
    }

    fn postgresCompatibilityInformationSchemaQueryAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
    ) !?PostgresCompatibilityInformationSchemaQuery {
        const raw = parsed_sql.statement.raw();
        const all_tokens = parsed_sql.items();
        if (raw.token_end > all_tokens.len or raw.token_start >= raw.token_end) return null;
        const tokens = all_tokens[raw.token_start..raw.token_end];
        if (tokens.len < 4 or !tokens[0].matchesKeywordTag(.select)) return null;

        var from_index: ?usize = null;
        for (tokens, 0..) |token, i| {
            if (i <= 1) continue;
            if (token.matchesKeywordTag(.from)) {
                from_index = i;
                break;
            }
        }
        const from_pos = from_index orelse return null;
        if (from_pos + 1 >= tokens.len) return null;
        const view: PostgresCompatibilityInformationSchemaView = if (postgresCompatibilityQualifiedNameMatches(tokens[from_pos + 1], "information_schema", "tables"))
            .tables
        else if (postgresCompatibilityQualifiedNameMatches(tokens[from_pos + 1], "information_schema", "columns"))
            .columns
        else
            return null;

        const selected_columns = (try self.postgresCompatibilityInformationSchemaSelectListAlloc(view, tokens[1..from_pos])) orelse return null;
        errdefer self.alloc.free(selected_columns);
        var tail = (try self.postgresCompatibilityInformationSchemaTailAlloc(view, selected_columns, tokens[from_pos + 2 ..])) orelse {
            self.alloc.free(selected_columns);
            return null;
        };
        errdefer tail.deinit(self.alloc);
        return .{
            .view = view,
            .columns = selected_columns,
            .filters = tail.filters,
            .order_by = tail.order_by,
        };
    }

    fn postgresCompatibilityInformationSchemaSelectListAlloc(
        self: *ApiHttpServer,
        view: PostgresCompatibilityInformationSchemaView,
        tokens: anytype,
    ) !?[]const []const u8 {
        if (tokens.len == 1 and tokens[0].kind == .star) {
            const defaults = switch (view) {
                .tables => &[_][]const u8{ "table_catalog", "table_schema", "table_name", "table_type" },
                .columns => &[_][]const u8{ "table_catalog", "table_schema", "table_name", "column_name", "ordinal_position", "data_type", "is_nullable" },
            };
            const out = try self.alloc.alloc([]const u8, defaults.len);
            @memcpy(out, defaults);
            return out;
        }

        var count: usize = 0;
        var expect_column = true;
        for (tokens) |token| {
            if (expect_column) {
                if (token.kind != .identifier) return null;
                const column = postgresCompatibilityIdentifierTail(token.text);
                if (!postgresCompatibilityInformationSchemaColumnAllowed(view, column)) return null;
                count += 1;
                expect_column = false;
            } else {
                if (token.kind != .comma) return null;
                expect_column = true;
            }
        }
        if (count == 0 or expect_column) return null;

        const out = try self.alloc.alloc([]const u8, count);
        var out_index: usize = 0;
        expect_column = true;
        for (tokens) |token| {
            if (expect_column) {
                out[out_index] = postgresCompatibilityIdentifierTail(token.text);
                out_index += 1;
                expect_column = false;
            } else {
                expect_column = true;
            }
        }
        return out;
    }

    fn postgresCompatibilityInformationSchemaColumnAllowed(view: PostgresCompatibilityInformationSchemaView, column: []const u8) bool {
        const allowed = switch (view) {
            .tables => &[_][]const u8{
                "table_catalog",
                "table_schema",
                "table_name",
                "table_type",
                "self_referencing_column_name",
                "reference_generation",
                "user_defined_type_catalog",
                "user_defined_type_schema",
                "user_defined_type_name",
                "is_insertable_into",
                "is_typed",
                "commit_action",
            },
            .columns => &[_][]const u8{
                "table_catalog",
                "table_schema",
                "table_name",
                "column_name",
                "ordinal_position",
                "column_default",
                "is_nullable",
                "data_type",
                "character_maximum_length",
                "character_octet_length",
                "numeric_precision",
                "numeric_precision_radix",
                "numeric_scale",
                "datetime_precision",
                "interval_type",
                "interval_precision",
                "character_set_catalog",
                "character_set_schema",
                "character_set_name",
                "collation_catalog",
                "collation_schema",
                "collation_name",
                "domain_catalog",
                "domain_schema",
                "domain_name",
                "udt_catalog",
                "udt_schema",
                "udt_name",
                "scope_catalog",
                "scope_schema",
                "scope_name",
                "maximum_cardinality",
                "dtd_identifier",
                "is_self_referencing",
                "is_identity",
                "identity_generation",
                "identity_start",
                "identity_increment",
                "identity_maximum",
                "identity_minimum",
                "identity_cycle",
                "is_generated",
                "generation_expression",
                "is_updatable",
            },
        };
        for (allowed) |allowed_column| {
            if (std.ascii.eqlIgnoreCase(column, allowed_column)) return true;
        }
        return false;
    }

    fn postgresCompatibilityInformationSchemaTailAlloc(
        self: *ApiHttpServer,
        view: PostgresCompatibilityInformationSchemaView,
        selected_columns: []const []const u8,
        tokens: anytype,
    ) !?PostgresCompatibilityInformationSchemaTail {
        if (tokens.len == 0) return .{};
        if (tokens[0].matchesKeywordTag(.order)) {
            const order_by = (try self.postgresCompatibilityInformationSchemaOrderByAlloc(view, selected_columns, tokens)) orelse return null;
            return .{ .order_by = order_by };
        }
        if (!tokens[0].matchesKeywordTag(.where)) return null;
        var filters = PostgresCompatibilityInformationSchemaFilters{};
        var i: usize = 1;
        while (i < tokens.len) {
            if (tokens[i].matchesKeywordTag(.order)) {
                const order_by = (try self.postgresCompatibilityInformationSchemaOrderByAlloc(view, selected_columns, tokens[i..])) orelse return null;
                return .{ .filters = filters, .order_by = order_by };
            }
            if (i + 2 >= tokens.len) return null;
            if (tokens[i].kind != .identifier or tokens[i + 1].kind != .eq or tokens[i + 2].kind != .string) return null;
            const field = postgresCompatibilityIdentifierTail(tokens[i].text);
            if (std.ascii.eqlIgnoreCase(field, "table_catalog")) {
                filters.table_catalog = tokens[i + 2].text;
            } else if (std.ascii.eqlIgnoreCase(field, "table_schema")) {
                filters.table_schema = tokens[i + 2].text;
            } else if (std.ascii.eqlIgnoreCase(field, "table_name")) {
                filters.table_name = tokens[i + 2].text;
            } else {
                return null;
            }
            i += 3;
            if (i == tokens.len) break;
            if (tokens[i].matchesKeywordTag(.order)) {
                const order_by = (try self.postgresCompatibilityInformationSchemaOrderByAlloc(view, selected_columns, tokens[i..])) orelse return null;
                return .{ .filters = filters, .order_by = order_by };
            }
            if (!tokens[i].matchesKeywordTag(.@"and")) return null;
            i += 1;
        }
        return .{ .filters = filters };
    }

    fn postgresCompatibilityInformationSchemaOrderByAlloc(
        self: *ApiHttpServer,
        view: PostgresCompatibilityInformationSchemaView,
        selected_columns: []const []const u8,
        tokens: anytype,
    ) !?[]const PostgresCompatibilityInformationSchemaOrderKey {
        if (tokens.len < 3) return null;
        if (!tokens[0].matchesKeywordTag(.order) or !tokens[1].matchesKeywordTag(.by)) return null;
        var count: usize = 0;
        var i: usize = 2;
        var expect_column = true;
        while (i < tokens.len) {
            if (expect_column) {
                if (tokens[i].kind != .identifier and tokens[i].kind != .number) return null;
                if (tokens[i].kind == .identifier) {
                    const column = postgresCompatibilityIdentifierTail(tokens[i].text);
                    if (!postgresCompatibilityInformationSchemaColumnAllowed(view, column)) return null;
                } else {
                    const ordinal = std.fmt.parseUnsigned(usize, tokens[i].text, 10) catch return null;
                    if (ordinal == 0 or ordinal > selected_columns.len) return null;
                }
                count += 1;
                i += 1;
                if (i < tokens.len and (tokens[i].matchesKeywordTag(.asc) or tokens[i].matchesKeywordTag(.desc))) i += 1;
                if (i < tokens.len and tokens[i].matchesKeywordTag(.nulls)) {
                    i += 1;
                    if (i >= tokens.len or (!tokens[i].matchesKeywordTag(.first) and !tokens[i].matchesKeywordTag(.last))) return null;
                    i += 1;
                }
                expect_column = false;
            } else {
                if (tokens[i].kind != .comma) return null;
                i += 1;
                expect_column = true;
            }
        }
        if (expect_column or count == 0) return null;

        const out = try self.alloc.alloc(PostgresCompatibilityInformationSchemaOrderKey, count);
        var out_index: usize = 0;
        errdefer self.alloc.free(out);
        i = 2;
        expect_column = true;
        while (i < tokens.len) {
            if (expect_column) {
                const column = if (tokens[i].kind == .number) blk: {
                    const ordinal = std.fmt.parseUnsigned(usize, tokens[i].text, 10) catch unreachable;
                    break :blk selected_columns[ordinal - 1];
                } else postgresCompatibilityIdentifierTail(tokens[i].text);
                i += 1;
                var descending = false;
                if (i < tokens.len and (tokens[i].matchesKeywordTag(.asc) or tokens[i].matchesKeywordTag(.desc))) {
                    descending = tokens[i].matchesKeywordTag(.desc);
                    i += 1;
                }
                if (i < tokens.len and tokens[i].matchesKeywordTag(.nulls)) i += 2;
                out[out_index] = .{ .column = column, .descending = descending };
                out_index += 1;
                expect_column = false;
            } else {
                i += 1;
                expect_column = true;
            }
        }
        return out;
    }

    fn postgresCompatibilityQualifiedNameMatches(token: anytype, expected_schema: []const u8, expected_name: []const u8) bool {
        if (token.kind != .identifier) return false;
        const dot = std.mem.indexOfScalar(u8, token.text, '.') orelse return false;
        if (std.mem.indexOfScalar(u8, token.text[dot + 1 ..], '.') != null) return false;
        return std.ascii.eqlIgnoreCase(token.text[0..dot], expected_schema) and
            std.ascii.eqlIgnoreCase(token.text[dot + 1 ..], expected_name);
    }

    fn postgresCompatibilityIdentifierTail(identifier: []const u8) []const u8 {
        if (std.mem.lastIndexOfScalar(u8, identifier, '.')) |dot| return identifier[dot + 1 ..];
        return identifier;
    }

    fn postgresCompatibilityScalarAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: catalog_resources.SqlCatalogSession,
    ) !?PostgresCompatibilityScalar {
        if (self.postgresCompatibilitySelectFunction(parsed_sql, "version")) {
            return .{
                .column_name = "version",
                .value = try std.fmt.allocPrint(self.alloc, "Antfly {s} PostgreSQL wire compatibility 16.0", .{build_options.antfly_version}),
            };
        }
        if (self.postgresCompatibilitySelectFunction(parsed_sql, "current_database")) {
            return .{
                .column_name = "current_database",
                .value = try self.alloc.dupe(u8, session.currentDatabase()),
            };
        }
        if (self.postgresCompatibilitySelectFunction(parsed_sql, "current_schema")) {
            return .{
                .column_name = "current_schema",
                .value = try self.alloc.dupe(u8, session.primarySearchPathNamespace()),
            };
        }
        if (self.postgresCompatibilitySelectCurrentSetting(parsed_sql)) |setting_name| {
            return .{
                .column_name = "current_setting",
                .value = try self.postgresCompatibilitySettingValueAlloc(setting_name, session),
            };
        }
        if (try self.postgresCompatibilitySelectLiteralAlloc(parsed_sql)) |literal| {
            return literal;
        }
        if (self.postgresCompatibilityShowSettingName(parsed_sql)) |setting_name| {
            return .{
                .column_name = setting_name,
                .value = try self.postgresCompatibilitySettingValueAlloc(setting_name, session),
            };
        }
        return null;
    }

    fn postgresCompatibilitySelectLiteralAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
    ) !?PostgresCompatibilityScalar {
        const raw = parsed_sql.statement.raw();
        const all_tokens = parsed_sql.items();
        if (raw.token_end > all_tokens.len or raw.token_start >= raw.token_end) return null;
        const tokens = all_tokens[raw.token_start..raw.token_end];
        if (tokens.len < 2 or !tokens[0].matchesKeywordTag(.select)) return null;

        const value_token = tokens[1];
        const value: []const u8 = switch (value_token.kind) {
            .number,
            .string,
            => value_token.text,
            else => if (value_token.matchesKeywordTag(.true) or value_token.matchesKeywordTag(.false) or value_token.matchesKeywordTag(.null))
                value_token.text
            else
                return null,
        };

        const column_name: []const u8 = if (tokens.len == 2)
            "?column?"
        else if (tokens.len == 4 and tokens[2].matchesKeywordTag(.as) and tokens[3].kind == .identifier)
            tokens[3].text
        else if (tokens.len == 3 and tokens[2].kind == .identifier)
            tokens[2].text
        else
            return null;

        return .{
            .column_name = column_name,
            .value = try self.alloc.dupe(u8, value),
        };
    }

    fn postgresCompatibilitySelectFunction(self: *ApiHttpServer, parsed_sql: *const sql_adapter.ParsedSql, function_name: []const u8) bool {
        _ = self;
        const raw = parsed_sql.statement.raw();
        const all_tokens = parsed_sql.items();
        if (raw.token_end > all_tokens.len or raw.token_start >= raw.token_end) return false;
        const tokens = all_tokens[raw.token_start..raw.token_end];
        if (tokens.len < 4) return false;
        if (!tokens[0].matchesKeywordTag(.select)) return false;
        if (!postgresCompatibilityTokenTextMatches(tokens[1], function_name)) return false;
        if (tokens[2].kind != .lparen or tokens[3].kind != .rparen) return false;
        return postgresCompatibilityOptionalAliasOnly(tokens[4..]);
    }

    fn postgresCompatibilitySelectCurrentSetting(self: *ApiHttpServer, parsed_sql: *const sql_adapter.ParsedSql) ?[]const u8 {
        _ = self;
        const raw = parsed_sql.statement.raw();
        const all_tokens = parsed_sql.items();
        if (raw.token_end > all_tokens.len or raw.token_start >= raw.token_end) return null;
        const tokens = all_tokens[raw.token_start..raw.token_end];
        if (tokens.len < 5) return null;
        if (!tokens[0].matchesKeywordTag(.select)) return null;
        if (!postgresCompatibilityTokenTextMatches(tokens[1], "current_setting")) return null;
        if (tokens[2].kind != .lparen or tokens[3].kind != .string or tokens[4].kind != .rparen) return null;
        if (!postgresCompatibilityOptionalAliasOnly(tokens[5..])) return null;
        return postgresCompatibilityCanonicalSettingName(tokens[3].text);
    }

    fn postgresCompatibilityShowSettingName(self: *ApiHttpServer, parsed_sql: *const sql_adapter.ParsedSql) ?[]const u8 {
        _ = self;
        const raw = parsed_sql.statement.raw();
        const all_tokens = parsed_sql.items();
        if (raw.token_end > all_tokens.len or raw.token_start >= raw.token_end) return null;
        const tokens = all_tokens[raw.token_start..raw.token_end];
        if (tokens.len != 2) return null;
        if (!tokens[0].matchesKeywordTag(.show)) return null;
        if (tokens[1].matchesKeywordTag(.all)) return null;
        return postgresCompatibilityCanonicalSettingName(tokens[1].text);
    }

    fn postgresCompatibilityShowAll(self: *ApiHttpServer, parsed_sql: *const sql_adapter.ParsedSql) bool {
        _ = self;
        const raw = parsed_sql.statement.raw();
        const all_tokens = parsed_sql.items();
        if (raw.token_end > all_tokens.len or raw.token_start >= raw.token_end) return false;
        const tokens = all_tokens[raw.token_start..raw.token_end];
        return tokens.len == 2 and tokens[0].matchesKeywordTag(.show) and tokens[1].matchesKeywordTag(.all);
    }

    fn postgresCompatibilityTokenTextMatches(token: anytype, expected: []const u8) bool {
        if (token.kind != .identifier) return false;
        if (std.ascii.eqlIgnoreCase(token.text, expected)) return true;
        const dot = std.mem.indexOfScalar(u8, token.text, '.') orelse return false;
        if (std.mem.indexOfScalar(u8, token.text[dot + 1 ..], '.') != null) return false;
        return std.ascii.eqlIgnoreCase(token.text[0..dot], "pg_catalog") and
            std.ascii.eqlIgnoreCase(token.text[dot + 1 ..], expected);
    }

    fn postgresCompatibilityOptionalAliasOnly(tokens: anytype) bool {
        if (tokens.len == 0) return true;
        if (tokens.len == 2 and tokens[0].matchesKeywordTag(.as) and tokens[1].kind == .identifier) return true;
        if (tokens.len == 1 and tokens[0].kind == .identifier) return true;
        return false;
    }

    fn postgresCompatibilityCanonicalSettingName(name: []const u8) ?[]const u8 {
        const settings = [_][]const u8{
            "server_version",
            "server_version_num",
            "server_encoding",
            "client_encoding",
            "DateStyle",
            "integer_datetimes",
            "standard_conforming_strings",
            "TimeZone",
            "application_name",
            "search_path",
            "transaction_isolation",
            "default_transaction_read_only",
            "transaction_read_only",
            "statement_timeout",
        };
        for (settings) |setting| {
            if (std.ascii.eqlIgnoreCase(name, setting)) return setting;
        }
        return null;
    }

    fn postgresCompatibilitySettingValueAlloc(
        self: *ApiHttpServer,
        name: []const u8,
        session: catalog_resources.SqlCatalogSession,
    ) ![]u8 {
        if (std.ascii.eqlIgnoreCase(name, "server_version")) return try self.alloc.dupe(u8, "16.0-antfly");
        if (std.ascii.eqlIgnoreCase(name, "server_version_num")) return try self.alloc.dupe(u8, "160000");
        if (std.ascii.eqlIgnoreCase(name, "server_encoding")) return try self.alloc.dupe(u8, "UTF8");
        if (std.ascii.eqlIgnoreCase(name, "client_encoding")) return try self.alloc.dupe(u8, "UTF8");
        if (std.ascii.eqlIgnoreCase(name, "DateStyle")) return try self.alloc.dupe(u8, "ISO, MDY");
        if (std.ascii.eqlIgnoreCase(name, "integer_datetimes")) return try self.alloc.dupe(u8, "on");
        if (std.ascii.eqlIgnoreCase(name, "standard_conforming_strings")) return try self.alloc.dupe(u8, "on");
        if (std.ascii.eqlIgnoreCase(name, "TimeZone")) return try self.alloc.dupe(u8, "UTC");
        if (std.ascii.eqlIgnoreCase(name, "application_name")) return try self.alloc.dupe(u8, "");
        if (std.ascii.eqlIgnoreCase(name, "search_path")) return try self.postgresCompatibilitySearchPathAlloc(session);
        if (std.ascii.eqlIgnoreCase(name, "transaction_isolation")) return try self.alloc.dupe(u8, "read committed");
        if (std.ascii.eqlIgnoreCase(name, "default_transaction_read_only")) return try self.alloc.dupe(u8, if (try sql_adapter.sqlDefaultTransactionReadOnlyFromSession(session)) "on" else "off");
        if (std.ascii.eqlIgnoreCase(name, "transaction_read_only")) {
            const read_only = (try sql_adapter.sqlTransactionReadOnlyFromSession(session)) orelse try sql_adapter.sqlDefaultTransactionReadOnlyFromSession(session);
            return try self.alloc.dupe(u8, if (read_only) "on" else "off");
        }
        if (std.ascii.eqlIgnoreCase(name, "statement_timeout")) return try self.alloc.dupe(u8, session.settingValue("statement_timeout") orelse "0");
        return error.InvalidSqlRequest;
    }

    fn postgresCompatibilitySearchPathAlloc(self: *ApiHttpServer, session: catalog_resources.SqlCatalogSession) ![]u8 {
        const default_search_path: []const []const u8 = &.{catalog_resources.default_namespace_name};
        const source = if (session.search_path.len == 0) default_search_path else session.search_path;
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        for (source, 0..) |namespace, i| {
            if (i != 0) try out.writer.writeAll(", ");
            try out.writer.writeAll(namespace);
        }
        return try out.toOwnedSlice();
    }

    fn publicSqlPostgresCompatibilityScalarReadAlloc(
        self: *ApiHttpServer,
        column_name: []const u8,
        value: []const u8,
    ) !PublicSqlResult.Read {
        const columns = try self.publicSqlPostgresCompatibilityColumnsAlloc(&.{column_name});
        errdefer relational_rows_api.freeRowsOutputColumns(self.alloc, columns);
        const rows = try self.alloc.alloc([]const u8, 1);
        errdefer self.alloc.free(rows);
        rows[0] = try self.publicSqlPostgresCompatibilityRowAlloc(&.{column_name}, &.{value});
        return .{
            .result = .{ .query = .{ .rows = rows, .total = 1 } },
            .columns = columns,
        };
    }

    fn publicSqlPostgresCompatibilityInformationSchemaReadAlloc(
        self: *ApiHttpServer,
        query: PostgresCompatibilityInformationSchemaQuery,
        session: catalog_resources.SqlCatalogSession,
    ) !PublicSqlResult.Read {
        var snapshot = try self.catalogSource().adminSnapshot();
        defer self.catalogSource().freeAdminSnapshot(&snapshot);
        const columns = try self.publicSqlPostgresCompatibilityColumnsAlloc(query.columns);
        errdefer relational_rows_api.freeRowsOutputColumns(self.alloc, columns);
        var rows_list = std.ArrayList(PostgresCompatibilityRenderedInformationSchemaRow).empty;
        errdefer {
            for (rows_list.items) |*row| row.deinit(self.alloc);
            rows_list.deinit(self.alloc);
        }

        for (snapshot.tables) |table| {
            if (!std.mem.eql(u8, table.database_name, session.currentDatabase())) continue;
            if (query.filters.table_catalog) |database_name| {
                if (!std.mem.eql(u8, table.database_name, database_name)) continue;
            }
            if (query.filters.table_schema) |schema_name| {
                if (!std.mem.eql(u8, table.namespace_name, schema_name)) continue;
            }
            if (query.filters.table_name) |table_name| {
                if (!std.mem.eql(u8, table.name, table_name)) continue;
            }
            switch (query.view) {
                .tables => try rows_list.append(self.alloc, try self.publicSqlPostgresCompatibilityInformationSchemaTableRowAlloc(query.columns, query.order_by, table)),
                .columns => try self.appendPostgresCompatibilityInformationSchemaColumnRows(&rows_list, query.columns, query.order_by, table),
            }
        }

        if (query.order_by.len != 0) {
            std.mem.sort(
                PostgresCompatibilityRenderedInformationSchemaRow,
                rows_list.items,
                query.order_by,
                ApiHttpServer.postgresCompatibilityInformationSchemaRowLessThan,
            );
        }

        const rows = try self.alloc.alloc([]const u8, rows_list.items.len);
        var rows_initialized: usize = 0;
        errdefer {
            for (rows[0..rows_initialized]) |row| self.alloc.free(@constCast(row));
            self.alloc.free(rows);
        }
        for (rows_list.items, 0..) |*row, i| {
            rows[i] = row.row;
            rows_initialized += 1;
            row.row = "";
            row.deinit(self.alloc);
        }
        rows_list.deinit(self.alloc);
        return .{
            .result = .{ .query = .{ .rows = rows, .total = @intCast(rows.len) } },
            .columns = columns,
        };
    }

    fn appendPostgresCompatibilityInformationSchemaColumnRows(
        self: *ApiHttpServer,
        rows: *std.ArrayList(PostgresCompatibilityRenderedInformationSchemaRow),
        selected_columns: []const []const u8,
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey,
        table: metadata_table_manager.TableRecord,
    ) !void {
        if (table.schema_json.len == 0) return;
        var parsed_schema = schema_mod.parseValidatedTableSchema(self.alloc, table.schema_json) catch return;
        defer parsed_schema.deinit(self.alloc);
        const schema = schema_mod.deriveRuntimeTableSchema(self.alloc, parsed_schema) catch return;
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        for (schema.relational_columns, 0..) |column, i| {
            try rows.append(
                self.alloc,
                try self.publicSqlPostgresCompatibilityInformationSchemaColumnRowAlloc(selected_columns, order_by, table, column, i + 1),
            );
        }
    }

    fn publicSqlPostgresCompatibilityInformationSchemaTableRowAlloc(
        self: *ApiHttpServer,
        selected_columns: []const []const u8,
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey,
        table: metadata_table_manager.TableRecord,
    ) !PostgresCompatibilityRenderedInformationSchemaRow {
        var values = try self.alloc.alloc([]const u8, selected_columns.len);
        defer self.alloc.free(values);
        for (selected_columns, 0..) |column, i| {
            values[i] = postgresCompatibilityInformationSchemaTableValue(column, table);
        }
        const row = try self.publicSqlPostgresCompatibilityRowAlloc(selected_columns, values);
        errdefer self.alloc.free(@constCast(row));
        return .{
            .row = row,
            .sort_values = try self.postgresCompatibilityInformationSchemaTableSortValuesAlloc(order_by, table),
        };
    }

    fn postgresCompatibilityInformationSchemaTableValue(column: []const u8, table: metadata_table_manager.TableRecord) []const u8 {
        if (std.ascii.eqlIgnoreCase(column, "table_catalog")) return table.database_name;
        if (std.ascii.eqlIgnoreCase(column, "table_schema")) return table.namespace_name;
        if (std.ascii.eqlIgnoreCase(column, "table_name")) return table.name;
        if (std.ascii.eqlIgnoreCase(column, "table_type")) return "BASE TABLE";
        if (std.ascii.eqlIgnoreCase(column, "is_insertable_into")) return "YES";
        if (std.ascii.eqlIgnoreCase(column, "is_typed")) return "NO";
        return "";
    }

    fn postgresCompatibilityInformationSchemaTableSortValuesAlloc(
        self: *ApiHttpServer,
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey,
        table: metadata_table_manager.TableRecord,
    ) ![]PostgresCompatibilityInformationSchemaSortValue {
        if (order_by.len == 0) return &.{};
        const out = try self.alloc.alloc(PostgresCompatibilityInformationSchemaSortValue, order_by.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*value| value.deinit(self.alloc);
            self.alloc.free(out);
        }
        for (order_by, 0..) |order_key, i| {
            out[i] = .{ .text = try self.alloc.dupe(u8, postgresCompatibilityInformationSchemaTableValue(order_key.column, table)) };
            initialized += 1;
        }
        return out;
    }

    fn publicSqlPostgresCompatibilityInformationSchemaColumnRowAlloc(
        self: *ApiHttpServer,
        selected_columns: []const []const u8,
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey,
        table: metadata_table_manager.TableRecord,
        column: runtime_schema_mod.RelationalColumn,
        ordinal_position: usize,
    ) !PostgresCompatibilityRenderedInformationSchemaRow {
        var values = try self.alloc.alloc([]const u8, selected_columns.len);
        defer {
            for (selected_columns, values) |selected_column, value| {
                if (std.ascii.eqlIgnoreCase(selected_column, "ordinal_position")) self.alloc.free(@constCast(value));
            }
            self.alloc.free(values);
        }
        for (selected_columns, 0..) |selected_column, i| {
            values[i] = if (std.ascii.eqlIgnoreCase(selected_column, "ordinal_position"))
                try std.fmt.allocPrint(self.alloc, "{d}", .{ordinal_position})
            else
                postgresCompatibilityInformationSchemaColumnValue(selected_column, table, column);
        }
        const row = try self.publicSqlPostgresCompatibilityRowAlloc(selected_columns, values);
        errdefer self.alloc.free(@constCast(row));
        return .{
            .row = row,
            .sort_values = try self.postgresCompatibilityInformationSchemaColumnSortValuesAlloc(order_by, table, column, ordinal_position),
        };
    }

    fn postgresCompatibilityInformationSchemaColumnValue(
        selected_column: []const u8,
        table: metadata_table_manager.TableRecord,
        column: runtime_schema_mod.RelationalColumn,
    ) []const u8 {
        if (std.ascii.eqlIgnoreCase(selected_column, "table_catalog")) return table.database_name;
        if (std.ascii.eqlIgnoreCase(selected_column, "table_schema")) return table.namespace_name;
        if (std.ascii.eqlIgnoreCase(selected_column, "table_name")) return table.name;
        if (std.ascii.eqlIgnoreCase(selected_column, "column_name")) return column.name;
        if (std.ascii.eqlIgnoreCase(selected_column, "is_nullable")) return if (column.nullable) "YES" else "NO";
        if (std.ascii.eqlIgnoreCase(selected_column, "data_type")) return postgresCompatibilityInformationSchemaDataType(column);
        if (std.ascii.eqlIgnoreCase(selected_column, "udt_catalog")) return table.database_name;
        if (std.ascii.eqlIgnoreCase(selected_column, "udt_schema")) return "pg_catalog";
        if (std.ascii.eqlIgnoreCase(selected_column, "udt_name")) return postgresCompatibilityInformationSchemaUdtName(column);
        if (std.ascii.eqlIgnoreCase(selected_column, "numeric_precision_radix")) return if (column.field_type == .numeric) "10" else "";
        if (std.ascii.eqlIgnoreCase(selected_column, "is_identity")) return "NO";
        if (std.ascii.eqlIgnoreCase(selected_column, "is_generated")) return if (column.generated != null) "ALWAYS" else "NEVER";
        if (std.ascii.eqlIgnoreCase(selected_column, "is_self_referencing")) return "NO";
        if (std.ascii.eqlIgnoreCase(selected_column, "is_updatable")) return if (column.generated != null) "NO" else "YES";
        return "";
    }

    fn postgresCompatibilityInformationSchemaColumnSortValuesAlloc(
        self: *ApiHttpServer,
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey,
        table: metadata_table_manager.TableRecord,
        column: runtime_schema_mod.RelationalColumn,
        ordinal_position: usize,
    ) ![]PostgresCompatibilityInformationSchemaSortValue {
        if (order_by.len == 0) return &.{};
        const out = try self.alloc.alloc(PostgresCompatibilityInformationSchemaSortValue, order_by.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*value| value.deinit(self.alloc);
            self.alloc.free(out);
        }
        for (order_by, 0..) |order_key, i| {
            out[i] = if (std.ascii.eqlIgnoreCase(order_key.column, "ordinal_position"))
                .{ .number = ordinal_position }
            else
                .{ .text = try self.alloc.dupe(u8, postgresCompatibilityInformationSchemaColumnValue(order_key.column, table, column)) };
            initialized += 1;
        }
        return out;
    }

    fn postgresCompatibilityInformationSchemaRowLessThan(
        order_by: []const PostgresCompatibilityInformationSchemaOrderKey,
        lhs: PostgresCompatibilityRenderedInformationSchemaRow,
        rhs: PostgresCompatibilityRenderedInformationSchemaRow,
    ) bool {
        for (order_by, 0..) |order_key, i| {
            if (i >= lhs.sort_values.len or i >= rhs.sort_values.len) return false;
            const cmp = switch (lhs.sort_values[i]) {
                .text => |lhs_text| switch (rhs.sort_values[i]) {
                    .text => |rhs_text| std.mem.order(u8, lhs_text, rhs_text),
                    .number => .lt,
                },
                .number => |lhs_number| switch (rhs.sort_values[i]) {
                    .text => .gt,
                    .number => |rhs_number| std.math.order(lhs_number, rhs_number),
                },
            };
            switch (cmp) {
                .lt => return !order_key.descending,
                .gt => return order_key.descending,
                .eq => {},
            }
        }
        return false;
    }

    fn postgresCompatibilityInformationSchemaDataType(column: runtime_schema_mod.RelationalColumn) []const u8 {
        return switch (column.field_type) {
            .keyword, .text, .html, .search_as_you_type, .link, .blob => "text",
            .numeric => "numeric",
            .boolean => "boolean",
            .datetime => "timestamp with time zone",
            .json => "jsonb",
            .array => "ARRAY",
            .embedding, .geopoint, .geoshape => "USER-DEFINED",
        };
    }

    fn postgresCompatibilityInformationSchemaUdtName(column: runtime_schema_mod.RelationalColumn) []const u8 {
        return switch (column.field_type) {
            .keyword, .text, .html, .search_as_you_type, .link, .blob => "text",
            .numeric => "numeric",
            .boolean => "bool",
            .datetime => "timestamptz",
            .json => "jsonb",
            .array => "_text",
            .embedding, .geopoint, .geoshape => "jsonb",
        };
    }

    fn publicSqlPostgresCompatibilityShowAllReadAlloc(
        self: *ApiHttpServer,
        session: catalog_resources.SqlCatalogSession,
    ) !PublicSqlResult.Read {
        const settings = try self.postgresCompatibilityShowAllSettingsAlloc(session);
        defer {
            for (settings) |*setting| setting.deinit(self.alloc);
            self.alloc.free(settings);
        }
        const columns = try self.publicSqlPostgresCompatibilityColumnsAlloc(&.{ "name", "setting", "description" });
        errdefer relational_rows_api.freeRowsOutputColumns(self.alloc, columns);
        const rows = try self.alloc.alloc([]const u8, settings.len);
        var initialized: usize = 0;
        errdefer {
            for (rows[0..initialized]) |row| self.alloc.free(@constCast(row));
            self.alloc.free(rows);
        }
        for (settings, 0..) |setting, i| {
            rows[i] = try self.publicSqlPostgresCompatibilityRowAlloc(
                &.{ "name", "setting", "description" },
                &.{ setting.name, setting.value, setting.description },
            );
            initialized += 1;
        }
        return .{
            .result = .{ .query = .{ .rows = rows, .total = @intCast(rows.len) } },
            .columns = columns,
        };
    }

    fn postgresCompatibilityShowAllSettingsAlloc(
        self: *ApiHttpServer,
        session: catalog_resources.SqlCatalogSession,
    ) ![]PostgresCompatibilitySetting {
        const source = [_]struct { name: []const u8, description: []const u8 }{
            .{ .name = "server_version", .description = "Shows the server version." },
            .{ .name = "server_version_num", .description = "Shows the server version as an integer." },
            .{ .name = "server_encoding", .description = "Shows the server encoding." },
            .{ .name = "client_encoding", .description = "Shows the client encoding." },
            .{ .name = "DateStyle", .description = "Sets the display format for date and time values." },
            .{ .name = "integer_datetimes", .description = "Shows whether datetimes are stored as integers." },
            .{ .name = "standard_conforming_strings", .description = "Shows whether ordinary string literals treat backslashes literally." },
            .{ .name = "TimeZone", .description = "Sets the time zone for displaying and interpreting time stamps." },
            .{ .name = "application_name", .description = "Sets the application name." },
            .{ .name = "search_path", .description = "Sets the schema search order." },
            .{ .name = "transaction_isolation", .description = "Sets the current transaction isolation level." },
            .{ .name = "default_transaction_read_only", .description = "Sets the default read-only status of new transactions." },
            .{ .name = "transaction_read_only", .description = "Shows whether the current transaction is read-only." },
            .{ .name = "statement_timeout", .description = "Sets the maximum allowed duration of any statement." },
        };
        const out = try self.alloc.alloc(PostgresCompatibilitySetting, source.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*setting| setting.deinit(self.alloc);
            self.alloc.free(out);
        }
        for (source, 0..) |row, i| {
            out[i] = .{
                .name = row.name,
                .value = try self.postgresCompatibilitySettingValueAlloc(row.name, session),
                .description = row.description,
            };
            initialized += 1;
        }
        return out;
    }

    fn publicSqlPostgresCompatibilityColumnsAlloc(
        self: *ApiHttpServer,
        names: []const []const u8,
    ) ![]const runtime_schema_mod.RelationalColumn {
        const columns = try self.alloc.alloc(runtime_schema_mod.RelationalColumn, names.len);
        var initialized: usize = 0;
        errdefer {
            for (columns[0..initialized]) |column| {
                self.alloc.free(column.name);
                self.alloc.free(column.path);
            }
            self.alloc.free(columns);
        }
        for (names, 0..) |name, i| {
            const owned_name = try self.alloc.dupe(u8, name);
            errdefer self.alloc.free(owned_name);
            const owned_path = try self.alloc.dupe(u8, name);
            errdefer self.alloc.free(owned_path);
            columns[i] = .{
                .name = owned_name,
                .path = owned_path,
                .field_type = .text,
                .nullable = false,
            };
            initialized += 1;
        }
        return columns;
    }

    fn publicSqlPostgresCompatibilityRowAlloc(
        self: *ApiHttpServer,
        columns: []const []const u8,
        values: []const []const u8,
    ) ![]const u8 {
        std.debug.assert(columns.len == values.len);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        try out.writer.writeByte('{');
        for (columns, values, 0..) |column, value, i| {
            if (i != 0) try out.writer.writeByte(',');
            try out.writer.print("{f}:{f}", .{ std.json.fmt(column, .{}), std.json.fmt(value, .{}) });
        }
        try out.writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    pub fn handlePublicSqlRequestResult(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlResultOrResponse {
        return try self.executePublicSqlRequestResult(request, authenticated_identity);
    }

    pub fn executePublicSqlRequestResult(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlResultOrResponse {
        if (std.mem.trim(u8, request.sql, " \t\r\n").len == 0) return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.parse, .invalid_sql_request)) };

        var session = self.ownedSqlCatalogSessionForPublicRequestAlloc(request) catch |err| switch (err) {
            error.InvalidSqlRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        defer session.deinit(self.alloc);

        var parsed_sql = sql_adapter.ParsedSql.initAlloc(self.alloc, request.sql) catch |err| switch (err) {
            error.UnsupportedSqlShape => {
                self.markPublicSqlTransactionFailedIfActive(&session);
                try self.savePublicSqlSession(session);
                return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.parse, .unsupported_sql_statement)) };
            },
            else => return err,
        };
        defer parsed_sql.deinit(self.alloc);

        var outcome = try self.executePublicParsedSqlRequestResult(.{
            .parsed_sql = &parsed_sql,
            .params = request.params,
            .session = &session,
            .authenticated_identity = authenticated_identity,
        });
        errdefer outcome.deinit(self.alloc);
        try self.savePublicSqlSession(session);
        return outcome;
    }

    pub const PublicParsedSqlExecutionRequest = struct {
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue = &.{},
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity = null,
    };

    const PublicSqlPlannedExecution = struct {
        logical_plan: sql_adapter.LogicalSqlPlan,
        row_claim_owner_id: ?[]const u8 = null,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            self.logical_plan.deinit(alloc);
            if (self.row_claim_owner_id) |owner_id| alloc.free(@constCast(owner_id));
            self.* = undefined;
        }
    };

    const PublicSqlPlannedExecutionOrResponse = union(enum) {
        planned: PublicSqlPlannedExecution,
        response: http_common.HttpResponse,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            switch (self.*) {
                .planned => |*planned| planned.deinit(alloc),
                .response => |*response| response.deinit(alloc),
            }
            self.* = undefined;
        }
    };

    fn planPublicParsedSqlExecutionAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
    ) !PublicSqlPlannedExecutionOrResponse {
        const write_statement_kind = parsed_sql.writeStatementKind();
        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        var write_options: sql_adapter.LowerWritePlanOptions = .{};
        var row_claim_owner_id: ?[]const u8 = null;
        defer if (row_claim_owner_id) |owner_id| self.alloc.free(@constCast(owner_id));
        if (write_statement_kind) |statement_kind| {
            if (try self.publicSqlReadOnlyActive(session)) {
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .read_only_transaction).withMessage("cannot execute write statement in a read-only transaction")) };
            }
            switch (statement_kind) {
                .insert, .insert_source, .update, .update_source, .update_joined_source, .delete, .delete_source, .delete_joined_source, .truncate, .merge => {},
            }

            const sync_level = sql_adapter.sqlSyncLevelFromSession(session.session()) catch |err| switch (err) {
                error.InvalidRoleSetting => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.bind, .invalid_role_setting)) },
            };
            const row_claim: ?db_mod.types.RowClaimRequest = switch (statement_kind) {
                .update, .update_source, .update_joined_source, .delete, .delete_source, .delete_joined_source, .truncate => try self.sqlMutationRowClaimAlloc(session),
                else => null,
            };
            row_claim_owner_id = if (row_claim) |claim| claim.owner_id else null;
            write_options = .{
                .unique_resolver = unique_resolver_ctx.resolver(),
                .row_claim = row_claim,
                .sync_level = sync_level,
            };
        }

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var logical_plan = sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, parsed_sql, .{
            .catalog = self.catalogSource(),
            .session = session.session(),
            .write_options = write_options,
            .function_bindings = function_bindings,
        }) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => {
                if (write_statement_kind != null) std.log.err("public sql write bind not found err={}", .{err});
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(404, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) };
            },
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.UnsupportedRowsSelector, error.RowSelectorNotFound => {
                if (write_statement_kind != null) return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.bind, .invalid_sql_write)) };
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.bind, .invalid_sql_request)) };
            },
            error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => {
                if (write_statement_kind == null and parsed_sql.readStatementKind() == null and try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
            },
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .response = try self.publicSqlParsedDiagnosticResponse(503, parsed_sql, .init(.plan, .unique_owner_unavailable)) },
            else => return err,
        };
        errdefer logical_plan.deinit(self.alloc);
        const owner_id = row_claim_owner_id;
        row_claim_owner_id = null;
        return .{ .planned = .{
            .logical_plan = logical_plan,
            .row_claim_owner_id = owner_id,
        } };
    }

    pub fn executePublicParsedSqlRequestResult(self: *ApiHttpServer, request: PublicParsedSqlExecutionRequest) !PublicSqlResultOrResponse {
        const parsed_sql = request.parsed_sql;
        const session = request.session;

        if (session.sql_transaction_failed and !parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql)) {
            return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .current_transaction_aborted)) };
        }
        if (try self.handlePublicSqlPostgresCompatibilityRead(parsed_sql, session)) |outcome_value| {
            var outcome = outcome_value;
            errdefer outcome.deinit(self.alloc);
            switch (outcome) {
                .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                .response => {},
            }
            return outcome;
        }
        if (parsed_sql.readStatementKind()) |statement_kind| {
            if (try self.handlePublicSqlQueryFunctionRead(parsed_sql, session, request.authenticated_identity, statement_kind)) |outcome_value| {
                var outcome = outcome_value;
                errdefer outcome.deinit(self.alloc);
                switch (outcome) {
                    .response => self.markPublicSqlTransactionFailedIfActive(session),
                    .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                }
                return outcome;
            }
        }
        var planned_or_response = self.planPublicParsedSqlExecutionAlloc(parsed_sql, session) catch |err| switch (err) {
            error.DocumentSqlViewMappingUnsupported => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.plan, .document_sql_view_mapping_unsupported)) };
            },
            error.SqlReadOnlyTransaction => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) };
            },
            error.UnsupportedSqlShape => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
            },
            error.StatementTimeout => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(408, parsed_sql, .init(.execute, .statement_timeout)) };
            },
            error.InvalidSqlSession,
            error.PreparedStatementAlreadyExists,
            error.PreparedStatementNotFound,
            error.PreparedStatementArgumentMismatch,
            error.InvalidSqlCatalog,
            error.InvalidRoleSetting,
            error.RoleSettingNotFound,
            => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) };
            },
            else => return err,
        };
        var planned_or_response_owned = true;
        defer if (planned_or_response_owned) planned_or_response.deinit(self.alloc);

        switch (planned_or_response) {
            .response => |*response| {
                self.markPublicSqlTransactionFailedIfActive(session);
                const out = response.*;
                planned_or_response_owned = false;
                return .{ .response = out };
            },
            .planned => |*planned| {
                var outcome: PublicSqlResultOrResponse = switch (planned.logical_plan) {
                    .catalog_write => try self.handlePublicSqlWrite(&planned.logical_plan, parsed_sql, request.params, session, request.authenticated_identity),
                    .catalog_read => try self.handlePublicSqlRead(&planned.logical_plan, parsed_sql, request.params, session, request.authenticated_identity),
                    .read, .write => return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) },
                    else => ddl_blk: {
                        const applied = ApiHttpServer.applyLogicalSqlPlanWithSession(self, &planned.logical_plan, session, .{ .parsed_sql = parsed_sql }) catch |err| switch (err) {
                            error.DocumentSqlViewMappingUnsupported => {
                                self.markPublicSqlTransactionFailedIfActive(session);
                                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.plan, .document_sql_view_mapping_unsupported)) };
                            },
                            error.SqlReadOnlyTransaction => {
                                self.markPublicSqlTransactionFailedIfActive(session);
                                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) };
                            },
                            error.UnsupportedSqlShape => {
                                self.markPublicSqlTransactionFailedIfActive(session);
                                return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
                            },
                            error.StatementTimeout => {
                                self.markPublicSqlTransactionFailedIfActive(session);
                                return .{ .response = try self.publicSqlParsedDiagnosticResponse(408, parsed_sql, .init(.execute, .statement_timeout)) };
                            },
                            error.InvalidSqlSession,
                            error.PreparedStatementAlreadyExists,
                            error.PreparedStatementNotFound,
                            error.PreparedStatementArgumentMismatch,
                            error.InvalidSqlCatalog,
                            error.InvalidRoleSetting,
                            error.RoleSettingNotFound,
                            => {
                                self.markPublicSqlTransactionFailedIfActive(session);
                                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) };
                            },
                            else => return err,
                        };
                        const session_id = self.ensureSqlProtocolSessionId(session);
                        break :ddl_blk .{ .result = .{
                            .session_id = session_id,
                            .statement_kind = "ddl",
                            .transaction_status = self.publicSqlTransactionStatus(session),
                            .result = .{ .ddl = .{
                                .applied = applied,
                                .command_tag = publicSqlDdlCommandTag(parsed_sql),
                            } },
                        } };
                    },
                };
                errdefer outcome.deinit(self.alloc);
                switch (outcome) {
                    .response => self.markPublicSqlTransactionFailedIfActive(session),
                    .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                }
                return outcome;
            },
        }
    }

    pub fn handlePublicSqlDescribeRequestResult(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlDescribeResultOrResponse {
        if (std.mem.trim(u8, request.sql, " \t\r\n").len == 0) return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.parse, .invalid_sql_request)) };

        var session = self.ownedSqlCatalogSessionForPublicRequestAlloc(request) catch |err| switch (err) {
            error.InvalidSqlRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        defer session.deinit(self.alloc);

        var parsed_sql = sql_adapter.ParsedSql.initAlloc(self.alloc, request.sql) catch |err| switch (err) {
            error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.parse, .unsupported_sql_statement)) },
            else => return err,
        };
        defer parsed_sql.deinit(self.alloc);
        if (try self.describePublicSqlPostgresCompatibilityReadAlloc(&parsed_sql, &session)) |result_value| {
            var result = result_value;
            errdefer result.deinit(self.alloc);
            try self.savePublicSqlSession(session);
            result.transaction_status = self.publicSqlTransactionStatus(&session);
            return .{ .result = result };
        }
        if (parsed_sql.readStatementKind() != null) {
            var outcome = try self.describePublicSqlReadColumnsAlloc(&parsed_sql, request.params, &session, authenticated_identity);
            errdefer outcome.deinit(self.alloc);
            try self.savePublicSqlSession(session);
            switch (outcome) {
                .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(&session),
                .response => {},
            }
            return outcome;
        }

        const statement_kind: []const u8 = if (parsed_sql.writeStatementKind()) |kind| @tagName(kind) else "ddl";
        const session_id = self.ensureSqlProtocolSessionId(&session);
        try self.savePublicSqlSession(session);
        return .{ .result = .{
            .session_id = session_id,
            .statement_kind = statement_kind,
            .transaction_status = self.publicSqlTransactionStatus(&session),
            .has_row_description = false,
        } };
    }

    fn applyPreparedTransactionPlan(
        self: *ApiHttpServer,
        plan: sql_adapter.PreparedTransactionPlan,
        timestamp_ns: u64,
    ) !sql_adapter.PreparedTransactionCoordinatorResult {
        return self.source.applyPreparedTransactionPlan(self.alloc, plan, timestamp_ns) catch |err| switch (err) {
            error.UnsupportedOperation => {
                const opened = self.opened_session_store orelse return err;
                return try sql_adapter.executePreparedTransactionRecoveryPlan(self.alloc, opened.docstore, plan, timestamp_ns);
            },
            else => return err,
        };
    }

    fn resolveRoutineSettingsFromCurrentInPlace(
        self: *ApiHttpServer,
        plan: *sql_adapter.FunctionCatalogPlan,
        session: catalog_resources.SqlCatalogSession,
    ) !void {
        switch (plan.*) {
            .create => |*create| try self.resolveCreateRoutineSettingsFromCurrentInPlace(create, session),
            .drop => {},
        }
    }

    fn resolveCreateRoutineSettingsFromCurrentInPlace(
        self: *ApiHttpServer,
        create: *sql_adapter.CreateRoutinePlan,
        session: catalog_resources.SqlCatalogSession,
    ) !void {
        if (create.settings.len == 0) return;
        const settings = @constCast(create.settings);
        for (settings) |*setting| {
            if (!setting.from_current) continue;
            if (setting.values.len != 0) return error.InvalidRoleSetting;
            const values = try self.currentRoutineSettingValuesAlloc(session, setting.name);
            setting.values = values;
            setting.from_current = false;
        }
    }

    fn currentRoutineSettingValuesAlloc(
        self: *ApiHttpServer,
        session: catalog_resources.SqlCatalogSession,
        name: []const u8,
    ) ![]const []const u8 {
        if (std.ascii.eqlIgnoreCase(name, "search_path")) {
            const default_search_path: []const []const u8 = &.{catalog_resources.default_namespace_name};
            const source = if (session.search_path.len == 0)
                default_search_path
            else
                session.search_path;
            return try cloneStringSliceConstAlloc(self.alloc, source);
        }

        const value = session.settingValue(name) orelse return error.RoleSettingNotFound;
        try sql_adapter.validateSqlDatabaseSettingValue(name, value);
        const values = try self.alloc.alloc([]const u8, 1);
        errdefer self.alloc.free(values);
        values[0] = try self.alloc.dupe(u8, value);
        return values;
    }

    fn cloneStringSliceConstAlloc(
        alloc: std.mem.Allocator,
        values: []const []const u8,
    ) ![]const []const u8 {
        const out = try alloc.alloc([]const u8, values.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |value| alloc.free(@constCast(value));
            alloc.free(out);
        }
        for (values, 0..) |value, i| {
            out[i] = try alloc.dupe(u8, value);
            initialized += 1;
        }
        return out;
    }

    fn schemaRewriteWakeOwnerId(self: *ApiHttpServer, runtime: *db_mod.background_runtime.BackendRuntime) u64 {
        if (self.schema_rewrite_wake_owner_id == 0) {
            self.schema_rewrite_wake_owner_id = runtime.allocOwnerId();
        }
        return self.schema_rewrite_wake_owner_id;
    }

    fn submitSchemaRewriteWakeForTable(
        self: *ApiHttpServer,
        runtime: *db_mod.background_runtime.BackendRuntime,
        write_source: table_writes.TableWriteSource,
        table: metadata_table_manager.TableRecord,
    ) !bool {
        if (!try self.schema_rewrite_wake_registry.tryAcquire(self.alloc, table.table_id)) return false;
        var acquired = true;
        errdefer if (acquired) self.schema_rewrite_wake_registry.release(table.table_id);
        try SchemaRewriteWakeJob.submitWithPromotionAndRegistry(
            runtime,
            self.schemaRewriteWakeOwnerId(runtime),
            write_source,
            table.name,
            self.source,
            table,
            &self.schema_rewrite_wake_registry,
            table.table_id,
        );
        acquired = false;
        return true;
    }

    fn scheduleSchemaRewriteRuntimeHintForAppliedDdl(
        self: *ApiHttpServer,
        applied: tables_api.AppliedRelationalSqlDdlRecord,
    ) !void {
        if (!catalog_jobs.appliedDdlHasSchemaRewriteWork(applied)) return;
        const runtime = self.cfg.backend_runtime orelse return;
        const write_source = self.table_writes orelse return;
        _ = try self.submitSchemaRewriteWakeForTable(runtime, write_source, applied.table);
    }

    fn refreshSqlExtensionQueryFunctions(self: *ApiHttpServer) !void {
        var snapshot = (try self.source.adminSnapshot()) orelse {
            try self.sql_routine_runtime.replaceNativeQueryFunctionBindings(&.{});
            return;
        };
        defer self.source.freeAdminSnapshot(&snapshot);
        const bindings = try extension_domain.listReadyNativeQueryFunctionBindingsAlloc(self.alloc, snapshot.installed_extensions, snapshot.extension_members);
        defer extension_domain.freeQueryFunctionBindings(self.alloc, bindings);
        try self.sql_routine_runtime.replaceNativeQueryFunctionBindings(bindings);
    }

    pub fn lowerRelationalSqlReadPlanWithRoutineBindingsAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        sql: []const u8,
        schema: runtime_schema_mod.TableSchema,
        params: []const sql_adapter.SqlValue,
        catalog: ?table_catalog.CatalogSource,
    ) !sql_adapter.LoweredReadPlan {
        return try self.lowerRelationalSqlReadPlanWithRoutineBindingsAndSessionAlloc(
            alloc,
            sql,
            schema,
            params,
            catalog,
            catalog_resources.SqlCatalogSession.default(),
        );
    }

    pub fn lowerRelationalSqlReadPlanWithRoutineBindingsAndSessionAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        sql: []const u8,
        schema: runtime_schema_mod.TableSchema,
        params: []const sql_adapter.SqlValue,
        catalog: ?table_catalog.CatalogSource,
        session: catalog_resources.SqlCatalogSession,
    ) !sql_adapter.LoweredReadPlan {
        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(alloc);
        defer sql_routines.freeExpressionRoutineBindings(alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(alloc, sql);
        defer parsed_sql.deinit(alloc);
        if (catalog) |source_catalog| {
            return try sql_adapter_runtime.lowerReadPlanWithCatalogSessionAndFunctionBindingsParsedSqlAlloc(alloc, &parsed_sql, schema, params, source_catalog, session, function_bindings);
        }
        return try sql_adapter_runtime.lowerReadPlanWithFunctionBindingsParsedSqlAlloc(alloc, &parsed_sql, schema, params, function_bindings);
    }

    pub fn executeBulkSqlCopyFromStdinWithSession(
        self: *ApiHttpServer,
        sql: []const u8,
        stdin_payload: []const u8,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !relational_rows_api.OwnedRowsBatchRequest {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(self.alloc, sql);
        defer parsed_sql.deinit(self.alloc);
        var logical_plan = try sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, &parsed_sql, .{
            .catalog = self.catalogSource(),
            .session = session,
        });
        defer logical_plan.deinit(self.alloc);
        const bulk_plan = switch (logical_plan) {
            .bulk_io => |plan| plan,
            else => return error.UnsupportedSqlShape,
        };
        const execution_plan = try sql_adapter.bulkSqlIoExecutionPlanFromDdlPlan(bulk_plan);
        if (execution_plan.operation != .import_rows or
            execution_plan.native_route != .rows_batch or
            execution_plan.stream != .stdin)
        {
            return error.UnsupportedSqlShape;
        }

        var rows = try self.executeBulkSqlImportPlanFromStdin(execution_plan, stdin_payload, session, authenticated_identity);
        errdefer rows.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        return rows;
    }

    pub fn executeBulkSqlWithSession(
        self: *ApiHttpServer,
        sql: []const u8,
        stdin_payload: ?[]const u8,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !BulkSqlExecutionResult {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(self.alloc, sql);
        defer parsed_sql.deinit(self.alloc);
        var logical_plan = try sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, &parsed_sql, .{
            .catalog = self.catalogSource(),
            .session = session,
        });
        defer logical_plan.deinit(self.alloc);
        const bulk_plan = switch (logical_plan) {
            .bulk_io => |plan| plan,
            else => return error.UnsupportedSqlShape,
        };
        const execution_plan = try sql_adapter.bulkSqlIoExecutionPlanFromDdlPlan(bulk_plan);
        var result: BulkSqlExecutionResult = switch (execution_plan.operation) {
            .import_rows => blk: {
                if (execution_plan.native_route != .rows_batch) return error.UnsupportedSqlShape;
                switch (execution_plan.stream) {
                    .stdin => {
                        const payload = stdin_payload orelse return error.InvalidRowsRequest;
                        break :blk .{
                            .import_rows = try self.executeBulkSqlImportPlanFromStdin(execution_plan, payload, session, authenticated_identity),
                        };
                    },
                    .file => {
                        if (stdin_payload != null) return error.InvalidRowsRequest;
                        break :blk .{
                            .import_rows = try self.executeBulkSqlImportPlanFromFile(execution_plan, session, authenticated_identity),
                        };
                    },
                    .program => {
                        if (stdin_payload != null) return error.InvalidRowsRequest;
                        break :blk .{
                            .import_rows = try self.executeBulkSqlImportPlanFromProgram(execution_plan, session, authenticated_identity),
                        };
                    },
                    .stdout => return error.UnsupportedSqlShape,
                }
            },
            .export_rows => blk: {
                if (stdin_payload != null) return error.InvalidRowsRequest;
                if (execution_plan.native_route != .rows_query) return error.UnsupportedSqlShape;
                switch (execution_plan.stream) {
                    .stdout => break :blk .{
                        .export_stdout = try self.executeBulkSqlExportPlanToStdout(execution_plan, session, authenticated_identity),
                    },
                    .file => {
                        try self.executeBulkSqlExportPlanToFile(execution_plan, session, authenticated_identity);
                        break :blk .{ .export_file = {} };
                    },
                    .program => {
                        try self.executeBulkSqlExportPlanToProgram(execution_plan, session, authenticated_identity);
                        break :blk .{ .export_file = {} };
                    },
                    .stdin => return error.UnsupportedSqlShape,
                }
            },
        };
        errdefer result.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        return result;
    }

    pub fn executeBulkSqlCopyToStdoutWithSession(
        self: *ApiHttpServer,
        sql: []const u8,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) ![]u8 {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(self.alloc, sql);
        defer parsed_sql.deinit(self.alloc);
        var logical_plan = try sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, &parsed_sql, .{
            .catalog = self.catalogSource(),
            .session = session,
        });
        defer logical_plan.deinit(self.alloc);
        const bulk_plan = switch (logical_plan) {
            .bulk_io => |plan| plan,
            else => return error.UnsupportedSqlShape,
        };
        const execution_plan = try sql_adapter.bulkSqlIoExecutionPlanFromDdlPlan(bulk_plan);
        if (execution_plan.operation != .export_rows or
            execution_plan.native_route != .rows_query or
            execution_plan.stream != .stdout)
        {
            return error.UnsupportedSqlShape;
        }

        const exported = try self.executeBulkSqlExportPlanToStdout(execution_plan, session, authenticated_identity);
        errdefer self.alloc.free(exported);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        return exported;
    }

    fn executeBulkSqlImportPlanFromStdin(
        self: *ApiHttpServer,
        execution_plan: sql_adapter.BulkSqlIoExecutionPlan,
        stdin_payload: []const u8,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !relational_rows_api.OwnedRowsBatchRequest {
        const target = try session.tableTargetFromObjectName(execution_plan.table_name);
        try self.requireSqlBulkIoPermission(target, execution_plan, authenticated_identity);
        return try self.executeBulkSqlImportPlanFromPayloadAuthorized(execution_plan, target, stdin_payload, authenticated_identity);
    }

    fn executeBulkSqlImportPlanFromPayloadAuthorized(
        self: *ApiHttpServer,
        execution_plan: sql_adapter.BulkSqlIoExecutionPlan,
        target: catalog_resources.TableTarget,
        payload: []const u8,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !relational_rows_api.OwnedRowsBatchRequest {
        errdefer |err| if (err != error.PermissionDenied) self.recordSqlBulkIoFailedAudit(execution_plan, target, 0, authenticated_identity, err);
        const source = self.table_writes orelse return error.UnsupportedOperation;
        const schema = try self.runtimeSchemaForCatalogRows(target);
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var rows_req = try sql_adapter.bulkSqlIoImportRowsBatchFromStdinAlloc(self.alloc, schema, execution_plan, payload);
        errdefer rows_req.deinit(self.alloc);
        try self.applyRowsBatchBeforeInsertTriggersForBulkImport(target.table_name, schema, &rows_req);
        try self.requireSqlBulkIoRowsSatisfyEffectiveFilter(execution_plan, target, schema, rows_req.req, authenticated_identity);

        if (rows_req.req.writes.len != 0 or rows_req.req.deletes.len != 0 or rows_req.req.transforms.len != 0 or rows_req.req.relational_identity_rewrites.len != 0) {
            _ = (try source.batchCatalog(self.alloc, target, rows_req.req)) orelse return error.TableNotFound;
        }
        try self.recordSqlBulkIoAudit(execution_plan, target, rows_req.writes.len, authenticated_identity);
        return rows_req;
    }

    fn applyRowsBatchBeforeInsertTriggersForBulkImport(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        rows_req: *relational_rows_api.OwnedRowsBatchRequest,
    ) !void {
        var trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .insert);
        defer if (trigger) |*value| value.deinit(self.alloc);
        const insert_trigger = trigger orelse return;
        if (rows_req.deletes.len != 0 or rows_req.relational_identity_rewrites.len != 0 or rows_req.transforms.len != 0 or rows_req.returning_rows.len != 0) {
            return error.UnsupportedOperation;
        }

        var writes = std.ArrayListUnmanaged(db_mod.types.BatchWrite).empty;
        var predicates = std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate).empty;
        errdefer {
            for (writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            writes.deinit(self.alloc);
            for (predicates.items) |predicate| self.alloc.free(@constCast(predicate.key));
            predicates.deinit(self.alloc);
        }

        for (rows_req.writes) |write| {
            const triggered_row = try self.sql_routine_runtime.executeTriggerRoutineAlloc(self.alloc, insert_trigger.function_name, write.value, null);
            defer self.alloc.free(triggered_row);
            var parsed_triggered = std.json.parseFromSlice(std.json.Value, self.alloc, triggered_row, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
            defer parsed_triggered.deinit();
            if (parsed_triggered.value == .null) continue;
            if (parsed_triggered.value != .object) return error.InvalidRowsRequest;

            const key = try relational_rows_api.physicalPrimaryKeyFromRowJsonAlloc(self.alloc, schema, triggered_row);
            var key_transferred = false;
            errdefer if (!key_transferred) self.alloc.free(key);
            const value = try self.alloc.dupe(u8, triggered_row);
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value);
            try writes.append(self.alloc, .{ .key = key, .value = value });
            key_transferred = true;
            value_transferred = true;

            const predicate_key = try self.alloc.dupe(u8, key);
            var predicate_key_transferred = false;
            errdefer if (!predicate_key_transferred) self.alloc.free(predicate_key);
            try predicates.append(self.alloc, .{ .key = predicate_key, .expected_version = 0 });
            predicate_key_transferred = true;
        }

        const writes_slice = try writes.toOwnedSlice(self.alloc);
        errdefer {
            for (writes_slice) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            if (writes_slice.len > 0) self.alloc.free(writes_slice);
        }
        const predicates_slice = try predicates.toOwnedSlice(self.alloc);
        errdefer {
            for (predicates_slice) |predicate| self.alloc.free(@constCast(predicate.key));
            if (predicates_slice.len > 0) self.alloc.free(predicates_slice);
        }

        var triggered_req = relational_rows_api.OwnedRowsBatchRequest{
            .writes = writes_slice,
            .predicates = predicates_slice,
            .req = .{
                .writes = writes_slice,
                .predicates = predicates_slice,
                .timestamp_ns = rows_req.req.timestamp_ns,
                .sync_level = rows_req.req.sync_level,
            },
            .inserted = @intCast(writes_slice.len),
        };
        errdefer triggered_req.deinit(self.alloc);
        rows_req.deinit(self.alloc);
        rows_req.* = triggered_req;
    }

    fn executeBulkSqlImportPlanFromFile(
        self: *ApiHttpServer,
        execution_plan: sql_adapter.BulkSqlIoExecutionPlan,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !relational_rows_api.OwnedRowsBatchRequest {
        if (execution_plan.stream != .file or execution_plan.endpoint_kind != .file) return error.UnsupportedSqlShape;
        const target = try session.tableTargetFromObjectName(execution_plan.table_name);
        try self.requireSqlBulkIoPermission(target, execution_plan, authenticated_identity);
        const file_io = self.cfg.sql_bulk_io_file_io orelse {
            const err = error.UnsupportedOperation;
            self.recordSqlBulkIoFailedAudit(execution_plan, target, 0, authenticated_identity, err);
            return err;
        };
        const payload = file_io.readImport(self.alloc, execution_plan.endpoint) catch |err| {
            self.recordSqlBulkIoFailedAudit(execution_plan, target, 0, authenticated_identity, err);
            return err;
        };
        defer self.alloc.free(payload);
        return try self.executeBulkSqlImportPlanFromPayloadAuthorized(execution_plan, target, payload, authenticated_identity);
    }

