                manager.removeRowFilter(user_path.user_name, user_path.table) catch |err| switch (err) {
                    error.UserNotFound, error.RowFilterNotFound => return try jsonErrorResponse(self.alloc, 404, "not found"),
                    else => return err,
                };
                return .{
                    .status = 204,
                    .content_type = null,
                    .body = &.{},
                };
            }
        }
        return null;
    }

    fn dispatchSecretRoutes(self: *ApiHttpServer, req: http_common.HttpRequest, uri_parts: UriParts) !?http_common.HttpResponse {
        if (req.method == .GET and std.mem.eql(u8, uri_parts.path, routes.Routes.secrets)) {
            const listed = if (self.cfg.secret_store) |secret_store|
                try secret_store.list(self.alloc)
            else
                try common_secrets.listEnvironmentSecrets(self.alloc);
            defer common_secrets.freeListedSecrets(self.alloc, listed);
            const secret_list = try makeSecretList(self.alloc, listed);
            defer self.alloc.free(secret_list.secrets);
            return try jsonResponse(self.alloc, secret_list);
        }
        if (req.method == .PUT) {
            if (routes.Routes.matchSecretPath(uri_parts.path)) |secret_path| {
                const secret_store = self.cfg.secret_store orelse return try textResponse(self.alloc, 503, "secret management not available in multi-node mode");
                var parsed = metadata_openapi.server.parsePutSecretBody(self.alloc, req.body) catch {
                    return try textResponse(self.alloc, 400, "invalid secret request");
                };
                defer parsed.deinit();
                var listed = secret_store.put(self.alloc, secret_path.key, parsed.value.value) catch |err| switch (err) {
                    error.InvalidSecretKey => return try textResponse(self.alloc, 400, "invalid secret key"),
                    else => return err,
                };
                defer listed.deinit(self.alloc);
                return try jsonResponse(self.alloc, makeSecretEntry(listed));
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchSecretPath(uri_parts.path)) |secret_path| {
                const secret_store = self.cfg.secret_store orelse return try textResponse(self.alloc, 503, "secret management not available in multi-node mode");
                if (!(try secret_store.delete(secret_path.key))) {
                    return try textResponse(self.alloc, 404, "not found");
                }
                return .{
                    .status = 204,
                    .content_type = null,
                    .body = &.{},
                };
            }
        }
        return null;
    }

    fn dispatchTransactionRoutes(self: *ApiHttpServer, req: http_common.HttpRequest, uri_parts: UriParts, authenticated_identity: ?AuthenticatedIdentity) !?http_common.HttpResponse {
        if (req.method == .GET) {
            if (std.mem.eql(u8, uri_parts.path, routes.Routes.transactions)) {
                const sessions = try self.txn_sessions.listStatuses(self.alloc);
                defer self.alloc.free(sessions);
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildSessionListResponse(arena_impl.allocator(), sessions);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST and std.mem.eql(u8, uri_parts.path, routes.Routes.transactions_cleanup)) {
            const now_ns = platform_time.realtimeNs();
            const cutoff_ns = if (try parseUnsignedQueryParam(uri_parts.query, "cutoff_ns")) |explicit_cutoff|
                explicit_cutoff
            else if (self.cfg.session_ttl_ns) |ttl_ns|
                now_ns -| ttl_ns
            else
                return try textResponse(self.alloc, 400, "missing cutoff");
            const removed = try self.cleanupExpiredSessions(cutoff_ns);
            return try jsonResponse(self.alloc, transactions_api.buildSessionCleanupResponse(removed, cutoff_ns));
        }
        if (req.method == .POST and std.mem.eql(u8, uri_parts.path, routes.Routes.eval)) {
            var parsed = metadata_openapi.server.parseEvaluateBody(self.alloc, req.body) catch {
                return try jsonErrorResponse(self.alloc, 400, "invalid eval request");
            };
            defer parsed.deinit();
            var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
            defer arena_impl.deinit();
            const response = retrieval_agent.buildEvalResponse(arena_impl.allocator(), parsed.value) catch |err| switch (err) {
                error.InvalidEvalRequest => return try jsonErrorResponse(self.alloc, 400, "invalid eval request"),
                else => return err,
            };
            return try jsonResponse(self.alloc, response);
        }
        if (req.method == .POST and std.mem.eql(u8, uri_parts.path, routes.Routes.agents_query_builder)) {
            var parsed = metadata_openapi.server.parseQueryBuilderAgentBody(self.alloc, req.body) catch {
                return try jsonErrorResponse(self.alloc, 400, "invalid query builder request");
            };
            defer parsed.deinit();
            if (parsed.value.intent.len == 0) return try jsonErrorResponse(self.alloc, 400, "invalid query builder request");

            var table_context: ?query_builder_agent.QueryBuilderTableContext = null;
            defer if (table_context) |context| freeQueryBuilderTableContext(self.alloc, context);
            var runtime_validator_context: ?QueryBuilderRuntimeQueryRequestValidatorContext = null;
            if (parsed.value.table) |table_name| {
                if (self.cfg.auth_enabled) {
                    const identity = authenticated_identity orelse return try unauthorizedResponse(self.alloc);
                    if (!permissionsAllow(identity.permissions, .table, table_name, .read)) {
                        return try jsonErrorResponse(self.alloc, 403, "forbidden");
                    }
                }
                table_context = self.loadQueryBuilderTableContext(table_name) catch |err| switch (err) {
                    error.TableNotFound => return try jsonErrorResponse(self.alloc, 404, "not found"),
                    else => return err,
                };
                if (self.table_reads) |reads| {
                    runtime_validator_context = .{
                        .server = self,
                        .source = reads,
                        .table_name = table_name,
                    };
                    table_context.?.runtime_query_request_validator = runtime_validator_context.?.iface();
                }
            }

            var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
            defer arena_impl.deinit();
            const QueryBuilderGenerationRunner = struct {
                antfly_provider: ?managed_embedder.AntflyProvider,
                secret_store: ?*common_secrets.FileStore,
                inference_api_key: ?[]const u8,

                fn iface(runner: *@This()) query_builder_agent.GenerationRunner {
                    return .{
                        .ptr = runner,
                        .vtable = &.{ .execute_chain = executeChain },
                    };
                }

                fn executeChain(
                    ptr: *anyopaque,
                    alloc: std.mem.Allocator,
                    chain: []const generating_runtime.ChainLink,
                    messages: []const generating_runtime.ChatMessage,
                ) !generating_runtime.GenerateResult {
                    const runner: *@This() = @ptrCast(@alignCast(ptr));
                    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
                    defer io_impl.deinit();
                    var client = httpx.Client.initWithConfig(alloc, io_impl.io(), .{ .keep_alive = false });
                    defer client.deinit();
                    return try generating_runtime.executeChainWithOptions(alloc, &client, chain, .{ .antfly_provider = runner.antfly_provider, .secret_store = runner.secret_store, .inference_api_key = runner.inference_api_key }, messages);
                }
            };
            var generation_runner = QueryBuilderGenerationRunner{ .antfly_provider = self.antfly_provider, .secret_store = self.cfg.secret_store, .inference_api_key = self.cfg.inference_api_key };
            var collected_context = query_builder_agent.collectQueryBuilderContext(table_context);
            const response = query_builder_agent.buildQueryBuilderResponseWithCollectedContext(arena_impl.allocator(), parsed.value, &collected_context, generation_runner.iface()) catch |err| switch (err) {
                error.InvalidQueryBuilderRequest => return try jsonErrorResponse(self.alloc, 400, "invalid query builder request"),
                error.DocIdentityNamespaceMismatch => return try jsonErrorResponse(self.alloc, 503, "doc identity unavailable"),
                else => return err,
            };
            return try jsonResponse(self.alloc, response);
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTransactionSession(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                var details = (self.txn_sessions.getDetails(self.alloc, txn_id) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                defer details.deinit(self.alloc);
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildSessionDetailsResponse(arena_impl.allocator(), details);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (std.mem.eql(u8, uri_parts.path, routes.Routes.transactions_begin)) {
                const begin_req = transactions_api.parseBeginRequest(self.alloc, req.body) catch {
                    return try textResponse(self.alloc, 400, "invalid transaction begin request");
                };
                const session = try self.txn_sessions.begin(self.alloc, begin_req, self.localSessionNodeId());
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildBeginResponse(arena_impl.allocator(), session);
                return try jsonResponseWithStatus(self.alloc, 201, response);
            }
        }
        if (req.method == .POST) {
            if (std.mem.eql(u8, uri_parts.path, routes.Routes.transactions_commit)) {
                const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
                var commit_req = transactions_api.parseCommitRequest(self.alloc, req.body) catch |err| switch (err) {
                    error.InvalidTransactionCommitRequest => {
                        return try textResponse(self.alloc, 400, "invalid transaction commit request");
                    },
                    else => return err,
                };
                defer commit_req.deinit(self.alloc);

                const distributed_tables = try commit_req.distributedTables(self.alloc);
                defer if (distributed_tables.len > 0) self.alloc.free(distributed_tables);
                self.validateCommitTablesAgainstSchema(distributed_tables) catch |err| switch (err) {
                    error.InvalidBatchRequest => return try textResponse(self.alloc, 400, "invalid transaction commit request"),
                    else => return err,
                };
                if (try self.validateCommitReadSet(commit_req)) |conflict| {
                    var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena_impl.deinit();
                    const response = try transactions_api.buildCommitResponse(
                        arena_impl.allocator(),
                        "aborted",
                        conflict,
                        null,
                    );
                    return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                }

                const outcome = (source.commitTransaction(self.alloc, distributed_tables, commit_req.sync_level) catch |err| switch (err) {
                    error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid transaction commit request"),
                    error.TopologyChanged => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildCommitResponse(
                            arena_impl.allocator(),
                            "aborted",
                            transactions_api.topologyChangedConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.DecisionConflict => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildCommitResponse(
                            arena_impl.allocator(),
                            "aborted",
                            transactions_api.decisionConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.DocIdentityNamespaceMismatch => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildCommitResponse(
                            arena_impl.allocator(),
                            "aborted",
                            transactions_api.docIdentityUnavailableConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.TxnNotFound, error.InvalidTxnRecord => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildCommitResponse(
                            arena_impl.allocator(),
                            "aborted",
                            transactions_api.tornStateConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                    error.TableNotFound, error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");

                switch (outcome) {
                    .committed => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildCommitResponse(arena_impl.allocator(), "committed", null, commit_req.tables);
                        return try jsonResponseOmitNullOptionals(self.alloc, response);
                    },
                    .conflict => |conflict| {
                        const enriched_conflict = try self.enrichCommitConflict(commit_req, conflict);
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildCommitResponse(
                            arena_impl.allocator(),
                            "aborted",
                            enriched_conflict,
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                }
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionRead(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                var read_req = transactions_api.parseStageReadPayload(self.alloc, req.body) catch {
                    return try textResponse(self.alloc, 400, "invalid transaction read request");
                };
                defer read_req.deinit(self.alloc);

                var owned_snapshot: transactions_api.SessionReadSnapshot = (self.txn_sessions.getReadSnapshot(self.alloc, txn_id, read_req.table_name, read_req.key) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse .{
                    .table_name = try self.alloc.dupe(u8, read_req.table_name),
                    .key = try self.alloc.dupe(u8, read_req.key),
                    .version = 0,
                    .document_json = null,
                };
                defer owned_snapshot.deinit(self.alloc);

                if (owned_snapshot.version == 0 and self.table_reads != null) {
                    const fetched = try self.lookupStageReadSnapshot(read_req.table_name, read_req.key);
                    if (owned_snapshot.document_json) |document_json| self.alloc.free(document_json);
                    self.alloc.free(owned_snapshot.table_name);
                    self.alloc.free(owned_snapshot.key);
                    owned_snapshot = .{
                        .table_name = try self.alloc.dupe(u8, fetched.table_name),
                        .key = try self.alloc.dupe(u8, fetched.key),
                        .version = fetched.version,
                        .document_json = if (fetched.document_json) |document_json| try self.alloc.dupe(u8, document_json) else null,
                    };
                    if (fetched.document_json) |document_json| self.alloc.free(document_json);
                } else if (owned_snapshot.version == 0) {
                    owned_snapshot.version = read_req.version;
                }
                if (owned_snapshot.version != read_req.version) {
                    var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena_impl.deinit();
                    const response = try transactions_api.buildSessionCommitResponse(
                        arena_impl.allocator(),
                        txn_id,
                        "conflict",
                        transactions_api.versionConflict(read_req.table_name, read_req.key, read_req.version, owned_snapshot.version),
                        null,
                    );
                    return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                }

                var stage_req = try transactions_api.ownedRequestFromStageReadRequest(self.alloc, read_req);
                defer stage_req.deinit(self.alloc);

                const session = (self.txn_sessions.stageRead(self.alloc, txn_id, &stage_req, owned_snapshot.stage()) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildStageReadResponse(arena_impl.allocator(), session.txn_id, owned_snapshot.stage());
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionWrite(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                var stage_req = transactions_api.parseStageWriteRequest(self.alloc, req.body) catch {
                    return try textResponse(self.alloc, 400, "invalid transaction write request");
                };
                defer stage_req.deinit(self.alloc);

                const session = (self.txn_sessions.stage(self.alloc, txn_id, &stage_req) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildStageResponse(arena_impl.allocator(), session.txn_id);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionDelete(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                var stage_req = transactions_api.parseStageDeleteRequest(self.alloc, req.body) catch {
                    return try textResponse(self.alloc, 400, "invalid transaction delete request");
                };
                defer stage_req.deinit(self.alloc);

                const session = (self.txn_sessions.stage(self.alloc, txn_id, &stage_req) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildStageResponse(arena_impl.allocator(), session.txn_id);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionSavepoints(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                const info = (self.txn_sessions.createSavepoint(self.alloc, txn_id) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    error.SavepointLimitExceeded => return try textResponse(self.alloc, 409, "savepoint limit exceeded"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildSavepointResponse(arena_impl.allocator(), info);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionRollback(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                const info = (self.txn_sessions.rollbackToSavepoint(self.alloc, txn_id, session_route.savepoint_id) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildRollbackResponse(arena_impl.allocator(), info);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionStage(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                var stage_req = transactions_api.parseCommitRequest(self.alloc, req.body) catch |err| switch (err) {
                    error.InvalidTransactionCommitRequest => {
                        return try textResponse(self.alloc, 400, "invalid transaction stage request");
                    },
                    else => return err,
                };
                defer stage_req.deinit(self.alloc);

                const session = (self.txn_sessions.stage(self.alloc, txn_id, &stage_req) catch |err| switch (err) {
                    error.SessionLeaseLost => return try textResponse(self.alloc, 409, "session lease lost"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildStageResponse(arena_impl.allocator(), session.txn_id);
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionCommit(uri_parts.path)) |session_route| {
                const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                const session = self.txn_sessions.getInfo(txn_id) orelse return try textResponse(self.alloc, 404, "not found");

                var parsed_req: ?transactions_api.OwnedTransactionCommitRequest = null;
                defer if (parsed_req) |*commit_req| commit_req.deinit(self.alloc);
                if (!transactions_api.isEmptySessionCommitBody(req.body)) {
                    parsed_req = transactions_api.parseCommitRequest(self.alloc, req.body) catch |err| switch (err) {
                        error.InvalidTransactionCommitRequest => {
                            return try textResponse(self.alloc, 400, "invalid transaction commit request");
                        },
                        else => return err,
                    };
                }
                var commit_req = (self.txn_sessions.cloneCommitRequest(self.alloc, txn_id, if (parsed_req) |*value| value else null) catch |err| switch (err) {
                    error.SessionLeaseLost => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(
                            arena_impl.allocator(),
                            txn_id,
                            "aborted",
                            transactions_api.sessionLeaseLostConflict(if (parsed_req) |value| if (value.tables.len > 0) value.tables[0].table_name else "" else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    else => return err,
                }) orelse {
                    return try textResponse(self.alloc, 400, "transaction has no staged writes");
                };
                defer commit_req.deinit(self.alloc);

                const distributed_tables = try commit_req.distributedTables(self.alloc);
                defer if (distributed_tables.len > 0) self.alloc.free(distributed_tables);
                self.validateCommitTablesAgainstSchema(distributed_tables) catch |err| switch (err) {
                    error.InvalidBatchRequest => return try textResponse(self.alloc, 400, "invalid transaction commit request"),
                    else => return err,
                };
                if (try self.validateCommitReadSet(commit_req)) |conflict| {
                    _ = self.txn_sessions.remove(self.alloc, txn_id);
                    var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena_impl.deinit();
                    const response = try transactions_api.buildSessionCommitResponse(
                        arena_impl.allocator(),
                        txn_id,
                        "aborted",
                        conflict,
                        null,
                    );
                    return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                }

                const outcome = (source.commitTransactionWithId(self.alloc, txn_id, session.begin_timestamp, distributed_tables, session.sync_level) catch |err| switch (err) {
                    error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid transaction commit request"),
                    error.TopologyChanged => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(
                            arena_impl.allocator(),
                            txn_id,
                            "aborted",
                            transactions_api.topologyChangedConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.DecisionConflict => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(
                            arena_impl.allocator(),
                            txn_id,
                            "aborted",
                            transactions_api.decisionConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.DocIdentityNamespaceMismatch => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(
                            arena_impl.allocator(),
                            txn_id,
                            "aborted",
                            transactions_api.docIdentityUnavailableConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                    error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.UnknownGroup => {
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(
                            arena_impl.allocator(),
                            txn_id,
                            "aborted",
                            transactions_api.participantUnavailableConflict(if (commit_req.tables.len > 0) commit_req.tables[0].table_name else ""),
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");

                switch (outcome) {
                    .committed => {
                        _ = self.txn_sessions.remove(self.alloc, txn_id);
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(arena_impl.allocator(), txn_id, "committed", null, commit_req.tables);
                        return try jsonResponseOmitNullOptionals(self.alloc, response);
                    },
                    .conflict => |conflict| {
                        _ = self.txn_sessions.remove(self.alloc, txn_id);
                        const enriched_conflict = try self.enrichCommitConflict(commit_req, conflict);
                        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                        defer arena_impl.deinit();
                        const response = try transactions_api.buildSessionCommitResponse(
                            arena_impl.allocator(),
                            txn_id,
                            "aborted",
                            enriched_conflict,
                            null,
                        );
                        return try jsonResponseWithStatusOmitNullOptionals(self.alloc, 409, response);
                    },
                }
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTransactionSessionAbort(uri_parts.path)) |session_route| {
                const txn_id = distributed_txn.parseTxnIdHex(session_route.txn_id) catch return try textResponse(self.alloc, 400, "invalid transaction id");
                if (try self.forwardSessionRequest(txn_id, req)) |resp| return resp;
                if (!self.txn_sessions.remove(self.alloc, txn_id)) return try textResponse(self.alloc, 404, "not found");
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = try transactions_api.buildAbortResponse(arena_impl.allocator(), txn_id);
                return try jsonResponse(self.alloc, response);
            }
        }
        return null;
    }

    fn internalRoutesContext(self: *ApiHttpServer, uri_parts: UriParts) http_internal_routes.Context {
        return .{
            .alloc = self.alloc,
            .path = uri_parts.path,
            .query = uri_parts.query,
            .read_ctx = .{
                .alloc = self.alloc,
                .reads = self.table_reads,
                .catalog = .{
                    .ptr = self.source.ptr,
                    .admin_snapshot = self.source.vtable.admin_snapshot,
                    .free_admin_snapshot = self.source.vtable.free_admin_snapshot,
                },
                .query_router = .{
                    .ptr = self,
                    .route_query_to_read_schema = routeInternalGroupQueryToReadSchema,
                },
            },
            .join_ctx = self.joinContext(),
            .join_job_store = &self.join_job_store,
            .write_ctx = .{
                .alloc = self.alloc,
                .shard_ops = self.cfg.shard_ops,
                .shard_db_adapter = self.cfg.shard_db_adapter,
                .writes = self.table_writes,
                .batch_validator = .{
                    .ptr = self,
                    .validate = validateInternalGroupBatchWrites,
                },
                .txn_validator = .{
                    .ptr = self,
                    .validate = validateInternalGroupTxnWrites,
                },
            },
            .retrieval_executor = .{
                .ptr = self,
                .execute = executeInternalRetrievalRoute,
            },
        };
    }

    pub fn executeA2aRetrieval(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        body: []const u8,
        task_id: []const u8,
        context_id: []const u8,
        queue: *a2a.EventQueue,
        authenticated_identity: ?protocol_adapters.DelegatedIdentity,
    ) !void {
        const source = self.table_reads orelse {
            try queue.status(alloc, task_id, context_id, "failed", "not found");
            return;
        };

        const RetrievalQueryRunner = struct {
            server: *ApiHttpServer,
            source: table_reads.TableReadSource,
            authenticated_identity: ?protocol_adapters.DelegatedIdentity,

            fn iface(runner: *@This()) retrieval_agent.QueryRunner {
                return .{
                    .ptr = runner,
                    .vtable = &.{
                        .run_query = runQuery,
                        .scan_keys = scanKeys,
                    },
                };
            }

            fn runQuery(
                ptr_inner: *anyopaque,
                inner_alloc: std.mem.Allocator,
                table_name: []const u8,
                query_json: []const u8,
            ) !query_api.QueryResponse {
                const runner: *@This() = @ptrCast(@alignCast(ptr_inner));
                try runner.ensureTableReadable(table_name);
                const row_filter_json = try runner.server.resolveEffectiveRowFilterJsonForDatabase(inner_alloc, runner.authenticated_identity, tables_api.default_database_name, table_name);
                defer if (row_filter_json) |value| inner_alloc.free(value);
                var semantic_resolver = SemanticStatusResolver{
                    .source = runner.server.source,
                    .antfly_provider = runner.server.antfly_provider,
                    .remote_content = runner.server.cfg.remote_content,
                    .inference_api_key = runner.server.cfg.inference_api_key,
                };
                var query_req = query_api.parsePublicQueryRequest(inner_alloc, semantic_resolver.iface(), table_name, query_json) catch |err| switch (err) {
                    error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidRetrievalAgentRequest,
                    else => return err,
                };
                defer query_req.deinit(inner_alloc);
                runner.server.maybeRouteQueryToReadSchema(table_name, &query_req.req) catch |err| switch (err) {
                    error.TableNotFound => return err,
                    error.InvalidSchemaUpdateRequest, error.InvalidTableIndexMetadata => return error.InvalidRetrievalAgentRequest,
                    else => return err,
                };
                if (row_filter_json) |value| try injectRowFilterIntoSearchRequest(inner_alloc, &query_req.req, value);
                return (runner.source.query(
                    inner_alloc,
                    table_name,
                    query_req.req,
                    .read_index,
                ) catch |err| {
                    if (err == error.DocIdentityNamespaceMismatch) return err;
                    std.log.err("retrieval query failed table={s} query={s} err={}", .{ table_name, query_json, err });
                    return err;
                }) orelse error.TableNotFound;
            }

            fn scanKeys(
                ptr_inner: *anyopaque,
                inner_alloc: std.mem.Allocator,
                table_name: []const u8,
            ) ![]const []const u8 {
                const runner: *@This() = @ptrCast(@alignCast(ptr_inner));
                try runner.ensureTableReadable(table_name);
                var scan = (try runner.source.scan(
                    inner_alloc,
                    table_name,
                    "",
                    "",
                    .{ .limit = 0 },
                    .read_index,
                )) orelse return error.TableNotFound;
                defer scan.deinit(inner_alloc);

                var keys = std.ArrayListUnmanaged([]const u8).empty;
                errdefer {
                    for (keys.items) |key| inner_alloc.free(key);
                    keys.deinit(inner_alloc);
                }

                var lines = std.mem.splitScalar(u8, scan.ndjson, '\n');
                while (lines.next()) |line| {
                    if (line.len == 0) continue;
                    const key = scanLineKey(inner_alloc, line) catch return error.InvalidRetrievalAgentRequest;
                    try keys.append(inner_alloc, key);
                }
                return try keys.toOwnedSlice(inner_alloc);
            }

            fn ensureTableReadable(runner: *@This(), table_name: []const u8) !void {
                const identity = runner.authenticated_identity orelse return;
                if (!permissionsAllow(identity.permissions, .table, table_name, .read)) return error.PermissionDenied;
            }
        };

        const RetrievalGenerationRunner = struct {
            antfly_provider: ?managed_embedder.AntflyProvider,
            secret_store: ?*common_secrets.FileStore,
            inference_api_key: ?[]const u8,

            fn iface(runner: *@This()) retrieval_agent.GenerationRunner {
                return .{
                    .ptr = runner,
                    .vtable = &.{ .execute_chain = executeChain },
                };
            }

            fn executeChain(
                runner_ptr: *anyopaque,
                inner_alloc: std.mem.Allocator,
                chain: []const generating_runtime.ChainLink,
                messages: []const generating_runtime.ChatMessage,
            ) !generating_runtime.GenerateResult {
                const runner: *@This() = @ptrCast(@alignCast(runner_ptr));
                var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
                defer io_impl.deinit();
                var client = httpx.Client.initWithConfig(inner_alloc, io_impl.io(), .{ .keep_alive = false });
                defer client.deinit();
                return try generating_runtime.executeChainWithOptions(inner_alloc, &client, chain, .{ .antfly_provider = runner.antfly_provider, .secret_store = runner.secret_store, .inference_api_key = runner.inference_api_key }, messages);
            }
        };
        var generation_runner = RetrievalGenerationRunner{ .antfly_provider = self.antfly_provider, .secret_store = self.cfg.secret_store, .inference_api_key = self.cfg.inference_api_key };

        var query_runner = RetrievalQueryRunner{
            .server = self,
            .source = source,
            .authenticated_identity = authenticated_identity,
        };

        const RetrievalA2aSink = struct {
            queue: *a2a.EventQueue,
            task_id: []const u8,
            context_id: []const u8,

            fn iface(sink: *@This()) retrieval_agent.EventSink {
                return .{ .ptr = sink, .emit_json_fn = emitJson };
            }

            fn emitJson(ptr_inner: *anyopaque, event_alloc: std.mem.Allocator, event_name: []const u8, json: []const u8) !void {
                const sink: *@This() = @ptrCast(@alignCast(ptr_inner));
                const parsed: std.json.Value = std.json.parseFromSliceLeaky(std.json.Value, event_alloc, json, .{}) catch .{ .string = try event_alloc.dupe(u8, json) };

                if (std.mem.eql(u8, event_name, "error")) {
                    try sink.queue.status(event_alloc, sink.task_id, sink.context_id, "failed", json);
                    return;
                }

                const artifact_name = if (std.mem.eql(u8, event_name, "done")) "result" else event_name;
                var payload = std.json.ObjectMap.empty;
                try payload.put(event_alloc, "event", .{ .string = event_name });
                try payload.put(event_alloc, "data", parsed);
                try sink.queue.artifact(event_alloc, sink.task_id, sink.context_id, artifact_name, try a2a.dataPart(event_alloc, .{ .object = payload }));

                if (std.mem.eql(u8, event_name, "done")) {
                    const status = if (parsed == .object) parsed.object.get("status") else null;
                    const state = if (status) |value| switch (value) {
                        .string => |text| text,
                        else => "completed",
                    } else "completed";
                    try sink.queue.status(event_alloc, sink.task_id, sink.context_id, state, "retrieval completed");
                }
            }
        };

        var sink = RetrievalA2aSink{
            .queue = queue,
            .task_id = task_id,
            .context_id = context_id,
        };
        try queue.status(alloc, task_id, context_id, "working", "retrieval started");
        const retrieval_resp = retrieval_agent.executeWithEventSink(alloc, query_runner.iface(), generation_runner.iface(), body, sink.iface()) catch |err| switch (err) {
            error.InvalidRetrievalAgentRequest, error.UnsupportedRetrievalAgentRequest => {
                try queue.status(alloc, task_id, context_id, "failed", "invalid retrieval agent request");
                return;
            },
            error.TableNotFound => {
                try queue.status(alloc, task_id, context_id, "failed", "not found");
                return;
            },
            error.PermissionDenied => {
                try queue.status(alloc, task_id, context_id, "failed", "forbidden");
                return;
            },
            error.DocIdentityNamespaceMismatch => {
                try queue.status(alloc, task_id, context_id, "failed", "doc identity unavailable");
                return;
            },
            else => {
                std.log.err("public retrieval failed err={}", .{err});
                return err;
            },
        };
        defer alloc.free(retrieval_resp.body);
    }

    fn executeInternalRetrievalRoute(ptr: *anyopaque, req: http_common.HttpRequest, path: []const u8) !?http_common.HttpResponse {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        if (req.method != .POST or !std.mem.eql(u8, path, routes.Routes.agents_retrieval)) return null;

        const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");

        const RetrievalQueryRunner = struct {
            server: *ApiHttpServer,
            source: table_reads.TableReadSource,

            fn iface(runner: *@This()) retrieval_agent.QueryRunner {
                return .{
                    .ptr = runner,
                    .vtable = &.{
                        .run_query = runQuery,
                        .scan_keys = scanKeys,
                    },
                };
            }

            fn runQuery(
                ptr_inner: *anyopaque,
                alloc: std.mem.Allocator,
                table_name: []const u8,
                query_json: []const u8,
            ) !query_api.QueryResponse {
                const runner: *@This() = @ptrCast(@alignCast(ptr_inner));
                var semantic_resolver = SemanticStatusResolver{
                    .source = runner.server.source,
                    .antfly_provider = runner.server.antfly_provider,
                    .remote_content = runner.server.cfg.remote_content,
                    .inference_api_key = runner.server.cfg.inference_api_key,
                };
                var query_req = query_api.parseQueryRequest(alloc, semantic_resolver.iface(), table_name, query_json) catch |err| switch (err) {
                    error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidRetrievalAgentRequest,
                    else => return err,
                };
                defer query_req.deinit(alloc);
                runner.server.maybeRouteQueryToReadSchema(table_name, &query_req.req) catch |err| switch (err) {
                    error.TableNotFound => return err,
                    error.InvalidSchemaUpdateRequest, error.InvalidTableIndexMetadata => return error.InvalidRetrievalAgentRequest,
                    else => return err,
                };
                return (runner.source.query(
                    alloc,
                    table_name,
                    query_req.req,
                    .read_index,
                ) catch |err| {
                    if (err == error.DocIdentityNamespaceMismatch) return err;
                    std.log.err("retrieval query failed table={s} query={s} err={}", .{ table_name, query_json, err });
                    return err;
                }) orelse error.TableNotFound;
            }

            fn scanKeys(
                ptr_inner: *anyopaque,
                alloc: std.mem.Allocator,
                table_name: []const u8,
            ) ![]const []const u8 {
                const runner: *@This() = @ptrCast(@alignCast(ptr_inner));
                var scan = (try runner.source.scan(
                    alloc,
                    table_name,
                    "",
                    "",
                    .{ .limit = 0 },
                    .read_index,
                )) orelse return error.TableNotFound;
                defer scan.deinit(alloc);

                var keys = std.ArrayListUnmanaged([]const u8).empty;
                errdefer {
                    for (keys.items) |key| alloc.free(key);
                    keys.deinit(alloc);
                }

                var lines = std.mem.splitScalar(u8, scan.ndjson, '\n');
                while (lines.next()) |line| {
                    if (line.len == 0) continue;
                    const key = scanLineKey(alloc, line) catch return error.InvalidRetrievalAgentRequest;
                    try keys.append(alloc, key);
                }
                return try keys.toOwnedSlice(alloc);
            }
        };

        const RetrievalGenerationRunner = struct {
            antfly_provider: ?managed_embedder.AntflyProvider,
            secret_store: ?*common_secrets.FileStore,
            inference_api_key: ?[]const u8,

            fn iface(runner: *@This()) retrieval_agent.GenerationRunner {
                return .{
                    .ptr = runner,
                    .vtable = &.{ .execute_chain = executeChain },
                };
            }

            fn executeChain(
                runner_ptr: *anyopaque,
                alloc: std.mem.Allocator,
                chain: []const generating_runtime.ChainLink,
                messages: []const generating_runtime.ChatMessage,
            ) !generating_runtime.GenerateResult {
                const runner: *@This() = @ptrCast(@alignCast(runner_ptr));
                var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
                defer io_impl.deinit();
                var client = httpx.Client.initWithConfig(alloc, io_impl.io(), .{ .keep_alive = false });
                defer client.deinit();
                return try generating_runtime.executeChainWithOptions(alloc, &client, chain, .{ .antfly_provider = runner.antfly_provider, .secret_store = runner.secret_store, .inference_api_key = runner.inference_api_key }, messages);
            }
        };
        var generation_runner = RetrievalGenerationRunner{ .antfly_provider = self.antfly_provider, .secret_store = self.cfg.secret_store, .inference_api_key = self.cfg.inference_api_key };

        var query_runner = RetrievalQueryRunner{
            .server = self,
            .source = source,
        };
        const retrieval_resp = retrieval_agent.execute(self.alloc, query_runner.iface(), generation_runner.iface(), req.body) catch |err| switch (err) {
            error.InvalidRetrievalAgentRequest, error.UnsupportedRetrievalAgentRequest => return try textResponse(self.alloc, 400, "invalid retrieval agent request"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
            else => {
                std.log.err("public retrieval failed err={}", .{err});
                return err;
            },
        };
        defer self.alloc.free(retrieval_resp.body);
        if (std.mem.eql(u8, retrieval_resp.content_type, "text/event-stream")) {
            return try eventStreamResponse(self.alloc, 200, retrieval_resp.body);
        }
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const response = try parseJsonResponseBody(metadata_openapi.RetrievalAgentResult, arena_impl.allocator(), retrieval_resp.body);
        return try jsonResponse(self.alloc, response);
    }

    const PublicDatabaseCatalogResponse = struct {
        database_id: u64,
        name: []const u8,
        settings_json: []const u8,
        tablespace_name: ?[]const u8 = null,
    };

    const PublicNamespaceCatalogResponse = struct {
        namespace_id: u64,
        database_id: u64,
        database_name: []const u8,
        name: []const u8,
        tablespace_name: ?[]const u8 = null,
    };

    const PublicTablespaceCatalogResponse = struct {
        tablespace_id: u64,
        name: []const u8,
        location_json: []const u8,
        placement_policy_json: []const u8,
    };

    const PublicCreateTablespaceRequest = struct {
        location_json: ?[]u8 = null,
        placement_policy_json: ?[]u8 = null,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.location_json) |value| alloc.free(value);
            if (self.placement_policy_json) |value| alloc.free(value);
            self.* = undefined;
        }
    };

    const PublicCatalogTablespaceBindingRequest = struct {
        tablespace_name: []u8,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.tablespace_name);
            self.* = undefined;
        }
    };

    pub fn handlePublicListDatabases(self: *ApiHttpServer) !http_common.HttpResponse {
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const out = try self.alloc.alloc(PublicDatabaseCatalogResponse, snapshot.databases.len);
        defer self.alloc.free(out);
        for (snapshot.databases, 0..) |database, i| out[i] = databaseResponse(database);
        return try jsonResponse(self.alloc, out);
    }

    pub fn handlePublicGetDatabase(self: *ApiHttpServer, database_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 404, "not found");
        return try jsonResponse(self.alloc, databaseResponse(database.*));
    }

    pub fn handlePublicCreateDatabase(self: *ApiHttpServer, database_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        var applied = self.source.applyDatabaseCatalogPlan(self.alloc, .{ .create = .{ .database_name = database_name } }) catch |err| switch (err) {
            error.DatabaseAlreadyExists => return try textResponse(self.alloc, 409, "database already exists"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        defer applied.deinit(self.alloc);
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 500, "database create did not converge");
        return try jsonResponseWithStatus(self.alloc, 201, databaseResponse(database.*));
    }

    pub fn handlePublicDropDatabase(self: *ApiHttpServer, database_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        var applied = self.source.applyDatabaseCatalogPlan(self.alloc, .{ .drop = .{ .database_name = database_name } }) catch |err| switch (err) {
            error.DatabaseNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.DatabaseNotEmpty => return try textResponse(self.alloc, 409, "database not empty"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        defer applied.deinit(self.alloc);
        return .{ .status = 204, .content_type = null, .body = &.{} };
    }

    pub fn handlePublicSetDatabaseTablespace(self: *ApiHttpServer, database_name: []const u8, body: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        var req = parseCatalogTablespaceBindingRequest(self.alloc, body) catch return try textResponse(self.alloc, 400, "invalid tablespace binding request");
        defer req.deinit(self.alloc);
        if (!catalogApiIdentifierValid(req.tablespace_name)) return try textResponse(self.alloc, 400, "invalid tablespace name");
        self.source.setDatabaseTablespace(database_name, req.tablespace_name) catch |err| switch (err) {
            error.DatabaseNotFound, error.TablespaceNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        return try self.handlePublicGetDatabase(database_name);
    }

    pub fn handlePublicClearDatabaseTablespace(self: *ApiHttpServer, database_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        self.source.setDatabaseTablespace(database_name, null) catch |err| switch (err) {
            error.DatabaseNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        return try self.handlePublicGetDatabase(database_name);
    }

    pub fn handlePublicListTablespaces(self: *ApiHttpServer) !http_common.HttpResponse {
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const out = try self.alloc.alloc(PublicTablespaceCatalogResponse, snapshot.tablespaces.len);
        defer self.alloc.free(out);
        for (snapshot.tablespaces, 0..) |tablespace, i| out[i] = tablespaceResponse(tablespace);
        return try jsonResponse(self.alloc, out);
    }

    pub fn handlePublicGetTablespace(self: *ApiHttpServer, tablespace_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(tablespace_name)) return try textResponse(self.alloc, 400, "invalid tablespace name");
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const tablespace = tables_api.findTablespaceByName(&snapshot, tablespace_name) orelse return try textResponse(self.alloc, 404, "not found");
        return try jsonResponse(self.alloc, tablespaceResponse(tablespace.*));
    }

    pub fn handlePublicCreateTablespace(self: *ApiHttpServer, tablespace_name: []const u8, body: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(tablespace_name)) return try textResponse(self.alloc, 400, "invalid tablespace name");
        var req = parseCreateTablespaceRequest(self.alloc, body) catch return try textResponse(self.alloc, 400, "invalid tablespace request");
        defer req.deinit(self.alloc);
        const location_json = req.location_json orelse "null";
        const placement_policy_json = req.placement_policy_json orelse "{}";
        var applied = self.source.applyTablespaceCatalogPlan(self.alloc, .{ .create = .{
            .tablespace_name = tablespace_name,
            .location_json = location_json,
            .placement_policy_json = placement_policy_json,
        } }) catch |err| switch (err) {
            error.TablespaceAlreadyExists => return try textResponse(self.alloc, 409, "tablespace already exists"),
            error.InvalidTablespaceLocation => return try textResponse(self.alloc, 400, "invalid tablespace location"),
            error.InvalidTablespacePlacementPolicy => return try textResponse(self.alloc, 400, "invalid tablespace placement policy"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        defer applied.deinit(self.alloc);
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const tablespace = tables_api.findTablespaceByName(&snapshot, tablespace_name) orelse return try textResponse(self.alloc, 500, "tablespace create did not converge");
        return try jsonResponseWithStatus(self.alloc, 201, tablespaceResponse(tablespace.*));
    }

    pub fn handlePublicDropTablespace(self: *ApiHttpServer, tablespace_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(tablespace_name)) return try textResponse(self.alloc, 400, "invalid tablespace name");
        var applied = self.source.applyTablespaceCatalogPlan(self.alloc, .{ .drop = .{ .tablespace_name = tablespace_name } }) catch |err| switch (err) {
            error.TablespaceNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.TablespaceInUse => return try textResponse(self.alloc, 409, "tablespace in use"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        defer applied.deinit(self.alloc);
        return .{ .status = 204, .content_type = null, .body = &.{} };
    }

    pub fn handlePublicListNamespaces(self: *ApiHttpServer, database_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 404, "not found");
        var count: usize = 0;
        for (snapshot.namespaces) |namespace| {
            if (namespace.database_id == database.database_id) count += 1;
        }
        const out = try self.alloc.alloc(PublicNamespaceCatalogResponse, count);
        defer self.alloc.free(out);
        var filled: usize = 0;
        for (snapshot.namespaces) |namespace| {
            if (namespace.database_id != database.database_id) continue;
            out[filled] = namespaceResponse(database.*, namespace);
            filled += 1;
        }
        return try jsonResponse(self.alloc, out);
    }

    pub fn handlePublicListNamespaceTables(self: *ApiHttpServer, database_name: []const u8, namespace_name: []const u8, query: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        _ = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 404, "not found");
        _ = tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) orelse return try textResponse(self.alloc, 404, "not found");
        const params = try parseListTablesParams(query);
        if (params.pattern != null) return try textResponse(self.alloc, 400, "unsupported table pattern");

        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const arena = arena_impl.allocator();
        const filtered_tables = try filteredCatalogTablesAlloc(arena, &snapshot, database_name, namespace_name);
        const filtered_ranges = try filteredCatalogRangesAlloc(arena, &snapshot, filtered_tables);
        var filtered = snapshot;
        filtered.tables = filtered_tables;
        filtered.ranges = filtered_ranges;
        const response = try tables_api.buildTableListWithStorageStatuses(arena, &filtered, params.prefix, null);
        return try jsonResponse(self.alloc, response);
    }

    fn filteredCatalogTablesAlloc(
        alloc: std.mem.Allocator,
        snapshot: *const metadata_api.AdminSnapshot,
        database_name: []const u8,
        namespace_name: []const u8,
    ) ![]metadata_table_manager.TableRecord {
        var count: usize = 0;
        for (snapshot.tables) |table| {
            if (std.mem.eql(u8, table.database_name, database_name) and std.mem.eql(u8, table.namespace_name, namespace_name)) count += 1;
        }
        const out = try alloc.alloc(metadata_table_manager.TableRecord, count);
        var filled: usize = 0;
        for (snapshot.tables) |table| {
            if (!std.mem.eql(u8, table.database_name, database_name) or !std.mem.eql(u8, table.namespace_name, namespace_name)) continue;
            out[filled] = table;
            filled += 1;
        }
        return out;
    }

    fn filteredCatalogRangesAlloc(
        alloc: std.mem.Allocator,
        snapshot: *const metadata_api.AdminSnapshot,
        tables: []const metadata_table_manager.TableRecord,
    ) ![]metadata_table_manager.RangeRecord {
        var count: usize = 0;
        for (snapshot.ranges) |range| {
            if (catalogRangeBelongsToTables(range, tables)) count += 1;
        }
        const out = try alloc.alloc(metadata_table_manager.RangeRecord, count);
        var filled: usize = 0;
        for (snapshot.ranges) |range| {
            if (!catalogRangeBelongsToTables(range, tables)) continue;
            out[filled] = range;
            filled += 1;
        }
        return out;
    }

    fn catalogRangeBelongsToTables(range: metadata_table_manager.RangeRecord, tables: []const metadata_table_manager.TableRecord) bool {
        for (tables) |table| {
            if (range.table_id == table.table_id) return true;
        }
        return false;
    }

    pub fn handlePublicCreateNamespace(self: *ApiHttpServer, database_name: []const u8, namespace_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        self.source.createNamespace(database_name, namespace_name) catch |err| switch (err) {
            error.DatabaseNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.NamespaceAlreadyExists => return try textResponse(self.alloc, 409, "namespace already exists"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 500, "namespace create did not converge");
        const namespace = tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) orelse return try textResponse(self.alloc, 500, "namespace create did not converge");
        return try jsonResponseWithStatus(self.alloc, 201, namespaceResponse(database.*, namespace.*));
    }

    pub fn handlePublicDropNamespace(self: *ApiHttpServer, database_name: []const u8, namespace_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        self.source.dropNamespace(database_name, namespace_name) catch |err| switch (err) {
            error.DatabaseNotFound, error.NamespaceNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.NamespaceNotEmpty => return try textResponse(self.alloc, 409, "namespace not empty"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        return .{ .status = 204, .content_type = null, .body = &.{} };
    }

    pub fn handlePublicSetNamespaceTablespace(self: *ApiHttpServer, database_name: []const u8, namespace_name: []const u8, body: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        var req = parseCatalogTablespaceBindingRequest(self.alloc, body) catch return try textResponse(self.alloc, 400, "invalid tablespace binding request");
        defer req.deinit(self.alloc);
        if (!catalogApiIdentifierValid(req.tablespace_name)) return try textResponse(self.alloc, 400, "invalid tablespace name");
        self.source.setNamespaceTablespace(database_name, namespace_name, req.tablespace_name) catch |err| switch (err) {
            error.DatabaseNotFound, error.NamespaceNotFound, error.TablespaceNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 404, "not found");
        const namespace = tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) orelse return try textResponse(self.alloc, 404, "not found");
        return try jsonResponse(self.alloc, namespaceResponse(database.*, namespace.*));
    }

    pub fn handlePublicClearNamespaceTablespace(self: *ApiHttpServer, database_name: []const u8, namespace_name: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        self.source.setNamespaceTablespace(database_name, namespace_name, null) catch |err| switch (err) {
            error.DatabaseNotFound, error.NamespaceNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const database = tables_api.findDatabaseByName(&snapshot, database_name) orelse return try textResponse(self.alloc, 404, "not found");
        const namespace = tables_api.findNamespaceByName(&snapshot, database_name, namespace_name) orelse return try textResponse(self.alloc, 404, "not found");
        return try jsonResponse(self.alloc, namespaceResponse(database.*, namespace.*));
    }

    fn databaseResponse(database: metadata_table_manager.DatabaseRecord) PublicDatabaseCatalogResponse {
        return .{
            .database_id = database.database_id,
            .name = database.name,
            .settings_json = database.settings_json,
            .tablespace_name = if (database.tablespace_name.len > 0) database.tablespace_name else null,
        };
    }

    fn namespaceResponse(database: metadata_table_manager.DatabaseRecord, namespace: metadata_table_manager.NamespaceRecord) PublicNamespaceCatalogResponse {
        return .{
            .namespace_id = namespace.namespace_id,
            .database_id = namespace.database_id,
            .database_name = database.name,
            .name = namespace.name,
            .tablespace_name = if (namespace.tablespace_name.len > 0) namespace.tablespace_name else null,
        };
    }

    fn tablespaceResponse(tablespace: metadata_table_manager.TablespaceRecord) PublicTablespaceCatalogResponse {
        return .{
            .tablespace_id = tablespace.tablespace_id,
            .name = tablespace.name,
            .location_json = tablespace.location_json,
            .placement_policy_json = tablespace.placement_policy_json,
        };
    }

    fn parseCreateTablespaceRequest(alloc: std.mem.Allocator, body: []const u8) !PublicCreateTablespaceRequest {
        if (body.len == 0) return .{};
        const ParsedCreateTablespaceRequest = struct {
            location_json: ?[]const u8 = null,
            placement_policy_json: ?[]const u8 = null,
        };
        var parsed = try std.json.parseFromSlice(ParsedCreateTablespaceRequest, alloc, body, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        if (parsed.value.location_json) |location_json| {
            var location = try std.json.parseFromSlice(std.json.Value, alloc, location_json, .{});
            defer location.deinit();
        }
        if (parsed.value.placement_policy_json) |placement_policy_json| {
            var placement = try std.json.parseFromSlice(std.json.Value, alloc, placement_policy_json, .{});
            defer placement.deinit();
        }
        return .{
            .location_json = if (parsed.value.location_json) |value| try alloc.dupe(u8, value) else null,
            .placement_policy_json = if (parsed.value.placement_policy_json) |value| try alloc.dupe(u8, value) else null,
        };
    }

    fn parseCatalogTablespaceBindingRequest(alloc: std.mem.Allocator, body: []const u8) !PublicCatalogTablespaceBindingRequest {
        const ParsedBindingRequest = struct {
            tablespace_name: []const u8,
        };
        var parsed = try std.json.parseFromSlice(ParsedBindingRequest, alloc, body, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        return .{ .tablespace_name = try alloc.dupe(u8, parsed.value.tablespace_name) };
    }

    fn catalogApiIdentifierValid(name: []const u8) bool {
        if (name.len == 0) return false;
        const first = name[0];
        if (!(std.ascii.isAlphabetic(first) or first == '_')) return false;
        for (name[1..]) |ch| {
            if (!(std.ascii.isAlphanumeric(ch) or ch == '_')) return false;
        }
        return true;
    }

    fn defaultPublicCatalog(database_name: []const u8, namespace_name: []const u8) bool {
        return catalog_resources.isDefaultPublicNamespace(database_name, namespace_name);
    }

    const CatalogTableSubroute = struct {
        table_name: []const u8,
        suffix: ?[]const u8 = null,
    };

    fn catalogTableSubroute(table_path: []const u8) CatalogTableSubroute {
        if (std.mem.indexOfScalar(u8, table_path, '/')) |slash| {
            return .{
                .table_name = table_path[0..slash],
                .suffix = table_path[slash + 1 ..],
            };
        }
        return .{ .table_name = table_path };
    }

    fn handlePublicCatalogTableSubroute(
        self: *ApiHttpServer,
        req: http_common.HttpRequest,
        uri_parts: UriParts,
        authenticated_identity: ?AuthenticatedIdentity,
        target: catalog_resources.TableTarget,
        suffix: []const u8,
    ) !http_common.HttpResponse {
        if (std.mem.eql(u8, suffix, "backup")) {
            if (req.method != .POST) return try textResponse(self.alloc, 405, "method not allowed");
            return try self.handlePublicCatalogTableBackup(target, req.body);
        }
        if (std.mem.eql(u8, suffix, "restore")) {
            if (req.method != .POST) return try textResponse(self.alloc, 405, "method not allowed");
            return try self.handlePublicCatalogTableRestore(target, req.body);
        }

        self.ensureCatalogTableExists(target) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        };

        if (std.mem.eql(u8, suffix, "query")) {
            if (req.method != .POST) return try textResponse(self.alloc, 405, "method not allowed");
            return try self.handlePublicCatalogTableQuery(target, req.body, authenticated_identity);
        }
        if (std.mem.eql(u8, suffix, "batch")) {
            if (req.method != .POST) return try textResponse(self.alloc, 405, "method not allowed");
            return try self.handlePublicCatalogTableBatch(target, req.body);
        }
        if (std.mem.eql(u8, suffix, "rows/batch")) {
            if (req.method != .POST) return try textResponse(self.alloc, 405, "method not allowed");
            return try self.handlePublicCatalogTableRowsBatch(target, req.body, authenticated_identity);
        }
        if (std.mem.eql(u8, suffix, "indexes")) {
            if (req.method != .GET) return try textResponse(self.alloc, 405, "method not allowed");
            return try self.handlePublicCatalogTableListIndexes(target);
        }
        if (std.mem.startsWith(u8, suffix, "indexes/")) {
            const index_name = suffix["indexes/".len..];
            if (index_name.len == 0 or std.mem.indexOfScalar(u8, index_name, '/') != null) return try textResponse(self.alloc, 404, "not found");
            return switch (req.method) {
                .GET => try self.handlePublicCatalogTableGetIndex(target, index_name),
                .POST => try self.handlePublicCatalogTableCreateIndex(target, index_name, req.body),
                .DELETE => try self.handlePublicCatalogTableDeleteIndex(target, index_name),
                else => try textResponse(self.alloc, 405, "method not allowed"),
            };
        }
        if (std.mem.startsWith(u8, suffix, "documents/")) {
            if (req.method != .GET) return try textResponse(self.alloc, 405, "method not allowed");
            const key = suffix["documents/".len..];
            if (key.len == 0 or std.mem.indexOfScalar(u8, key, '/') != null) return try textResponse(self.alloc, 404, "not found");
            return try self.handlePublicCatalogTableDocumentLookup(target, key, uri_parts.query, authenticated_identity);
        }
        return try textResponse(self.alloc, 404, "not found");
    }

    fn ensureCatalogTableExists(self: *ApiHttpServer, target: catalog_resources.TableTarget) !void {
        var snapshot = (try self.source.adminSnapshot()) orelse return error.TableNotFound;
        defer self.source.freeAdminSnapshot(&snapshot);
        _ = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;
    }

    pub fn handlePublicCatalogTableListIndexes(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
    ) !http_common.HttpResponse {
        var snapshot = (try self.statusAdminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return try textResponse(self.alloc, 404, "not found");
        var local_statuses = self.localCatalogTableRuntimeStatusesWithSnapshot(target, &snapshot) catch return try textResponse(self.alloc, 500, "index lookup failed");
        defer if (local_statuses) |*status| status.deinit(self.alloc);
        const body = indexes_api.encodeIndexListForTable(
            self.alloc,
            &snapshot,
            table,
            if (local_statuses) |*status| status else null,
        ) catch return try textResponse(self.alloc, 500, "index lookup failed");
        defer self.alloc.free(body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, body);
    }

    pub fn handlePublicCatalogTableGetIndex(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        index_name: []const u8,
    ) !http_common.HttpResponse {
        var snapshot = (try self.statusAdminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return try textResponse(self.alloc, 404, "not found");
        var local_statuses = self.localCatalogTableRuntimeStatusesWithSnapshot(target, &snapshot) catch return try textResponse(self.alloc, 500, "index lookup failed");
        defer if (local_statuses) |*status| status.deinit(self.alloc);
        const body = (indexes_api.encodeSingleIndexForTableWithSnapshot(
            self.alloc,
            &snapshot,
            table,
            index_name,
            if (local_statuses) |*status| status else null,
        ) catch return try textResponse(self.alloc, 500, "index lookup failed")) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, body);
    }

    pub fn handlePublicCatalogTableCreateIndex(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        index_name: []const u8,
        body: []const u8,
    ) !http_common.HttpResponse {
        const table_before = (self.loadOwnedCatalogTableRecord(target) catch return try textResponse(self.alloc, 500, "index create failed")) orelse return try textResponse(self.alloc, 404, "not found");
        defer metadata_table_manager.freeTable(self.alloc, table_before);
        const index_json = table_contract.parseCreateIndexRequest(self.alloc, index_name, body) catch {
            return try textResponse(self.alloc, 400, "unsupported index configuration");
        };
        defer self.alloc.free(index_json);
        tables_api.validatePublicAlgebraicIndexJson(self.alloc, index_json) catch {
            return try textResponse(self.alloc, 400, "unsupported index configuration");
        };
        tables_api.validateDerivedIndexFieldRefsForSchemaAlloc(self.alloc, index_json, table_before.schema_json) catch {
            return try textResponse(self.alloc, 400, "unsupported index configuration");
        };
        const expanded_index_json = tables_api.expandSchemaDerivedAlgebraicIndexAlloc(self.alloc, target.table_name, index_json, table_before.schema_json) catch |err| switch (err) {
            error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported index configuration"),
            else => return try textResponse(self.alloc, 500, "index create failed"),
        };
        defer self.alloc.free(expanded_index_json);
        const normalized_index_json = table_writes.normalizeManagedEmbeddingIndexDimensionJsonWithOptions(
            self.alloc,
            index_name,
            expanded_index_json,
            .{
                .antfly_provider = self.antfly_provider,
                .secret_store = self.cfg.secret_store,
                .remote_content = self.cfg.remote_content,
                .inference_api_key = self.cfg.inference_api_key,
            },
        ) catch |err| switch (err) {
            error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported index configuration"),
            error.EmbeddingProbeUnavailable => return try textResponse(self.alloc, 503, "index validation probe unavailable"),
            else => return try textResponse(self.alloc, 500, "index create failed"),
        };
        defer self.alloc.free(normalized_index_json);

        table_writes.validateIndexConfigWithOptions(self.alloc, index_name, normalized_index_json, .{
            .antfly_provider = self.antfly_provider,
            .secret_store = self.cfg.secret_store,
            .remote_content = self.cfg.remote_content,
            .inference_api_key = self.cfg.inference_api_key,
        }) catch |err| switch (err) {
            error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported index configuration"),
            error.EmbeddingProbeUnavailable => return try textResponse(self.alloc, 503, "index validation probe unavailable"),
            else => return try textResponse(self.alloc, 500, "index create failed"),
        };

        self.source.createCatalogIndex(self.alloc, target, index_name, normalized_index_json) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.ExtensionOwnedObject, error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            error.InvalidTableIndexMetadata, error.InvalidCreateIndexRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported index configuration"),
            else => {
                std.log.err("public create catalog index metadata update failed table={s}.{s}.{s} index={s} err={}", .{ target.database_name, target.namespace_name, target.table_name, index_name, err });
                return try textResponse(self.alloc, 500, "index create failed");
            },
        };
        const expected_indexes_json = indexes_api.addIndexToTableIndexesJson(self.alloc, table_before.indexes_json, index_name, normalized_index_json) catch |err| switch (err) {
            error.InvalidTableIndexMetadata, error.InvalidCreateIndexRequest => return try textResponse(self.alloc, 400, "unsupported index configuration"),
            else => return try textResponse(self.alloc, 500, "index create failed"),
        };
        defer self.alloc.free(expected_indexes_json);
        self.waitForCatalogMetadataProjection(target, null, expected_indexes_json) catch {
            return try textResponse(self.alloc, 500, "index create failed");
        };
        if (self.table_writes) |table_writes_source| {
            _ = table_writes_source.createCatalogIndex(self.alloc, target, index_name, normalized_index_json) catch |err| switch (err) {
                error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported index configuration"),
                error.EmbeddingProbeUnavailable => return try textResponse(self.alloc, 503, "index validation probe unavailable"),
                else => {
                    std.log.err("public create catalog index local apply failed table={s}.{s}.{s} index={s} err={}", .{ target.database_name, target.namespace_name, target.table_name, index_name, err });
                },
            };
        }
        return try jsonResponseWithStatus(self.alloc, 201, .{});
    }

    pub fn handlePublicCatalogTableDeleteIndex(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        index_name: []const u8,
    ) !http_common.HttpResponse {
        const table_before = (self.loadOwnedCatalogTableRecord(target) catch return try textResponse(self.alloc, 500, "index delete failed")) orelse return try textResponse(self.alloc, 404, "not found");
        defer metadata_table_manager.freeTable(self.alloc, table_before);
        self.source.dropCatalogIndex(self.alloc, target, index_name) catch |err| switch (err) {
            error.TableNotFound, error.IndexNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.ExtensionOwnedObject, error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return try textResponse(self.alloc, 500, "index delete failed"),
        };
        const expected_indexes_json = (indexes_api.removeIndexFromTableIndexesJson(self.alloc, table_before.indexes_json, index_name) catch return try textResponse(self.alloc, 500, "index delete failed")) orelse {
            return try textResponse(self.alloc, 404, "not found");
        };
        defer self.alloc.free(expected_indexes_json);
        self.waitForCatalogMetadataProjection(target, null, expected_indexes_json) catch {
            return try textResponse(self.alloc, 500, "index delete failed");
        };
        if (self.table_writes) |table_writes_source| {
            _ = table_writes_source.dropCatalogIndex(self.alloc, target, index_name) catch |err| switch (err) {
                error.TableNotFound, error.IndexNotFound => null,
                else => {
                    std.log.err("public delete catalog index local apply failed table={s}.{s}.{s} index={s} err={}", .{ target.database_name, target.namespace_name, target.table_name, index_name, err });
                },
            };
        }
        return try jsonResponseWithStatus(self.alloc, 201, .{});
    }

    pub fn handlePublicGetCatalogTable(self: *ApiHttpServer, target: catalog_resources.TableTarget) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(target.database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(target.namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        if (!catalogApiIdentifierValid(target.table_name)) return try textResponse(self.alloc, 400, "invalid table name");
        var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.source.freeAdminSnapshot(&snapshot);
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const response = (try tables_api.buildSingleQualifiedTableStatusWithStorageStatuses(
            arena_impl.allocator(),
            &snapshot,
            target.database_name,
            target.namespace_name,
            target.table_name,
            null,
        )) orelse return try textResponse(self.alloc, 404, "not found");
        return try jsonResponse(self.alloc, response);
    }

    pub fn handlePublicCreateCatalogTable(self: *ApiHttpServer, target: catalog_resources.TableTarget, body: []const u8) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(target.database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(target.namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        if (!catalogApiIdentifierValid(target.table_name)) return try textResponse(self.alloc, 400, "invalid table name");
        var create_req = table_contract.parseCreateTableRequest(self.alloc, body) catch |err| {
            std.log.err("create table parse failed: {} body_len={d}", .{ err, body.len });
            return try textResponse(self.alloc, 400, "invalid create table request");
        };
        defer create_req.deinit(self.alloc);
        const normalized_indexes_json = table_writes.normalizeManagedEmbeddingIndexDimensionsJsonWithOptions(
            self.alloc,
            create_req.indexes_json orelse tables_api.default_indexes_json,
            .{
                .antfly_provider = self.antfly_provider,
                .secret_store = self.cfg.secret_store,
                .remote_content = self.cfg.remote_content,
            },
        ) catch |err| switch (err) {
            error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported table index configuration"),
            error.EmbeddingProbeUnavailable => return try textResponse(self.alloc, 503, "table index validation probe unavailable"),
            else => return err,
        };
        if (create_req.indexes_json) |old_indexes_json| self.alloc.free(old_indexes_json);
        create_req.indexes_json = normalized_indexes_json;
        tables_api.validatePublicAlgebraicIndexesJson(self.alloc, create_req.indexes_json orelse tables_api.default_indexes_json) catch {
            return try textResponse(self.alloc, 400, "unsupported table index configuration");
        };

        self.source.createCatalogTable(self.alloc, target, create_req) catch |err| switch (err) {
            error.InvalidTablespacePlacementPolicy => return try textResponse(self.alloc, 400, "invalid tablespace placement policy"),
            error.DatabaseNotFound, error.NamespaceNotFound, error.TablespaceNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.TableAlreadyExists => return try textResponse(self.alloc, 409, "table already exists"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => {
                std.log.err("public create catalog table metadata create failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return err;
            },
        };

        if (self.table_writes) |table_writes_source| {
            _ = table_writes_source.createCatalogTable(self.alloc, target, create_req) catch |err| switch (err) {
                error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported table index configuration"),
                else => {
                    std.log.err("public create catalog table local create failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                    return err;
                },
            };
        }

        self.waitForCatalogTableVisibility(target, .present) catch |err| switch (err) {
            error.TableVisibilityTimeout => return try textResponse(self.alloc, 500, "table create did not converge"),
            else => return err,
        };
        return try self.handlePublicGetCatalogTable(target);
    }

    pub fn handlePublicDropCatalogTable(self: *ApiHttpServer, target: catalog_resources.TableTarget) !http_common.HttpResponse {
        if (!catalogApiIdentifierValid(target.database_name)) return try textResponse(self.alloc, 400, "invalid database name");
        if (!catalogApiIdentifierValid(target.namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
        if (!catalogApiIdentifierValid(target.table_name)) return try textResponse(self.alloc, 400, "invalid table name");
        var local_drop_group_ids: ?[]u64 = null;
        defer if (local_drop_group_ids) |group_ids| self.alloc.free(group_ids);
        if (self.table_writes != null) {
            if (try self.source.adminSnapshot()) |snapshot_value| {
                var snapshot = snapshot_value;
                defer self.source.freeAdminSnapshot(&snapshot);
                local_drop_group_ids = try catalogTableGroupIdsFromSnapshot(self.alloc, &snapshot, target);
            }
        }
        self.source.dropCatalogTable(self.alloc, target) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.ExtensionOwnedObject => return try textResponse(self.alloc, 405, "method not allowed"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            else => {
                std.log.err("public drop catalog table metadata remove failed table={s}.{s}.{s} err={s}", .{
                    target.database_name,
                    target.namespace_name,
                    target.table_name,
                    @errorName(err),
                });
                return err;
            },
        };
        if (self.table_writes) |write_source| {
            const group_ids = local_drop_group_ids orelse &.{};
            _ = write_source.dropCatalogTable(self.alloc, target, group_ids) catch |err| switch (err) {
                error.TableNotFound => null,
                else => {
                    std.log.err("public drop catalog table local cleanup failed table={s}.{s}.{s} err={s}", .{
                        target.database_name,
                        target.namespace_name,
                        target.table_name,
                        @errorName(err),
                    });
                    return err;
                },
            };
        }
        self.waitForCatalogTableVisibility(target, .absent) catch |err| switch (err) {
            error.TableVisibilityTimeout => return try textResponse(self.alloc, 500, "table delete did not converge"),
            else => return err,
        };
        return .{ .status = 204, .content_type = null, .body = &.{} };
    }

    fn waitForCatalogTableVisibility(self: *ApiHttpServer, target: catalog_resources.TableTarget, expected: TableVisibility) !void {
        const timeout_ns = 5 * std.time.ns_per_s;
        const poll_ns = 50 * std.time.ns_per_ms;
        const start_ns = platform_time.monotonicNs();
        while (true) {
            if (try self.source.adminSnapshot()) |snapshot_value| {
                var snapshot = snapshot_value;
                defer self.source.freeAdminSnapshot(&snapshot);
                const present = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) != null;
                if ((expected == .present and present) or (expected == .absent and !present)) return;
            }
            if (platform_time.monotonicNs() -| start_ns >= timeout_ns) return error.TableVisibilityTimeout;
            sleepNs(poll_ns);
        }
    }

    pub fn handlePublicTableDocumentLookup(
        self: *ApiHttpServer,
        table_name: []const u8,
        encoded_key: []const u8,
        query: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
        const decoded_key = try http_route_helpers.decodePercentEncodedPathComponentAlloc(self.alloc, encoded_key);
        defer self.alloc.free(decoded_key);
        var lookup_opts = try http_route_helpers.parseLookupOptions(self.alloc, query);
        defer lookup_opts.deinit(self.alloc);

        var result = (try source.lookup(self.alloc, table_name, decoded_key, lookup_opts.opts, .read_index)) orelse {
            return try textResponse(self.alloc, 404, "not found");
        };
        defer result.deinit(self.alloc);
        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, tables_api.default_database_name, table_name);
        defer if (row_filter_json) |value| self.alloc.free(value);
        if (row_filter_json) |value| {
            if (!(try self.docJsonMatchesRowFilter(decoded_key, result.json, value))) {
                return try textResponse(self.alloc, 404, "not found");
            }
        }
        return try http_route_helpers.jsonWithHeadersResponse(self.alloc, 200, result.json, &.{
            .{
                .name = "X-Antfly-Version",
                .value = try std.fmt.allocPrint(self.alloc, "{d}", .{result.version}),
            },
        });
    }

    pub fn handlePublicCatalogTableDocumentLookup(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        encoded_key: []const u8,
        query: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
        const decoded_key = try http_route_helpers.decodePercentEncodedPathComponentAlloc(self.alloc, encoded_key);
        defer self.alloc.free(decoded_key);
        var lookup_opts = try http_route_helpers.parseLookupOptions(self.alloc, query);
        defer lookup_opts.deinit(self.alloc);

        var result = (try source.lookupCatalog(self.alloc, target, decoded_key, lookup_opts.opts, .read_index)) orelse {
            return try textResponse(self.alloc, 404, "not found");
        };
        defer result.deinit(self.alloc);
        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, target.database_name, resource_name);
        defer if (row_filter_json) |value| self.alloc.free(value);
        if (row_filter_json) |value| {
            if (!(try self.docJsonMatchesRowFilter(decoded_key, result.json, value))) {
                return try textResponse(self.alloc, 404, "not found");
            }
        }
        return try http_route_helpers.jsonWithHeadersResponse(self.alloc, 200, result.json, &.{
            .{
                .name = "X-Antfly-Version",
                .value = try std.fmt.allocPrint(self.alloc, "{d}", .{result.version}),
            },
        });
    }

    const TableDocumentLookupPath = struct {
        table_name: []const u8,
        key: []const u8,
    };

    fn matchPublicTableDocumentLookup(path: []const u8) ?TableDocumentLookupPath {
        if (!std.mem.startsWith(u8, path, routes.Routes.tables_prefix)) return null;
        const rest = path[routes.Routes.tables_prefix.len..];
        const marker_index = std.mem.indexOf(u8, rest, routes.Routes.documents_marker) orelse return null;
        if (marker_index == 0) return null;
        const table_name = rest[0..marker_index];
        const key = rest[marker_index + routes.Routes.documents_marker.len ..];
        if (key.len == 0 or std.mem.indexOfScalar(u8, key, '/') != null) return null;
        return .{ .table_name = table_name, .key = key };
    }

    fn dispatchPublicTableRoutes(self: *ApiHttpServer, req: http_common.HttpRequest, uri_parts: UriParts, authenticated_identity: ?AuthenticatedIdentity) !?http_common.HttpResponse {
        if (req.method == .GET and std.mem.eql(u8, uri_parts.path, routes.Routes.backups)) {
            const params = parseListBackupsParams(uri_parts.query) catch return try textResponse(self.alloc, 400, "missing location");
            return try self.handlePublicClusterBackupList(params.location);
        }
        if (req.method == .GET and std.mem.eql(u8, uri_parts.path, routes.Routes.tablespaces)) {
            return try self.handlePublicListTablespaces();
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTablespacePath(uri_parts.path)) |tablespace_path| {
                return try self.handlePublicGetTablespace(tablespace_path.tablespace_name);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTablespacePath(uri_parts.path)) |tablespace_path| {
                return try self.handlePublicCreateTablespace(tablespace_path.tablespace_name, req.body);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchTablespacePath(uri_parts.path)) |tablespace_path| {
                return try self.handlePublicDropTablespace(tablespace_path.tablespace_name);
            }
        }
        if (req.method == .GET and std.mem.eql(u8, uri_parts.path, routes.Routes.databases)) {
            return try self.handlePublicListDatabases();
        }
        if (req.method == .PUT) {
            if (routes.Routes.matchDatabaseTablespace(uri_parts.path)) |database_path| {
                return try self.handlePublicSetDatabaseTablespace(database_path.database_name, req.body);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchDatabaseTablespace(uri_parts.path)) |database_path| {
                return try self.handlePublicClearDatabaseTablespace(database_path.database_name);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchDatabasePath(uri_parts.path)) |database_path| {
                return try self.handlePublicGetDatabase(database_path.database_name);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchDatabasePath(uri_parts.path)) |database_path| {
                return try self.handlePublicCreateDatabase(database_path.database_name);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchDatabasePath(uri_parts.path)) |database_path| {
                return try self.handlePublicDropDatabase(database_path.database_name);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchDatabaseNamespaces(uri_parts.path)) |database_path| {
                return try self.handlePublicListNamespaces(database_path.database_name);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchDatabaseNamespaceTables(uri_parts.path)) |tables_path| {
                return try self.handlePublicListNamespaceTables(tables_path.database_name, tables_path.namespace_name, uri_parts.query);
            }
        }
        if (req.method == .PUT) {
            if (routes.Routes.matchDatabaseNamespaceTablespace(uri_parts.path)) |namespace_path| {
                return try self.handlePublicSetNamespaceTablespace(namespace_path.database_name, namespace_path.namespace_name, req.body);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchDatabaseNamespaceTablespace(uri_parts.path)) |namespace_path| {
                return try self.handlePublicClearNamespaceTablespace(namespace_path.database_name, namespace_path.namespace_name);
            }
        }
        if (routes.Routes.matchDatabaseNamespaceTablePath(uri_parts.path)) |table_path| {
            if (!catalogApiIdentifierValid(table_path.database_name)) return try textResponse(self.alloc, 400, "invalid database name");
            if (!catalogApiIdentifierValid(table_path.namespace_name)) return try textResponse(self.alloc, 400, "invalid namespace name");
            const subroute = catalogTableSubroute(table_path.table_path);
            if (!catalogApiIdentifierValid(subroute.table_name)) return try textResponse(self.alloc, 400, "invalid table name");
            const target = try catalog_resources.tableTargetFromOptional(table_path.database_name, table_path.namespace_name, subroute.table_name);
            if (subroute.suffix) |suffix| {
                return try self.handlePublicCatalogTableSubroute(req, uri_parts, authenticated_identity, target, suffix);
            }
            return switch (req.method) {
                .GET => try self.handlePublicGetCatalogTable(target),
                .POST => try self.handlePublicCreateCatalogTable(target, req.body),
                .DELETE => try self.handlePublicDropCatalogTable(target),
                else => try textResponse(self.alloc, 405, "method not allowed"),
            };
        }
        if (req.method == .POST) {
            if (routes.Routes.matchDatabaseNamespacePath(uri_parts.path)) |namespace_path| {
                return try self.handlePublicCreateNamespace(namespace_path.database_name, namespace_path.namespace_name);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchDatabaseNamespacePath(uri_parts.path)) |namespace_path| {
                return try self.handlePublicDropNamespace(namespace_path.database_name, namespace_path.namespace_name);
            }
        }
        if (req.method == .GET and std.mem.eql(u8, uri_parts.path, routes.Routes.tables)) {
            var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
            defer self.source.freeAdminSnapshot(&snapshot);
            const params = try parseListTablesParams(uri_parts.query);
            if (params.pattern != null) return try textResponse(self.alloc, 400, "unsupported table pattern");
            const storage_statuses = try self.collectTableStorageStatuses(&snapshot, params.prefix);
            defer if (storage_statuses) |items| self.alloc.free(items);
            var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
            defer arena_impl.deinit();
            const response = try tables_api.buildTableListWithStorageStatuses(arena_impl.allocator(), &snapshot, params.prefix, storage_statuses);
            return try jsonResponse(self.alloc, response);
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableIndexes(uri_parts.path)) |table_indexes| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_indexes.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableListIndexes(table_name);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableIndex(uri_parts.path)) |table_index| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_index.table_name);
                defer self.alloc.free(table_name);
                const index_name = try decodeRequestPathParamAlloc(self.alloc, table_index.index_name);
                defer self.alloc.free(index_name);
                if (runtimeSchemaDebugRequested(uri_parts.query)) {
                    if (!self.runtimeSchemaDebugAllowed(authenticated_identity)) return try textResponse(self.alloc, 403, "forbidden");
                    var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
                    defer self.source.freeAdminSnapshot(&snapshot);
                    var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena_impl.deinit();
                    const arena = arena_impl.allocator();
                    const table = tables_api.findTableByName(&snapshot, table_name) orelse return try textResponse(self.alloc, 404, "not found");
                    var local_statuses = self.localTableRuntimeStatusesWithSnapshot(table_name, &snapshot) catch return try textResponse(self.alloc, 500, "index lookup failed");
                    defer if (local_statuses) |*status| status.deinit(self.alloc);
                    const body = (indexes_api.encodeSingleIndex(
                        arena,
                        &snapshot,
                        table_name,
                        index_name,
                        if (local_statuses) |*status| status else null,
                    ) catch return try textResponse(self.alloc, 500, "index lookup failed")) orelse return try textResponse(self.alloc, 404, "not found");
                    var value = parseOwnedJsonValueAlloc(arena, body) catch return try textResponse(self.alloc, 500, "index lookup failed");
                    if (value != .object) return try textResponse(self.alloc, 500, "index lookup failed");
                    try value.object.put(arena, try arena.dupe(u8, "debug"), try tables_api.buildTableIndexRuntimeSchemaDebugValue(arena, table, index_name));
                    return try jsonResponse(self.alloc, value);
                }
                return try self.handlePublicTableGetIndex(table_name, index_name);
            }
        }
        if (req.method == .POST and std.mem.eql(u8, uri_parts.path, routes.Routes.backup)) {
            return try self.handlePublicClusterBackup(req.body);
        }
        if (req.method == .POST) {
            if (std.mem.eql(u8, uri_parts.path, routes.Routes.restore)) {
                if (try self.forwardMetadataMutationToLeader(req)) |resp| return resp;
                return try self.handlePublicClusterRestore(req.body);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableBackup(uri_parts.path)) |table_backup| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_backup.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableBackup(table_name, req.body);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRestore(uri_parts.path)) |table_restore| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_restore.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRestore(table_name, req.body);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableArtifactReprocessJobs(uri_parts.path)) |job_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, job_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicStartDocumentArtifactReprocessJob(table_name, job_route.artifact_name, req.body);
            }
            if (routes.Routes.matchTableArtifactReprocessJobAdvance(uri_parts.path)) |job_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, job_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicAdvanceDocumentArtifactReprocessJob(table_name, job_route.artifact_name, job_route.job_id);
            }
            if (routes.Routes.matchTableArtifactReprocessJobCancel(uri_parts.path)) |job_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, job_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicCancelDocumentArtifactReprocessJob(table_name, job_route.artifact_name, job_route.job_id);
            }
            if (routes.Routes.matchTableArtifactReprocess(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicReprocessDocumentArtifactRange(table_name, artifact_route.artifact_name, req.body);
            }
            if (routes.Routes.matchTableDocumentArtifactReprocess(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicReprocessDocumentArtifact(table_name, artifact_route.key, artifact_route.artifact_name, authenticated_identity);
            }
            if (routes.Routes.matchTableForeignKeyIntegrity(uri_parts.path)) |fk_integrity| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, fk_integrity.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableForeignKeyIntegrity(table_name, req.body);
            }
            if (routes.Routes.matchTableUniqueIntegrity(uri_parts.path)) |unique_integrity| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, unique_integrity.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableUniqueIntegrity(table_name, req.body);
            }
            if (routes.Routes.matchTableGraphMetric(uri_parts.path)) |graph_metric| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, graph_metric.table_name);
                defer self.alloc.free(table_name);
                const index_name = try decodeRequestPathParamAlloc(self.alloc, graph_metric.index_name);
                defer self.alloc.free(index_name);
                const metric_name = try decodeRequestPathParamAlloc(self.alloc, graph_metric.metric_name);
                defer self.alloc.free(metric_name);
                const action = try decodeRequestPathParamAlloc(self.alloc, graph_metric.action);
                defer self.alloc.free(action);
                return try self.handlePublicTableGraphMetricAction(
                    table_name,
                    index_name,
                    metric_name,
                    action,
                );
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableIndex(uri_parts.path)) |table_index| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_index.table_name);
                defer self.alloc.free(table_name);
                const index_name = try decodeRequestPathParamAlloc(self.alloc, table_index.index_name);
                defer self.alloc.free(index_name);
                return try self.handlePublicTableCreateIndex(table_name, index_name, req.body);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTablePath(uri_parts.path)) |table_path| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_path.table_name);
                defer self.alloc.free(table_name);
                var create_req = table_contract.parseCreateTableRequest(self.alloc, req.body) catch |err| {
                    std.log.err("create table parse failed: {} body_len={d}", .{ err, req.body.len });
                    return try textResponse(self.alloc, 400, "invalid create table request");
                };
                defer create_req.deinit(self.alloc);
                const normalized_indexes_json = table_writes.normalizeManagedEmbeddingIndexDimensionsJsonWithOptions(
                    self.alloc,
                    create_req.indexes_json orelse tables_api.default_indexes_json,
                    .{
                        .antfly_provider = self.antfly_provider,
                        .secret_store = self.cfg.secret_store,
                        .remote_content = self.cfg.remote_content,
                    },
                ) catch |err| switch (err) {
                    error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported table index configuration"),
                    error.EmbeddingProbeUnavailable => return try textResponse(self.alloc, 503, "table index validation probe unavailable"),
                    else => return err,
                };
                if (create_req.indexes_json) |old_indexes_json| self.alloc.free(old_indexes_json);
                create_req.indexes_json = normalized_indexes_json;
                tables_api.validatePublicAlgebraicIndexesJson(self.alloc, create_req.indexes_json orelse tables_api.default_indexes_json) catch {
                    return try textResponse(self.alloc, 400, "unsupported table index configuration");
                };
                std.log.info("public create table begin table={s}", .{table_name});
                const metadata_create_timeout_ns = 5 * std.time.ns_per_s;
                const metadata_create_poll_ns = 50 * std.time.ns_per_ms;
                const metadata_create_start_ns = platform_time.monotonicNs();
                while (true) {
                    self.source.createTable(self.alloc, table_name, create_req) catch |err| switch (err) {
                        error.InvalidTablespacePlacementPolicy => return try textResponse(self.alloc, 400, "invalid tablespace placement policy"),
                        error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                        error.UnexpectedHttpStatus => {
                            if (platform_time.monotonicNs() -| metadata_create_start_ns >= metadata_create_timeout_ns) {
                                std.log.err("public create table metadata create failed table={s} err={}", .{ table_name, err });
                                return err;
                            }
                            sleepNs(metadata_create_poll_ns);
                            continue;
                        },
                        else => {
                            std.log.err("public create table metadata create failed table={s} err={}", .{ table_name, err });
                            return err;
                        },
                    };
                    break;
                }
                std.log.info("public create table metadata done table={s}", .{table_name});
                const local_create_handled = if (self.table_writes) |table_writes_source| blk: {
                    break :blk (table_writes_source.createTable(self.alloc, table_name, create_req) catch |err| switch (err) {
                        error.InvalidCreateTableRequest, error.UnsupportedCreateTableRequest => return try textResponse(self.alloc, 400, "unsupported table index configuration"),
                        else => {
                            std.log.err("public create table local create failed table={s} err={}", .{ table_name, err });
                            return err;
                        },
                    }) != null;
                } else false;
                if (local_create_handled) {
                    std.log.info("public create table wait projected presence table={s}", .{table_name});
                    self.waitForProjectedTablePresence(table_name) catch |err| switch (err) {
                        error.TableVisibilityTimeout => {
                            std.log.err("public create table metadata visibility timed out table={s}", .{table_name});
                            return try textResponse(self.alloc, 500, "table create did not converge");
                        },
                        else => return err,
                    };
                    self.waitForProjectedTableWriteQuorum(table_name) catch |err| switch (err) {
                        error.TableVisibilityTimeout => {
                            std.log.err("public create table write quorum timed out table={s}", .{table_name});
                            return try textResponse(self.alloc, 500, "table create did not converge");
                        },
                        else => return err,
                    };
                } else {
                    const metadata_wait_handled = self.source.waitTableLifecycle(table_name, .present) catch |err| lifecycle: {
                        break :lifecycle switch (err) {
                            error.TableVisibilityTimeout => {
                                self.waitForProjectedTableCreateReadiness(table_name) catch |fallback_err| switch (fallback_err) {
                                    error.TableVisibilityTimeout => {
                                        std.log.err("public create table metadata lifecycle timed out table={s}", .{table_name});
                                        return try textResponse(self.alloc, 500, "table create did not converge");
                                    },
                                    else => return fallback_err,
                                };
                                break :lifecycle true;
                            },
                            else => {
                                std.log.err("public create table metadata lifecycle failed table={s} err={}", .{ table_name, err });
                                return err;
                            },
                        };
                    };
                    if (!metadata_wait_handled) {
                        std.log.info("public create table wait metadata visibility table={s}", .{table_name});
                        self.waitForTableVisibility(table_name, .present) catch |err| switch (err) {
                            error.TableVisibilityTimeout => {
                                std.log.err("public create table metadata visibility timed out table={s}", .{table_name});
                                return try textResponse(self.alloc, 500, "table create did not converge");
                            },
                            else => return err,
                        };
                    }
                }
                std.log.info("public create table visible table={s}", .{table_name});

                var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
                defer self.source.freeAdminSnapshot(&snapshot);
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = (try tables_api.buildSingleTableStatusWithStorageStatuses(arena_impl.allocator(), &snapshot, table_name, null)) orelse {
                    return try textResponse(self.alloc, 404, "not found");
                };
                return try jsonResponse(self.alloc, response);
            }
        }
        if (req.method == .PUT) {
            if (routes.Routes.matchTableArtifactEnrichment(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicPutArtifactEnrichment(table_name, artifact_route.artifact_name, req.body);
            }
            if (routes.Routes.matchTableSchema(uri_parts.path)) |table_schema| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_schema.table_name);
                defer self.alloc.free(table_name);
                const schema_json = table_contract.parseSchemaUpdateRequest(self.alloc, req.body) catch {
                    return try textResponse(self.alloc, 400, "invalid schema update request");
                };
                defer self.alloc.free(schema_json);

                const table_before = try self.loadOwnedTableRecord(table_name);
                if (table_before == null) {
                    self.source.updateSchema(self.alloc, table_name, schema_json) catch |err| switch (err) {
                        error.InvalidSchemaUpdateRequest => return try textResponse(self.alloc, 400, "invalid schema update request"),
                        error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                        error.ExtensionOwnedObject => return try textResponse(self.alloc, 405, "method not allowed"),
                        error.UnsupportedOperation => {
                            const table_writes_source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
                            _ = table_writes_source.updateSchema(self.alloc, table_name, schema_json) catch |write_err| switch (write_err) {
                                error.InvalidSchemaUpdateRequest, error.InvalidCreateTableRequest => return try textResponse(self.alloc, 400, "invalid schema update request"),
                                else => return write_err,
                            } orelse return try textResponse(self.alloc, 404, "not found");
                        },
                        else => return err,
                    };
                    var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena_impl.deinit();
                    const value = try buildLocalSchemaUpdateStatus(arena_impl.allocator(), table_name, schema_json);
                    return try jsonResponse(self.alloc, value);
                }
                defer metadata_table_manager.freeTable(self.alloc, table_before.?);

                var local_schema_applied = false;
                self.source.updateSchema(self.alloc, table_name, schema_json) catch |err| switch (err) {
                    error.InvalidSchemaUpdateRequest => return try textResponse(self.alloc, 400, "invalid schema update request"),
                    error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.ExtensionOwnedObject => return try textResponse(self.alloc, 405, "method not allowed"),
                    error.UnsupportedOperation => {
                        const table_writes_source = self.table_writes orelse return try textResponse(self.alloc, 405, "method not allowed");
                        _ = table_writes_source.updateSchema(self.alloc, table_name, schema_json) catch |write_err| switch (write_err) {
                            error.InvalidSchemaUpdateRequest, error.InvalidCreateTableRequest => return try textResponse(self.alloc, 400, "invalid schema update request"),
                            else => return write_err,
                        };
                        local_schema_applied = true;
                    },
                    else => return err,
                };
                const expected_table = try tables_api.applySchemaUpdateRecord(self.alloc, &table_before.?, schema_json);
                defer metadata_table_manager.freeTable(self.alloc, expected_table);
                self.waitForMetadataProjection(table_name, expected_table.schema_json, expected_table.indexes_json) catch |err| switch (err) {
                    error.TableVisibilityTimeout => return try textResponse(self.alloc, 500, "schema update did not converge"),
                    else => return err,
                };
                if (self.table_writes) |table_writes_source| {
                    if (!local_schema_applied) {
                        _ = table_writes_source.updateSchema(self.alloc, table_name, schema_json) catch |write_err| switch (write_err) {
                            error.InvalidSchemaUpdateRequest, error.InvalidCreateTableRequest => return try textResponse(self.alloc, 400, "invalid schema update request"),
                            else => return write_err,
                        };
                    }
                    if (try self.source.runRound()) {
                        _ = try self.source.runRound();
                        _ = try self.source.runRound();
                    }
                }

                const body = try self.encodeSchemaUpdateResponse(table_name, schema_json);
                defer self.alloc.free(body);
                return try jsonBodyResponseWithStatus(self.alloc, 200, body);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchTableArtifactEnrichment(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicDeleteArtifactEnrichment(table_name, artifact_route.artifact_name);
            }
            if (routes.Routes.matchTableIndex(uri_parts.path)) |table_index| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_index.table_name);
                defer self.alloc.free(table_name);
                const index_name = try decodeRequestPathParamAlloc(self.alloc, table_index.index_name);
                defer self.alloc.free(index_name);
                return try self.handlePublicTableDeleteIndex(table_name, index_name);
            }
        }
        if (req.method == .GET) {
            if (matchPublicTableDocumentLookup(uri_parts.path)) |document| {
                return try self.handlePublicTableDocumentLookup(document.table_name, document.key, uri_parts.query, authenticated_identity);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableLookup(uri_parts.path)) |lookup| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, lookup.table_name);
                defer self.alloc.free(table_name);
                const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
                const decoded_key = try decodeRequestPathParamAlloc(self.alloc, lookup.key);
                defer self.alloc.free(decoded_key);
                var lookup_opts = try http_route_helpers.parseLookupOptions(self.alloc, uri_parts.query);
                defer lookup_opts.deinit(self.alloc);
                const consistency = parseLookupReadConsistency(uri_parts.query) catch {
                    return try textResponse(self.alloc, 400, "invalid read consistency");
                };

                var result = (source.lookup(self.alloc, table_name, decoded_key, lookup_opts.opts, consistency) catch |err| switch (err) {
                    error.NotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.HAReadRequiresPrimary, error.ReadRequiresPrimary => return try textResponse(self.alloc, 503, "read requires primary"),
                    error.HAReadWaitForApply, error.HAReadWaitForMetadata, error.ReadUnavailable => return try textResponse(self.alloc, 503, "standby read unavailable"),
                    else => {
                        std.log.err("public table lookup failed table={s} key={s} err={}", .{ table_name, decoded_key, err });
                        return try textResponse(self.alloc, 500, "lookup failed");
                    },
                }) orelse {
                    return try textResponse(self.alloc, 404, "not found");
                };
                defer result.deinit(self.alloc);
                const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, tables_api.default_database_name, table_name);
                defer if (row_filter_json) |value| self.alloc.free(value);
                if (row_filter_json) |value| {
                    if (!(try self.docJsonMatchesRowFilter(decoded_key, result.json, value))) {
                        return try textResponse(self.alloc, 404, "not found");
                    }
                }
                return try http_route_helpers.jsonWithHeadersResponse(self.alloc, 200, result.json, &.{
                    .{
                        .name = "X-Antfly-Version",
                        .value = try std.fmt.allocPrint(self.alloc, "{d}", .{result.version}),
                    },
                });
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableArtifactReprocessJob(uri_parts.path)) |job_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, job_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicDocumentArtifactReprocessJob(table_name, job_route.artifact_name, job_route.job_id);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableDocumentArtifacts(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicDocumentArtifactManifests(table_name, artifact_route.key, uri_parts.query, authenticated_identity);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableDocumentArtifact(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicDocumentArtifactManifest(table_name, artifact_route.key, artifact_route.artifact_name, uri_parts.query, authenticated_identity);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableArtifacts(uri_parts.path)) |artifact_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, artifact_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicListArtifactEnrichments(table_name);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTablePath(uri_parts.path)) |table_path| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_path.table_name);
                defer self.alloc.free(table_name);
                if (runtimeSchemaDebugRequested(uri_parts.query) and !self.runtimeSchemaDebugAllowed(authenticated_identity)) {
                    return try textResponse(self.alloc, 403, "forbidden");
                }
                var snapshot = (try self.source.adminSnapshot()) orelse return try textResponse(self.alloc, 404, "not found");
                defer self.source.freeAdminSnapshot(&snapshot);
                var storage_status_buf: [1]tables_api.TableStorageStatus = undefined;
                const storage_statuses = try self.bestEffortSingleTableStorageStatuses(table_name, &storage_status_buf);
                if (runtimeSchemaDebugRequested(uri_parts.query)) {
                    var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena_impl.deinit();
                    const response =
                        (try tables_api.buildSingleTableStatusWithRuntimeSchemaDebug(arena_impl.allocator(), &snapshot, table_name, storage_statuses)) orelse return try textResponse(self.alloc, 404, "not found");
                    return try jsonResponse(self.alloc, response);
                }
                const body = (try tables_api.encodeSingleTableStatusWithStorageStatuses(self.alloc, &snapshot, table_name, storage_statuses)) orelse return try textResponse(self.alloc, 404, "not found");
                defer self.alloc.free(body);
                return try jsonBodyResponseWithStatus(self.alloc, 200, body);
            }
        }
        if (req.method == .DELETE) {
            if (routes.Routes.matchTablePath(uri_parts.path)) |table_path| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, table_path.table_name);
                defer self.alloc.free(table_name);
                var local_drop_group_ids: ?[]u64 = null;
                defer if (local_drop_group_ids) |group_ids| self.alloc.free(group_ids);
                if (self.table_writes != null) {
                    if (try self.source.adminSnapshot()) |snapshot_value| {
                        var snapshot = snapshot_value;
                        defer self.source.freeAdminSnapshot(&snapshot);
                        local_drop_group_ids = try tableGroupIdsFromSnapshot(self.alloc, &snapshot, table_name);
                    }
                }
                self.source.dropTable(self.alloc, table_name) catch |err| switch (err) {
                    error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.ExtensionOwnedObject => return try textResponse(self.alloc, 405, "method not allowed"),
                    error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                    else => {
                        std.log.err("public drop table metadata remove failed table={s} err={s}", .{
                            table_name,
                            @errorName(err),
                        });
                        return err;
                    },
                };
                if (self.table_writes) |write_source| {
                    const group_ids = local_drop_group_ids orelse &.{};
                    _ = write_source.dropTable(self.alloc, table_name, group_ids) catch |err| switch (err) {
                        error.TableNotFound => null,
                        else => {
                            std.log.err("public drop table local cleanup failed table={s} err={s}", .{
                                table_name,
                                @errorName(err),
                            });
                            return err;
                        },
                    };
                }
                self.waitForTableVisibility(table_name, .absent) catch |err| switch (err) {
                    error.TableVisibilityTimeout => {
                        std.log.err("public drop table metadata visibility timed out table={s}", .{table_name});
                        return try textResponse(self.alloc, 500, "table delete did not converge");
                    },
                    else => return err,
                };
                return .{
                    .status = 204,
                    .content_type = null,
                    .body = &.{},
                };
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableScan(uri_parts.path)) |scan| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, scan.table_name);
                defer self.alloc.free(table_name);
                const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
                var scan_req = try http_route_helpers.parseScanKeysRequest(self.alloc, req.body);
                defer scan_req.deinit(self.alloc);

                var result = (try source.scan(
                    self.alloc,
                    table_name,
                    scan_req.from,
                    scan_req.to,
                    scan_req.opts,
                    .read_index,
                )) orelse return try textResponse(self.alloc, 404, "not found");
                defer result.deinit(self.alloc);
                const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, tables_api.default_database_name, table_name);
                defer if (row_filter_json) |value| self.alloc.free(value);
                if (row_filter_json) |value| {
                    const filtered = try self.filterScanResultByRowFilter(source, table_name, result.ndjson, value);
                    defer self.alloc.free(filtered);
                    return try http_route_helpers.ndjsonResponse(self.alloc, 200, filtered);
                }
                return try http_route_helpers.ndjsonResponse(self.alloc, 200, result.ndjson);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableQuery(uri_parts.path)) |query_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, query_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableQueryWithContentType(table_name, req.body, req.content_type, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsBatch(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsBatch(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsGet(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsGet(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsPlan(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsPlan(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsQuery(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsQuery(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsAggregate(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsAggregate(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsWindow(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsWindow(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsJoin(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsJoin(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsLateral(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsLateral(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsMutationSource(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsMutationSource(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableRowsSource(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsSource(table_name);
            }
        }
        if (req.method == .GET) {
            if (routes.Routes.matchTableRowsExplain(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsExplain(table_name, &.{}, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableRowsExplain(uri_parts.path)) |rows_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, rows_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableRowsExplain(table_name, req.body, authenticated_identity);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableBatch(uri_parts.path)) |batch_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, batch_route.table_name);
                defer self.alloc.free(table_name);
                return try self.handlePublicTableBatch(table_name, req.body);
            }
        }
        if (req.method == .POST) {
            if (routes.Routes.matchTableMerge(uri_parts.path)) |merge_route| {
                const table_name = try decodeRequestPathParamAlloc(self.alloc, merge_route.table_name);
                defer self.alloc.free(table_name);
                const reads = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
                const writes = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
                if (!(try self.tableExists(table_name))) return try textResponse(self.alloc, 404, "not found");

                var merge_req = linear_merge_api.parseRequest(self.alloc, req.body) catch |err| switch (err) {
                    error.ValueTooLong => return try textResponse(self.alloc, 413, "value too large"),
                    error.InvalidLinearMergeRequest => return try textResponse(self.alloc, 400, "invalid linear merge request"),
                    else => return err,
                };
                defer merge_req.deinit(self.alloc);

                self.validateTableWritesAgainstSchema(table_name, merge_req.writes) catch |err| switch (err) {
                    error.InvalidBatchRequest => return try textResponse(self.alloc, 400, "invalid linear merge request"),
                    else => return err,
                };

                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const response = linear_merge_api.executeResponse(
                    arena_impl.allocator(),
                    reads,
                    writes,
                    table_name,
                    merge_req,
                ) catch |err| switch (err) {
                    error.InvalidLinearMergeRequest => return try textResponse(self.alloc, 400, "invalid linear merge request"),
                    error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.InvalidBatchRequest => return try textResponse(self.alloc, 400, "invalid linear merge request"),
                    else => return err,
                };
                return try jsonResponse(self.alloc, response);
            }
        }
        return null;
    }

    pub fn localSessionNodeId(self: *ApiHttpServer) u64 {
        const router = self.cfg.session_router orelse return 0;
        return router.localNodeId();
    }

    fn maybeCleanupExpiredSessions(self: *ApiHttpServer) !void {
        const ttl_ns = self.cfg.session_ttl_ns orelse return;
        const now_ns = platform_time.realtimeNs();
        const interval_ns = self.cfg.session_cleanup_interval_ns orelse ttl_ns;
        if (self.last_session_cleanup_ns != 0 and now_ns -| self.last_session_cleanup_ns < interval_ns) return;
        self.last_session_cleanup_ns = now_ns;
        _ = try self.txn_sessions.cleanupExpired(self.alloc, now_ns -| ttl_ns);
    }

    fn routeInternalGroupQueryToReadSchema(ptr: *anyopaque, table_name: []const u8, req: *db_mod.types.SearchRequest) !void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        return try self.maybeRouteQueryToReadSchema(table_name, req);
    }

    fn validateInternalGroupBatchWrites(ptr: *anyopaque, table_name: []const u8, writes: []const db_mod.types.BatchWrite) !void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        return try self.validateTableWritesAgainstSchema(table_name, writes);
    }

    fn validateInternalGroupTxnWrites(ptr: *anyopaque, table_name: []const u8, writes: []const db_mod.types.TransactionWrite) !void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        return try self.validateTableWritesAgainstSchema(table_name, writes);
    }

    pub fn maybeRouteQueryToReadSchema(self: *ApiHttpServer, table_name: []const u8, query_req: *db_mod.types.SearchRequest) !void {
        var snapshot = (try self.source.adminSnapshot()) orelse return;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
        try tables_api.routeQueryRequestToActiveReadIndex(self.alloc, table, query_req);
    }

    pub fn maybeRouteCatalogQueryToReadSchema(self: *ApiHttpServer, target: catalog_resources.TableTarget, query_req: *db_mod.types.SearchRequest) !void {
        var snapshot = (try self.source.adminSnapshot()) orelse return;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;
        try tables_api.routeQueryRequestToActiveReadIndex(self.alloc, table, query_req);
    }

    pub fn validateTableWritesAgainstSchema(self: *ApiHttpServer, table_name: []const u8, writes: anytype) !void {
        if (writes.len == 0) return;
        var snapshot = (try self.source.adminSnapshot()) orelse return;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;

        if (table.schema_json.len != 0) {
            var parsed_schema = try tables_api.parseValidatedTableSchema(self.alloc, table.schema_json);
            defer parsed_schema.deinit(self.alloc);
            try tables_api.validateWritesAgainstTableSchema(self.alloc, parsed_schema, writes);
        }
        try validateWritesAgainstExtensionDataShapes(self.alloc, &snapshot, table_name, writes);
    }

    pub fn validateCatalogTableWritesAgainstSchema(self: *ApiHttpServer, target: catalog_resources.TableTarget, writes: anytype) !void {
        if (writes.len == 0) return;
        var snapshot = (try self.source.adminSnapshot()) orelse return;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;

        if (table.schema_json.len != 0) {
            var parsed_schema = try tables_api.parseValidatedTableSchema(self.alloc, table.schema_json);
            defer parsed_schema.deinit(self.alloc);
            try tables_api.validateWritesAgainstTableSchema(self.alloc, parsed_schema, writes);
        }
        try validateWritesAgainstExtensionDataShapes(self.alloc, &snapshot, target.table_name, writes);
    }

    pub fn validateCommitTablesAgainstSchema(self: *ApiHttpServer, tables: []const distributed_txn.TableCommitRequest) !void {
        for (tables) |table| try self.validateTableWritesAgainstSchema(table.table_name, table.writes);
    }

    pub fn validateCommitReadSet(
        self: *ApiHttpServer,
        req: transactions_api.OwnedTransactionCommitRequest,
    ) !?transactions_api.CommitConflict {
        const source = self.table_reads orelse return null;
        for (req.read_set) |item| {
            var lookup = (try source.lookup(self.alloc, item.table_name, item.key, .{}, .read_index)) orelse {
                return transactions_api.versionConflict(item.table_name, item.key, item.expected_version, 0);
            };
            defer lookup.deinit(self.alloc);
            if (lookup.version != item.expected_version) {
                return transactions_api.versionConflict(item.table_name, item.key, item.expected_version, lookup.version);
            }
        }
        return null;
    }

    pub fn maybeEncodeTableStatus(self: *ApiHttpServer, table_name: []const u8) !?[]u8 {
        var snapshot = (try self.source.adminSnapshot()) orelse return null;
        defer self.source.freeAdminSnapshot(&snapshot);
        var storage_status_buf: [1]tables_api.TableStorageStatus = undefined;
        const storage_statuses = try self.bestEffortSingleTableStorageStatuses(table_name, &storage_status_buf);
        return try tables_api.encodeSingleTableStatusWithStorageStatuses(self.alloc, &snapshot, table_name, storage_statuses);
    }

    pub fn encodeSchemaUpdateResponse(self: *ApiHttpServer, table_name: []const u8, schema_json: []const u8) ![]u8 {
        if (try self.maybeEncodeTableStatus(table_name)) |body| return body;

        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const value = try buildLocalSchemaUpdateStatus(arena_impl.allocator(), table_name, schema_json);
        return try std.json.Stringify.valueAlloc(self.alloc, value, .{});
    }

    pub fn probeTableStorageStatus(self: *ApiHttpServer, table_name: []const u8) !?tables_api.TableStorageStatus {
        const source = self.table_reads orelse return null;
        var result = (try source.scan(
            self.alloc,
            table_name,
            "",
            "",
            .{ .limit = 1 },
            .read_index,
        )) orelse return null;
        defer result.deinit(self.alloc);
        return .{
            .table_name = table_name,
            .empty = result.ndjson.len == 0,
            .lsm = try self.bestEffortLsmStorageStatus(table_name),
        };
    }

    pub fn probeCatalogTableStorageStatus(self: *ApiHttpServer, target: catalog_resources.TableTarget) !?tables_api.TableStorageStatus {
        if (self.table_reads) |source| {
            if (try source.localRuntimeStatusesCatalog(self.alloc, target)) |statuses| {
                var owned = statuses;
                defer owned.deinit(self.alloc);
                var doc_count: u64 = 0;
                for (owned.items) |item| doc_count +|= item.stats.doc_count;
                return .{
                    .table_name = target.table_name,
                    .empty = doc_count == 0,
                };
            }
        }
        if (self.table_writes) |source| {
            if (try source.localRuntimeStatusesCatalog(self.alloc, target)) |statuses| {
                var owned = statuses;
                defer owned.deinit(self.alloc);
                var doc_count: u64 = 0;
                for (owned.items) |item| doc_count +|= item.stats.doc_count;
                return .{
                    .table_name = target.table_name,
                    .empty = doc_count == 0,
                };
            }
        }
        return null;
    }

    pub fn collectTableStorageStatuses(
        self: *ApiHttpServer,
        snapshot: *const metadata_api.AdminSnapshot,
        prefix: ?[]const u8,
    ) !?[]tables_api.TableStorageStatus {
        var items = std.ArrayListUnmanaged(tables_api.TableStorageStatus).empty;
        defer items.deinit(self.alloc);

        for (snapshot.tables) |*table| {
            if (prefix) |pfx| {
                if (!std.mem.startsWith(u8, table.name, pfx)) continue;
            }
            const status = (try self.bestEffortSingleTableStorageStatus(table.name)) orelse continue;
            try items.append(self.alloc, status);
        }

        if (items.items.len == 0) return null;
        return try items.toOwnedSlice(self.alloc);
    }

    pub fn tableGroupIdsFromSnapshot(
        alloc: std.mem.Allocator,
        snapshot: *const metadata_api.AdminSnapshot,
        table_name: []const u8,
    ) ![]u64 {
        const table = tables_api.findTableByName(snapshot, table_name) orelse return try alloc.alloc(u64, 0);
        const ranges = try metadata_admin.listTableRanges(alloc, snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);

        const group_ids = try alloc.alloc(u64, ranges.len);
        for (ranges, 0..) |range, i| group_ids[i] = range.group_id;
        return group_ids;
    }

    pub fn catalogTableGroupIdsFromSnapshot(
        alloc: std.mem.Allocator,
        snapshot: *const metadata_api.AdminSnapshot,
        target: catalog_resources.TableTarget,
    ) ![]u64 {
        const table = tables_api.findTableByQualifiedName(snapshot, target.database_name, target.namespace_name, target.table_name) orelse return try alloc.alloc(u64, 0);
        const ranges = try metadata_admin.listTableRanges(alloc, snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);

        const group_ids = try alloc.alloc(u64, ranges.len);
        for (ranges, 0..) |range, i| group_ids[i] = range.group_id;
        return group_ids;
    }

    pub fn loadOwnedTableRecord(self: *ApiHttpServer, table_name: []const u8) !?metadata_table_manager.TableRecord {
        var snapshot = (try self.source.adminSnapshot()) orelse return null;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
        return try metadata_table_manager.cloneTable(self.alloc, table.*);
    }

    pub fn loadOwnedCatalogTableRecord(self: *ApiHttpServer, target: catalog_resources.TableTarget) !?metadata_table_manager.TableRecord {
        var snapshot = (try self.source.adminSnapshot()) orelse return null;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return null;
