        self.applyRowsLateralPlanRowFilterWithSchemas(table_name, left_table_name, right_table_name, authenticated_identity, cte_schema, left_schema, right_schema, &plan) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "forbidden"),
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return try textResponse(self.alloc, 403, "row filter pushdown required"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows lateral request"),
            else => return err,
        };
        const result_schema = relational_rows_api.rowsReadPlanOutputColumnsWithSchemasAlloc(self.alloc, cte_schema, left_schema, right_schema, .{ .lateral = plan }) catch return try textResponse(self.alloc, 400, "invalid rows lateral request");
        defer relational_rows_api.freeRowsOutputColumns(self.alloc, result_schema);

        const same_table = std.mem.eql(u8, left_table_name, table_name) and std.mem.eql(u8, right_table_name, table_name);
        var result = ((if (same_table)
            source.rowsLateralPlan(self.alloc, table_name, cte_schema, plan, .read_index)
        else
            table_reads.rowsLateralPlanFromRoutedScansWithSchemasAlloc(self.alloc, source, table_name, left_table_name, right_table_name, cte_schema, left_schema, right_schema, plan, .read_index)) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return try textResponse(self.alloc, 400, "invalid rows lateral request"),
            error.RelationalRowsCteSpillRequired => return try textResponse(self.alloc, 429, "rows lateral backpressured"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 501, "rows lateral plan unavailable"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
            else => {
                std.log.err("public table rows lateral failed table={s} err={}", .{ table_name, err });
                return try textResponse(self.alloc, 500, "rows lateral failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);
        const response_body = try relational_rows_api.encodeRowsJoinResponseWithSchemaAlloc(self.alloc, result, result_schema);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

    const RowsAuthFilterPlan = struct {
        predicates: []const runtime_schema_mod.RelationalCheck = &.{},
        array_any: []const db_mod.types.RelationalRowsArrayAnyPredicate = &.{},
        in_predicates: []const db_mod.types.RelationalRowsInPredicate = &.{},
        json_contains: []const db_mod.types.RelationalRowsJsonContainsPredicate = &.{},
        expression_predicates: []const db_mod.types.RelationalRowsExpressionCondition = &.{},
        access_or_predicates: []const db_mod.types.RelationalRowsAccessPredicateGroup = &.{},
        expression_or_predicates: []const db_mod.types.RelationalRowsExpressionPredicateGroup = &.{},

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            freeRowsAuthPredicates(alloc, self.predicates);
            if (self.predicates.len > 0) alloc.free(self.predicates);
            for (self.array_any) |predicate| {
                alloc.free(predicate.field);
                alloc.free(predicate.value_json);
            }
            if (self.array_any.len > 0) alloc.free(self.array_any);
            for (self.in_predicates) |predicate| {
                alloc.free(predicate.field);
                alloc.free(predicate.values_json);
            }
            if (self.in_predicates.len > 0) alloc.free(self.in_predicates);
            for (self.json_contains) |predicate| {
                alloc.free(predicate.field);
                alloc.free(predicate.value_json);
            }
            if (self.json_contains.len > 0) alloc.free(self.json_contains);
            relational_rows_api.freeRowsQueryExpressionConditions(alloc, self.expression_predicates);
            freeRowsAuthAccessPredicateGroups(alloc, self.access_or_predicates);
            if (self.access_or_predicates.len > 0) alloc.free(self.access_or_predicates);
            relational_rows_api.freeRowsQueryExpressionPredicateGroups(alloc, self.expression_or_predicates);
            self.* = undefined;
        }

        fn empty(self: @This()) bool {
            return self.predicates.len == 0 and
                self.array_any.len == 0 and
                self.in_predicates.len == 0 and
                self.json_contains.len == 0 and
                self.expression_predicates.len == 0 and
                self.access_or_predicates.len == 0 and
                self.expression_or_predicates.len == 0;
        }
    };

    fn applyRowsQueryPlanRowFilter(
        self: *ApiHttpServer,
        table_name: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        schema: runtime_schema_mod.TableSchema,
        plan: *relational_rows_api.OwnedRowsQueryPlan,
    ) !void {
        var filter = try self.rowsAuthFilterPlanForIdentity(table_name, authenticated_identity, schema);
        defer if (filter) |*value| value.deinit(self.alloc);
        const active = filter orelse return;
        for (@constCast(plan.ctes)) |*cte| try self.applyRowsAuthFilterToQuery(schema, active, &cte.query);
        try self.applyRowsAuthFilterToQuery(schema, active, &plan.query);
    }

