            201 => blk: {
                const BackupSuccess = struct {
                    backup: []const u8,
                };
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const parsed = try parseJsonResponseBody(BackupSuccess, arena_impl.allocator(), resp.body);
