            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }
    };

    const config_json =
        \\{
        \\  "connections": {
        \\    "mocked": {
        \\      "kind": "inference",
        \\      "capabilities": ["models.generate"],
        \\      "inference": {
        \\        "provider": "mock",
        \\        "configured_model_types": ["generator"]
        \\      }
        \\    },
        \\    "broken-openai": {
        \\      "kind": "inference",
        \\      "capabilities": ["models.embed"],
        \\      "inference": {
        \\        "provider": "openai",
        \\        "url": "http://127.0.0.1:9",
        \\        "api_key": "test-key",
        \\        "configured_model_types": ["embedder"]
        \\      }
        \\    },
        \\    "wiki": {
        \\      "kind": "external_io",
        \\      "capabilities": ["content.fetch", "indexing.use"],
        \\      "external_io": {
        \\        "protocol": "http",
        \\        "hosts": ["https://en.wikipedia.org"]
        \\      }
        \\    }
        \\  }
        \\}
    ;
    var node_config = try common_config.Config.parseFromSlice(std.testing.allocator, config_json);
    defer node_config.deinit();

    var source = FakeSource{};
    var server = ApiHttpServer.init(
        std.testing.allocator,
        .{ .node_config = &node_config },
        source.iface(),
        null,
        null,
    );
    defer server.deinit();

    var resp = try server.handle(.{ .method = .GET, .uri = "/connections?include=models" });
    defer resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), resp.status);
    try std.testing.expectEqualStrings("application/json", resp.content_type.?);

    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, resp.body, .{});
    defer parsed.deinit();
    const connection_list = parsed.value.object.get("connections").?.array.items;
    try std.testing.expectEqual(@as(usize, 3), connection_list.len);

    var saw_mock = false;
    var saw_openai = false;
    var saw_wiki = false;
    for (connection_list) |connection| {
        const name = connection.object.get("name").?.string;
        const conn_status = connection.object.get("status").?.string;
        if (std.mem.eql(u8, name, "mocked")) {
            saw_mock = true;
            try std.testing.expectEqualStrings("connected", conn_status);
            const provider = connection.object.get("inference").?.object;
            const models = provider.get("models").?.object;
            try std.testing.expect(models.get("generators") != null);
        } else if (std.mem.eql(u8, name, "broken-openai")) {
            saw_openai = true;
            // Partial failure: the unreachable provider reports an error
            // without failing the whole response.
            try std.testing.expectEqualStrings("error", conn_status);
            try std.testing.expect(connection.object.get("error").? == .string);
        } else if (std.mem.eql(u8, name, "wiki")) {
            saw_wiki = true;
            try std.testing.expectEqualStrings("external_io", connection.object.get("kind").?.string);
            try std.testing.expectEqualStrings("configured", conn_status);
        }
    }
    try std.testing.expect(saw_mock);
    try std.testing.expect(saw_openai);
    try std.testing.expect(saw_wiki);

    // The kind filter trims the response to the requested connection types.
    var filtered = try server.handle(.{ .method = .GET, .uri = "/connections?types=external_io" });
    defer filtered.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), filtered.status);
    var parsed_filtered = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, filtered.body, .{});
    defer parsed_filtered.deinit();
    const filtered_list = parsed_filtered.value.object.get("connections").?.array.items;
    try std.testing.expectEqual(@as(usize, 1), filtered_list.len);
    try std.testing.expectEqualStrings("wiki", filtered_list[0].object.get("name").?.string);

    // The /db/v1 prefix variant resolves to the same route.
    var prefixed = try server.handle(.{ .method = .GET, .uri = "/db/v1/connections" });
    defer prefixed.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), prefixed.status);
}

test "api http server serves mcp and a2a protocol surfaces" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 77, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .name = "docs",
                    .database_name = "tenant_ops",
                    .namespace_name = "analytics",
                    .schema_json = "{\"default_type\":\"doc\",\"document_schemas\":{\"doc\":{\"schema\":{\"type\":\"object\",\"properties\":{\"title\":{\"type\":\"text\"}}}}}}",
                    .indexes_json = "{\"full_text_index_v0\":{\"type\":\"full_text\"}}",
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);
    defer server.deinit();

    var mcp_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.mcp_v1,
        .content_type = "application/json",
        .body = "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{}}",
    });
    defer mcp_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), mcp_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, mcp_resp.body, "\"protocolVersion\":\"2025-06-18\"") != null);
    try std.testing.expectEqual(@as(usize, 2), mcp_resp.headers.len);
    try std.testing.expectEqualStrings("Mcp-Session-Id", mcp_resp.headers[0].name);
    try std.testing.expectEqualStrings("Mcp-Protocol-Version", mcp_resp.headers[1].name);
    try std.testing.expectEqualStrings("2025-06-18", mcp_resp.headers[1].value);
    const mcp_session_headers = [_]http_common.RequestHeader{
        .{ .name = mcp.session_id_header, .value = mcp_resp.headers[0].value },
    };

    var mcp_stream = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.mcp_v1,
        .headers = &mcp_session_headers,
    });
    defer mcp_stream.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), mcp_stream.status);
    try std.testing.expectEqualStrings("text/event-stream", mcp_stream.content_type.?);
    try std.testing.expect(std.mem.indexOf(u8, mcp_stream.body, "id: 1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, mcp_stream.body, "event: endpoint") != null);

    const mcp_resume_headers = [_]http_common.RequestHeader{
        .{ .name = mcp.session_id_header, .value = mcp_resp.headers[0].value },
        .{ .name = mcp.last_event_id_header, .value = "9" },
    };
    var mcp_resumed_stream = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.mcp_v1,
        .headers = &mcp_resume_headers,
    });
    defer mcp_resumed_stream.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), mcp_resumed_stream.status);
    try std.testing.expect(std.mem.indexOf(u8, mcp_resumed_stream.body, "id: 10\n") != null);

    var mcp_delete = try server.handle(.{
        .method = .DELETE,
        .uri = routes.Routes.mcp_v1,
        .headers = &mcp_session_headers,
    });
    defer mcp_delete.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 202), mcp_delete.status);

    var mcp_missing_session = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.mcp_v1,
    });
    defer mcp_missing_session.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 400), mcp_missing_session.status);

    var card_resp = try server.handle(.{ .method = .GET, .uri = routes.Routes.agent_card });
    defer card_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), card_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, card_resp.body, "\"id\":\"query-builder\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, card_resp.body, "\"id\":\"retrieval\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, card_resp.body, "\"scopes\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, card_resp.body, "\"database:*\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, card_resp.body, "\"namespace:*\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, card_resp.body, "\"table:*\"") != null);

    var a2a_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.a2a,
        .content_type = "application/json",
        .body = "{\"jsonrpc\":\"2.0\",\"id\":\"card\",\"method\":\"agent/getAuthenticatedExtendedCard\",\"params\":{}}",
    });
    defer a2a_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), a2a_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, a2a_resp.body, "\"preferredTransport\":\"JSONRPC\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, a2a_resp.body, "\"table:*\"") != null);

    var stream_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.a2a,
        .content_type = "application/json",
        .body = "{\"jsonrpc\":\"2.0\",\"id\":\"stream\",\"method\":\"message/stream\",\"params\":{\"taskId\":\"t1\",\"contextId\":\"c1\",\"message\":{\"kind\":\"message\",\"role\":\"user\",\"metadata\":{\"skill\":\"query-builder\"},\"parts\":[{\"kind\":\"text\",\"text\":\"find docs\"}]}}}",
    });
    defer stream_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), stream_resp.status);
    try std.testing.expectEqualStrings("text/event-stream", stream_resp.content_type.?);
    try std.testing.expect(std.mem.indexOf(u8, stream_resp.body, "event: message") != null);
    try std.testing.expect(std.mem.indexOf(u8, stream_resp.body, "event: done") != null);

    var a2a_non_default_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.a2a,
        .content_type = "application/json",
        .body = "{\"jsonrpc\":\"2.0\",\"id\":\"non-default\",\"method\":\"message/send\",\"params\":{\"taskId\":\"t-non-default\",\"contextId\":\"c-non-default\",\"message\":{\"kind\":\"message\",\"role\":\"user\",\"metadata\":{\"skill\":\"query-builder\"},\"parts\":[{\"kind\":\"text\",\"text\":\"find docs\"},{\"kind\":\"data\",\"data\":{\"database\":\"tenant_ops\",\"namespace\":\"analytics\",\"table\":\"docs\"}}]}}}",
    });
    defer a2a_non_default_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), a2a_non_default_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, a2a_non_default_resp.body, "\"state\":\"completed\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, a2a_non_default_resp.body, "tenant_ops.analytics.docs") != null);

    var task_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.a2a,
        .content_type = "application/json",
        .body = "{\"jsonrpc\":\"2.0\",\"id\":\"get\",\"method\":\"tasks/get\",\"params\":{\"id\":\"t1\"}}",
    });
    defer task_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), task_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, task_resp.body, "\"id\":\"t1\"") != null);

    var cancel_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.a2a,
        .content_type = "application/json",
        .body = "{\"jsonrpc\":\"2.0\",\"id\":\"cancel\",\"method\":\"tasks/cancel\",\"params\":{\"id\":\"t1\"}}",
    });
    defer cancel_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), cancel_resp.status);
    try std.testing.expect(std.mem.indexOf(u8, cancel_resp.body, "\"state\":\"canceled\"") != null);
}

test "api http server serves ARD catalogs with public bootstrap and authenticated tenant entries" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{
        .ard_publisher_domain = "tenant.example.com",
        .ard_display_name = "Tenant Antfly",
    }, source.iface(), null, null);
    defer server.deinit();

    var public_catalog = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.ai_catalog,
    });
    defer public_catalog.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), public_catalog.status);
    try std.testing.expectEqualStrings("application/json", public_catalog.content_type.?);
    try std.testing.expectEqual(@as(usize, 1), public_catalog.headers.len);
    try std.testing.expectEqualStrings("Access-Control-Allow-Origin", public_catalog.headers[0].name);
    try std.testing.expectEqualStrings("*", public_catalog.headers[0].value);
    try std.testing.expect(std.mem.indexOf(u8, public_catalog.body, "\"type\":\"application/ai-registry+json\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, public_catalog.body, "\"type\":\"application/mcp-server+json\"") == null);

    var tenant_catalog = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.ard_v1_catalog,
    });
    defer tenant_catalog.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), tenant_catalog.status);
    try std.testing.expect(std.mem.indexOf(u8, tenant_catalog.body, "\"type\":\"application/mcp-server+json\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, tenant_catalog.body, "\"displayName\":\"Tenant Antfly\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, tenant_catalog.body, "\"identifier\":\"did:web:tenant.example.com\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, tenant_catalog.body, "urn:ai:tenant.example.com:antfly:mcp") != null);

    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, tenant_catalog.body, .{});
    defer parsed.deinit();
    const entries = parsed.value.object.get("entries").?.array.items;
    try std.testing.expect(entries.len >= 4);
    for (entries) |entry| {
        const object = entry.object;
        try std.testing.expect(object.get("identifier") != null);
        try std.testing.expect(object.get("displayName") != null);
        try std.testing.expect(object.get("type") != null);
        const has_url = object.get("url") != null;
        const has_data = object.get("data") != null;
        try std.testing.expect(has_url != has_data);
    }
}

test "api http server requires auth for ARD tenant catalog when auth is enabled" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }
    };

    const secret = "ard-catalog-trusted-principal-secret";
    var auth = try initTestAuthManager(std.testing.allocator);
    try bindTestAuthManager(std.testing.allocator, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var admin_permission = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(std.testing.allocator, .@"*", "*", .admin),
    };
    defer admin_permission[0].deinit(std.testing.allocator);
    var admin_user = try auth.manager.createUser("admin", "admin", &admin_permission);
    defer admin_user.deinit(std.testing.allocator);

    var source = FakeSource{};
    var server = ApiHttpServer.init(
        std.testing.allocator,
        .{
            .auth_enabled = true,
            .user_manager = &auth.manager,
            .trusted_principal_secret = secret,
            .trusted_principal_issuer = "trusted-upstream",
        },
        source.iface(),
        null,
        null,
    );
    defer server.deinit();

    var unauthorized = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.ard_v1_catalog,
    });
    defer unauthorized.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 401), unauthorized.status);

    var unauthorized_well_known = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.ai_catalog,
    });
    defer unauthorized_well_known.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 401), unauthorized_well_known.status);

    const now: i64 = @intCast(@divFloor(nowNs(), std.time.ns_per_s));
    const payload = try std.fmt.allocPrint(
        std.testing.allocator,
        \\{{"iss":"trusted-upstream","sub":"user:alice","tenant":"tenant-1","tables":["docs"],"operations":["read"],"iat":{d},"exp":{d}}}
    ,
        .{ now, now + 60 },
    );
    defer std.testing.allocator.free(payload);
    const token = try encodeTrustedPrincipalToken(std.testing.allocator, secret, payload);
    defer std.testing.allocator.free(token);
    const trusted_principal_headers = [_]http_common.RequestHeader{
        .{ .name = trusted_principal_header, .value = token },
    };

    var authorized = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.ard_v1_catalog,
        .headers = &trusted_principal_headers,
    });
    defer authorized.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), authorized.status);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "\"type\":\"application/mcp-server+json\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "Antfly Extensions OpenAPI") == null);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "Antfly Auth OpenAPI") == null);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "Antfly Extension Management") == null);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "Antfly Retrieval") != null);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "Antfly Query Builder") != null);
    try std.testing.expect(std.mem.indexOf(u8, authorized.body, "Antfly Schema Design") == null);

    var authorized_well_known = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.ai_catalog,
        .headers = &trusted_principal_headers,
    });
    defer authorized_well_known.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), authorized_well_known.status);
    try std.testing.expectEqual(@as(usize, 0), authorized_well_known.headers.len);
    try std.testing.expect(std.mem.indexOf(u8, authorized_well_known.body, "\"type\":\"application/mcp-server+json\"") != null);

    var forbidden_spec = try server.handle(.{
