                        .table_name = "docs",
                        .owner_metadata_json = "{\"description\":\"Search docs\",\"input_schema\":{\"type\":\"object\"},\"required_capabilities\":[{\"name\":\"db:read\",\"scope\":\"docsaf\"}]}",
                    },
                    .{
                        .extension_name = "docsaf",
                        .scope = .{ .kind = .table, .table_name = "docs" },
                        .object_kind = .mcp_tool,
