                        .table_name = "docs",
                        .owner_metadata_json = "{\"description\":\"Store docs\",\"input_schema\":{\"type\":\"object\"},\"required_capabilities\":[{\"name\":\"db:write\",\"scope\":\"docsaf\"}]}",
                    },
                    .{
