        .body = "{\"resource\":\"reports\",\"resource_type\":\"table\",\"type\":\"write\"}",
    });
    defer add_permission_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), add_permission_resp.status);
    try std.testing.expectEqualStrings("application/json", add_permission_resp.content_type.?);
    var add_permission = try std.json.parseFromSlice(usermgr_openapi.SuccessMessage, alloc, add_permission_resp.body, .{});
    defer add_permission.deinit();
    try std.testing.expect(add_permission.value.message != null);
    try std.testing.expect(add_permission.value.message.?.len > 0);

    var add_role_resp = try server.handle(.{
        .method = .POST,
        .uri = "/auth/v1/users/alice/roles",
        .authorization = admin_auth,
        .body = "{\"role\":\"role:tenant_reader\"}",
    });
    defer add_role_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), add_role_resp.status);
    try std.testing.expectEqualStrings("application/json", add_role_resp.content_type.?);

    var roles_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/users/alice/roles",
        .authorization = admin_auth,
    });
    defer roles_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), roles_resp.status);
    try std.testing.expectEqualStrings("application/json", roles_resp.content_type.?);
    var roles = try std.json.parseFromSlice([]const []const u8, alloc, roles_resp.body, .{});
    defer roles.deinit();
    try std.testing.expectEqual(@as(usize, 1), roles.value.len);
    try std.testing.expectEqualStrings("role:tenant_reader", roles.value[0]);

    var subjects_resp = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.auth_subjects,
        .authorization = admin_auth,
    });
    defer subjects_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), subjects_resp.status);
    try std.testing.expectEqualStrings("application/json", subjects_resp.content_type.?);
    var subjects = try std.json.parseFromSlice([]AuthSubjectResponse, alloc, subjects_resp.body, .{});
    defer subjects.deinit();
    try std.testing.expect(subjects.value.len >= 2);

    var delete_role_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/auth/v1/users/alice/roles?role=role:tenant_reader",
        .authorization = admin_auth,
    });
    defer delete_role_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 204), delete_role_resp.status);

    var password_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/auth/v1/users/alice/password",
        .authorization = admin_auth,
        .body = "{\"new_password\":\"new-secret\"}",
    });
    defer password_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), password_resp.status);
    try std.testing.expectEqualStrings("application/json", password_resp.content_type.?);
    var password_result = try std.json.parseFromSlice(usermgr_openapi.SuccessMessage, alloc, password_resp.body, .{});
    defer password_result.deinit();
    try std.testing.expect(password_result.value.message != null);
    try std.testing.expect(password_result.value.message.?.len > 0);

    var authed = try auth.manager.authenticateUser("alice", "new-secret");
    defer authed.deinit(alloc);
    try std.testing.expectEqualStrings("alice", authed.username);

    var delete_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/auth/v1/users/alice",
        .authorization = admin_auth,
    });
    defer delete_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 204), delete_resp.status);

    try std.testing.expectError(error.UserNotFound, auth.manager.getUser("alice"));
}

test "api http server applies authorization SQL DDL through user manager" {
    const alloc = std.testing.allocator;
    const usage_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id","tenant_id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const FakeSource = struct {
        tables: [2]metadata_table_manager.TableRecord = .{
            .{ .table_id = 1, .name = "usage_records", .schema_json = usage_schema_json },
            .{ .table_id = 2, .name = "docs" },
        },

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdlPlanWithSession(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            return error.TestUnexpectedResult;
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(alloc);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{
        .user_manager = &auth.manager,
    }, source.iface(), null, null);
    defer server.deinit();

    var created = try server.applyRelationalSqlDdl("CREATE ROLE app_writer;");
    defer created.deinit(alloc);
    var granted = try server.applyRelationalSqlDdl("GRANT SELECT ON TABLE usage_records TO app_writer;");
    defer granted.deinit(alloc);
    try std.testing.expectError(error.TableNotFound, server.applyRelationalSqlDdl("GRANT SELECT ON TABLE missing_records TO app_writer;"));
    var schema_granted = try server.applyRelationalSqlDdl("GRANT SELECT ON ALL TABLES IN SCHEMA public TO app_writer;");
    defer schema_granted.deinit(alloc);
    var row_security_enabled = try server.applyRelationalSqlDdl("ALTER TABLE usage_records ENABLE ROW LEVEL SECURITY;");
    defer row_security_enabled.deinit(alloc);
    var row_policy = try server.applyRelationalSqlDdl("CREATE POLICY usage_records_tenant_policy ON usage_records USING (tenant_id = current_setting('app.tenant_id'));");
    defer row_policy.deinit(alloc);
    var routine = try server.applyRelationalSqlDdl("CREATE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT lower($1)';");
    defer routine.deinit(alloc);
    var routine_policy = try server.applyRelationalSqlDdl("CREATE POLICY usage_records_normalized_policy ON usage_records USING (normalize_status(status) = 'active');");
    defer routine_policy.deinit(alloc);
    var disjunction_policy = try server.applyRelationalSqlDdl("CREATE POLICY usage_records_or_policy ON usage_records USING (tenant_id = 'tenant-a' OR status = 'active');");
    defer disjunction_policy.deinit(alloc);
    var mixed_policy = try server.applyRelationalSqlDdl("CREATE POLICY usage_records_mixed_policy ON usage_records USING (tenant_id = 'tenant-a' OR status = 'active' AND id = 'evt-1');");
    defer mixed_policy.deinit(alloc);
    try std.testing.expectError(error.TableNotFound, server.applyRelationalSqlDdl("CREATE POLICY missing_tenant_policy ON missing_records USING (tenant_id = 'tenant-a');"));
    try std.testing.expectError(error.UnsupportedSqlShape, server.applyRelationalSqlDdl("CREATE POLICY missing_column_policy ON usage_records USING (missing_tenant = 'tenant-a');"));

    try auth.manager.addRoleToUser("alice", "role:app_writer");
    try std.testing.expect(try auth.manager.enforce("alice", .table, "default.public.usage_records", .read));
    try std.testing.expect(try auth.manager.enforce("alice", .table, "default.public.docs", .read));
    try std.testing.expect(!(try auth.manager.enforce("alice", .table, "future_table", .read)));
    const stored_policy = try auth.manager.getSqlRowSecurityPolicy("usage_records_tenant_policy", "default.public.usage_records");
    defer alloc.free(stored_policy);
    try std.testing.expect(std.mem.indexOf(u8, stored_policy, "\"$auth\":\"settings.app.tenant_id\"") != null);
    const stored_routine_policy = try auth.manager.getSqlRowSecurityPolicy("usage_records_normalized_policy", "default.public.usage_records");
    defer alloc.free(stored_routine_policy);
    try std.testing.expect(std.mem.indexOf(u8, stored_routine_policy, "\"expression_where\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, stored_routine_policy, "\"op\":\"lower\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, stored_routine_policy, "\"field\":\"status\"") != null);
    const stored_disjunction_policy = try auth.manager.getSqlRowSecurityPolicy("usage_records_or_policy", "default.public.usage_records");
    defer alloc.free(stored_disjunction_policy);
    try std.testing.expectEqualStrings("{\"disjuncts\":[{\"term\":{\"tenant_id\":\"tenant-a\"}},{\"term\":{\"status\":\"active\"}}]}", stored_disjunction_policy);
    const stored_mixed_policy = try auth.manager.getSqlRowSecurityPolicy("usage_records_mixed_policy", "default.public.usage_records");
    defer alloc.free(stored_mixed_policy);
    try std.testing.expectEqualStrings("{\"disjuncts\":[{\"term\":{\"tenant_id\":\"tenant-a\"}},{\"conjuncts\":[{\"term\":{\"status\":\"active\"}},{\"term\":{\"id\":\"evt-1\"}}]}]}", stored_mixed_policy);
    try std.testing.expect(try auth.manager.sqlRowSecurityEnabled("default.public.usage_records"));

    var altered_policy = try server.applyRelationalSqlDdl("ALTER POLICY usage_records_tenant_policy ON usage_records USING (status = 'active');");
    defer altered_policy.deinit(alloc);
    const altered_policy_json = try auth.manager.getSqlRowSecurityPolicy("usage_records_tenant_policy", "default.public.usage_records");
    defer alloc.free(altered_policy_json);
    try std.testing.expectEqualStrings("{\"term\":{\"status\":\"active\"}}", altered_policy_json);
    try std.testing.expectError(error.RowFilterNotFound, server.applyRelationalSqlDdl("ALTER POLICY missing_policy ON usage_records USING (status = 'active');"));

    try std.testing.expectError(error.RoleInUse, server.applyRelationalSqlDdl("DROP ROLE app_writer;"));
    var revoked = try server.applyRelationalSqlDdl("REVOKE SELECT ON TABLE usage_records FROM app_writer;");
    defer revoked.deinit(alloc);
    var schema_revoked = try server.applyRelationalSqlDdl("REVOKE SELECT ON ALL TABLES IN SCHEMA public FROM app_writer;");
    defer schema_revoked.deinit(alloc);
    var dropped_policy = try server.applyRelationalSqlDdl("DROP POLICY usage_records_tenant_policy ON usage_records;");
    defer dropped_policy.deinit(alloc);
    try std.testing.expectError(error.RowFilterNotFound, auth.manager.getSqlRowSecurityPolicy("usage_records_tenant_policy", "default.public.usage_records"));
    var dropped_routine_policy = try server.applyRelationalSqlDdl("DROP POLICY usage_records_normalized_policy ON usage_records;");
    defer dropped_routine_policy.deinit(alloc);
    try std.testing.expectError(error.RowFilterNotFound, auth.manager.getSqlRowSecurityPolicy("usage_records_normalized_policy", "default.public.usage_records"));
    var dropped_disjunction_policy = try server.applyRelationalSqlDdl("DROP POLICY usage_records_or_policy ON usage_records;");
    defer dropped_disjunction_policy.deinit(alloc);
    try std.testing.expectError(error.RowFilterNotFound, auth.manager.getSqlRowSecurityPolicy("usage_records_or_policy", "default.public.usage_records"));
    var dropped_routine = try server.applyRelationalSqlDdl("DROP FUNCTION normalize_status(text);");
    defer dropped_routine.deinit(alloc);
    var dropped_policy_if_exists = try server.applyRelationalSqlDdl("DROP POLICY IF EXISTS usage_records_tenant_policy ON usage_records;");
    defer dropped_policy_if_exists.deinit(alloc);
    try std.testing.expect(dropped_policy_if_exists.noop);
    try auth.manager.removeRoleFromUser("alice", "role:app_writer");
    var dropped = try server.applyRelationalSqlDdl("DROP ROLE app_writer;");
    defer dropped.deinit(alloc);
    try std.testing.expect(!(try auth.manager.enforce("alice", .table, "default.public.usage_records", .read)));
}

test "api http server enforces SQL row security WITH CHECK on row writes" {
    const alloc = std.testing.allocator;
    const usage_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id","tenant_id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const table_target: catalog_resources.TableTarget = .{
        .database_name = catalog_resources.default_database_name,
        .namespace_name = catalog_resources.default_namespace_name,
        .table_name = "usage_records",
    };
    const table_resource = "default.public.usage_records";
    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord = .{.{
            .table_id = 1,
            .name = "usage_records",
            .database_name = catalog_resources.default_database_name,
            .namespace_name = catalog_resources.default_namespace_name,
            .schema_json = usage_schema_json,
        }},

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };
    const FakeReads = struct {
        lookup_calls: usize = 0,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .lookup_catalog = lookupCatalog,
                    .scan = scan,
                    .query = query,
                },
            };
        }

        fn lookup(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: db_mod.types.LookupOptions, _: raft_mod.ReadConsistency) anyerror!?table_reads.LookupResponse {
            return error.UnsupportedOperation;
        }

        fn lookupCatalog(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            key: []const u8,
            _: db_mod.types.LookupOptions,
            consistency: raft_mod.ReadConsistency,
        ) anyerror!?table_reads.LookupResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqual(raft_mod.ReadConsistency.read_index, consistency);
            try std.testing.expectEqualStrings(catalog_resources.default_database_name, target.database_name);
            try std.testing.expectEqualStrings(catalog_resources.default_namespace_name, target.namespace_name);
            try std.testing.expectEqualStrings("usage_records", target.table_name);
            self.lookup_calls += 1;
            if (std.mem.eql(u8, key, "missing")) return null;
            if (std.mem.eql(u8, key, "tenant-b-existing")) {
                return .{
                    .json = try allocator.dupe(u8, "{\"id\":\"tenant-b-existing\",\"tenant_id\":\"tenant-b\",\"status\":\"active\"}"),
                    .version = 7,
                };
            }
            return .{
                .json = try allocator.dupe(u8, "{\"id\":\"existing\",\"tenant_id\":\"tenant-a\",\"status\":\"archived\"}"),
                .version = 3,
            };
        }

        fn scan(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8, _: db_mod.types.ScanOptions, _: raft_mod.ReadConsistency) anyerror!?table_reads.ScanResponse {
            return error.UnsupportedOperation;
        }

        fn query(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.SearchRequest, _: raft_mod.ReadConsistency) anyerror!?query_api.QueryResponse {
            return error.UnsupportedOperation;
        }
    };
    const BatchHelper = struct {
        fn oneWrite(allocator: std.mem.Allocator, key: []const u8, json: []const u8) !relational_rows_api.OwnedRowsBatchRequest {
            const writes = try allocator.alloc(db_mod.types.BatchWrite, 1);
            errdefer allocator.free(writes);
            const owned_key = try allocator.dupe(u8, key);
            errdefer allocator.free(owned_key);
            const owned_value = try allocator.dupe(u8, json);
            errdefer allocator.free(owned_value);
            writes[0] = .{
                .key = owned_key,
                .value = owned_value,
            };
            return .{
                .writes = writes,
                .req = .{ .writes = writes },
                .inserted = 1,
            };
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(alloc);

    var source = FakeSource{};
    var reads = FakeReads{};
    var server = ApiHttpServer.init(alloc, .{ .user_manager = &auth.manager }, source.iface(), reads.source(), null);
    defer server.deinit();

    var enabled = try server.applyRelationalSqlDdl("ALTER TABLE usage_records ENABLE ROW LEVEL SECURITY;");
    defer enabled.deinit(alloc);
    var policy = try server.applyRelationalSqlDdl("CREATE POLICY usage_records_write_policy ON usage_records USING (tenant_id = 'tenant-a') WITH CHECK (status = 'active');");
    defer policy.deinit(alloc);

    const read_filters = try auth.manager.getRowFilters("alice");
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
        .row_filter = read_filters,
    };
    defer identity.deinit(alloc);

    var accepted_insert = try BatchHelper.oneWrite(
        alloc,
        "missing",
        "{\"id\":\"missing\",\"tenant_id\":\"tenant-b\",\"status\":\"active\"}",
    );
    defer accepted_insert.deinit(alloc);
    try server.requireRowsBatchSatisfiesEffectiveFilterForDatabase(
        catalog_resources.default_database_name,
        table_resource,
        table_target,
        accepted_insert,
        identity,
    );

    var rejected_check = try BatchHelper.oneWrite(
        alloc,
        "existing",
        "{\"id\":\"existing\",\"tenant_id\":\"tenant-a\",\"status\":\"archived\"}",
    );
    defer rejected_check.deinit(alloc);
    try std.testing.expectError(
        error.PermissionDenied,
        server.requireRowsBatchSatisfiesEffectiveFilterForDatabase(
            catalog_resources.default_database_name,
            table_resource,
            table_target,
            rejected_check,
            identity,
        ),
    );

    var rejected_visibility = try BatchHelper.oneWrite(
        alloc,
        "tenant-b-existing",
        "{\"id\":\"tenant-b-existing\",\"tenant_id\":\"tenant-b\",\"status\":\"active\"}",
    );
    defer rejected_visibility.deinit(alloc);
    try std.testing.expectError(
        error.PermissionDenied,
        server.requireRowsBatchSatisfiesEffectiveFilterForDatabase(
            catalog_resources.default_database_name,
            table_resource,
            table_target,
            rejected_visibility,
            identity,
        ),
    );

    try std.testing.expect(reads.lookup_calls >= 3);
}

