test "api http server applies SQL DDL with explicit catalog session" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        saw_session_create: bool = false,
        tables: [1]metadata_table_manager.TableRecord = .{.{
            .table_id = 10,
            .name = "events",
            .database_name = "tenant_ops",
            .namespace_name = "analytics",
        }},

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const table_plan = switch (plan.*) {
                .table_ddl => |table| table,
                else => return error.TestUnexpectedResult,
            };
            var target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(alloc_arg, table_plan, session);
            defer target.deinit(alloc_arg);
            try std.testing.expect(target.createsTable());
            try std.testing.expectEqualStrings("tenant_ops", target.database_name);
            if (std.mem.eql(u8, target.table_name, "events")) {
                try std.testing.expectEqualStrings("analytics", target.namespace_name);
                self.saw_session_create = true;
            } else if (std.mem.eql(u8, target.table_name, "local_events")) {
                try std.testing.expectEqualStrings("public", target.namespace_name);
            } else {
                return error.TestUnexpectedResult;
            }
            return .{ .table = try metadata_table_manager.cloneTable(alloc_arg, .{
                .table_id = 0,
                .name = target.table_name,
                .database_name = target.database_name,
                .namespace_name = target.namespace_name,
            }) };
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(alloc);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{
        .user_manager = &auth.manager,
    }, source.iface(), null, null);

    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, .{
        .current_database_name = "tenant_ops",
        .search_path = &.{"public"},
    });
    defer session.deinit(alloc);

    var created_role = try server.applyRelationalSqlDdlWithSession("CREATE ROLE app_reader;", &session);
    defer created_role.deinit(alloc);
    try auth.manager.addRoleToUser("alice", "role:app_reader");

    var set_tenant = try server.applyRelationalSqlDdlWithSession("SET app.tenant_id = 'tenant-a';", &session);
    defer set_tenant.deinit(alloc);
    try std.testing.expect(set_tenant.noop);
    try std.testing.expectEqualStrings("tenant-a", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);

    var stored_tenant = try server.applyRelationalSqlDdlWithSession("ALTER ROLE app_reader SET app.tenant_id = current_setting('app.tenant_id');", &session);
    defer stored_tenant.deinit(alloc);
    const role_tenant = try auth.manager.getRoleSetting("role:app_reader", "app.tenant_id");
    defer alloc.free(role_tenant);
    try std.testing.expectEqualStrings("tenant-a", role_tenant);

    var set_path = try server.applyRelationalSqlDdlWithSession("SET search_path TO analytics, public;", &session);
    defer set_path.deinit(alloc);
    try std.testing.expect(set_path.noop);
    try std.testing.expectEqualStrings("analytics", session.search_path[0]);
    try std.testing.expectEqualStrings("public", session.search_path[1]);
    try std.testing.expect(!session.transaction_local_search_path);

    var created_table = try server.applyRelationalSqlDdlWithSession("CREATE TABLE events (id text PRIMARY KEY);", &session);
    defer created_table.deinit(alloc);
    try std.testing.expect(source.saw_session_create);

    var granted = try server.applyRelationalSqlDdlWithSession("GRANT SELECT ON TABLE events TO app_reader;", &session);
    defer granted.deinit(alloc);
    try std.testing.expect(try auth.manager.enforce("alice", .table, "tenant_ops.analytics.events", .read));
    try std.testing.expect(!(try auth.manager.enforce("alice", .table, "default.public.events", .read)));

    var set_local = try server.applyRelationalSqlDdlWithSession("SET LOCAL search_path TO public;", &session);
    defer set_local.deinit(alloc);
    try std.testing.expect(set_local.noop);
    try std.testing.expectEqualStrings("public", session.search_path[0]);
    try std.testing.expect(session.transaction_local_search_path);

    var local_table = try server.applyRelationalSqlDdlWithSession("CREATE TABLE local_events (id text PRIMARY KEY);", &session);
    defer local_table.deinit(alloc);
    try std.testing.expectEqualStrings("public", local_table.table.namespace_name);

    var set_local_tenant = try server.applyRelationalSqlDdlWithSession("SET LOCAL app.tenant_id = 'tenant-b';", &session);
    defer set_local_tenant.deinit(alloc);
    try std.testing.expect(set_local_tenant.noop);
    try std.testing.expect(session.transaction_local_settings);
    try std.testing.expectEqualStrings("tenant-b", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);

    var committed = try server.applyRelationalSqlDdlWithSession("COMMIT;", &session);
    defer committed.deinit(alloc);
    try std.testing.expect(committed.noop);
    try std.testing.expect(!session.transaction_local_search_path);
    try std.testing.expect(session.transaction_local_search_path_base == null);
    try std.testing.expect(!session.transaction_local_settings);
    try std.testing.expect(session.transaction_local_settings_base == null);
    try std.testing.expectEqualStrings("analytics", session.search_path[0]);
    try std.testing.expectEqualStrings("public", session.search_path[1]);
    try std.testing.expectEqualStrings("tenant-a", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);
}

test "api http server classifies SQL transaction session cleanup from parsed statements" {
    const alloc = std.testing.allocator;
