        defer parsed_sql.deinit(alloc);
        try std.testing.expectEqual(case.clears, ApiHttpServer.parsedSqlTransactionBoundaryClearsLocalSession(&parsed_sql));
    }
}

test "api http server enforces SQL statement timeout on session-backed DDL" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        calls: usize = 0,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const expected_timeout: []const u8 = if (self.calls == 0) "100ms" else "0";
            try std.testing.expectEqualStrings(expected_timeout, session.settingValue("statement_timeout") orelse return error.TestUnexpectedResult);
            self.calls += 1;
            sleepNs(120 * std.time.ns_per_ms);
            return try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc_arg);
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var set_timeout = try server.applyRelationalSqlDdlWithSession("SET statement_timeout = '100ms';", &session);
    defer set_timeout.deinit(alloc);
    try std.testing.expect(set_timeout.noop);
    try std.testing.expectEqualStrings("100ms", session.session().settingValue("statement_timeout") orelse return error.TestUnexpectedResult);

    try std.testing.expectError(
        error.StatementTimeout,
        server.applyRelationalSqlDdlWithSession("ALTER TABLE events DROP COLUMN IF EXISTS stale;", &session),
    );
    try std.testing.expectEqual(@as(usize, 1), source.calls);

    var disable_timeout = try server.applyRelationalSqlDdlWithSession("SET statement_timeout = '0';", &session);
    defer disable_timeout.deinit(alloc);
    var applied = try server.applyRelationalSqlDdlWithSession("ALTER TABLE events DROP COLUMN IF EXISTS stale;", &session);
    defer applied.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), source.calls);
}

test "api http server routes prepared transaction SQL DDL to coordinator recovery" {
    const alloc = std.testing.allocator;
    const mem_backend = @import("../storage/mem_backend.zig");
    const FakeSource = struct {
        backend: *mem_backend.Backend,
        applied: usize = 0,
        last_pending: bool = false,
        last_committed: bool = false,
        last_aborted: bool = false,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_prepared_transaction_plan = applyPreparedTransactionPlan,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyPreparedTransactionPlan(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            plan: sql_adapter.PreparedTransactionPlan,
            timestamp_ns: u64,
        ) !sql_adapter.PreparedTransactionCoordinatorResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            var runtime_store = try self.backend.runtimeStore(alloc_arg, .{ .name = "sql-prepared-txn-server" });
            defer runtime_store.deinit();
            const result = try sql_adapter.executePreparedTransactionRecoveryPlan(alloc_arg, &runtime_store, plan, timestamp_ns);
            self.applied += 1;
            self.last_pending = result.status == .pending;
            self.last_committed = result.status == .committed;
            self.last_aborted = result.status == .aborted;
            return result;
        }
    };

    var backend = mem_backend.Backend.init(alloc, .{});
    defer backend.close();
    var source = FakeSource{ .backend = &backend };
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var set_path = try server.applyRelationalSqlDdlWithSession("SET search_path TO analytics, public;", &session);
    defer set_path.deinit(alloc);
    var set_local_path = try server.applyRelationalSqlDdlWithSession("SET LOCAL search_path TO public;", &session);
    defer set_local_path.deinit(alloc);
    var set_local_tenant = try server.applyRelationalSqlDdlWithSession("SET LOCAL app.tenant_id = 'tenant-b';", &session);
    defer set_local_tenant.deinit(alloc);
    try std.testing.expect(session.transaction_local_search_path);
    try std.testing.expect(session.transaction_local_settings);
    try std.testing.expectEqualStrings("public", session.search_path[0]);
    try std.testing.expectEqualStrings("tenant-b", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);

    var prepared = try server.applyRelationalSqlDdlWithSession("PREPARE TRANSACTION 'usage_batch';", &session);
    defer prepared.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), source.applied);
    try std.testing.expect(source.last_pending);
    try std.testing.expect(!session.transaction_local_search_path);
    try std.testing.expect(session.transaction_local_search_path_base == null);
    try std.testing.expect(!session.transaction_local_settings);
    try std.testing.expect(session.transaction_local_settings_base == null);
    try std.testing.expectEqualStrings("analytics", session.search_path[0]);
    try std.testing.expectEqualStrings("public", session.search_path[1]);
    try std.testing.expect(session.session().settingValue("app.tenant_id") == null);

    var committed = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'usage_batch';", &session);
    defer committed.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), source.applied);
    try std.testing.expect(source.last_committed);

    var committed_retry = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'usage_batch';", &session);
    defer committed_retry.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), source.applied);
    try std.testing.expect(source.last_committed);

    try std.testing.expectError(
        error.PreparedTransactionDecisionConflict,
        server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'usage_batch';", &session),
    );

    var abort_prepared = try server.applyRelationalSqlDdlWithSession("PREPARE TRANSACTION 'usage_abort';", &session);
    defer abort_prepared.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 4), source.applied);
    try std.testing.expect(source.last_pending);

    var aborted = try server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'usage_abort';", &session);
    defer aborted.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 5), source.applied);
    try std.testing.expect(source.last_aborted);

    var aborted_retry = try server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'usage_abort';", &session);
    defer aborted_retry.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 6), source.applied);
    try std.testing.expect(source.last_aborted);
}

test "api http server persists prepared transaction SQL DDL through durable session store fallback" {
    const alloc = std.testing.allocator;
    const session_path = "/tmp/antfly-api-http-prepared-transaction-fallback";
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};
    defer std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};

    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    {
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .session_store_path = session_path }, source.iface(), null, null);
        defer server.deinit();
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(alloc);

        var set_local = try server.applyRelationalSqlDdlWithSession("SET LOCAL search_path TO analytics;", &session);
        defer set_local.deinit(alloc);
        try std.testing.expect(session.transaction_local_search_path);

        var prepared = try server.applyRelationalSqlDdlWithSession("PREPARE TRANSACTION 'durable_usage_batch';", &session);
        defer prepared.deinit(alloc);
        try std.testing.expect(!session.transaction_local_search_path);
    }

    {
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .session_store_path = session_path }, source.iface(), null, null);
        defer server.deinit();
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(alloc);

        var committed = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'durable_usage_batch';", &session);
        defer committed.deinit(alloc);

        var committed_retry = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'durable_usage_batch';", &session);
        defer committed_retry.deinit(alloc);

        try std.testing.expectError(
            error.PreparedTransactionDecisionConflict,
            server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'durable_usage_batch';", &session),
        );
    }
}

test "api http server applies prepared statement SQL plans to session runtime" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var session_a = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session_a.deinit(alloc);
    var session_b = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session_b.deinit(alloc);

    var prepared = try server.applyRelationalSqlDdlWithSession(
        "PREPARE usage_plan(text) AS SELECT id FROM usage_records WHERE status = $1;",
        &session_a,
    );
    defer prepared.deinit(alloc);
    try std.testing.expect(prepared.noop);
    try std.testing.expect(session_a.notification_session_id != 0);
    try std.testing.expectEqual(
        @as(usize, 1),
        server.sql_prepared_statement_runtime.statementCountForTest(session_a.notification_session_id),
    );

    try std.testing.expectError(
        error.PreparedStatementAlreadyExists,
        server.applyRelationalSqlDdlWithSession(
            "PREPARE usage_plan(text) AS SELECT id FROM usage_records WHERE status = $1;",
            &session_a,
        ),
    );

    var executed = try server.applyRelationalSqlDdlWithSession("EXECUTE usage_plan('open');", &session_a);
    defer executed.deinit(alloc);
    try std.testing.expect(executed.noop);
    try std.testing.expectError(
        error.PreparedStatementArgumentMismatch,
        server.applyRelationalSqlDdlWithSession("EXECUTE usage_plan();", &session_a),
    );
    try std.testing.expectError(
        error.PreparedStatementNotFound,
        server.applyRelationalSqlDdlWithSession("EXECUTE usage_plan('open');", &session_b),
    );

    var deallocated = try server.applyRelationalSqlDdlWithSession("DEALLOCATE PREPARE usage_plan;", &session_a);
    defer deallocated.deinit(alloc);
    try std.testing.expect(deallocated.noop);
    try std.testing.expectEqual(
        @as(usize, 0),
        server.sql_prepared_statement_runtime.statementCountForTest(session_a.notification_session_id),
    );
    try std.testing.expectError(
        error.PreparedStatementNotFound,
        server.applyRelationalSqlDdlWithSession("EXECUTE usage_plan('open');", &session_a),
    );

    var prepared_read = try server.applyRelationalSqlDdlWithSession(
        "PREPARE read_plan AS SELECT id FROM usage_records;",
        &session_a,
    );
    defer prepared_read.deinit(alloc);
    var prepared_write = try server.applyRelationalSqlDdlWithSession(
        "PREPARE write_plan(text) AS INSERT INTO usage_records(id, status) VALUES ($1, 'prepared');",
        &session_a,
    );
    defer prepared_write.deinit(alloc);
    try std.testing.expectEqual(
        @as(usize, 2),
        server.sql_prepared_statement_runtime.statementCountForTest(session_a.notification_session_id),
    );
    var discarded = try server.applyRelationalSqlDdlWithSession("DISCARD ALL;", &session_a);
    defer discarded.deinit(alloc);
    try std.testing.expect(discarded.noop);
    try std.testing.expectEqual(
        @as(usize, 0),
        server.sql_prepared_statement_runtime.statementCountForTest(session_a.notification_session_id),
    );
}

test "api http server decodes public sql params into owned sql values" {
    const alloc = std.testing.allocator;
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, "[\"open\",10,true,null,{\"ok\":true}]", .{});
    defer parsed.deinit();
    try std.testing.expect(parsed.value == .array);

    var params = try ApiHttpServer.publicSqlParamsFromJsonAlloc(alloc, parsed.value.array.items);
    defer params.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 5), params.values.len);
    try std.testing.expect(params.values[0] == .string);
    try std.testing.expectEqualStrings("open", params.values[0].string);
    try std.testing.expect(params.values[1] == .integer);
    try std.testing.expectEqual(@as(i64, 10), params.values[1].integer);
    try std.testing.expect(params.values[2] == .bool);
    try std.testing.expect(params.values[2].bool);
    try std.testing.expect(params.values[3] == .null);
    try std.testing.expect(params.values[4] == .json);
    try std.testing.expectEqualStrings("{\"ok\":true}", params.values[4].json);
}

test "api http server exposes psql-style SQL session endpoint" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var prepare_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"read_only\":null,\"sql\":\"PREPARE usage_plan(text) AS SELECT id FROM usage_records WHERE status = $1;\"}",
    });
    defer prepare_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), prepare_resp.status);
    var parsed_prepare = try std.json.parseFromSlice(std.json.Value, alloc, prepare_resp.body, .{ .allocate = .alloc_always });
    defer parsed_prepare.deinit();
    const session_id = @as(u64, @intCast(parsed_prepare.value.object.get("session_id").?.integer));
    try std.testing.expect(session_id != 0);
    try std.testing.expectEqualStrings("ddl", parsed_prepare.value.object.get("kind").?.string);
    try std.testing.expect(parsed_prepare.value.object.get("noop").?.bool);
    try std.testing.expectEqual(
        @as(usize, 1),
        server.sql_prepared_statement_runtime.statementCountForTest(session_id),
    );

    const prepare_write_body = try std.fmt.allocPrint(
        alloc,
        "{{\"session_id\":{d},\"sql\":\"PREPARE write_plan(text) AS INSERT INTO usage_records(id, status) VALUES ($1, 'prepared');\"}}",
        .{session_id},
    );
    defer alloc.free(prepare_write_body);
    var prepare_write_resp = try server.handle(.{
        .method = .POST,
