test "api http server applies SQL row triggers to public SQL writes" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/public-sql-write-triggers", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    var read_source = table_reads.BoundTableReadSource.init("events", 1, &db, raft_mod.read_gate.noopReadableLeaseRequester());
    var write_source = table_writes.BoundTableWriteSource.init("events", &db);

    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{ .tables = .{.{
        .table_id = 1,
        .name = "events",
        .schema_json = schema_json,
        .desired_replica_count = 1,
    }} };
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), read_source.source(), write_source.source());
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var baseline_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"sql\":\"INSERT INTO events (id, status) VALUES ('evt-existing', 'open') RETURNING id;\"}",
    });
    defer baseline_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), baseline_resp.status);

    var created_insert_function = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION skip_event_insert() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NULL; END';",
        &session,
    );
    defer created_insert_function.deinit(alloc);
    var created_insert_trigger = try server.applyRelationalSqlDdlWithSession(
        "CREATE TRIGGER skip_event_insert BEFORE INSERT ON events FOR EACH ROW EXECUTE FUNCTION skip_event_insert();",
        &session,
    );
    defer created_insert_trigger.deinit(alloc);

    var skipped_insert_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"sql\":\"INSERT INTO events (id, status) VALUES ('evt-skipped', 'new') RETURNING id;\"}",
    });
    defer skipped_insert_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), skipped_insert_resp.status);
    var parsed_skipped_insert = try std.json.parseFromSlice(std.json.Value, alloc, skipped_insert_resp.body, .{ .allocate = .alloc_always });
    defer parsed_skipped_insert.deinit();
    const skipped_result = parsed_skipped_insert.value.object.get("result").?.object;
    try std.testing.expectEqual(@as(i64, 0), skipped_result.get("inserted").?.integer);
    if (skipped_result.get("returning")) |returning| {
        try std.testing.expectEqual(@as(usize, 0), returning.array.items.len);
    }

    var created_update_function = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION keep_event_update_old() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN OLD; END';",
        &session,
    );
    defer created_update_function.deinit(alloc);
    var created_update_trigger = try server.applyRelationalSqlDdlWithSession(
        "CREATE TRIGGER keep_event_update_old BEFORE UPDATE ON events FOR EACH ROW EXECUTE FUNCTION keep_event_update_old();",
        &session,
    );
    defer created_update_trigger.deinit(alloc);

    var update_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"sql\":\"UPDATE events SET status = 'closed' WHERE id = 'evt-existing' RETURNING id, status;\"}",
    });
    defer update_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 501), update_resp.status);

    var created_delete_function = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION skip_event_delete() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NULL; END';",
        &session,
    );
    defer created_delete_function.deinit(alloc);
    var created_delete_trigger = try server.applyRelationalSqlDdlWithSession(
        "CREATE TRIGGER skip_event_delete BEFORE DELETE ON events FOR EACH ROW EXECUTE FUNCTION skip_event_delete();",
        &session,
    );
    defer created_delete_trigger.deinit(alloc);

    var delete_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"sql\":\"DELETE FROM events WHERE id = 'evt-existing' RETURNING id;\"}",
    });
    defer delete_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 501), delete_resp.status);

    var query_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"sql\":\"SELECT id, status FROM events ORDER BY id ASC;\"}",
    });
    defer query_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), query_resp.status);
    var parsed_query = try std.json.parseFromSlice(std.json.Value, alloc, query_resp.body, .{ .allocate = .alloc_always });
    defer parsed_query.deinit();
    const result = parsed_query.value.object.get("result").?.object;
    try std.testing.expectEqual(@as(i64, 1), result.get("total").?.integer);
    const row = result.get("rows").?.array.items[0].object;
    try std.testing.expectEqualStrings("evt-existing", row.get("id").?.string);
    try std.testing.expectEqualStrings("open", row.get("status").?.string);
}

test "api http server executes SQL notification channel plans through native runtime" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            return error.TestUnexpectedResult;
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session_a = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session_a.deinit(alloc);
    var session_b = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session_b.deinit(alloc);

    var listen_a = try server.applyRelationalSqlDdlWithSession("LISTEN usage_events;", &session_a);
    defer listen_a.deinit(alloc);
    var listen_b = try server.applyRelationalSqlDdlWithSession("LISTEN usage_events;", &session_b);
    defer listen_b.deinit(alloc);
    var duplicate_listen_b = try server.applyRelationalSqlDdlWithSession("LISTEN usage_events;", &session_b);
    defer duplicate_listen_b.deinit(alloc);
    try std.testing.expect(session_a.notification_session_id != 0);
    try std.testing.expect(session_b.notification_session_id != 0);
    try std.testing.expect(session_a.notification_session_id != session_b.notification_session_id);
    try std.testing.expectEqual(
        @as(usize, 1),
        server.sql_notification_runtime.subscriptionCountForTest(session_b.notification_session_id, "usage_events"),
    );

    var set_path = try server.applyRelationalSqlDdlWithSession("SET search_path TO public;", &session_b);
    defer set_path.deinit(alloc);
    try std.testing.expectEqual(
        @as(usize, 1),
        server.sql_notification_runtime.subscriptionCountForTest(session_b.notification_session_id, "usage_events"),
    );

    var notified = try server.applyRelationalSqlDdlWithSession("NOTIFY usage_events, 'updated';", &session_a);
    defer notified.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), server.sql_notification_runtime.eventCountForTest());
    var event = (try server.sql_notification_runtime.cloneLastEventForTest(alloc)) orelse return error.TestUnexpectedResult;
    defer event.deinit(alloc);
    try std.testing.expectEqual(@as(u64, 1), event.sequence);
    try std.testing.expectEqualStrings("usage_events", event.channel_name);
    try std.testing.expectEqualStrings("\"updated\"", event.payload_json orelse return error.TestUnexpectedResult);
    try std.testing.expectEqual(@as(usize, 2), event.delivered_session_ids.len);

    var unlisten_b = try server.applyRelationalSqlDdlWithSession("UNLISTEN usage_events;", &session_b);
    defer unlisten_b.deinit(alloc);
    try std.testing.expectEqual(
        @as(usize, 0),
        server.sql_notification_runtime.subscriptionCountForTest(session_b.notification_session_id, "usage_events"),
    );

    var unlisten_a = try server.applyRelationalSqlDdlWithSession("UNLISTEN *;", &session_a);
    defer unlisten_a.deinit(alloc);
    try std.testing.expectEqual(
        @as(usize, 0),
        server.sql_notification_runtime.subscriptionCountForTest(session_a.notification_session_id, "usage_events"),
    );
}

test "api http server applies SQL routine catalog plans through native runtime" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            return error.TestUnexpectedResult;
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var created = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT lower($1)';",
        &session,
    );
    defer created.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), server.sql_routine_runtime.routineCountForTest());

    const normalized = try server.sql_routine_runtime.executeExpressionRoutineAlloc(alloc, "normalize_status", "\"ACTIVE\"");
    defer alloc.free(normalized);
    try std.testing.expectEqualStrings("\"active\"", normalized);

    var replaced = try server.applyRelationalSqlDdlWithSession(
        "CREATE OR REPLACE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT upper($1)';",
        &session,
    );
    defer replaced.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), server.sql_routine_runtime.routineCountForTest());
    const uppered = try server.sql_routine_runtime.executeExpressionRoutineAlloc(alloc, "normalize_status", "\"active\"");
    defer alloc.free(uppered);
    try std.testing.expectEqualStrings("\"ACTIVE\"", uppered);

    var created_multi_arg = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION add_amounts(numeric, numeric) RETURNS numeric LANGUAGE sql AS 'SELECT $1 + $2';",
        &session,
    );
    defer created_multi_arg.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), server.sql_routine_runtime.routineCountForTest());
    const added = try server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "add_amounts", &.{ "2", "3.5" });
    defer alloc.free(added);
    try std.testing.expectEqualStrings("5.5", added);

    var created_concat = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION status_label(text, text) RETURNS text LANGUAGE sql AS 'SELECT concat_ws('' '', $1, $2)';",
        &session,
    );
    defer created_concat.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), server.sql_routine_runtime.routineCountForTest());
    const label = try server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "status_label", &.{ "\"tenant\"", "\"active\"" });
    defer alloc.free(label);
    try std.testing.expectEqualStrings("\"tenant active\"", label);

    var created_clamp = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION clamp_amount(numeric, numeric, numeric) RETURNS numeric LANGUAGE sql AS 'SELECT least(greatest($1, $2), $3)';",
        &session,
    );
    defer created_clamp.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 4), server.sql_routine_runtime.routineCountForTest());
    const clamped = try server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "clamp_amount", &.{ "5", "10", "8" });
    defer alloc.free(clamped);
    try std.testing.expectEqualStrings("8", clamped);

    var created_strict = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION strict_normalize_status(text) RETURNS text LANGUAGE sql STRICT AS 'SELECT lower($1)';",
        &session,
    );
    defer created_strict.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 5), server.sql_routine_runtime.routineCountForTest());
    const strict_null = try server.sql_routine_runtime.executeExpressionRoutineAlloc(alloc, "strict_normalize_status", "null");
    defer alloc.free(strict_null);
    try std.testing.expectEqualStrings("null", strict_null);

    var dropped = try server.applyRelationalSqlDdlWithSession("DROP FUNCTION normalize_status(text);", &session);
    defer dropped.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 4), server.sql_routine_runtime.routineCountForTest());
}

test "api http server recovers durable SQL routine catalog" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-routine-catalog", .{tmp.sub_path});
    defer alloc.free(path);

    {
        var source = FakeSource{};
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .sql_routine_store_path = path }, source.iface(), null, null);
        defer server.deinit();
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(alloc);

        var created = try server.applyRelationalSqlDdlWithSession(
            "CREATE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT lower($1)';",
            &session,
        );
        defer created.deinit(alloc);
        var created_procedure = try server.applyRelationalSqlDdlWithSession(
            "CREATE PROCEDURE rotate_usage() LANGUAGE plpgsql AS 'BEGIN NULL; END';",
            &session,
        );
        defer created_procedure.deinit(alloc);
        try std.testing.expectEqual(@as(usize, 2), server.sql_routine_runtime.routineCountForTest());
    }

    {
        var source = FakeSource{};
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .sql_routine_store_path = path }, source.iface(), null, null);
        defer server.deinit();
        try std.testing.expectEqual(@as(usize, 2), server.sql_routine_runtime.routineCountForTest());
        const normalized = try server.sql_routine_runtime.executeExpressionRoutineAlloc(alloc, "normalize_status", "\"ACTIVE\"");
        defer alloc.free(normalized);
        try std.testing.expectEqualStrings("\"active\"", normalized);

        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(alloc);
        var called = try server.applyRelationalSqlDdlWithSession("CALL rotate_usage();", &session);
        defer called.deinit(alloc);
        try std.testing.expectError(error.UnsupportedSqlShape, server.applyRelationalSqlDdlWithSession("CALL rotate_usage(1);", &session));
        try std.testing.expectError(error.RoutineNotFound, server.applyRelationalSqlDdlWithSession("CALL missing_usage();", &session));
        var dropped = try server.applyRelationalSqlDdlWithSession("DROP FUNCTION normalize_status(text);", &session);
        defer dropped.deinit(alloc);
        var dropped_procedure = try server.applyRelationalSqlDdlWithSession("DROP PROCEDURE rotate_usage();", &session);
        defer dropped_procedure.deinit(alloc);
        try std.testing.expectEqual(@as(usize, 0), server.sql_routine_runtime.routineCountForTest());
    }

    {
        var source = FakeSource{};
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .sql_routine_store_path = path }, source.iface(), null, null);
        defer server.deinit();
        try std.testing.expectEqual(@as(usize, 0), server.sql_routine_runtime.routineCountForTest());
    }
}

