test "api http server passes SQL routine bindings to source-backed schema DDL" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        table: ?metadata_table_manager.TableRecord = null,
        binding_aware_calls: usize = 0,

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.table) |record| metadata_table_manager.freeTable(allocator, record);
            self.* = undefined;
        }

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.binding_aware_calls += 1;

            const table_plan = switch (plan.*) {
                .table_ddl => |*table| table,
                else => return error.TestUnexpectedResult,
            };
            var target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(allocator, table_plan.*, session);
            defer target.deinit(allocator);

            var base_table = tables_api.deriveRelationalSqlDdlTargetTableRecord(target);
            const source_table = if (self.table) |*record| record else &base_table;
            var applied = try tables_api.applyTableDdlPlanToTableRecordWithSessionAlloc(
                allocator,
                source_table,
                table_plan,
                session,
            );
            errdefer applied.deinit(allocator);

            const stored = try metadata_table_manager.cloneTable(allocator, applied.table);
            errdefer metadata_table_manager.freeTable(allocator, stored);
            if (self.table) |record| metadata_table_manager.freeTable(allocator, record);
            self.table = stored;
            return applied;
        }
    };

    var source = FakeSource{};
    defer source.deinit(alloc);
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var created_routine = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT lower($1)';",
        &session,
    );
    defer created_routine.deinit(alloc);

    var created_table = try server.applyRelationalSqlDdlWithSession(
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, status_key text GENERATED ALWAYS AS (normalize_status(status)) STORED, CONSTRAINT usage_records_status_check CHECK (normalize_status(status) != 'deleted'));",
        &session,
    );
    defer created_table.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), source.binding_aware_calls);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"generated\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"checks\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "usage_records_status_check") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"op\":\"lower\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"field\":\"status\"") != null);
}

test "api http server refreshes SQL routine hooks from ready extension query functions" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        installed_ready: bool = false,
        installed_record: extension_domain.InstalledExtension = .{
            .name = "pgcrypto",
            .package_name = "pgcrypto",
            .package_version = "1.0.0",
            .package_digest = "sha256:pgcrypto",
            .scope = .{ .kind = .cluster },
            .status = .ready,
        },
        member_record: extension_domain.ExtensionMember = .{
            .extension_name = "pgcrypto",
            .scope = .{ .kind = .cluster },
            .object_kind = .query_function,
            .object_name = "gen_random_uuid",
            .owner_metadata_json = "{\"native_expression\":\"uuid_v4\",\"arity\":0,\"sql_names\":[\"gen_random_uuid\"]}",
        },

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
                .projected_installed_extensions = 1,
                .projected_extension_members = 1,
            };
        }

        fn installedSlice(self: *@This()) []extension_domain.InstalledExtension {
            if (!self.installed_ready) return &.{};
            return @as([*]extension_domain.InstalledExtension, @ptrCast(&self.installed_record))[0..1];
        }

        fn memberSlice(self: *@This()) []extension_domain.ExtensionMember {
            if (!self.installed_ready) return &.{};
            return @as([*]extension_domain.ExtensionMember, @ptrCast(&self.member_record))[0..1];
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = &.{},
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .installed_extensions = self.installedSlice(),
                .extension_members = self.memberSlice(),
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            switch (plan.*) {
                .extension => |extension_plan| switch (extension_plan) {
                    .create => self.installed_ready = true,
                    .drop => self.installed_ready = false,
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            }
            return try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc_arg);
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var created = try server.applyRelationalSqlDdlWithSession("CREATE EXTENSION pgcrypto;", &session);
    defer created.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), server.sql_routine_runtime.routineCountForTest());
    const generated = try server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "gen_random_uuid", &.{});
    defer alloc.free(generated);
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, generated, .{});
    defer parsed.deinit();
    switch (parsed.value) {
        .string => |value| try std.testing.expect(value.len > 0),
        else => return error.TestUnexpectedResult,
    }

    var dropped = try server.applyRelationalSqlDdlWithSession("DROP EXTENSION pgcrypto;", &session);
    defer dropped.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), server.sql_routine_runtime.routineCountForTest());
    try std.testing.expectError(error.RoutineNotFound, server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "gen_random_uuid", &.{}));
}

