    const FakeAudit = struct {
        const Captured = struct {
            outcome: SqlBulkIoAuditOutcome,
            action: sql_adapter.BulkSqlIoAuditAction,
            operation: sql_adapter.BulkSqlIoOperation,
            native_route: sql_adapter.BulkSqlIoNativeRoute,
            stream: sql_adapter.BulkSqlIoStream,
            codec: sql_adapter.BulkSqlIoCodec,
            required_permission: usermgr.PermissionType,
            authenticated_subject: ?[]u8 = null,
            database_name: []u8,
            namespace_name: []u8,
            table_name: []u8,
            row_count: usize,
            error_name: ?[]u8 = null,

            fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                if (self.authenticated_subject) |value| allocator.free(value);
                allocator.free(self.database_name);
                allocator.free(self.namespace_name);
                allocator.free(self.table_name);
                if (self.error_name) |value| allocator.free(value);
                self.* = undefined;
            }
        };

        alloc: std.mem.Allocator,
        events: [13]Captured = undefined,
        count: usize = 0,

        fn deinit(self: *@This()) void {
            for (self.events[0..self.count]) |*event| event.deinit(self.alloc);
        }

        fn sink(self: *@This()) SqlBulkIoAuditSink {
            return .{ .ptr = self, .record = record };
        }

        fn record(ptr: *anyopaque, event: SqlBulkIoAuditRecord) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.count >= self.events.len) return error.TestUnexpectedResult;
            self.events[self.count] = .{
                .outcome = event.outcome,
                .action = event.action,
                .operation = event.operation,
                .native_route = event.native_route,
                .stream = event.stream,
                .codec = event.codec,
                .required_permission = event.required_permission,
                .authenticated_subject = if (event.authenticated_subject) |subject| try self.alloc.dupe(u8, subject) else null,
                .database_name = try self.alloc.dupe(u8, event.target.database_name),
                .namespace_name = try self.alloc.dupe(u8, event.target.namespace_name),
                .table_name = try self.alloc.dupe(u8, event.target.table_name),
                .row_count = event.row_count,
                .error_name = if (event.error_name) |name| try self.alloc.dupe(u8, name) else null,
            };
            self.count += 1;
        }
    };
    const FakeFileIo = struct {
        import_payload: []const u8,
        last_export_path: []u8 = &.{},
        last_export_payload: []u8 = &.{},

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.last_export_path.len > 0) allocator.free(self.last_export_path);
            if (self.last_export_payload.len > 0) allocator.free(self.last_export_payload);
        }

        fn iface(self: *@This()) SqlBulkIoFileIo {
            return .{
                .ptr = self,
                .read_import = readImport,
                .write_export = writeExport,
            };
        }

        fn readImport(ptr: *anyopaque, allocator: std.mem.Allocator, path: []const u8) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("/tmp/events.csv", path);
            return try allocator.dupe(u8, self.import_payload);
        }

        fn writeExport(ptr: *anyopaque, path: []const u8, payload: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.last_export_path.len > 0) std.testing.allocator.free(self.last_export_path);
            if (self.last_export_payload.len > 0) std.testing.allocator.free(self.last_export_payload);
            self.last_export_path = try std.testing.allocator.dupe(u8, path);
            self.last_export_payload = try std.testing.allocator.dupe(u8, payload);
        }
    };
    const FakeProgramIo = struct {
        import_payload: []const u8,
        last_import_command: []u8 = &.{},
        last_export_command: []u8 = &.{},
        last_export_payload: []u8 = &.{},

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.last_import_command.len > 0) allocator.free(self.last_import_command);
            if (self.last_export_command.len > 0) allocator.free(self.last_export_command);
            if (self.last_export_payload.len > 0) allocator.free(self.last_export_payload);
        }

        fn iface(self: *@This()) SqlBulkIoProgramIo {
            return .{
                .ptr = self,
                .read_import = readImport,
                .write_export = writeExport,
            };
        }

        fn readImport(ptr: *anyopaque, allocator: std.mem.Allocator, command: []const u8) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.last_import_command.len > 0) allocator.free(self.last_import_command);
            self.last_import_command = try allocator.dupe(u8, command);
            return try allocator.dupe(u8, self.import_payload);
        }

        fn writeExport(ptr: *anyopaque, command: []const u8, payload: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.last_export_command.len > 0) std.testing.allocator.free(self.last_export_command);
            if (self.last_export_payload.len > 0) std.testing.allocator.free(self.last_export_payload);
            self.last_export_command = try std.testing.allocator.dupe(u8, command);
            self.last_export_payload = try std.testing.allocator.dupe(u8, payload);
        }
    };

    var source = FakeSource{};
    var reads = FakeReads{};
    var writes = FakeWrites{};
    var audit = FakeAudit{ .alloc = alloc };
    var file_io = FakeFileIo{ .import_payload = "id,status\nu_file,Ready\n" };
