        .body = "{\"table\":\"docs_multi\",\"intent\":\"find related raft architecture\",\"mode\":\"graph\",\"interactive\":true,\"max_user_clarifications\":1,\"decisions\":[{\"question_id\":\"select_graph_index\",\"answer\":\"topic_graph\"}]}",
