    const DeleteExplainResponse = struct {
        valid: bool,
        delete_plan: struct {
            exists: bool,
            allowed: bool,
            block_reason: []const u8,
            planned_set_null_updates: u64,
            planned_cascade_deletes: u64,
        },
    };
    const ActionJobResponse = struct {
        complete: bool,
        groups: []const struct {
            group_id: u64,
            job_id: []const u8,
            action: []const u8,
            worker_id: []const u8,
