    var status_identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "status_reader"),
        .row_filter = status_row_filters,
    };
    defer status_identity.deinit(alloc);

    var rejected_filtered_update_resp = try server.handlePublicTableRowsBatch("records", "{\"operations\":[{\"op\":\"update\",\"where\":{\"primary\":{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o1\"}},\"patch\":{\"status\":\"closed\"}}]}", status_identity);
    defer rejected_filtered_update_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 403), rejected_filtered_update_resp.status);

    var filtered_query_resp = try server.handlePublicTableRowsQuery("records", "{\"query\":{\"where\":{\"all\":[{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"order\"},{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"}]},\"select\":[\"tenant\",\"id\",\"amount\"],\"order_by\":[{\"field\":\"amount\",\"direction\":\"desc\"}]}}", identity);
    defer filtered_query_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), filtered_query_resp.status);
    var parsed_filtered_query = try std.json.parseFromSlice(std.json.Value, alloc, filtered_query_resp.body, .{ .allocate = .alloc_always });
    defer parsed_filtered_query.deinit();
    try std.testing.expectEqual(@as(i64, 2), parsed_filtered_query.value.object.get("total").?.integer);
    try std.testing.expectEqualStrings("t1", parsed_filtered_query.value.object.get("rows").?.array.items[0].object.get("tenant").?.string);

    var filtered_aggregate_resp = try server.handlePublicTableRowsAggregate("records", "{\"ctes\":[{\"name\":\"open_orders\",\"query\":{\"where\":{\"all\":[{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"order\"},{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"}]}}}],\"aggregate\":{\"source\":{\"source_cte\":\"open_orders\"},\"group_by\":[\"customer_id\"],\"aggregations\":[{\"name\":\"amount_sum\",\"op\":\"sum\",\"field\":\"amount\"}]}}", identity);
    defer filtered_aggregate_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), filtered_aggregate_resp.status);
    var parsed_filtered_aggregate = try std.json.parseFromSlice(std.json.Value, alloc, filtered_aggregate_resp.body, .{ .allocate = .alloc_always });
    defer parsed_filtered_aggregate.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_filtered_aggregate.value.object.get("total_groups").?.integer);
    try std.testing.expectEqual(@as(i64, 30), parsed_filtered_aggregate.value.object.get("rows").?.array.items[0].object.get("amount_sum").?.integer);

    var filtered_join_resp = try server.handlePublicTableRowsJoin("records", "{\"join\":{\"left\":{\"where\":{\"all\":[{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"order\"},{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"}]}},\"right\":{\"where\":{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"customer\"}},\"on\":[{\"left_field\":\"customer_id\",\"right_field\":\"id\"}],\"select\":[{\"as\":\"tenant\",\"side\":\"left\",\"field\":\"tenant\"},{\"as\":\"order_id\",\"side\":\"left\",\"field\":\"id\"},{\"as\":\"customer_name\",\"side\":\"right\",\"field\":\"name\"}]}}", identity);
    defer filtered_join_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), filtered_join_resp.status);
    var parsed_filtered_join = try std.json.parseFromSlice(std.json.Value, alloc, filtered_join_resp.body, .{ .allocate = .alloc_always });
    defer parsed_filtered_join.deinit();
    try std.testing.expectEqual(@as(i64, 2), parsed_filtered_join.value.object.get("total_rows").?.integer);
    try std.testing.expectEqualStrings("t1", parsed_filtered_join.value.object.get("rows").?.array.items[0].object.get("tenant").?.string);

    var disjunctive_row_filters = try alloc.alloc(usermgr.RowFilterEntry, 1);
    disjunctive_row_filters[0] = try usermgr.RowFilterEntry.initOwned(alloc, "records", "{\"disjuncts\":[{\"term\":{\"tenant\":\"t1\"}},{\"term\":{\"tenant\":\"t2\"}}]}");
    var disjunctive_identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "disjunctive_reader"),
        .row_filter = disjunctive_row_filters,
    };
    defer disjunctive_identity.deinit(alloc);

    var disjunctive_resp = try server.handlePublicTableRowsQuery("records", "{\"query\":{\"where\":{\"all\":[{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"order\"},{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"}]},\"select\":[\"tenant\",\"id\",\"amount\"],\"order_by\":[{\"field\":\"amount\",\"direction\":\"desc\"}]}}", disjunctive_identity);
    defer disjunctive_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), disjunctive_resp.status);
    var parsed_disjunctive_query = try std.json.parseFromSlice(std.json.Value, alloc, disjunctive_resp.body, .{ .allocate = .alloc_always });
    defer parsed_disjunctive_query.deinit();
    try std.testing.expectEqual(@as(i64, 3), parsed_disjunctive_query.value.object.get("total").?.integer);
    try std.testing.expectEqualStrings("t2", parsed_disjunctive_query.value.object.get("rows").?.array.items[0].object.get("tenant").?.string);

    const disjunctive_mutation_txn_hex = "10112233445566778899aabbccddeeff";
    const disjunctive_mutation_txn_id = try distributed_txn.parseTxnIdHex(disjunctive_mutation_txn_hex);
    _ = try db.beginTransactionWithId(disjunctive_mutation_txn_id, 1_002);
    var disjunctive_mutation_resp = try server.handlePublicTableRowsMutationSource("records", "{\"op\":\"update\",\"source\":{\"where\":{\"all\":[{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"order\"},{\"field\":\"tenant\",\"op\":\"eq\",\"value\":\"t2\"}]},\"row_claim\":{\"mode\":\"for_update\",\"owner_id\":\"worker:or-auth\",\"transaction_id\":\"10112233445566778899aabbccddeeff\"}},\"patch\":{\"status\":\"claimed\"},\"returning\":[\"tenant\",\"id\",\"status\"]}", disjunctive_identity);
    defer disjunctive_mutation_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), disjunctive_mutation_resp.status);
    var parsed_disjunctive_mutation = try std.json.parseFromSlice(std.json.Value, alloc, disjunctive_mutation_resp.body, .{ .allocate = .alloc_always });
    defer parsed_disjunctive_mutation.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_disjunctive_mutation.value.object.get("matched").?.integer);
    try std.testing.expectEqual(@as(i64, 1), parsed_disjunctive_mutation.value.object.get("staged").?.integer);
    const disjunctive_returning = parsed_disjunctive_mutation.value.object.get("returning").?.array.items[0].object;
    try std.testing.expectEqualStrings("t2", disjunctive_returning.get("tenant").?.string);
    try std.testing.expectEqualStrings("o9", disjunctive_returning.get("id").?.string);
    try std.testing.expectEqualStrings("claimed", disjunctive_returning.get("status").?.string);
    try db.commitTransaction(disjunctive_mutation_txn_id, 1_003);
}

test "api http server executes public cross-table relational join and lateral row plans" {
    const alloc = std.testing.allocator;
    const orders_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"customer_id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["id","customer_id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const customers_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"name":{"type":"keyword"},"enabled":{"type":"boolean"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const orders_path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/rows-plan-cross-table-orders", .{tmp.sub_path});
    defer alloc.free(orders_path);
    const customers_path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/rows-plan-cross-table-customers", .{tmp.sub_path});
    defer alloc.free(customers_path);

    var orders_db = try db_mod.DB.open(alloc, orders_path, .{});
    defer orders_db.close();
    try orders_db.applyTableSchemaJson(alloc, orders_schema_json, .{});
    var customers_db = try db_mod.DB.open(alloc, customers_path, .{});
    defer customers_db.close();
    try customers_db.applyTableSchemaJson(alloc, customers_schema_json, .{});

    const FakeStatusSource = struct {
        tables: [2]metadata_table_manager.TableRecord,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 2 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var status_source = FakeStatusSource{ .tables = .{
        .{
            .table_id = 1,
            .name = "orders",
            .schema_json = orders_schema_json,
            .desired_replica_count = 1,
        },
        .{
            .table_id = 2,
            .name = "customers",
            .schema_json = customers_schema_json,
            .desired_replica_count = 1,
        },
    } };

    var orders_write_source = table_writes.BoundTableWriteSource.init("orders", &orders_db);
    var customers_write_source = table_writes.BoundTableWriteSource.init("customers", &customers_db);
    var orders_seed_server = ApiHttpServer.init(alloc, .{}, status_source.iface(), null, orders_write_source.source());
    var customers_seed_server = ApiHttpServer.init(alloc, .{}, status_source.iface(), null, customers_write_source.source());

    var orders_insert_resp = try orders_seed_server.handlePublicTableRowsBatch("orders", "{\"operations\":[{\"op\":\"insert\",\"row\":{\"id\":\"o1\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":10}},{\"op\":\"insert\",\"row\":{\"id\":\"o2\",\"customer_id\":\"c2\",\"status\":\"open\",\"amount\":20}},{\"op\":\"insert\",\"row\":{\"id\":\"o3\",\"customer_id\":\"c1\",\"status\":\"closed\",\"amount\":30}}]}", null);
    defer orders_insert_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), orders_insert_resp.status);
    var customers_insert_resp = try customers_seed_server.handlePublicTableRowsBatch("customers", "{\"operations\":[{\"op\":\"insert\",\"row\":{\"id\":\"c1\",\"name\":\"Ada\",\"enabled\":true}},{\"op\":\"insert\",\"row\":{\"id\":\"c2\",\"name\":\"Bob\",\"enabled\":false}}]}", null);
    defer customers_insert_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), customers_insert_resp.status);

    var orders_read_source = table_reads.BoundTableReadSource.init("orders", 1, &orders_db, raft_mod.read_gate.noopReadableLeaseRequester());
    var customers_read_source = table_reads.BoundTableReadSource.init("customers", 2, &customers_db, raft_mod.read_gate.noopReadableLeaseRequester());
    const MultiTableReadSource = struct {
        orders: table_reads.TableReadSource,
        customers: table_reads.TableReadSource,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                },
            };
        }

        fn table(self: *@This(), table_name: []const u8) ?table_reads.TableReadSource {
            if (std.mem.eql(u8, table_name, "orders")) return self.orders;
            if (std.mem.eql(u8, table_name, "customers")) return self.customers;
            return null;
        }

        fn lookup(
            ptr: *anyopaque,
            lookup_alloc: std.mem.Allocator,
            table_name: []const u8,
            key: []const u8,
            opts: db_mod.types.LookupOptions,
            consistency: raft_mod.ReadConsistency,
        ) !?table_reads.LookupResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const table_source = self.table(table_name) orelse return null;
            return try table_source.lookup(lookup_alloc, table_name, key, opts, consistency);
        }

        fn scan(
            ptr: *anyopaque,
            scan_alloc: std.mem.Allocator,
            table_name: []const u8,
            from_key: []const u8,
            to_key: []const u8,
            opts: db_mod.types.ScanOptions,
            consistency: raft_mod.ReadConsistency,
        ) !?table_reads.ScanResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const table_source = self.table(table_name) orelse return null;
            return try table_source.scan(scan_alloc, table_name, from_key, to_key, opts, consistency);
        }

        fn query(
            ptr: *anyopaque,
            query_alloc: std.mem.Allocator,
            table_name: []const u8,
            req: db_mod.types.SearchRequest,
            consistency: raft_mod.ReadConsistency,
        ) !?query_api.QueryResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const table_source = self.table(table_name) orelse return null;
            return try table_source.query(query_alloc, table_name, req, consistency);
        }
    };
    var multi_read_source = MultiTableReadSource{
        .orders = orders_read_source.source(),
        .customers = customers_read_source.source(),
    };
    var server = ApiHttpServer.init(alloc, .{}, status_source.iface(), multi_read_source.source(), null);

    var join_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/orders/rows/join",
        .content_type = "application/json",
        .body = "{\"left_table\":\"orders\",\"right_table\":\"customers\",\"join\":{\"left\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"}},\"right\":{\"where\":{\"field\":\"enabled\",\"op\":\"eq\",\"value\":true}},\"on\":[{\"left_field\":\"customer_id\",\"right_field\":\"id\"}],\"select\":[{\"as\":\"order_id\",\"side\":\"left\",\"field\":\"id\"},{\"as\":\"customer_name\",\"side\":\"right\",\"field\":\"name\"}],\"order_by\":[{\"field\":\"order_id\"}]}}",
    });
    defer join_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), join_resp.status);
    var parsed_join = try std.json.parseFromSlice(std.json.Value, alloc, join_resp.body, .{ .allocate = .alloc_always });
    defer parsed_join.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_join.value.object.get("total_rows").?.integer);
    try std.testing.expectEqualStrings("o1", parsed_join.value.object.get("rows").?.array.items[0].object.get("order_id").?.string);
    try std.testing.expectEqualStrings("Ada", parsed_join.value.object.get("rows").?.array.items[0].object.get("customer_name").?.string);
    try expectRowsResultSchemaColumn(parsed_join.value, "order_id", "keyword", false, null);
    try expectRowsResultSchemaColumn(parsed_join.value, "customer_name", "keyword", true, null);

    var lateral_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/orders/rows/lateral",
        .content_type = "application/json",
        .body = "{\"left_table\":\"orders\",\"right_table\":\"customers\",\"lateral\":{\"left\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"},\"order_by\":[{\"field\":\"id\"}]},\"right\":{\"where\":{\"field\":\"enabled\",\"op\":\"eq\",\"value\":true},\"order_by\":[{\"field\":\"name\"}],\"limit\":1},\"correlations\":[{\"left_field\":\"customer_id\",\"right_field\":\"id\"}],\"select\":[{\"as\":\"order_id\",\"side\":\"left\",\"field\":\"id\"},{\"as\":\"customer_name\",\"side\":\"right\",\"field\":\"name\"}],\"order_by\":[{\"field\":\"order_id\"}]}}",
    });
    defer lateral_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), lateral_resp.status);
    var parsed_lateral = try std.json.parseFromSlice(std.json.Value, alloc, lateral_resp.body, .{ .allocate = .alloc_always });
    defer parsed_lateral.deinit();
    try std.testing.expectEqual(@as(i64, 2), parsed_lateral.value.object.get("total_rows").?.integer);
    try std.testing.expectEqualStrings("o1", parsed_lateral.value.object.get("rows").?.array.items[0].object.get("order_id").?.string);
    try std.testing.expectEqualStrings("Ada", parsed_lateral.value.object.get("rows").?.array.items[0].object.get("customer_name").?.string);
    try std.testing.expectEqualStrings("o2", parsed_lateral.value.object.get("rows").?.array.items[1].object.get("order_id").?.string);
    try std.testing.expectEqual(std.json.Value{ .null = {} }, parsed_lateral.value.object.get("rows").?.array.items[1].object.get("customer_name").?);
    try expectRowsResultSchemaColumn(parsed_lateral.value, "order_id", "keyword", false, null);
    try expectRowsResultSchemaColumn(parsed_lateral.value, "customer_name", "keyword", true, null);
}

test "api http server lake text candidate planning rejects ambiguous field sidecars" {
    const alloc = std.testing.allocator;
    const description_columns = [_][]const u8{"description"};
    const category_columns = [_][]const u8{"category"};
    const base_binding = lake_source_binding_api.Binding{
        .sidecar_kind = .text,
        .source_kind = .external_parquet,
        .row_ref_kind = .external,
        .source_id = "events",
        .snapshot_id = "snapshot-1",
        .schema_fingerprint = "schema-v1",
        .column_bindings = description_columns[0..],
        .index_config_hash = "sha256:text-simple",
    };
    const sidecars = [_]lake_sidecar_manifest.DeclaredArtifact{
        .{
            .name = "events.description.simple",
            .binding = base_binding,
            .artifact = .{
                .kind = .text_segment,
                .name = "events.description.simple",
                .artifact_id = "artifact:text-simple",
                .byte_len = 1,
                .checksum = "sha256:text-simple",
            },
        },
        .{
            .name = "events.category.simple",
            .binding = .{
                .sidecar_kind = .text,
                .source_kind = .external_parquet,
                .row_ref_kind = .external,
                .source_id = "events",
                .snapshot_id = "snapshot-1",
                .schema_fingerprint = "schema-v1",
                .column_bindings = category_columns[0..],
                .index_config_hash = "sha256:text-category",
            },
            .artifact = .{
                .kind = .text_segment,
                .name = "events.category.simple",
                .artifact_id = "artifact:text-category",
                .byte_len = 1,
                .checksum = "sha256:text-category",
            },
        },
        .{
            .name = "events.description.keyword",
            .binding = .{
                .sidecar_kind = .text,
                .source_kind = .external_parquet,
                .row_ref_kind = .external,
                .source_id = "events",
                .snapshot_id = "snapshot-1",
                .schema_fingerprint = "schema-v1",
                .column_bindings = description_columns[0..],
                .index_config_hash = "sha256:text-keyword",
            },
            .artifact = .{
                .kind = .text_segment,
                .name = "events.description.keyword",
                .artifact_id = "artifact:text-keyword",
                .byte_len = 1,
                .checksum = "sha256:text-keyword",
            },
        },
    };

    const category_plan = (try ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc,
        sidecars[0..],
        .{ .field = "category", .pattern = "news" },
    )) orelse return error.TestExpectedEqual;
    defer alloc.free(category_plan.sidecar_names.?);
    try std.testing.expectEqual(@as(usize, 1), category_plan.sidecar_names.?.len);
    try std.testing.expectEqualStrings("events.category.simple", category_plan.sidecar_names.?[0]);
    try std.testing.expectEqual(serverless_query.QueryOperator.phrase, category_plan.request.operator);

    const category_phrase_plan = (try ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc,
        sidecars[0..],
        .{ .field = "category", .pattern = "News Room", .case_insensitive = true },
    )) orelse return error.TestExpectedEqual;
    defer alloc.free(category_phrase_plan.sidecar_names.?);
    try std.testing.expectEqualStrings("News Room", category_phrase_plan.request.text);
    try std.testing.expectEqual(serverless_query.QueryOperator.phrase, category_phrase_plan.request.operator);
    try std.testing.expectEqualStrings("events.category.simple", category_phrase_plan.sidecar_names.?[0]);

    const category_prefix_plan = (try ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc,
        sidecars[0..],
        .{ .field = "category", .pattern = "new%" },
    )) orelse return error.TestExpectedEqual;
    defer alloc.free(category_prefix_plan.sidecar_names.?);
    try std.testing.expectEqualStrings("new", category_prefix_plan.request.text);
    try std.testing.expectEqual(serverless_query.QueryOperator.prefix_any_term, category_prefix_plan.request.operator);
    try std.testing.expectEqualStrings("events.category.simple", category_prefix_plan.sidecar_names.?[0]);

    const category_multi_prefix_queries = ApiHttpServer.textPatternCandidateQueriesFromPattern(.{
        .field = "category",
        .pattern = "news ro%",
    }) orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(@as(usize, 2), category_multi_prefix_queries.len);
    try std.testing.expectEqualStrings("news", category_multi_prefix_queries.items[0].text);
    try std.testing.expectEqual(serverless_query.QueryOperator.all_terms, category_multi_prefix_queries.items[0].operator);
    try std.testing.expectEqualStrings("ro", category_multi_prefix_queries.items[1].text);
    try std.testing.expectEqual(serverless_query.QueryOperator.prefix_any_term, category_multi_prefix_queries.items[1].operator);

    const category_trailing_space_queries = ApiHttpServer.textPatternCandidateQueriesFromPattern(.{
        .field = "category",
        .pattern = "news room %",
    }) orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(@as(usize, 1), category_trailing_space_queries.len);
    try std.testing.expectEqualStrings("news room", category_trailing_space_queries.items[0].text);
    try std.testing.expectEqual(serverless_query.QueryOperator.all_terms, category_trailing_space_queries.items[0].operator);

    try std.testing.expect((try ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc,
        sidecars[0..],
        .{ .field = "category", .pattern = "%news" },
    )) == null);
    try std.testing.expect((try ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc,
        sidecars[0..],
        .{ .field = "category", .pattern = "ne_s" },
    )) == null);
    try std.testing.expect((try ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc,
        sidecars[0..],
        .{ .field = "category", .pattern = "news\\%" },
    )) == null);

    try std.testing.expectError(
        error.AmbiguousLakeSidecarCandidateSource,
        ApiHttpServer.textSidecarCandidatePlanForRowsTextPatternAlloc(
            alloc,
            sidecars[0..],
            .{ .field = "description", .pattern = "beta" },
        ),
    );
}

test "api http server routes public external lake row queries through configured resolver" {
    const alloc = std.testing.allocator;
    const object_storage_api = @import("../storage/object_storage.zig");
    const object_store_support = @import("../serverless/object_store_support.zig");
    const external_binding_api = @import("../serverless/external_source/catalog_binding.zig");
    const external_source_api = @import("../serverless/external_source/mod.zig");
    const external_rowsource = @import("../storage/rowsource/external.zig");
    const lake_source_binding = @import("../serverless/segment/source_binding.zig");
    const lake_sidecar_text_build = @import("../serverless/build/lake_sidecar_text.zig");
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"base_source":{"kind":"external","table_id":"events","format":"parquet","uri":"s3://bucket/events","schema_fingerprint":"schema-v1"},"document_schemas":{"row":{"schema":{"type":"object","properties":{"amount":{"type":"numeric"},"discount":{"type":"numeric"},"tenant":{"type":"numeric"},"rank":{"type":"numeric"},"description":{"type":"text"},"category":{"type":"text"}},"required":["amount","discount","tenant","rank","description","category"],"additionalProperties":false}}},"primary_key":{"columns":["amount"]}}
    ;
