    try std.testing.expect(std.mem.indexOf(u8, list_db.body, "\"name\":\"default\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, list_db.body, "\"name\":\"tenant_ops\"") != null);

    var create_namespace = try server.handle(.{
